#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[3];
    char reg;
    char data[2];
    int16_t raw;

    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE << 7) | (ADS1115_CONFIG_MUX_AIN0_GND << 2) |
                (ADS1115_CONFIG_PGA_4_096V << 1) | (ADS1115_CONFIG_DR_128SPS << 0);
    config[2] = 0x83;

    if (i2cWriteDevice(handle, config, 3) < 0) {
        return -1;
    }

    reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) < 0) {
        return -1;
    }

    raw = (int16_t)((data[0] << 8) | data[1]);
    return raw;
}

static double convert_to_amperes(int16_t raw) {
    return (double)raw * 0.0000610352;
}

int main(void) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "Error reading ADS1115\n");
        } else {
            double current = convert_to_amperes(raw);
            printf("Current: %.4f A\n", current);
        }
        usleep(500000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

