/*
 * Raspberry Pi 3 Model B+ — KY-026 Flame Sensor + MCP3008 ADC logger
 *
 * Wiring (BCM numbering):
 *   KY-026 D0  -> GPIO4  (SPI0 MISO)
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> A0
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:    sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4          /* KY-026 D0 on SPI0 MISO */
#define MCP3008_CHANNEL 0           /* Single-ended CH0 */
#define SPI_BAUD         1000000    /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_FLAGS        0          /* CE0 active-low, 8-bit words */
#define SAMPLE_PERIOD_S  1          /* seconds between samples */
#define CSV_FILENAME     "flame_data.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read (3-byte transfer, SPI mode 0)             */
/* Returns 0–1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (mode 0, MSB-first):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1 single-ended, D2..D0=channel)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in upper nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Temperature approximation from analog reading (Vref = 3.3 V)       */
/* ------------------------------------------------------------------ */
static float adc_to_temperature(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float voltage = (float)adc_value / 1023.0f * 3.3f;
    return voltage * 100.0f;   /* degrees Celsius */
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, bool flame_detected, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected ? 1 : 0, temperature) < 0) {
        fprintf(stderr, "Error: fprintf to CSV failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on CSV file\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* --- SPI0 CE0 ---------------------------------------------------- */
    g_spi_handle = spiOpen(0, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    /* --- Open CSV file ----------------------------------------------- */
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for append\n", CSV_FILENAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,flame_detected,temperature_c\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header\n");
            fclose(fp);
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush failed on CSV header\n");
        }
    }

    printf("Flame sensor logging started. Press Ctrl+C to stop.\n");
    printf("  Sensor : KY-026 D0 on GPIO4 (BCM)\n");
    printf("  ADC    : MCP3008 CH0 on SPI0 CE0 (BCM8)\n");
    printf("  File   : %s\n", CSV_FILENAME);
    printf("  Period : %d s\n\n", SAMPLE_PERIOD_S);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        int adc_value = mcp3008_read(g_spi_handle, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: MCP3008 read failed — skipping sample\n");
        } else {
            bool flame_detected = (adc_value > 200);   /* rough threshold */
            float temperature = adc_to_temperature(adc_value);

            if (log_data(fp, flame_detected, temperature) != 0) {
                fprintf(stderr, "Error: logging failed — skipping sample\n");
            } else {
                printf("ADC=%4d  Flame=%3d  Temp=%.2f C\n",
                       adc_value, flame_detected ? 1 : 0, temperature);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

