#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define HEAT_SENSOR_PIN  0
#define BUZZER_PIN       27
#define I2C_BUS          1
#define ADC_CHANNEL      0
#define LOG_FILE         "fire_log.txt"
#define TEMP_THRESHOLD   60.0f
#define BUZZER_DURATION  2
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_US      50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int val = gpioRead(FLAME_SENSOR_PIN);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on flame sensor pin %d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    gpioDelay(DEBOUNCE_US);
    return val;
}

static int read_heat_sensor(void) {
    char config[2];
    config[0] = 0x01;
    config[1] = (0x80 | (ADC_CHANNEL << 4));
    if (i2cWriteDevice(i2c_handle, config, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for ADC config\n");
        return -1;
    }
    gpioDelay(1000);
    char reg = 0x00;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed for reg select\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed for ADC data\n");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    return (int)raw;
}

static void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_PIN, 0);
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUZZER_PIN, RISING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flame sensor pin %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, 0x41, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed for SIGINT\n");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame = read_flame_sensor();
        int heat = read_heat_sensor();

        if (flame < 0 || heat < 0) {
            fprintf(stderr, "Warning: sensor read error, skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (flame) {
            log_event("Flame detected!");
            if (heat > TEMP_THRESHOLD) {
                log_event("Temperature exceeds threshold, logging reading");
                printf("Temperature: %.2f C\n", heat);
            }
        } else if (heat > TEMP_THRESHOLD) {
            log_event("Temperature exceeds threshold");
            printf("Temperature: %.2f C\n", heat);
        }

        if (flame && heat) {
            log_event("Fire detected!");
            activate_buzzer(BUZZER_DURATION);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

