#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define FAN_GPIO_CHIP   "gpiochip4"
#define FAN_GPIO_LINE   18

#define CURRENT_THRESHOLD 100.0
#define LOG_FILE         "current_log.txt"
#define SAMPLE_INTERVAL  1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_current(int adc_value)
{
    if (adc_value < 0) return -1.0;
    if (adc_value == 0) return 0.0;
    if (adc_value == 1023) return 100.0;

    double voltage = (adc_value / 1023.0) * 3.3;
    double current = (voltage / 3.3) * 100.0;
    return current;
}

static void log_current(double current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Current: %.2f A\n", timestamp, current);
    fclose(fp);
}

static void control_fan(double current)
{
    int fan_state = (current > CURRENT_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(gpiod_line, fan_state) < 0) {
        fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    /* Release GPIO line and close chip */
    struct gpiod_chip *chip = gpiod_line_get_chip(gpiod_line);
    if (chip) {
        gpiod_line_release(gpiod_line);
        gpiod_chip_close(chip);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(FAN_GPIO_CHIP);
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct gpiod_line *fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FAN_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (current < 0.0) {
            fprintf(stderr, "Invalid ADC value %d; sensor absent or bus error\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_current(current);
        control_fan(current);

        printf("Current: %.2f A\n", current);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(gpiod_line, 0);
    cleanup();
    printf("Fan OFF, GPIO released, SPI closed.\n");
    return 0;
}

