/*
 * IMP23ABSU dual-channel sound-pressure-level logger for Raspberry Pi 4.
 *
 * Wiring:
 *   IMP23ABSU VDD  -> 3.3 V (Pin 1)
 *   IMP23ABSU GND  -> GND   (Pin 9)
 *   IMP23ABSU AOUT1 -> GPIO2 (Pin 3)  [I2C bus 1, address 0x23]
 *   IMP23ABSU AOUT2 -> GPIO3 (Pin 5)  [I2C bus 1, address 0x24]
 *
 * The IMP23ABSU is an analog MEMS mic; the bit-banged I2C interface
 * reads the analog output voltage and converts it to dB.
 *
 * Build:  gcc -O2 -Wall -Wextra -o imp23absu_logger imp23absu_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR1      0x23
#define I2C_ADDR2      0x24
#define LOG_FILE       "audio_log.txt"
#define SAMPLE_US      100000   /* 100 ms between samples */
#define ERROR_VALUE    (-999.0f)

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit big-endian register from the IMP23ABSU.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_dB)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_dB);

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd1 = -1, fd2 = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    fd1 = i2c_open(I2C_ADDR1);
    if (fd1 < 0) goto out;

    fd2 = i2c_open(I2C_ADDR2);
    if (fd2 < 0) goto out;

    printf("IMP23ABSU logger started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        int16_t v1 = ERROR_VALUE, v2 = ERROR_VALUE;
        int ok1 = (i2c_read_reg16(fd1, 0x00, &v1) == 0);
        int ok2 = (i2c_read_reg16(fd2, 0x00, &v2) == 0);

        if (ok1 && ok2) {
            float dB1 = (float)v1;
            float dB2 = (float)v2;
            float avg = (dB1 + dB2) / 2.0f;
            log_data(avg);
            printf("Avg dB: %.2f\n", avg);
        } else {
            fprintf(stderr, "Error reading one or both microphones.\n");
            log_data(ERROR_VALUE);
        }

        usleep(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

out:
    if (fd1 >= 0) close(fd1);
    if (fd2 >= 0) close(fd2);
    return rc;
}

