code:
/*
 * Raspberry Pi 4 Model B — Dual ADMP401 MEMS Microphone RMS Sampler
 *
 * Hardware (SPI0):
 *   MCP3008 ADC  -> SPI0 CE0 (GPIO8), MISO (GPIO9), MOSI (GPIO10), SCLK (GPIO11)
 *   MCP3008 CH0  -> ADMP401 Mic 1
 *   MCP3008 CH1  -> ADMP401 Mic 2
 *   LED          -> GPIO27 (BCM)
 *
 * Build:  gcc -O2 -Wall -o audio_events audio_events.c -lpigpio -lrt
 * Run:    sudo ./audio_events
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL_0      0          /* CE0  (GPIO8)  */
#define SPI_CHANNEL_1      1          /* CE1  (GPIO9)  */
#define SPI_SPEED          1000000    /* 1 MHz   */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */

#define LED_GPIO           27         /* BCM 27 */
#define SAMPLE_WINDOW_MS   100        /* 100 samples @ 1 ms = 100 ms window */
#define SAMPLE_PERIOD_US   1000       /* 1 ms */
#define LED_ON_MS          500        /* LED on duration */
#define HIGH_THRESHOLD     0.5f      /* RMS threshold for alert */
#define ERROR_THRESHOLD    0.0f       /* RMS below this = warning only */

#define CSV_FILENAME       "audio_events.csv"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle_0 = -1;
static int g_spi_handle_1 = -1;

/* --------------------------- Function Prototypes ------------------------- */
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static float calculate_rms(const int *samples, int num_samples);
static void log_data(float mic1_rms, float mic2_rms);
static void trigger_alert(float mic1_rms, float mic2_rms);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI ------------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle_0 < 0) {
        fprintf(stderr, "Error: spiOpen(CE0) failed (pigpio error %d).\n", g_spi_handle_0);
        return -1;
    }

    g_spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle_1 < 0) {
        fprintf(stderr, "Error: spiOpen(CE1) failed (pigpio error %d).\n", g_spi_handle_1);
        spiClose(g_spi_handle_0);
        g_spi_handle_0 = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                 (start bit)
 *   tx[1] = (0x08 | channel) << 4 (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                 (clock out low bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle_0, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer(CE0) returned %d.\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* --------------------------- RMS Calculation ----------------------------- */
static float calculate_rms(const int *samples, int num_samples)
{
    if (num_samples <= 0) return 0.0f;

    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return (float)(sum_sq / num_samples);
}

/* --------------------------- CSV Logging ---------------------------------- */
static void log_data(float mic1_rms, float mic2_rms)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("Error opening CSV file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.4f,%.4f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                mic1_rms, mic2_rms);
    } else {
        fprintf(fp, "timestamp,%.4f,%.4f\n", mic1_rms, mic2_rms);
    }

    if (fclose(fp) != 0)
        perror("Warning: error closing CSV file");
}

/* --------------------------- Alert Logic --------------------------------- */
static void trigger_alert(float mic1_rms, float mic2_rms)
{
    if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
        if (gpioWrite(LED_GPIO, 1) < 0)
            fprintf(stderr, "Warning: gpioWrite(LED on) failed.\n");
        gpioDelay(LED_ON_MS * 1000); /* pigpio microseconds */
        if (gpioWrite(LED_GPIO, 0) < 0)
            fprintf(stderr, "Warning: gpioWrite(LED off) failed.\n");
    }
}

/* --------------------------- Cleanup / Signal ----------------------------- */
static void cleanup(void)
{
