    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }

    int mic1_samples[SAMPLE_WINDOW_MS];
    int mic2_samples[SAMPLE_WINDOW_MS];
    int idx = 0;
    int samples_acquired = 0;

    while (g_running) {
        int v1 = 0, v2 = 0;

        if (read_mcp3008(SPI_CHANNEL_0, &v1) != 0) {
            fprintf(stderr, "Error: failed to read Mic1 (CE0).\n");
            break;
        }
        if (read_mcp3008(SPI_CHANNEL_1, &v2) != 0) {
            fprintf(stderr, "Error: failed to read Mic2 (CE1).\n");
            break;
        }

        mic1_samples[idx] = v1;
        mic2_samples[idx] = v2;
        idx = (idx + 1) % SAMPLE_WINDOW_MS;
        if (idx == 0) samples_acquired++;

        if (samples_acquired == SAMPLE_WINDOW_MS) {
            float rms1 = calculate_rms(mic1_samples, SAMPLE_WINDOW_MS);
            float rms2 = calculate_rms(mic2_samples, SAMPLE_WINDOW_MS);
            log_data(rms1, rms2);
            trigger_alert(rms1, rms2);
            samples_acquired = 0;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
