/*
 * Raspberry Pi 4 Model B — MLX91204 Hall-effect current sensor monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (SDA=GPIO2 BCM, SCL=GPIO3 BCM)
 *   - MLX91204 analog output connected to ADS1115 AIN0
 *   - Warning LED on GPIO17 BCM (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -li2c
 *
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <linux/i2c.h>
#include <linux/i2c.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN    (1u << 15)
#define ADS1115_CFG_MUX_AIN0    (0x04u << 12)   /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096V (0x01u << 9)
#define ADS1115_CFG_MODE_SINGLE (0x00u << 8)
#define ADS1115_CFG_DR_128SPS  (0x04u << 5)
#define ADS1115_CFG_CQUE_NONE  (0x03u << 0)

#define LED_GPIO             17
#define CURRENT_THRESHOLD    50.0f
#define BUFFER_SIZE          100
#define SAMPLE_PERIOD_US     100000u   /* 10 Hz */
#define ADC_MAX_VALUE        32767.0f  /* 16-bit signed positive max */
#define ADC_VREF             4.096f

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg16(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int ads1115_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg16 write(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg16 read(0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success and stores the signed ADC value in *adc,
 * -1 on error.
 */
static int ads1115_read_ain0(int fd, int16_t *adc)
{
    uint16_t cfg;
    uint16_t raw;

    /* Start a single conversion on AIN0 */
    cfg = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
          ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SINGLE |
          ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Poll OS bit (bit 15) until it reads 1 */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg_read;
        if (ads1115_read_reg16(fd, ADS1115_REG_CONFIG, &cfg_read) != 0)
            return -1;
        if (cfg_read & ADS1115_CFG_OS_BEGIN)
            break;
        usleep(5000);
    }
    if (!(cfg_read & ADS1115_CFG_OS_BEGIN)) {
        fprintf(stderr, "ads1115_read_ain0: conversion timeout\n");
        return -1;
    }

    /* Read conversion result */
    if (ads1115_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *adc = (int16_t)raw;
    return 0;
}

/* ----------------------------- Circular buffer --------------------------- */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg16(g_i2c_fd, ADS1115_REG_CONFIG, &cfg_check) != 0) {
        fprintf(stderr, "ADS1115 not detected at 0x%02X\n", ADS1115_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", LED_GPIO, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    CircularBuffer current_buffer;
    cb_init(&current_buffer);

    printf("MLX91204 current monitor started. Sampling at 10 Hz.\n");
    printf("Threshold: %.1f A  |  Buffer: %d |  LED: GPIO%d\n",
           CURRENT_THRESHOLD, BUFFER_SIZE, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t adc_value;
        float current;

        if (ads1115_read_ain0(g_i2c_fd, &adc_value) != 0) {
            fprintf(stderr, "ADC read error — continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        current = (float)adc_value * (ADC_VREF / ADC_MAX_VALUE);

        cb_push(&current_buffer, current);
        float avg = cb_average(&current_buffer);

        printf("Current: %7.2f A  |  Buffer avg: %7.2f A  |  LED: %s\n",
               current, avg,
               (avg > CURRENT_THRESHOLD) ? "ON" : "OFF");

        if (gpioWrite(LED_GPIO, avg > CURRENT_THRESHOLD ? 1 : 0) != 0)
            fprintf(stderr, "gpioWrite(%d): %s\n", LED_GPIO, strerror(errno));

        usleep(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_GPIO, 0);
    close(g_i2c_fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

