#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define LOG_FILE       "color_log.csv"
#define SAMPLE_PERIOD  1000000  /* microseconds (1 second) */
#define MAX_CONSEC_ERRORS 3

/* TCS34725 registers */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ENABLE_AEN_PON 0x03

#define TCS34725_ID_VALUE  0x44

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        tcs34725_driver_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* TCS34725 driver (pigpio driver interface)                           */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    /* Read ID register to confirm sensor is present */
    if (i2c_read_byte(handle, TCS34725_ID, &id) < 0)
        return -1;

    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-on delay */

    /* Set integration time (ATIME) to 0x0C (4.5 ms) */
    if (i2c_write_byte(handle, TCS34725_ATIME, 0x0C) < 0)
        return -1;

    /* Set gain (CONTROL register) to 0x00 (gain x1) */
    if (i2c_write_byte(handle, TCS34725_CONTROL, 0x00) < 0)
        return -1;

    /* Enable both ADC and RGBC channels */
    if (i2c_write_byte(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    gpioDelay(3000);  /* 3 ms settle */
    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *clear,
                               uint16_t *red, uint16_t *green,
                               uint16_t *blue)
{
    uint8_t c, r, g, b;

    if (i2c_read_byte(handle, TCS34725_CDATA, &c) < 0) return -1;
    if (i2c_read_byte(handle, TCS34725_RDATA, &r) < 0) return -1;
    if (i2c_read_byte(handle, TCS34725_GDATA, &g) < 0) return -1;
    if (i2c_read_byte(handle, TCS34725_BDATA, &b) < 0) return -1;

    *clear = (uint16_t)c;
    *red   = (uint16_t)r;
    *green = (uint16_t)g;
    *blue  = (uint16_t)b;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n",
                timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t clear, red, green, blue;
    int      consecutive_errors = 0;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file (create with header) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    /* --- driver init --- */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 logging started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        if (tcs34725_read_color(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_errors = 0;
            if (log_data(g_log_file, clear, red, green, blue) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown --- */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

