/*
 * MLX90817 absolute pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_logger mlx90817_logger.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* MLX90817 default I2C address (7-bit) */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_CONSEC_ERR 10            /* consecutive I2C errors before abort */

/* MLX90817 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE  0x00
#define REG_TEMP      0x02
#define REG_CONFIG    0x04
#define REG_ID        0x07

#define PRESSURE_LSB  0x0000
#define PRESSURE_MSB  0x0001
#define TEMP_LSB     0x0002
#define TEMP_MSB     0x0003
#define CONFIG_LSB   0x0004
#define CONFIG_MSB   0x0005
#define ID_LSB       0x0006
#define ID_MSB       0x0007

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0)
        return -1;

    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[2];
    buf[0] = (char)((val >> 8) & 0xFF);
    buf[1] = (char)(val & 0xFF);

    if (i2cWriteByte(handle, reg) < 0)
        return -1;

    if (i2cWriteDevice(handle, buf, 2) != 2)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    uint16_t id = 0;

    if (i2c_read_reg16(handle, REG_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read sensor ID register (I2C error).\n");
        return -1;
    }

    if (id != 0x9080) {
        fprintf(stderr, "Error: unexpected sensor ID 0x%04X (expected 0x9080).\n", id);
        return -1;
    }

    /* Configure: 1 Hz sample rate, 16-bit resolution, no oversampling */
    if (i2c_write_reg16(handle, REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error: failed to write CONFIG register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure (kPa) from the MLX90817                             */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure)
{
    uint16_t raw = 0;

    if (i2c_read_reg16(handle, REG_PRESSURE, &raw) < 0) {
        fprintf(stderr, "Error: failed to read pressure register.\n");
        return -1;
    }

    *pressure = (float)((int16_t)raw) / 100.0f;   /* 16-bit signed, 1 LSB = 0.0625 kPa */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a pressure reading                                           */
/* ------------------------------------------------------------------ */
static int log_pressure(FILE *fp, float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed.\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush() failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus ------------------------------------------------ */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ------------------------------------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header.\n");
            fclose(g_log_file);
            i2cClose(g_i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    /* --- sensor init ------------------------------------------------- */
    if (initialize_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("MLX90817 logger started. Logging to '%s' every %d s. "
           "Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_PERIOD);

    /* --- main loop ---------------------------------------------------- */
    int consec_err = 0;

    while (g_running) {
        float pressure = 0.0f;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            consec_err = 0;
            if (log_pressure(g_log_file, pressure) < 0) {
                fprintf(stderr, "Error: failed to log pressure reading.\n");
            }
        } else {
            consec_err++;
            fprintf(stderr, "Warning: I2C read error (%d/%d).\n",
                    consec_err, MAX_CONSEC_ERR);
            if (consec_err >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Error: %d consecutive I2C failures. "
                                "Sensor may be absent or bus error.\n",
                        consec_err);
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    /* --- graceful shutdown ------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

