/*
 * Raspberry Pi 4 Model B — MLX90834 pressure sensor via ADS1115 ADC bridge
 *
 * Wiring:
 *   MLX90834 VDD  -> 3.3 V (Pin 1)
 *   MLX90834 GND  -> GND   (Pin 9)
 *   MLX90834 SDA  -> GPIO2 / I2C SDA (Pin 3)
 *   MLX90834 SCL  -> GPIO3 / I2C SCL (Pin 5)
 *   MLX90834 AOUT -> ADS1115 AOUT (AIN0)
 *   MLX90834 TOUT -> ADS1115 TOUT (AIN1)
 *   MLX90834 GND  -> GND
 *   Warning LED  -> GPIO17 (Pin 11) via 330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90834_ads1115 mlx90834_ads1115.c -lpigpio -lrt
 * Run:    sudo ./mlx90834_ads1115
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1          /* /dev/i2c-1 on RPi 4 */
#define ADS1115_ADDR         0x48       /* Default I2C address (ADDR pin tied to GND) */
#define ADS1115_REG_CONV     0x00       /* Conversion register */
#define ADS1115_REG_CONFIG   0x01       /* Config register */
#define ADS1115_CONFIG_OS    0x8000     /* Operational status / single-shot start */
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000 /* AIN0 single-ended vs GND */
#define ADS1115_CONFIG_MUX_AIN1_GND 0x5000 /* AIN1 single-ended vs GND */
#define ADS1115_CONFIG_PGA_4_096V  0x0200 /* +/-4.096 V range */
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 /* Single-shot mode */
#define ADS1115_CONFIG_DR_128SPS  0x0080 /* 128 SPS */
#define ADS1115_CONFIG_CQUE_NONE  0x0003 /* Disable comparator */
#define ADS1115_CONFIG_DEFAULT   (ADS1115_CONFIG_OS | ADS1115_CONFIG_MUX_AIN0_GND | \
                                 ADS1115_CONFIG_MUX_AIN1_GND | ADS1115_CONFIG_PGA_4_096V | \
                                 ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | \
                                 ADS1115_CONFIG_CQUE_NONE)

#define LED_GPIO              17
#define PRESSURE_THRESHOLD    105.0f   /* kPa — warning when exceeded */
#define SAMPLE_PERIOD_US      1000000 /* 1 second */
#define MAX_RETRIES           3

/* ADS1115 16-bit register addresses */
#define ADS1115_REG_CONFIG_A  0x01
#define ADS1115_REG_CONFIG_B  0x02
#define ADS1115_REG_CONFIG_C  0x03
#define ADS1115_REG_CONFIG_D  0x04
#define ADS1115_REG_CONFIG_E  0x05
#define ADS1115_REG_CONFIG_F  0x06
#define ADS1115_REG_CONFIG_G  0x07
#define ADS1115_REG_CONFIG_H  0x08
#define ADS1115_REG_CONFIG_I  0x09
#define ADS1115_REG_CONFIG_J  0x0A
#define ADS1115_REG_CONFIG_K  0x0B
#define ADS1115_REG_CONFIG_L  0x0C
#define ADS1115_REG_CONFIG_M  0x0D
#define ADS1115_REG_CONFIG_N  0x0E
#define ADS1115_REG_CONFIG_O  0x0F
#define ADS1115_REG_CONFIG_P  0x10
#define ADS1115_REG_CONFIG_Q  0x11
#define ADS1115_REG_CONFIG_R  0x12
#define ADS1115_REG_CONFIG_S  0x13
#define ADS1115_REG_CONFIG_T  0x14
#define ADS1115_REG_CONFIG_U  0x15
#define ADS1115_REG_CONFIG_V  0x16
#define ADS1115_REG_CONFIG_W  0x17
#define ADS1115_REG_CONFIG_X  0x18
#define ADS1115_REG_CONFIG_Y  0x19
#define ADS1115_REG_CONFIG_Z  0x1A
#define ADS1115_REG_CONFIG_AA 0x1B
#define ADS1115_REG_CONFIG_AB 0x1C
#define ADS1115_REG_CONFIG_AC 0x1D
#define ADS1115_REG_CONFIG_AD 0x1E
#define ADS1115_REG_CONFIG_AE 0x1F

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers --------------------------- */
static int ads1115_write_reg(uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(uint8_t reg, uint16_t *val)
{
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int ads1115_init(void)
{
    /* Write config: OS=1 (start), MUX_AIN0_GND, MUX_AIN1_GND, PGA=+/-4.096V, MODE=1, DR=128 SPS, CQUE=0 */
    if (ads1115_write_reg(ADS1115_REG_CONFIG_A, ADS1115_CONFIG_DEFAULT) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_B, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_C, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_D, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_E, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_F, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_G, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_H, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_I, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_J, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_K, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_L, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_M, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_N, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_O, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_P, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_Q, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_R, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_S, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_T, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_U, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_V, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_W, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_X, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_Y, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_Z, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_AA, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_AB, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_AC, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_AD, 0x0000) < 0)
        return -1;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_AE, 0x0000) < 0)
        return -1;

    /* Wait for conversion to complete (OS bit reads 1) */
    for (int i = 0; i < 100; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(ADS1115_REG_CONFIG_A, &cfg) < 0)
            return -1;
        if (cfg & ADS1115_CONFIG_OS)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(cfg & ADS1115_CONFIG_OS)) {
        fprintf(stderr, "Error: ADS1115 conversion timeout\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_pressure_kPa(float *pressure)
{
    uint16_t cfg;
    if (ads1115_read_reg(ADS1115_REG_CONFIG_A, &cfg) < 0)
        return -1;

    /* Trigger a new conversion on AIN0 */
    cfg |= ADS1115_CONFIG_OS;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_A, cfg) < 0)
        return -1;

    for (int i = 0; i < 100; i++) {
        uint16_t cfg_read;
        if (ads1115_read_reg(ADS1115_REG_CONFIG_A, &cfg_read) < 0)
            return -1;
        if (cfg_read & ADS1115_CONFIG_OS)
            break;
        gpioDelay(1000);
    }
    if (!(cfg_read & ADS1115_CONFIG_OS)) {
        fprintf(stderr, "Error: ADS1115 pressure conversion timeout\n");
        return -1;
    }

    /* Read conversion register (16-bit, two's complement) */
    uint16_t raw;
    if (ads1115_read_reg(ADS1115_REG_CONV, &raw) < 0)
        return -1;

    /* PGA = +/-4.096 V -> 1 bit = 125 uV */
    int16_t signed_raw = (int16_t)raw;
    *pressure = (float)signed_raw * 0.000125f; /* kPa */
    return 0;
}

static int ads1115_read_temperature_C(float *temperature)
{
    uint16_t cfg;
    if (ads1115_read_reg(ADS1115_REG_CONFIG_A, &cfg) < 0)
        return -1;

    /* Trigger a new conversion on AIN1 */
    cfg |= ADS1115_CONFIG_OS;
    if (ads1115_write_reg(ADS1115_REG_CONFIG_A, cfg) < 0)
        return -1;

    for (int i = 0; i < 100; i++) {
        uint16_t cfg_read;
        if (ads1115_read_reg(ADS1115_REG_CONFIG_A, &cfg_read) < 0)
            return -1;
        if (cfg_read & ADS1115_CONFIG_OS)
            break;
        gpioDelay(1000);
    }
    if (!(cfg_read & ADS1115_CONFIG_OS)) {
        fprintf(stderr, "Error: ADS1115 temperature conversion timeout\n");
        return -1;
    }

    /* Read conversion register (16-bit, two's complement) */
    uint16_t raw;
    if (ads1115_read_reg(ADS1115_REG_CONV, &raw) < 0)
        return -1;

    /* PGA = +/-4.096 V -> 1 bit = 125 uV */
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.000125f; /* °C */
    return 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init() < 0) {
        fprintf(stderr, "Error: ADS1115 initialisation failed\n");
