#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define ADC_MAX_VALUE 32767.0f
#define ADC_VREF 4.096f
#define ADC_RESOLUTION 16.0f
#define MIN_PRESSURE 0.0f
#define MAX_PRESSURE 100.0f
#define ERROR_VALUE -999.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, uint16_t *raw_value) {
    char config[3];
    char data[2];
    int result;

    config[0] = 0x01;
    config[1] = 0xC0;
    config[2] = 0x83;

    result = i2cWriteDevice(handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float convert_to_pressure(uint16_t raw_value) {
    float voltage = ((float)raw_value / ADC_MAX_VALUE) * ADC_VREF;
    return voltage * 100.0f;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_value = 0;
