#define ADC_MAX_VALUE 32767.0f
#define ADC_VREF 4.096f
#define ADC_RESOLUTION 16.0f
#define MIN_PRESSURE 0.0f
#define MAX_PRESSURE 100.0f
#define ERROR_VALUE -999.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, uint16_t *raw_value) {
    char config[3];
    char data[2];
    int result;

    config[0] = 0x01;
    config[1] = 0xC0;
    config[2] = 0x83;

    result = i2cWriteDevice(handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    result = i2cReadDevice(handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float convert_to_pressure(uint16_t raw_value) {
    float voltage = ((float)raw_value / ADC_MAX_VALUE) * ADC_VREF;
    return voltage * 100.0f;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

