#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity threshold exceeded. Current humidity: %.2f%%"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3208(int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x00, (char)((0x08 | channel) << 4), 0x00};
    char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *value = ((rx_buf[1] & 0x0F) << 8) | (rx_buf[2] & 0xFF);
    return 0;
}

static float calculate_humidity(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    float humidity = 100.0 - ((float)adc_value / 4095.0) * 100.0;

    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

static float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -273.15;
    }

    float temperature = 25.0 + ((float)adc_value / 4095.0) * 150.0;

    if (temperature < -40.0) temperature = -40.0;
    if (temperature > 125.0) temperature = 125.0;

    return temperature;
}

static int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

static int send_email_alert(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time for email\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[256];
    snprintf(command, sizeof(command), "ssmtp %s", EMAIL_RECIPIENT);
    snprintf(command + strlen(command), sizeof(command) - strlen(command), " Subject: %s\n\nEmail Body: %s\nTimestamp: %s\nHumidity: %.2f%%\n", EMAIL_SUBJECT, EMAIL_BODY, timestamp, humidity);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to execute ssmtp command\n");
        return -1;
    }

    if (pclose(fp) != 0) {
        fprintf(stderr, "Failed to send email\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return 1;
    }

    printf("Starting humidity monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value;
        if (read_mcp3208(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (humidity < 0.0 || temperature < -273.15) {
            fprintf(stderr, "Invalid sensor readings\n");
            sleep(1);
            continue;
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

