/*
 * Raspberry Pi 5 - TMP36 Temperature Logger via MCP3208 ADC
 *
 * Hardware:
 *   - TMP36 analog temperature sensor (Vout -> MCP3208 CH0)
 *   - MCP3208 12-bit ADC on SPI0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - TMP36 VDD/VREF tied to 3.3V
 *
 * Build: gcc -O2 -Wall -o temp_logger temp_logger.c -lpigpio -lrt
 * Run:   sudo ./temp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define MCP3208_CHANNEL  0
#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_INTERVAL 1.0
#define TEMP_MIN_C      (-40.0f)
#define TEMP_MAX_C      (125.0f)

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3208 single-ended read (3-byte transfer):
 *   tx[0] = 0x06  (start bit + single-ended + channel)
 *   tx[1] = 0x00  (don't care)
 *   tx[2] = 0x00  (don't care)
 * Result: 12-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3208_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x06, 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;  /* 0..4095 */
}

/* ------------------------------------------------------------------ */
/* Temperature conversion                                               */
/* ------------------------------------------------------------------ */
static float adc_to_temperature_c(int adc_value)
{
    /* TMP36: 10 mV/°C output, VREF = 3.3V */
    float voltage = (float)adc_value / 4095.0f * 3.3f;
    return (voltage - 0.5f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    /* Check if file exists / is empty to decide on header */
    int write_header = 0;
    FILE *check = fopen(LOG_FILE, "r");
    if (check) {
        if (fseek(check, 0, SEEK_END) == 0) {
            long sz = ftell(check);
            if (sz == 0) {
                write_header = 1;
            }
            fclose(check);
        } else {
            fclose(check);
        }
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (write_header) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = mcp3208_read(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = adc_to_temperature_c(adc_value);

        if (temperature < TEMP_MIN_C || temperature > TEMP_MAX_C) {
            fprintf(stderr, "Temperature out of range: %.2f C (ADC=%d)\n",
                    temperature, adc_value);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_temperature(temperature);
        printf("Temperature: %.2f C (ADC=%d)\n", temperature, adc_value);

        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

