/*
 * Raspberry Pi Zero W - Si1172-A30-GMR Heart Rate / SpO2 Logger
 *
 * Reads raw PPG samples from a Si1172-A30-GMR optical heart-rate sensor
 * on I2C bus 1 and logs them to biometric_log.csv.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples into true heart-rate and SpO2 values.  This program logs the
 * raw 16-bit IR and RED ADC values as proxy values for HR and SpO2.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hr_logger hr_logger.c -lpigpio -lrt
 * Run:    sudo ./hr_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1172-A30-GMR register map (16-bit addresses, 8-bit data) ---- */
#define SI1172_REG_HW_KEY          0x00
#define SI1172_REG_MEAS_RATE       0x08
#define SI1172_REG_ALS_IR_DATA0    0x22
#define SI1172_REG_ALS_IR_DATA1    0x23
#define SI1172_REG_ALS_RED_DATA0   0x24
#define SI1172_REG_ALS_RED_DATA1   0x25

#define SI1172_HW_KEY_VAL          0x17
#define SI1172_MEAS_RATE_1_S       0x01   /* 1 sample per second */

#define I2C_BUS                   1
#define LOG_FILE                  "biometric_log.csv"
#define SAMPLE_PERIOD_US          1000000  /* 1 second */
#define MAX_CONSECUTIVE_ERRORS    10

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, val, rc);
    }
    return rc;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    uint8_t hw_key = 0;

    if (i2c_read_reg8(handle, SI1172_REG_HW_KEY, &hw_key) != 0) {
        fprintf(stderr, "[Sensor] Cannot read HW_KEY - sensor may be absent\n");
        return -1;
    }

    if (hw_key != SI1172_HW_KEY_VAL) {
        fprintf(stderr, "[Sensor] HW_KEY mismatch: got 0x%02X, expected 0x%02X\n",
                hw_key, SI1172_HW_KEY_VAL);
        return -1;
    }

    if (i2c_write_reg8(handle, SI1172_REG_MEAS_RATE, SI1172_MEAS_RATE_1_S) != 0) {
        fprintf(stderr, "[Sensor] Failed to set measurement rate\n");
        return -1;
    }

    printf("[Sensor] Si1172 initialized (HW_KEY=0x%02X, meas_rate=1s)\n", hw_key);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw PPG samples                                              */
/* ------------------------------------------------------------------ */
static int read_ppg_samples(int handle, uint16_t *ir, uint16_t *red)
{
    uint8_t ir_lo, ir_hi, red_lo, red_hi;

    if (i2c_read_reg8(handle, SI1172_REG_ALS_IR_DATA0, &ir_lo) != 0)
        return -1;
    if (i2c_read_reg8(handle, SI1172_REG_ALS_IR_DATA1, &ir_hi) != 0)
        return -1;
    if (i2c_read_reg8(handle, SI1172_REG_ALS_RED_DATA0, &red_lo) != 0)
        return -1;
    if (i2c_read_reg8(handle, SI1172_REG_ALS_RED_DATA1, &red_hi) != 0)
        return -1;

    *ir = ((uint16_t)ir_hi << 8) | ir_lo;
    *red = ((uint16_t)red_hi << 8) | red_lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a sample row                                                    */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, uint16_t ir, uint16_t red,
                       int hr, int spo2, int error_flag)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%d,%d,%d\n",
            (long)now, ir, red, hr, spo2, error_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t ir = 0, red = 0;
    int      hr = 0, spo2 = 0;
    int      error_count = 0;
    int      consecutive_errors = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x79, 0);  /* Si1172 default addr */
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[Sensor] Initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[File] fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,HR_bpm,SpO2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[Sig] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[App] Logging to %s. Press Ctrl-C to stop.\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        if (read_ppg_samples(g_i2c_handle, &ir, &red) == 0) {
            consecutive_errors = 0;
            error_count = 0;

            /* NOTE: Si1172 requires proprietary conversion.
             *  We log the raw IR and RED values as proxy values for HR and SpO2. */
            hr = (int)ir;
            spo2 = (int)red;

            log_sample(g_log_file, ir, red, hr, spo2, 0);
        } else {
            consecutive_errors++;
            error_count++;

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "[App] %d consecutive I2C errors - "
                                "sensor may be absent or bus fault\n",
                        consecutive_errors);
                log_sample(g_log_file, 0, 0, 0, 0, 2);  /* error_flag=2 */
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[App] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

