    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature) {
    if (i2c_write_cmd(fd, CMD_READ_RESULT) < 0) return -1;
    usleep(10000);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0) return -1;

    *pressure    = (int32_t)((buf[0] << 8) | buf[1]);
    *temperature = (int32_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static void calibrate_sensor(int32_t raw_pressure, int32_t raw_temperature,
                             float *pressure, float *temperature) {
    const float c0 = 0.0f, c1 = 0.0f, c00 = 0.0f, c10 = 0.0f, c01 = 0.0f, c11 = 0.0f;
    const float p0 = 0.0f, p1 = 0.0f, t0 = 0.0f, t1 = 0.0f;

    *pressure    = c0 + c1 * (float)raw_pressure;
    *temperature = c0 + c1 * (float)raw_temperature;

    float p_comp = p0 + p1 * (float)raw_pressure;
    float t_comp = t0 + t1 * (float)raw_temperature;

    if (c00 != 0.0f) {
        float p_comp2 = c00 + c10 * (float)raw_temperature;
        float t_comp2 = c01 + c11 * (float)raw_temperature;
        *pressure    = p_comp2;
        *temperature = t_comp2;
    }
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
        fflush(log_file);
    }

    printf("Starting ICP-10125 environmental monitoring...\n");

    while (running) {
        int32_t raw_pressure, raw_temperature;

        if (read_sensor_data(i2c_fd, &raw_pressure, &raw_temperature) < 0) {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float pressure, temperature;
        calibrate_sensor(raw_pressure, raw_temperature, &pressure, &temperature);

        log_data(log_file, pressure, temperature);
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

