#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define NUM_CHANNELS 2
#define SAMPLE_RATE 44100
#define DURATION 1
#define NUM_SAMPLES (SAMPLE_RATE * DURATION)

#define GAIN_MIN 0
#define GAIN_MAX 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int apply_gain(int *audio, int gain) {
    if (gain < GAIN_MIN || gain > GAIN_MAX) {
        fprintf(stderr, "Invalid gain %d (must be %d-%d)\n", gain, GAIN_MIN, GAIN_MAX);
        return -1;
    }

    int offset = (gain - GAIN_MIN) * 1000 / (GAIN_MAX - GAIN_MIN);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        audio[i] += offset;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int spi_fd = -1;
    int *audio[NUM_CHANNELS] = {0};
    int opt;

    while ((opt = getopt(argc, argv, "g:")) != -1) {
        switch (opt) {
            case 'g':
                int gain = atoi(optarg);
                if (gain < GAIN_MIN || gain > GAIN_MAX) {
                    fprintf(stderr, "Gain %d out of range\n", gain);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-g gain]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spi_init(&spi_fd) < 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Sampling audio from two MP23ABS1 microphones...\n");
    printf("Gain: %d\n", gain);
    printf("Press Ctrl+C to stop.\n");

    for (int i = 0; i < NUM_SAMPLES && running; i++) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int val = read_mcp3008(spi_fd, ch);
            if (val < 0) {
                fprintf(stderr, "Error reading channel %d\n", ch);
                running = 0;
                break;
            }
            audio[ch] = val;
        }

        if (apply_gain(audio, gain) < 0) {
            running = 0;
            break;
        }

        printf("%d", audio[0]);
        for (int ch = 1; ch < NUM_CHANNELS; ch++) {
            printf(", %d", audio[ch]);
        }
        printf("\n");
        fflush(stdout);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();

    return 0;
}

