#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_PIN     17
#define WATER_LEVEL_THRESHOLD_HIGH  75.0f
#define WATER_LEVEL_THRESHOLD_LOW   70.0f
#define SAMPLE_INTERVAL_US  5000000
#define LOOP_SLEEP_US      100000
#define JSON_FILE         "water_levels.json"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = value;
    return 0;
}

static float calculate_water_level_percentage(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_water_level(float percentage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_json_fp, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n",
            timestamp, percentage);
    fflush(g_json_fp);
}

static void control_led(float water_level)
{
    static int led_state = 0;
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        if (led_state == 0) {
            gpioWrite(LED_PIN, 1);
            led_state = 1;
        }
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
        if (led_state == 1) {
            gpioWrite(LED_PIN, 0);
            led_state = 0;
        }
    }
}

static void cleanup(void)
{
    if (g_json_fp) {
        fprintf(g_json_fp, "]\n");
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    g_json_fp = fopen(JSON_FILE, "w");
    if (!g_json_fp) {
        fprintf(stderr, "Failed to open %s for writing\n", JSON_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_json_fp, "[\n");
    fflush(g_json_fp);

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(0, &adc_value) != 0) {
            fprintf(stderr, "Skipping reading due to SPI error\n");
            gpioDelay(LOOP_SLEEP_US);
            continue;
        }

        float water_level = calculate_water_level_percentage(adc_value);
        log_water_level(water_level);
        control_led(water_level);

        printf("Water Level: %.2f%%\n", water_level);
        fflush(stdout);

        gpioDelay(LOOP_SLEEP_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

