#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/stat.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIB 300
#define DEFAULT_MAX_CALIB 800
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "msmtprc"
#define DEFAULT_SPI_SPEED 500000
#define DEFAULT_SPI_MODE 0
#define DEFAULT_SPI_BITS_PER_WORD 8

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_adc_channel = DEFAULT_ADC_CHANNEL;
static int g_min_calib = DEFAULT_MIN_CALIB;
static int g_max_calib = DEFAULT_MAX_CALIB;
static int g_moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int g_logging_interval = DEFAULT_LOGGING_INTERVAL;
static char *g_recipient_email = DEFAULT_RECIPIENT_EMAIL;
static char *g_msmtp_config = DEFAULT_MSMTP_CONFIG;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_adc(int channel, int *out_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = DEFAULT_SPI_SPEED,
        .bits_per_word = DEFAULT_SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int calibrate_moisture(int raw_value) {
    if (raw_value < g_min_calib) raw_value = g_min_calib;
    if (raw_value > g_max_calib) raw_value = g_max_calib;
    return raw_value;
}

static int log_moisture_data(int raw_value, int calibrated_value, int moisture_percent) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open plant_data.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, moisture_percent) < 0) {
        fprintf(stderr, "Failed to write to plant_data.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close plant_data.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int send_email_alert(int moisture_percent) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level is below threshold. Raw: %d, Calibrated: %d, Moisture: %d%%\" | msmtp -t %s",
        0, 0, moisture_percent, g_recipient_email);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Email command buffer too small\n");
        return -1;
    }

    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Failed to execute msmtp: %s\n", strerror(errno));
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "pclose failed: %s\n", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

static int load_msmtp_config(const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open msmtp config file %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "recipient", 9) == 0) {
            if (sscanf(line, "recipient = %255s", g_recipient_email) != 1) {
                fprintf(stderr, "Invalid recipient in msmtp config\n");
                fclose(fp);
                return -1;
            }
        }
    }

    fclose(fp);
    return 0;
}

static int initialize_spi(int channel, int speed, int mode, int bits) {
    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d", channel);

    g_spi_fd = open(spi_device, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open SPI device %s: %s\n", spi_device, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:a:t:i:e:")) != -1) {
        switch (opt) {
            case 'c': g_adc_channel = atoi(optarg); break;
            case 'a': g_min_calib = atoi(optarg); break;
            case 'A': g_max_calib = atoi(optarg); break;
            case 't': g_moisture_threshold = atoi(optarg); break;
            case 'i': g_logging_interval = atoi(optarg); break;
            case 'e': g_recipient_email = strdup(optarg); break;
            case 'M': g_msmtp_config = strdup(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-c channel] [-a min_calib] [-A max_calib] [-t threshold] [-i interval] [-e recipient] [-M msmtp_config]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_recipient_email == NULL) {
        fprintf(stderr, "Recipient email must be specified\n");
        return EXIT_FAILURE;
    }

    if (g_msmtp_config == NULL) {
        fprintf(stderr, "MSMTP configuration file must be specified\n");
        return EXIT_FAILURE;
    }

    if (load_msmtp_config(g_msmtp_config) != 0) {
        fprintf(stderr, "Failed to load msmtp configuration\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_spi(DEFAULT_SPI_CHANNEL, DEFAULT_SPI_SPEED, 0, DEFAULT_SPI_BITS_PER_WORD) != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    printf("Plant monitoring started. Logging every %d seconds.\n", g_logging_interval);
    printf("SPI channel: %d, ADC channel: %d, Min: %d, Max: %d, Threshold: %d%%\n",
           g_adc_channel, g_min_calib, g_max_calib, g_moisture_threshold);
    printf("Logging to plant_data.txt, Email to: %s\n", g_recipient_email);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw_value = 0;
        if (read_adc(g_adc_channel, &raw_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            int calibrated_value = calibrate_moisture(raw_value);
            int moisture_percent = (calibrated_value * 100) / (g_max_calib - g_min_calib);

            if (log_moisture_data(raw_value, calibrated_value, moisture_percent) != 0) {
                fprintf(stderr, "Failed to log moisture data\n");
            }

            if (moisture_percent < g_moisture_threshold) {
                if (send_email_alert(moisture_percent) != 0) {
                    fprintf(stderr, "Failed to send email alert\n");
                }
            }
        }

        for (int i = 0; i < g_logging_interval && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

