    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:a:t:i:e:")) != -1) {
        switch (opt) {
            case 'c': g_adc_channel = atoi(optarg); break;
            case 'a': g_min_calib = atoi(optarg); break;
            case 'A': g_max_calib = atoi(optarg); break;
            case 't': g_moisture_threshold = atoi(optarg); break;
            case 'i': g_logging_interval = atoi(optarg); break;
            case 'e': g_recipient_email = strdup(optarg); break;
            case 'M': g_msmtp_config = strdup(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-c channel] [-a min_calib] [-A max_calib] [-t threshold] [-i interval] [-e recipient] [-M msmtp_config]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_recipient_email == NULL) {
        fprintf(stderr, "Recipient email must be specified\n");
        return EXIT_FAILURE;
    }

    if (g_msmtp_config == NULL) {
        fprintf(stderr, "MSMTP configuration file must be specified\n");
        return EXIT_FAILURE;
    }

    if (load_msmtp_config(g_msmtp_config) != 0) {
        fprintf(stderr, "Failed to load msmtp configuration\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_spi(DEFAULT_SPI_CHANNEL, DEFAULT_SPI_SPEED, 0, DEFAULT_SPI_BITS_PER_WORD) != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    printf("Plant monitoring started. Logging every %d seconds.\n", g_logging_interval);
    printf("SPI channel: %d, ADC channel: %d, Min: %d, Max: %d, Threshold: %d%%\n",
           g_adc_channel, g_min_calib, g_max_calib, g_moisture_threshold);
    printf("Logging to plant_data.txt, Email to: %s\n", g_recipient_email);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw_value = 0;
        if (read_adc(g_adc_channel, &raw_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            int calibrated_value = calibrate_moisture(raw_value);
            int moisture_percent = (calibrated_value * 100) / (g_max_calib - g_min_calib);

            if (log_moisture_data(raw_value, calibrated_value, moisture_percent) != 0) {
                fprintf(stderr, "Failed to log moisture data\n");
            }

            if (moisture_percent < g_moisture_threshold) {
                if (send_email_alert(moisture_percent) != 0) {
                    fprintf(stderr, "Failed to send email alert\n");
                }
            }
        }

        for (int i = 0; i < g_logging_interval && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

