#define ADC_MAX_VALUE  3.3f
#define ADC_STUCK_MIN  0.0f
#define ADC_STUCK_MAX  3.3f
#define ADC_OUT_OF_RANGE 32767.0f /* 2^15 - 1 */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0):
     *   Byte 0: 0x01  (Start bit)
     *   Byte 1: (0x08 | channel) << 4  (Single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (Don't care, clocks out low 2 bits)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..4 undefined, bit 3 = null, bits 2..0 = MSB of result
     *   Byte 2: bits 7..0 = LSB of result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3): %s\n",
