    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("MLX90823 Pressure Sensor via MCP3008\n");
    printf("SPI0 CE0 @ %d Hz, ADC CH0\n", SPI_SPEED);
    printf("Press Ctrl+C to exit\n\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read ADC value\n");
        } else {
            float voltage = (float)adc_value * ADC_VREF / (float)ADC_MAX_VALUE;

            sensor_data_t data;
            data.timestamp = time(NULL);
            data.adc_value = adc_value;
            data.voltage = voltage;
            data.valid = true;

            if (validate_sensor_data(&data)) {
                char ts[32];
                get_timestamp(ts, sizeof(ts));

                if (data.valid) {
                    printf("[%s] ADC: %4d  Voltage: %.3f V\n",
                           ts, data.adc_value, data.voltage);
                } else {
                    printf("[%s] ADC: %4d  Voltage: %.3f V  (out of range)\n",
                           ts, data.adc_value, data.voltage);
                }
            } else {
                fprintf(stderr, "[%s] Sensor data invalid (ADC: %d)\n",
                        ts, adc_value);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

