    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Sensor0,Sensor1,Sensor2,Sensor3\n");
        fflush(csv_file);
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        int sensor_values[NUM_SENSORS];
        int error_flag = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = read_mcp3008(i);
            if (value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                error_flag = 1;
                break;
            }
            sensor_values[i] = value;
        }

        if (!error_flag) {
            if (log_data(csv_file, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nCleaning up and exiting...\n");

    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    return 0;
}

