/*
 * Raspberry Pi 3 Model B+ – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   MCP3008 ADC on SPI bus 0, CE0 (GPIO8), MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11
 *   VH400 analog output -> MCP3008 CH0 (single-ended)
 *   12 V water pump via relay on GPIO17 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on SPI bus 0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define MCP3008_CHANNEL 0         /* VH400 on CH0 */
#define PUMP_GPIO       17         /* BCM 17, active-high relay */

#define LOW_THRESHOLD   300        /* turn pump ON below this */
#define HIGH_THRESHOLD  600        /* turn pump OFF above this */
#define SAMPLE_INTERVAL 5          /* seconds between samples */
#define BUFFER_SIZE     20         /* entries in the circular log */

/* ----------------------------- Data Types ------------------------------- */
typedef struct {
    time_t timestamp;
    int    moisture_level;
    bool   pump_state;          /* true = ON, false = OFF */
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int      head;                /* next write slot */
    int      count;               /* valid entries */
} CircularBuffer;

/* ----------------------------- Globals ---------------------------------- */
static CircularBuffer  log_buffer;
static volatile sig_atomic_t g_running = 1;
static int           g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static int   init_gpio(void);
static int   init_spi(void);
static int   read_mcp3008(int channel);
static void  control_pump(int moisture_level);
static void  log_data(int moisture_level, bool pump_state);
static void  print_log_buffer(void);
static void  cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO Init --------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PUMP_GPIO);
        return -1;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {   /* pump OFF at startup */
        fprintf(stderr, "Error: failed to initialise pump GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

/* ----------------------------- SPI Init --------------------------------- */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- MCP3008 Read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Pump Control ------------------------------- */
static void control_pump(int moisture_level)
{
    bool current_state = (moisture_level < LOW_THRESHOLD);

    if (current_state && !log_buffer.count) {
        /* First sample – pump ON */
        if (gpioWrite(PUMP_GPIO, 1) != 0) {
            fprintf(stderr, "Error: failed to turn pump ON\n");
            return;
        }
        log_data(moisture_level, true);
    } else if (!current_state && log_buffer.count) {
        /* First sample – pump OFF */
        if (gpioWrite(PUMP_GPIO, 0) != 0) {
            fprintf(stderr, "Error: failed to turn pump OFF\n");
            return;
        }
        log_data(moisture_level, false);
    }

    log_data(moisture_level, current_state);
}

/* ----------------------------- Log Entry --------------------------------- */
static void log_data(int moisture_level, bool pump_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    LogEntry *entry = &log_buffer.entries[log_buffer.head];
    entry->timestamp   = now;
    entry->moisture_level = moisture_level;
    entry->pump_state    = pump_state;

    log_buffer.head = (log_buffer.head + 1) % BUFFER_SIZE;
    if (log_buffer.count < BUFFER_SIZE) {
        log_buffer.count++;
    }
}

/* ----------------------------- Print Log Buffer --------------------------- */
static void print_log_buffer(void)
{
    printf("\n--- Moisture Log (%d entries) ---\n", log_buffer.count);
    for (int i = 0; i < log_buffer.count; i++) {
        int idx = (log_buffer.head - log_buffer.count + i + BUFFER_SIZE)
                 % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&log_buffer.entries[idx].timestamp,
                        &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(ts, "----", sizeof(ts));
        }
        printf("[%s] Moisture: %d  Pump: %s\n",
               ts,
               log_buffer.entries[idx].moisture_level,
               log_buffer.entries[idx].pump_state ? "ON" : "OFF");
    }
    printf("-------------------------\n\n");
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is OFF before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil moisture monitor started. Sampling every %d s.\n",
           SAMPLE_INTERVAL);
    printf("Low=%d  High=%d  Pump=GPIO%d  SPI=CE%d\n",
           LOW_THRESHOLD, HIGH_THRESHOLD, PUMP_GPIO, SPI_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "Warning: ADC read failed – skipping sample\n");
        } else {
            control_pump(moisture_level);
            print_log_buffer();
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

