code:
/*
 * MAX30102 SpO2 / Heart-Rate Monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   MAX30102 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MAX30102 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MAX30102 VDD  -> 3.3 V (pin 1)
 *   MAX30102 GND  -> GND  (pin 6)
 *
 * Build: gcc -O2 -Wall -o max30102_monitor max30102_monitor.c -lpigpio -lrt
 * Run:   sudo ./max30102_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MAX30102 register addresses ---- */
#define REG_INTR_STATUS_1   0x00
#define REG_INTR_STATUS_2   0x01
#define REG_INTR_ENABLE_1   0x02
#define REG_INTR_ENABLE_2   0x03
#define REG_FIFO_WR_PTR     0x04
#define REG_OVF_COUNTER     0x05
#define REG_FIFO_RD_PTR     0x06
#define REG_FIFO_DATA       0x07
#define REG_FIFO_CONFIG     0x08
#define REG_MODE_CONFIG     0x09
#define REG_SPO2_CONFIG     0x0A
#define REG_HR_CONFIG       0x0B
#define REG_PART_ID         0x00
#define REG_REV_ID          0x01
#define REG_MFR_ID          0x02
#define REG_ECR             0x3E

#define I2C_BUS             1
#define SAMPLE_PERIOD_US    1000000  /* 1 second */
#define LOG_FILE            "health_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; abort on failure                       */
/* ------------------------------------------------------------------ */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; abort on failure                      */
/* ------------------------------------------------------------------ */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                           */
/* ------------------------------------------------------------------ */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(handle, reg, &lo) < 0) return -1;
    if (reg_read(handle, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MAX30102: verify Part ID, configure FIFOs, mode, etc.  */
/* ------------------------------------------------------------------ */
static int max30102_init(int handle)
{
    uint8_t part_id = 0;

    /* Read Part ID to confirm sensor is present */
    if (reg_read(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read Part ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "[ERROR] Unexpected Part ID 0x%02X (expected 0x15). Wrong sensor?\n",
                part_id);
        return -1;
    }
    printf("[INFO] MAX30102 detected (Part ID = 0x%02X).\n", part_id);

    /* Clear any pending interrupts */
    if (reg_read16(handle, REG_INTR_STATUS_1, NULL) < 0) return -1;
    if (reg_read16(handle, REG_INTR_STATUS_2, NULL) < 0) return -1;

    /* FIFO configuration: 64 samples, 8-bit, no rollover */
    if (reg_write(handle, REG_FIFO_CONFIG, 0x4F) < 0) return -1;

    /* Mode: continuous SpO2 + HR */
    if (reg_write(handle, REG_MODE_CONFIG, 0x03) < 0) return -1;

    /* SpO2 config: 4096 samples average, 60 Hz IR, 4096 samples average */
    if (reg_write(handle, REG_SPO2_CONFIG, 0x3B) < 0) return -1;

    /* HR config: 60 Hz, 4096 samples average */
    if (reg_write(handle, REG_HR_CONFIG, 0x3B) < 0) return -1;

    /* Enable interrupts for both channels */
    if (reg_write(handle, REG_INTR_ENABLE_1, 0x03) < 0) return -1;
    if (reg_write(handle, REG_INTR_ENABLE_2, 0x03) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample: returns 0 on success, -1 on error                   */
/* ------------------------------------------------------------------ */
static int max30102_read(int handle, uint16_t *spo2, uint16_t *hr)
{
    uint8_t fifo_wr_ptr = 0, fifo_rd_ptr = 0;

    /* Wait for FIFO to be full (write pointer >= read pointer) */
    while (fifo_wr_ptr == fifo_rd_ptr) {
        if (reg_read(handle, REG_FIFO_WR_PTR, &fifo_wr_ptr) < 0) return -1;
        if (reg_read(handle, REG_FIFO_RD_PTR, &fifo_rd_ptr) < 0) return -1;
