    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed\n");
        return -1;
    }

    /* SpO2 sample is bytes 0-1, HR sample is bytes 2-3 */
    *spo2 = (uint16_t)((data[0] << 8) | data[1]);
    *hr   = (uint16_t)((data[2] << 8) | data[3]);

    /* Advance pointers so next sample is in FIFO */
    fifo_wr_ptr = (fifo_wr_ptr + 6) & 0x3F;
    fifo_rd_ptr = (fifo_rd_ptr + 6) & 0x3F;

    return 0;
}

