    if (max30102_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] MAX30102 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Monitoring SpO2 and HR. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t spo2 = 0, hr = 0;
        int rc = max30102_read(g_i2c_handle, &spo2, &hr);

        if (rc == 0) {
            time_t now = time(NULL);
