            }
            printf("%s  SpO2=%u  HR=%u\n", ts, spo2, hr);
        } else {
            fprintf(stderr, "[WARN] Read failed — continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
