/*
 * MCP3008 3-channel voltage logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3V3 (pin 1)
 *   MCP3008 VREF -> 3V3 (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> analog input 0
 *   MCP3008 CH1  -> analog input 1
 *   MCP3008 CH2  -> analog input 2
 *
 * Build: gcc -O2 -Wall -o mcp3008_logger mcp3008_logger.c -lpigpio -lrt
 * Run:   sudo ./mcp3008_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define NUM_CHANNELS   3
#define SAMPLE_PERIOD  500000     /* microseconds (500 ms) */
#define LOG_FILE       "analog_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read (3-byte transfer)                       */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d (must be 0–7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (don't care, clocks out low bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in upper nibble
     *   rx[2] = b7 b6 b5 b4 b3 b2 b1 b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int channel, double voltage)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.4f\n", timestamp, channel, voltage) < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- CSV header ------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "Timestamp,Channel,Voltage\n") < 0) {
        fprintf(stderr, "Failed to write CSV header\n");
        fclose(g_log_file);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Failed to flush CSV header\n");
        fclose(g_log_file);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logger started. Logging to '%s' every %d ms.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int value = mcp3008_read(g_spi_handle, ch);
            if (value < 0) {
                fprintf(stderr, "Error reading channel %d; skipping.\n", ch);
                continue;
            }

            double voltage = (double)value / 1023.0 * 3.3;
            if (log_data(g_log_file, ch, voltage) != 0) {
                fprintf(stderr, "Error logging channel %d.\n", ch);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

