#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/time.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define RELAY_GPIO      17
#define DOOR_SENSOR_GPIO 27

#define SAMPLE_INTERVAL_US  200000
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_US 50000
#define RELAY_PULSE_US      3000000
#define LOG_FILE            "/var/log/door_events.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000 | 0x4000 | 0x0000 | 0x0080 | 0x0003;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t config = 0x8000 | 0x4000 | 0x0000 | 0x0080 | 0x0003;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    usleep(10000);
    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &conv) < 0) {
        return -1;
    }
    *raw = (int16_t)conv;
    return 0;
}

static int calibrate_sensor(int fd) {
    int16_t sum = 0;
    printf("Calibrating sensor (taking %d samples)...\n", CALIBRATION_SAMPLES);
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (i2c_read_reg16(fd, ADS1115_REG_CONV, (uint16_t *)(&sum)) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        usleep(CALIBRATION_DELAY_US);
    }
    int16_t avg = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Average raw value: %d\n", avg);
    return avg;
}

static int read_distance(int fd, int16_t *distance) {
    if (ads1115_read_raw(fd, distance) < 0) {
        return -1;
    }
    *distance = (int16_t)distance;
    return 0;
}

static int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm;
    localtime_r(&tv.tv_sec, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, tv.tv_usec / 1000, event);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(g_i2c_fd);
        return 1;
    }

    if (calibrate_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Calibration failed\n");
        close(g_i2c_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        close(g_i2c_fd);
        return 1;
    }
    if (gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set door sensor GPIO %d as input\n", DOOR_SENSOR_GPIO);
        gpioTerminate();
        close(g_i2c_fd);
        return 1;
    }
    if (gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on door sensor GPIO %d\n", DOOR_SENSOR_GPIO);
        gpioTerminate();
        close(g_i2c_fd);
        return 1;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t distance;
        if (read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int distance_raw = (int)distance;
        int distance_mm = distance_raw * 2 - 500;

        if (distance_mm < 300) {
            printf("Distance: %d mm (below threshold)\n", distance_mm);
            if (control_relay(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Relay pulse failed\n");
            } else {
                log_event("door opened");
                sleep(3);
                if (control_relay(RELAY_GPIO, 0) < 0) {
                    fprintf(stderr, "Relay de-energize failed\n");
                } else {
                    log_event("door closed");
                }
            }
        } else {
            log_event("door not opened");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    printf("Cleanup complete.\n");
    return 0;
}

