    if (gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on door sensor GPIO %d\n", DOOR_SENSOR_GPIO);
        gpioTerminate();
        close(g_i2c_fd);
        return 1;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t distance;
        if (read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int distance_raw = (int)distance;
        int distance_mm = distance_raw * 2 - 500;

        if (distance_mm < 300) {
            printf("Distance: %d mm (below threshold)\n", distance_mm);
            if (control_relay(RELAY_GPIO, 1) < 0) {
                fprintf(stderr, "Relay pulse failed\n");
            } else {
                log_event("door opened");
                sleep(3);
                if (control_relay(RELAY_GPIO, 0) < 0) {
                    fprintf(stderr, "Relay de-energize failed\n");
                } else {
                    log_event("door closed");
                }
            }
        } else {
            log_event("door not opened");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_relay(RELAY_GPIO, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    printf("Cleanup complete.\n");
    return 0;
}

