#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define CS0_LINE 8
#define CS1_LINE 7
#define CS2_LINE 25

#define NUM_SENSORS 3
#define LOG_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_lines[NUM_SENSORS];
static const int cs_pins[NUM_SENSORS] = {CS0_LINE, CS1_LINE, CS2_LINE};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
    };

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_set_value(cs_lines[i], 0) < 0) {
            perror("Failed to assert CS line");
            return -1;
        }

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI transfer failed");
            gpiod_line_set_value(cs_lines[i], 1);
            return -1;
        }

        if (gpiod_line_set_value(cs_lines[i], 1) < 0) {
            perror("Failed to deassert CS line");
            return -1;
        }
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Failed to flush log file");
        return -1;
    }

    return 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("Failed to open gpiochip4");
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (cs_lines[i] == NULL) {
            fprintf(stderr, "Failed to get CS line %d\n", cs_pins[i]);
            return -1;
        }

        if (gpiod_line_request_output(cs_lines[i], "mcp3008", 1) < 0) {
            perror("Failed to request CS line as output");
            return -1;
        }
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i] != NULL) {
            gpiod_line_set_value(cs_lines[i], 1);
            gpiod_line_release(cs_lines[i]);
            cs_lines[i] = NULL;
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (setup_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen("soil_moisture_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("Failed to write CSV header");
            cleanup();
            return 1;
        }
        if (fflush(log_file) != 0) {
            perror("Failed to flush CSV header");
            cleanup();
            return 1;
        }
    }

    printf("Soil moisture logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int sensor_values[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_adc(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                read_error = 1;
            }
        }

        if (!read_error) {
            if (log_data(log_file, sensor_values[0], sensor_values[1], sensor_values[2]) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        for (int i = 0; i < LOG_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

