#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define DEFAULT_SPI_SPEED 1000000
#define DEFAULT_SPI_MODE 0
#define DEFAULT_SPI_BITS 8
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_PUMP_GPIO 18
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pump_gpio = DEFAULT_PUMP_GPIO;
static int threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int spi_speed = DEFAULT_SPI_SPEED;
static int spi_mode = DEFAULT_SPI_MODE;
static int spi_bits = DEFAULT_SPI_BITS;
static int spi_channel = DEFAULT_SPI_CHANNEL;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = spi_speed,
        .bits_per_word = spi_bits,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static void control_pump(int on) {
    if (gpioWrite(pump_gpio, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d\n", pump_gpio);
    }
}

static void cleanup(void) {
    control_pump(0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': pump_duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (parse_arguments(argc, argv) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_fd = open(DEFAULT_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEFAULT_SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char mode = spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned char bits = spi_bits;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    unsigned int speed = spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CHANNEL, &spi_channel) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CHANNEL failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(pump_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", pump_gpio);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Irrigation controller started");

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_message("Error reading moisture sensor");
            sleep_interval = DEFAULT_SLEEP_INTERVAL;
            sleep(sleep_interval);
            continue;
        }

        float moisture_pct = (moisture / 1023.0f) * 100.0f;
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture level: %.1f%% (ADC: %d)", moisture_pct, moisture);
        log_message(msg);

        if (moisture_pct < threshold) {
            log_message("Moisture below threshold, activating pump");
            control_pump(1);
            sleep(pump_duration);
            control_pump(0);
            log_message("Pump deactivated");
        }

        sleep(sleep_interval);
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

