/*
 * sound_monitor.c — Raspberry Pi 3 Model B+
 *
 * Samples an Adafruit MAX4466 electret microphone via an MCP3008 ADC
 * on SPI0 (CE0/GPIO8, CLK/GPIO11, MOSI/GPIO10, MISO/GPIO9)
 * and logs peaks exceeding a dynamic threshold to
 * /var/log/sound_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c -lpigpio -lrt
 * Run:    sudo ./sound_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define LOG_FILE       "/var/log/sound_events.log"
#define SAMPLE_PERIOD_US 10000    /* 10 ms between samples */
#define PEAK_THRESHOLD  500       /* raw ADC counts */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int spi_handle, int channel);
static int  detect_peak(int adc_value);
static void log_event(int adc_value);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error.
 *
 * MCP3008 SPI protocol (3-byte transfer, Mode 0):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (clock out low bits)
 * Result: bits 9..0 are in the low 2 bits of byte 1 and all 8 bits of byte 2.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/*
 * Detect whether the current ADC value exceeds the current peak.
 * Returns 1 if a new peak is detected, 0 otherwise.
 */
static int detect_peak(int adc_value)
{
    if (adc_value > PEAK_THRESHOLD) {
        return 1;
    }
    return 0;
}

/*
 * Append a timestamped event line to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_event(int adc_value)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s ADC=%d\n", ts, adc_value) < 0) {
        fprintf(stderr, "fprintf() to log failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    return 0;
}

/*
 * Signal handler — set flag so main loop exits cleanly.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: ", LOG_FILE);
        perror("");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Sound monitoring started.  SPI0 CE0 @ %d Hz, ADC ch0, "
           "threshold=%d, log=%s.  Ctrl-C to exit.\n",
           SPI_SPEED, PEAK_THRESHOLD, LOG_FILE);

    /* --- Main loop --- */
    int last_peak = 0;
    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many SPI errors; aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        int peak = detect_peak(adc_value);
        if (peak) {
            if (adc_value != last_peak) {
                if (log_event(adc_value) != 0) {
                    fprintf(stderr, "Failed to log event\n");
                }
                last_peak = adc_value;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

