#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define AIN0_CHANNEL   0x00
#define SAMPLE_PERIOD  100000  /* microseconds (100 ms) */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    /* Dummy read: the PCF8591 returns the result of the *previous* conversion. */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        perror("read(dummy)");
        goto cleanup;
    }

    while (g_running) {
        uint8_t sample;
        ssize_t n = read(fd, &sample, 1);
        if (n != 1) {
            if (n < 0) {
                perror("read(AIN0)");
            } else {
                fprintf(stderr, "read returned %zd byte(s)\n", n);
            }
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)sample);
        fflush(stdout);

        usleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

