    if (read(fd, &dummy, 1) != 1) {
        perror("read(dummy)");
        goto cleanup;
    }

    while (g_running) {
        uint8_t sample;
        ssize_t n = read(fd, &sample, 1);
        if (n != 1) {
            if (n < 0) {
                perror("read(AIN0)");
            } else {
                fprintf(stderr, "read returned %zd byte(s)\n", n);
            }
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)sample);
        fflush(stdout);

        usleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

