/*
 * SS49E Hall-effect sensor monitor with ADS1115 ADC and GPIO27 shutdown.
 *
 * Board:  Raspberry Pi 3 Model B+
 * ADC:    ADS1115 on I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Honeywell SS49E on ADS1115 AIN0
 * GPIO:   BCM 27 (physical pin 13) — motor shutdown output
 *
 * Build:  gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            "/dev/i2c-1"
#define ADS1115_ADDR       0x48
#define ADS1115_REG_CONV   0x00
#define ADS1115_REG_CONFIG 0x01

#define GPIO_SHUTDOWN      27          /* BCM 27, physical pin 13 */
#define SAMPLE_HZ          1
#define SAMPLE_PERIOD_US   (1000000 / SAMPLE_HZ)
#define THRESHOLD_GAUSS     500.0f
#define BUFFER_SIZE        100
#define ADC_VREF           3.3f
#define ADC_MAX_COUNT      32767.0f   /* 16-bit signed, single-ended positive */
#define ADC_MIN_COUNT      (-32768.0f)

/* ADS1115 config: single-shot, AIN0 vs GND, +/-4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE   0x8000      /* OS bit */
#define ADS1115_CFG_MUX    0x4000      /* AIN0 vs GND */
#define ADS1115_CFG_PGA    0x0800      /* +/-4.096 V */
#define ADS1115_CFG_DR     0x0080      /* 128 SPS */
#define ADS1115_CFG_CQUE   0x0003      /* disable comparator */

#define ADC_V_MIN           0.0f
#define ADC_V_MAX           (ADC_VREF * 4.096f / 32768.0f)

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_gpio_initialized = 0;
static int  g_gpio_shutdown = 0;

/* Circular buffer of magnetic field strength (Gauss) */
static float g_buffer[BUFFER_SIZE];
static int   g_buf_idx   = 0;
static int   g_buf_count = 0;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static int  ads1115_init(void);
static int  ads1115_read_raw(int16_t *raw);
static float adc_to_gauss(int16_t raw);
static void buffer_add(float gauss);
static void shutdown_motor(void);
static void cleanup(void);

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers -------------------------- */
static int ads1115_init(void)
{
    uint16_t cfg = ADS1115_CFG_BASE | ADS1115_CFG_MUX |
                   ADS1115_CFG_PGA | ADS1115_CFG_DR |
                   ADS1115_CFG_CQUE;

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "ioctl(I2C_SLAVE, 0x%02X): %s", ADS1115_ADDR, strerror(errno));
        return -1;
    }

    uint8_t cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CONFIG;
    cfg_buf[1] = (uint8_t)(cfg >> 8);
    cfg_buf[2] = (uint8_t)(cfg & 0xFF);

    if (write(g_i2c_fd, cfg_buf, 3) != 3) {
        syslog(LOG_ERR, "ADS1115 config write: %s", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (128 SPS -> ~8 ms; poll up to 100 ms) */
    for (int i = 0; i < 20; i++) {
        uint8_t reg;
        if (read(g_i2c_fd, &reg, 1) != 1) {
            syslog(LOG_ERR, "ADS1115 config read: %s", strerror(errno));
            return -1;
        }
        if ((reg & 0x80) == 0) {
            break;
        }
        usleep(5000);
    }
    return 0;
}

static int ads1115_read_raw(int16_t *raw)
{
    uint8_t reg = ADS1115_REG_CONV;
    if (write(g_i2c_fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "ADS1115 conv reg select: %s", strerror(errno));
        return -1;
    }

    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conv read: %s", strerror(errno));
        return -1;
    }

    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float adc_to_gauss(int16_t raw)
{
    float voltage = (float)raw * (ADC_VREF / ADC_MAX_COUNT);
    if (voltage < ADC_V_MIN) voltage = ADC_V_MIN;
    if (voltage > ADC_V_MAX) voltage = ADC_V_MAX;
    return (voltage / ADC_VREF) * 10000.0f;   /* Gauss = V * 10000 */
}

/* ----------------------------- Circular buffer -------------------------- */
static void buffer_add(float gauss)
{
    g_buffer[g_buf_idx] = gauss;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) g_buf_count++;
}

/* ----------------------------- Motor shutdown ---------------------------- */
static void shutdown_motor(void)
{
    if (g_gpio_initialized) {
        if (gpioWrite(GPIO_SHUTDOWN, 1) < 0) {
            syslog(LOG_ERR, "gpioWrite(GPIO_SHUTDOWN, 1) failed: %s",
                   pigpio_error(gpioRead(GPIO_SHUTDOWN)));
        } else {
            g_gpio_shutdown = 1;
            syslog(LOG_INFO, "Motor shutdown simulated (GPIO %d HIGH).", GPIO_SHUTDOWN);
        }
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_gpio_initialized) {
        if (g_gpio_shutdown) {
            gpioWrite(GPIO_SHUTDOWN, 0);
            g_gpio_shutdown = 0;
        }
        gpioTerminate();
        g_gpio_initialized = 0;
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    closelog();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", pigpio_error(gpioInitialise()));
        closelog();
        return EXIT_FAILURE;
    }
    g_gpio_initialized = 1;

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GPIO %d, OUTPUT) failed: %s",
               GPIO_SHUTDOWN, pigpio_error(gpioGetMode(GPIO_SHUTDOWN)));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    g_gpio_shutdown = 0;

    /* --- I2C init --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "open(%s): %s", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ads1115_init() < 0) {
        syslog(LOG_ERR, "ADS1115 initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall monitor started (threshold %.1f G).", THRESHOLD_GAUSS);

    /* --- Main loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(&raw) < 0) {
            syslog(LOG_WARNING, "ADC read failed; skipping sample.");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = adc_to_gauss(raw);

        buffer_add(gauss);

        if (gauss > THRESHOLD_GAUSS) {
            shutdown_motor();
        }

        syslog(LOG_DEBUG, "Gauss: %.2f  Buffer: %d/%d",
               gauss, g_buf_count, BUFFER_SIZE);

        usleep(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    cleanup();
    return EXIT_SUCCESS;
}

