/*
 * Raspberry Pi Zero W – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (GPIO8), SPI mode 0, 1 MHz
 *   - Vegetronix VH400 analog output -> MCP3008 CH0
 *   - Relay-driven water pump on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define PUMP_GPIO      18         /* BCM 18 */
#define PUMP_DURATION  10         /* seconds */
#define WATERING_THRESHOLD 300
#define SAMPLE_INTERVAL  60       /* seconds */

#define LOG_FILE       "watering_events.txt"

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_state = 0;   /* 0 = off, 1 = on */

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static int  set_pump(int state);
static void log_event(int moisture_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;  /* 0..1023 */
}

/* ----------------------------- Pump control ------------------------------ */
static int set_pump(int state)
{
    if (state != 0 && state != 1) {
        fprintf(stderr, "Invalid pump state %d\n", state);
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", PUMP_GPIO, state);
        return -1;
    }
    g_pump_state = state;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d  Moisture: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    } else {
        fprintf(fp, "(time-error) Moisture: %d\n", moisture_level);
    }

    fclose(fp);
}

/* ----------------------------- Cleanup / signal --------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_pump_state) {
        set_pump(0);
        g_pump_state = 0;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    set_pump(0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Vegetronix VH400 watering monitor started.\n");
    printf("SPI0 CE0 @ 1 MHz, MCP3008 CH0, pump on GPIO18, threshold %d.\n",
           WATERING_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture = read_mcp3008(ADC_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "ADC read error – skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        printf("Moisture level: %d\n", moisture);

        if (moisture < WATERING_THRESHOLD) {
            printf("Moisture below threshold – activating pump.\n");
            if (set_pump(1) == 0) {
                log_event(moisture);

                /* Run pump for PUMP_DURATION seconds, checking for shutdown */
                for (int i = 0; i < PUMP_DURATION && g_running; i++) {
                    sleep(1);
                }

