/*
 * Raspberry Pi SPI + MCP3008 + PWM motor control
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK, BCM 11)
 *   MCP3008 DOUT -> GPIO9  (MISO, BCM 9)
 *   MCP3008 DIN  -> GPIO10 (MOSI, BCM 10)
 *   MCP3008 CS   -> GPIO8  (CE0, BCM 8)
 *   MCP3008 CH0  -> potentiometer wiper (0-3.3 V)
 *   Motor driver PWM -> GPIO18 (BCM 18)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 / GPIO8 (BCM 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define PWM_GPIO       18         /* BCM 18 */
#define PWM_FREQUENCY  1000       /* 1 kHz */
#define PWM_RANGE      1024       /* 0..1023 */
#define SAMPLE_PERIOD  100000     /* 100 ms in microseconds */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static int  read_mcp3008(int channel);
static int  map_adc_to_pwm(int adc_value);
static void set_motor_pwm(int pwm_value);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup / exit ------------------------------ */
static void cleanup(void)
{
    /* Stop PWM output first for safety */
    if (g_spi_handle >= 0) {
        set_motor_pwm(0);
    }

    /* Close SPI handle */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio library */
    gpioTerminate();
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (don't care, clocks out low bits)
 * Result:
 *   rx[1] bits 1..0  -> high byte
 *   rx[2]           -> low byte
 * Returns 0..1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* --------------------------- PWM mapping ----------------------------------- */
static int map_adc_to_pwm(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* 0..1023 -> 0..1023 */
    return adc_value;
}

/* --------------------------- Motor PWM control --------------------------- */
static void set_motor_pwm(int pwm_value)
{
    if (pwm_value < 0)   pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

    /* pigpio hardware PWM: duty cycle 0..PWM_RANGE */
    gpioPWM(PWM_GPIO, pwm_value);
}

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel (CE0, 1 MHz, mode 0) */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM on GPIO18 */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 ADC -> PWM motor control started.\n");
    printf("SPI: CE0 @ %d Hz, ADC ch0, PWM GPIO%d @ %d Hz, range %d\n",
           SPI_SPEED, PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        int pwm_value = map_adc_to_pwm(adc_value);
        set_motor_pwm(pwm_value);

        printf("ADC: %4d  PWM: %3d\n", adc_value, pwm_value);
        fflush(stdout);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

