        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM on GPIO18 */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 ADC -> PWM motor control started.\n");
    printf("SPI: CE0 @ %d Hz, ADC ch0, PWM GPIO%d @ %d Hz, range %d\n",
           SPI_SPEED, PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        int pwm_value = map_adc_to_pwm(adc_value);
        set_motor_pwm(pwm_value);

        printf("ADC: %4d  PWM: %3d\n", adc_value, pwm_value);
        fflush(stdout);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

