#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_TOPIC "pump_control"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_KEEPALIVE 60
#define SAMPLE_INTERVAL 60
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int mqtt_client_id_len = 0;
static char *mqtt_client_id = NULL;
static int mqtt_client_id_copy_len = 0;
static char *mqtt_client_id_copy = NULL;
static int mqtt_keepalive = 0;
static int mqtt_qos = 0;
static int mqtt_ret_code = 0;
static int pump_state = 0;
static int pump_gpio = PUMP_GPIO;
static int moisture_threshold_low = MOISTURE_THRESHOLD_LOW;
static int moisture_threshold_high = MOISTURE_THRESHOLD_HIGH;
static int moisture_level = 0;
static int mqtt_subscribed = 0;
static int mqtt_connected = 0;
static int mqtt_subscribed_ok = 0;
static int mqtt_connect_ok = 0;
static int mqtt_publish_ok = 0;
static int mqtt_subscribe_ok = 0;
static int mqtt_unsubscribe_ok = 0;
static int mqtt_disconnect_ok = 0;
static int mqtt_message_arrived_ok = 0;
static int mqtt_message_arrived = 0;
static int mqtt_message_arrived_len = 0;
static int mqtt_message_arrived_payload_len = 0;
static int mqtt_message_arrived_payload = 0;
static int mqtt_message_arrived_topic_len = 0;
static char *mqtt_message_arrived_topic = NULL;
static int mqtt_message_arrived_payload_copy_len = 0;
static char *mqtt_message_arrived_payload_copy = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel: %d", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int read_moisture_level(void) {
    int raw = read_mcp3008(ADC_CHANNEL);
    if (raw < 0) {
        syslog(LOG_ERR, "Failed to read moisture sensor");
        return -1;
    }
    moisture_level = raw;
    return 0;
}

static int control_pump(int state) {
    if (gpioWrite(pump_gpio, state) != 0) {
        syslog(LOG_ERR, "Failed to write pump GPIO %d", pump_gpio);
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static int mqtt_connect(void) {
    if (mqtt_connected) return 0;

    mqtt_client_id_len = strlen(MQTT_CLIENT_ID);
    mqtt_client_id = malloc(mqtt_client_id_len + 1);
    if (!mqtt_client_id) {
        syslog(LOG_ERR, "MQTT client ID allocation failed: %s", strerror(errno));
        return -1;
    }
    memcpy(mqtt_client_id, MQTT_CLIENT_ID, mqtt_client_id_len);

    mqtt_client_id_copy_len = mqtt_client_id_len;
    mqtt_client_id_copy = malloc(mqtt_client_id_copy_len + 1);
    if (!mqtt_client_id_copy) {
        syslog(LOG_ERR, "MQTT client ID copy allocation failed: %s", strerror(errno));
        free(mqtt_client_id);
        mqtt_client_id = NULL;
        return -1;
    }
    memcpy(mqtt_client_id_copy, mqtt_client_id, mqtt_client_id_copy_len);

    syslog(LOG_INFO, "MQTT client ID: %s", mqtt_client_id_copy);

    int rc = mosquitto_connect(mqtt_client_id_copy, "localhost", 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        free(mqtt_client_id_copy);
        mqtt_client_id_copy = NULL;
        mqtt_client_id = NULL;
        return -1;
    }
    mqtt_connected = 1;
    syslog(LOG_INFO, "MQTT connected");
    return 0;
}

static int mqtt_subscribe(void) {
    if (mqtt_subscribed) return 0;

    int rc = mosquitto_subscribe(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, 1);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc));
        mqtt_subscribed = 1;
        return -1;
    }
    mqtt_subscribed = 1;
    syslog(LOG_INFO, "MQTT subscribed to %s", MQTT_PUMP_TOPIC);
    return 0;
}

static int mqtt_unsubscribe(void) {
    if (!mqtt_subscribed) return 0;
    int rc = mosquitto_unsubscribe(mqtt_client_id_copy, MQTT_PUMP_TOPIC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT unsubscribe failed: %s", mosquitto_strerror(rc));
        mqtt_subscribed = 0;
        return -1;
    }
    mqtt_subscribed = 0;
    syslog(LOG_INFO, "MQTT unsubscribed from %s", MQTT_PUMP_TOPIC);
    return 0;
}

static int mqtt_message_arrived(void *userdata, const struct mosquitto_message *message) {
    (void)userdata;
    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message received");
        return 1;
    }
    if (message->topic[0] != MQTT_PUMP_TOPIC) {
        syslog(LOG_WARNING, "Unexpected MQTT topic: %s", message->topic);
        return 1;
    }

    if (message->payloadlen > 32) {
        syslog(LOG_WARNING, "Payload too large: %d", message->payloadlen);
        return 1;
    }

    mqtt_message_arrived = 1;
    mqtt_message_arrived_len = message->payloadlen;
    mqtt_message_arrived_payload = message->payload;
    mqtt_message_arrived_topic_len = message->topiclen;
    mqtt_message_arrived_topic = message->topic;
    mqtt_message_arrived_payload_copy_len = message->payloadlen;
    mqtt_message_arrived_payload_copy = malloc(mqtt_message_arrived_payloadlen);
    if (mqtt_message_arrived_payload_copy) {
        memcpy(mqtt_message_arrived_payload_copy, message->payload, message->payloadlen);
    }

    syslog(LOG_INFO, "Received message on %s: %s", message->topic, message->payload);

    if (strcmp((char *)mqtt_message_arrived_topic, "pump_on") == 0) {
        if (control_pump(1) == 0) {
            mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1] = '\0';
            if (mqtt_publish_ok) {
                syslog(LOG_INFO, "Received pump_on command, publishing to MQTT");
                int rc = mosquitto_publish(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1], MQTT_PUBLISH_OK);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to control pump");
        }
    } else if (strcmp((char *)mqtt_message_arrived_topic, "pump_off") == 0) {
        if (control_pump(0) == 0) {
            mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1] = '\0';
            if (mqtt_publish_ok) {
                syslog(LOG_INFO, "Received pump_off command, publishing to MQTT");
                int rc = mosquitto_publish(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1], MQTT_PUBLISH_OK);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to control pump");
        }
    } else {
        syslog(LOG_WARNING, "Unknown command: %s", mqtt_message_arrived_topic);
    }

    mqtt_message_arrived = 0;
    mqtt_message_arrived_payload = 0;
    mqtt_message_arrived_topic = NULL;
    mqtt_message_arrived_payload_copy = NULL;
    return 1;
}

static int mqtt_disconnect(void) {
    if (!mqtt_connected) return 0;
    syslog(LOG_INFO, "MQTT disconnect");
    int rc = mosquitto_disconnect(mqtt_client_id_copy);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT disconnect failed: %s", mosquitto_strerror(rc));
    }
    mqtt_connected = 0;
    return 0;
}

static int mqtt_publish(const char *message) {
    if (!mqtt_connected) return -1;
    int rc = mosquitto_publish(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, strlen(message), message, MQTT_PUBLISH_OK);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    mqtt_publish_ok = 1;
    return 0;
}

static int mqtt_message_arrived_callback(void *userdata) {
    (void)userdata;
    return mqtt_message_arrived_callback_func(mqtt_message_arrived_payload, mqtt_message_arrived_payload_copy_len, mqtt_message_arrived_topic, mqtt_message_arrived_topic_len);
}

static int mqtt_message_arrived_callback_func(const char *payload, int payloadlen, const char *topic, int topiclen) {
    (void)payload;
    (void)payloadlen;
    (void)topic;
    (void)topiclen;
    return 1;
}

static void cleanup(void) {
    if (pump_gpio >= 0) {
        control_pump(0);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mqtt_client_id) {
