static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel: %d", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int read_moisture_level(void) {
    int raw = read_mcp3008(ADC_CHANNEL);
    if (raw < 0) {
        syslog(LOG_ERR, "Failed to read moisture sensor");
        return -1;
    }
    moisture_level = raw;
    return 0;
}

static int control_pump(int state) {
    if (gpioWrite(pump_gpio, state) != 0) {
        syslog(LOG_ERR, "Failed to write pump GPIO %d", pump_gpio);
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static int mqtt_connect(void) {
    if (mqtt_connected) return 0;

    mqtt_client_id_len = strlen(MQTT_CLIENT_ID);
    mqtt_client_id = malloc(mqtt_client_id_len + 1);
    if (!mqtt_client_id) {
        syslog(LOG_ERR, "MQTT client ID allocation failed: %s", strerror(errno));
        return -1;
    }
    memcpy(mqtt_client_id, MQTT_CLIENT_ID, mqtt_client_id_len);

    mqtt_client_id_copy_len = mqtt_client_id_len;
    mqtt_client_id_copy = malloc(mqtt_client_id_copy_len + 1);
    if (!mqtt_client_id_copy) {
        syslog(LOG_ERR, "MQTT client ID copy allocation failed: %s", strerror(errno));
        free(mqtt_client_id);
        mqtt_client_id = NULL;
        return -1;
    }
    memcpy(mqtt_client_id_copy, mqtt_client_id, mqtt_client_id_copy_len);

    syslog(LOG_INFO, "MQTT client ID: %s", mqtt_client_id_copy);

    int rc = mosquitto_connect(mqtt_client_id_copy, "localhost", 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        free(mqtt_client_id_copy);
