}

static int mqtt_message_arrived(void *userdata, const struct mosquitto_message *message) {
    (void)userdata;
    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message received");
        return 1;
    }
    if (message->topic[0] != MQTT_PUMP_TOPIC) {
        syslog(LOG_WARNING, "Unexpected MQTT topic: %s", message->topic);
        return 1;
    }

    if (message->payloadlen > 32) {
        syslog(LOG_WARNING, "Payload too large: %d", message->payloadlen);
        return 1;
    }

    mqtt_message_arrived = 1;
    mqtt_message_arrived_len = message->payloadlen;
    mqtt_message_arrived_payload = message->payload;
    mqtt_message_arrived_topic_len = message->topiclen;
    mqtt_message_arrived_topic = message->topic;
    mqtt_message_arrived_payload_copy_len = message->payloadlen;
    mqtt_message_arrived_payload_copy = malloc(mqtt_message_arrived_payloadlen);
    if (mqtt_message_arrived_payload_copy) {
        memcpy(mqtt_message_arrived_payload_copy, message->payload, message->payloadlen);
    }

    syslog(LOG_INFO, "Received message on %s: %s", message->topic, message->payload);

    if (strcmp((char *)mqtt_message_arrived_topic, "pump_on") == 0) {
        if (control_pump(1) == 0) {
            mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1] = '\0';
            if (mqtt_publish_ok) {
                syslog(LOG_INFO, "Received pump_on command, publishing to MQTT");
                int rc = mosquitto_publish(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1], MQTT_PUBLISH_OK);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to control pump");
        }
    } else if (strcmp((char *)mqtt_message_arrived_topic, "pump_off") == 0) {
        if (control_pump(0) == 0) {
            mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1] = '\0';
            if (mqtt_publish_ok) {
                syslog(LOG_INFO, "Received pump_off command, publishing to MQTT");
                int rc = mosquitto_publish(mqtt_client_id_copy, NULL, MQTT_PUMP_TOPIC, mqtt_message_arrived_payload_copy[mqtt_message_arrived_payload_copy_len - 1], MQTT_PUBLISH_OK);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to control pump");
        }
    } else {
        syslog(LOG_WARNING, "Unknown command: %s", mqtt_message_arrived_topic);
    }

    mqtt_message_arrived = 0;
    mqtt_message_arrived_payload = 0;
    mqtt_message_arrived_topic = NULL;
    mqtt_message_arrived_payload_copy = NULL;
    return 1;
}

