/*
 * Raspberry Pi 3 Model B+ – MAX9814 microphone vibration monitor
 *
 * Hardware:
 *   MAX9814  – electret microphone amplifier, channel 0
 *   MCP3008   – 8-channel ADC on SPI0 CE0 (/dev/spidev0.0)
 *   Vibration motors (3 V) – hardware PWM on GPIO17 and GPIO27
 *     (each driven through a transistor: e.g. MOSFET + 330 Ω resistor)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vib_monitor vib_monitor.c -lpigpio -lrt
 *   sudo ./vib_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000          /* 1 MHz – well within MCP3008 limits */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0               /* SPI mode 0 (CPOL=0, CPHA=0) */

#define ADC_CHANNEL       0               /* MCP3008 channel 0 */
#define ADC_MAX_VALUE     1023            /* 10-bit ADC */

#define MOTOR1_PIN        17              /* BCM GPIO17 – PWM0 */
#define MOTOR2_PIN        27              /* BCM GPIO27 – PWM1 */

#define PWM_FREQUENCY     100             /* Hz – typical for 3 V vibration motors */
#define PWM_RANGE         1000            /* duty-cycle resolution */
#define NOISE_THRESHOLD   500             /* samples above this = vibration event */

#define SAMPLE_PERIOD_US  10000           /* 10 ms – well below 100 Hz PWM */
#define LOG_FILE          "vibration_log.txt"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */

static int  spi_init(void);
static int  read_adc(int channel, int *out_value);
static void motor_on(int pin);
static void motor_off(int pin);
static void set_pwm_duty(int pin, int duty_percent);
static void log_event(int motor1_duty, int motor2_duty);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI ---------------------------------------- */

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       – start bit
     *   tx[1] = (0x08 | channel) << 4      – SGL/DIFF=1, D2 D1 D0 = channel
     *   tx[2] = 0x00                       – clock out remaining bits
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ----------------------------- Motor control -------------------------------- */

static void motor_on(int pin)
{
    if (gpioPWM(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "Warning: gpioPWM(%d) failed\n", pin);
    }
}

static void motor_off(int pin)
{
    if (gpioPWM(pin, 0) < 0) {
        fprintf(stderr, "Warning: gpioPWM(%d, 0) failed\n", pin);
    }
}

static void set_pwm_duty(int pin, int duty_percent)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > PWM_RANGE) duty_percent = PWM_RANGE;
    int duty = (duty_percent * PWM_RANGE) / 100;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n", pin, duty);
    }
}

/* ----------------------------- Logging ------------------------------------- */

static void log_event(int motor1_duty, int motor2_duty)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d – Motor1: %d%%, Motor2: %d%%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                motor1_duty, motor2_duty);
    } else {
        fprintf(fp, "(timestamp error) – Motor1: %d%%, Motor2: %d%%\n",
                motor1_duty, motor2_duty);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing log file: %s\n", strerror(errno));
    }
}

/* ----------------------------- Signal / cleanup ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Stop motors first for safety */
    motor_off(MOTOR1_PIN);
    motor_off(MOTOR2_PIN);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motors start off */
    motor_off(MOTOR1_PIN);
    motor_off(MOTOR2_PIN);

    /* Initialize SPI */
    if (spi_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");
    printf("Sampling MCP3008 channel %d every %d ms, PWM %d Hz on GPIO%d/GPIO%d.\n",
           ADC_CHANNEL, SAMPLE_PERIOD_US / 1000, PWM_FREQUENCY,
           MOTOR1_PIN, MOTOR2_PIN);
    printf("Noise threshold: %d samples. Logging to %s.\n\n",
           NOISE_THRESHOLD, LOG_FILE);

    int motor1_duty = 0;
    int motor2_duty = 0;
    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive SPI errors – aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        int noise_level = adc_value;

        if (noise_level > NOISE_THRESHOLD) {
            /* Vibration detected – modulate motors */
            if (noise_level > NOISE_THRESHOLD * 2) {
                motor1_duty = PWM_RANGE;
                motor2_duty = PWM_RANGE;
            } else {
                motor1_duty = (int)((float)noise_level / (float)ADC_MAX_VALUE * PWM_RANGE);
                motor2_duty = (int)((float)noise_level / (float)ADC_MAX_VALUE * PWM_RANGE);
            }
            set_pwm_duty(MOTOR1_PIN, motor1_duty);
            set_pwm_duty(MOTOR2_PIN, motor2_duty);
            log_event(motor1_duty, motor2_duty);
        } else {
            /* No vibration – keep motors off */
            motor1_duty = 0;
            motor2_duty = 0;
            set_pwm_duty(MOTOR1_PIN, motor1_duty);
            set_pwm_duty(MOTOR2_PIN, motor2_duty);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

