/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0), SPI mode 0, 1 MHz
 *   - Vegetronix VH400 sensor on MCP3008 CH0
 *   - Relay-driven water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture_monitor moisture_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./moisture_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define MCP3008_CHANNEL 0         /* VH400 on CH0 */
#define PUMP_GPIO      17         /* BCM 17, active-high relay */
#define MOISTURE_THRESHOLD 30.0f   /* Percent */
#define SAMPLE_INTERVAL 60        /* Seconds */
#define MAX_RETRIES    3
#define ADC_MAX        1023       /* 10-bit ADC */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static bool g_pump_active = false;

/* --------------------------- Function prototypes ------------------------- */
static int  init_spi(void);
static int  read_mcp3008(int channel);
static float convert_to_percent(int adc_value);
static void control_pump(float moisture);
static void log_data(float moisture);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI ------------------------------------ */
static int init_spi(void)
{
