/*
 * air_quality_monitor.c
 *
 * Raspberry Pi 3 Model B+ — MQ-135 CO2 monitor via MCP3008 ADC (SPI0 CE0)
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MQ-135 analog output
 *   Fan control  -> GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality_monitor air_quality_monitor.c -lpigpio -lrt
 * Run:    sudo ./air_quality_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (pigpio spiOpen channel 0)        */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 3.3 V limit     */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words          */

#define FAN_GPIO       18         /* BCM 18 — fan control                      */
#define CO2_THRESHOLD  700.0      /* ppm — fan activates above this              */
#define LOG_FILE       "air_quality.log"
#define SAMPLE_PERIOD  5          /* seconds between readings                   */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0             */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel, int *adc_value);
static float adc_to_co2(int adc_value);
static void control_fan(int fan_state);
static void log_data(float co2_ppm, int fan_state);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *adc_value = adc;
    return 0;
}

/* --------------------------- CO2 conversion ------------------------------- */
static float adc_to_co2(int adc_value)
{
    /* Placeholder linear conversion — replace with calibrated curve from
     * MQ-135 datasheet and calibration data. */
    return (float)adc_value * 0.1f;
}

/* --------------------------- Fan control ---------------------------------- */
static void control_fan(int fan_state)
{
    if (gpioWrite(FAN_GPIO, fan_state) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", FAN_GPIO, fan_state);
    }
}

/* --------------------------- Logging -------------------------------------- */
static void log_data(float co2_ppm, int fan_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            co2_ppm, fan_state);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    /* Ensure fan is off before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(FAN_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);  /* Fan off at startup */

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(channel=%d, speed=%d) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Air quality monitoring started.\n");
    printf("  SPI0 CE0 @ %d Hz, MCP3008 CH0, fan on GPIO%d\n", SPI_SPEED, FAN_GPIO);
    printf("  Threshold: %.0f ppm — fan ON above this\n", CO2_THRESHOLD);
    printf("  Logging: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main monitoring loop */
    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Validate ADC value (10-bit: 0–1023) */
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float co2_ppm = adc_to_co2(adc_value);

        int fan_state = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
        control_fan(fan_state);

        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm  Fan: %s\n",
               co2_ppm, fan_state ? "ON" : "OFF");

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

