    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *adc_value = adc;
    return 0;
}

/* --------------------------- CO2 conversion ------------------------------- */
static float adc_to_co2(int adc_value)
{
    /* Placeholder linear conversion — replace with calibrated curve from
     * MQ-135 datasheet and calibration data. */
    return (float)adc_value * 0.1f;
}

/* --------------------------- Fan control ---------------------------------- */
static void control_fan(int fan_state)
{
    if (gpioWrite(FAN_GPIO, fan_state) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", FAN_GPIO, fan_state);
    }
}

/* --------------------------- Logging -------------------------------------- */
static void log_data(float co2_ppm, int fan_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            co2_ppm, fan_state);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
