    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);  /* Fan off at startup */

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(channel=%d, speed=%d) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Air quality monitoring started.\n");
    printf("  SPI0 CE0 @ %d Hz, MCP3008 CH0, fan on GPIO%d\n", SPI_SPEED, FAN_GPIO);
    printf("  Threshold: %.0f ppm — fan ON above this\n", CO2_THRESHOLD);
    printf("  Logging: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main monitoring loop */
    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Validate ADC value (10-bit: 0–1023) */
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float co2_ppm = adc_to_co2(adc_value);

        int fan_state = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
        control_fan(fan_state);

        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm  Fan: %s\n",
               co2_ppm, fan_state ? "ON" : "OFF");

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

