/*
 * Raspberry Pi Zero W – GP2Y0A21YK0F IR distance sensor (MCP3008 ADC) door opener.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> GP2Y0A21YK0F analog output
 *   Relay IN     -> GPIO17 (BCM)
 *   Relay VCC    -> 3.3 V
 *   Relay GND    -> GND
 *
 * Build:  gcc -O2 -Wall -o door_opener door_opener.c -lpigpio -lrt
 * Run:    sudo ./door_opener
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on SPI0 */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 limits */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define RELAY_GPIO       17         /* BCM 17 – active-high relay */
#define DISTANCE_THRESHOLD_CM 20.0f   /* Door opens when distance < 20 cm */
#define DEBOUNCE_MS      1000       /* 1 s between detections */
#define POLL_MS          100        /* 100 ms polling interval */
#define LOG_FILE         "door_events.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  read_mcp3008(int channel);
static float adc_to_distance_cm(int adc_value);
static void log_event(const char *event);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- MCP3008 read ---------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                 (start bit)
 *   tx[1] = (0x08 | channel) << 4 (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                 (clock out low 8 bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------- Distance conversion --------------------- */
static float adc_to_distance_cm(int adc_value)
{
    /*
     * GP2Y0A21YK0F transfer function (approximate, valid ~10–100 cm):
     *   d = 27.43 * (V^2 / 10) - 0.03 * V + 0.0001 * V^2
     *   V = (adc / 1023.0) * 3.3
     * Simplified linear approximation for 10–100 cm:
     *   d = 27.43 * (adc / 1023.0)^2
     */
    if (adc_value <= 0) return 100.0f;   /* sensor absent or shorted */
    float v = (float)adc_value / 1023.0f * 3.3f;
    return 27.43f * v * v / 100.0f;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event)
{
    if (!g_log_file) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s - %s\n", ts, event);
    fflush(g_log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO setup --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);   /* relay off at start */

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door opener started. Press Ctrl+C to exit.\n");

    bool door_open = false;
    uint32_t last_open_tick = 0;

    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error – log and back off briefly */
            log_event("SPI read error");
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        float dist = adc_to_distance_cm(adc);

        if (dist < DISTANCE_THRESHOLD_CM && !door_open) {
            printf("Distance: %.2f cm < %.1f cm – opening door\n",
                   dist, DISTANCE_THRESHOLD_CM);

            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to energize relay\n");
            } else {
                door_open = true;
                last_open_tick = gpioTick();
            }
            log_event("Door opened");
        } else if (door_open) {
            uint32_t now = gpioTick();
            if ((now - last_open_tick) >= DEBOUNCE_MS * 1000) {
                door_open = false;
                gpioWrite(RELAY_GPIO, 0);
                log_event("Door closed");
            }
        }

        gpioDelay(POLL_MS * 1000);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

