#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SAMPLES 3
#define LOG_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_average(int *samples, int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return (float)sum / num_samples;
}

static int set_valve_position(float average) {
    int duty_cycle = (int)(average * (float)PWM_RANGE);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(VALVE_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(int *samples, float average, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < NUM_SAMPLES; i++) {
        fprintf(log_file, "%d ", samples[i]);
    }
    fprintf(log_file, ", %.2f, %d\n", average, valve_position);
    fflush(log_file);
}

int main(void) {
    int samples[NUM_SAMPLES];
    float average;
    int valve_position;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", VALVE_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and valve control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val = read_mcp3008(SPI_CHANNEL);
            if (val < 0) {
                fprintf(stderr, "Failed to read ADC sample %d\n", i + 1);
                continue;
            }
            samples[i] = val;
        }

        average = calculate_average(samples, NUM_SAMPLES);

        if (set_valve_position(average) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        valve_position = gpioGetPWMdutycycle(VALVE_GPIO);
        if (valve_position < 0) {
            fprintf(stderr, "Failed to read PWM duty cycle\n");
        }

        log_data(samples, average, valve_position);

        for (int i = 0; i < LOG_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioPWM(VALVE_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Program terminated.\n");
    return 0;
}

