/*
 * Raspberry Pi Zero W - YL-69 Soil Moisture Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> YL-69 analog output
 *
 * Build: gcc -O2 -Wall -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define MCP3008_CH     0          /* Single-ended channel 0 */
#define SAMPLE_INTERVAL 5         /* Seconds between samples */
#define MAX_RETRIES    5
#define MAX_ADC_VALUE  1023.0f     /* 10-bit ADC full-scale */
#define LOG_FILE       "soil_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI command (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response (3 bytes):
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = LSBs of result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to moisture percentage (0-100).                  */
/* ------------------------------------------------------------------ */
static float adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    float pct = ((float)adc_value / MAX_ADC_VALUE) * 100.0f;
    if (pct < 0.0f)       pct = 0.0f;
    if (pct > 100.0f)     pct = 100.0f;
    return pct;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp.                                        */
/* ------------------------------------------------------------------ */
static void log_reading(float moisture_pct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Moisture: %.2f%%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_pct);
    } else {
        fprintf(fp, "(timestamp error), Moisture: %.2f%%\n", moisture_pct);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Retry SPI read with exponential backoff.                            */
/* ------------------------------------------------------------------ */
static int read_mcp3008_retry(int channel, int *out_value)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        int adc = read_mcp3008(channel);
        if (adc >= 0) {
            *out_value = adc;
            return 0;
        }

        fprintf(stderr, "SPI read attempt %d/%d failed (adc=%d)\n",
                attempt, MAX_RETRIES, adc);
        if (attempt < MAX_RETRIES) {
            gpioDelay(100000 * attempt);  /* 100 ms, 200 ms, 400 ms, 800 ms */
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc = -1;
        if (read_mcp3008_retry(MCP3008_CH, &adc) != 0) {
            fprintf(stderr, "Failed to read ADC after %d retries; skipping sample.\n",
                    MAX_RETRIES);
            log_reading(-1.0f);
        } else {
            float moisture = adc_to_moisture(adc);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc, moisture);
            log_reading(moisture);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            gpioDelay(1000000);  /* 1 s */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

