#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define CONFIG_FILE "theremin_config.txt"
#define SAMPLE_DELAY_US 100000
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define MAX_VOLUME 100
#define MIN_VOLUME 0
#define MAX_FREQ 2000
#define MIN_FREQ 100
#define TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static double last_valid_distance = 0.0;
static int last_valid_volume = 0;
static int pwm_initialized = 0;

static int spi_fd = -1;
static FILE *config_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int load_config(void) {
    if (!config_file) {
        config_file = fopen(CONFIG_FILE, "r");
        if (!config_file) {
            fprintf(stderr, "Warning: cannot open config file, using defaults\n");
            return -1;
        }
    }
    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "TRIGGER_PIN") == 0) trigger_pin = atoi(value);
        else if (strcmp(key, "ECHO_PIN") == 0) echo_pin = atoi(value);
        else if (strcmp(key, "PWM_PIN") == 0) pwm_pin = atoi(value);
        else if (strcmp(key, "SPI_DEVICE") == 0) spi_device = strdup(value);
        else if (strcmp(key, "SPI_SPEED") == 0) spi_speed = atoi(value);
        else if (strcmp(key, "SPI_BITS") == 0) spi_bits = atoi(value);
        else if (strcmp(key, "SPI_MODE") == 0) spi_mode = atoi(value);
    }
    fclose(config_file);
    config_file = NULL;
    return 0;
}

static void save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) return;
    fprintf(fp, "TRIGGER_PIN=%d,ECHO_PIN=%d,PWM_PIN=%d,SPI_DEVICE=%s,SPI_SPEED=%d,SPI_BITS=%d,SPI_MODE=%d\n",
            trigger_pin, echo_pin, pwm_pin, spi_device ? spi_device : "", spi_speed, spi_bits, spi_mode);
    fclose(fp);
}

static int init_spi(void) {
    spi_fd = open(spi_fd, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }
    unsigned char mode = spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    unsigned char bits = spi_bits;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    unsigned int speed = spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int read_ldr(void) {
    if (spi_fd < 0) return -1;
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = spi_speed,
        .bits_per_word = spi_bits,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double read_distance(void) {
    if (spi_fd < 0) return last_valid_distance;
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return last_valid_distance;
    gpioDelay(10);
