/*
 * MQ-3 Alcohol Sensor Monitor via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MQ-3 VCC     -> 5 V
 *   MQ-3 GND     -> GND
 *   MQ-3 AOUT    -> MCP3008 CH0
 *
 * Build: gcc -O2 -Wall -o alcohol_monitor alcohol_monitor.c -lpigpio -lrt
 * Run:   sudo ./alcohol_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, 8-bit words, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "alcohol_log.txt"
#define SAMPLE_PERIOD  1          /* seconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000     /* 100 ms */
#define ADC_MAX        1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read via pigpio SPI                         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed: returned %d (%s)\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Sensor classification                                               */
/* ------------------------------------------------------------------ */
static const char *classify_alcohol_level(int adc_value)
{
    if (adc_value < 0) {
        return "ADC read error";
    }

    /* Sensor-absent / short / open circuit: ADC stuck at rail */
    if (adc_value == 0 || adc_value == ADC_MAX) {
        return "Sensor absent or disconnected";
    }

    /* Calibration thresholds (example values) */
    const int above_50_ppm = 500;
    const int below_20_ppm  = 200;

    if (adc_value > above_50_ppm) {
        return "Alcohol detected! Limit exceeded.";
    } else if (adc_value < below_20_ppm) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, const char *level)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(fp, "%s, ADC: %d, Level: %s\n", timestamp, adc_value, level);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_handle = -1;
    int rc = EXIT_FAILURE;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        goto cleanup;
    }

    /* --- Log file --------------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        /* Retry on transient SPI errors */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "ADC read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after %d retries.\n", MAX_RETRIES);
            log_data(g_log, -1, "ADC read error");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        const char *level = classify_alcohol_level(adc_value);

        printf("ADC: %d, Level: %s\n", adc_value, level);

        log_data(g_log, adc_value, level);

        sleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    cleanup();
    return rc;
}

