/*
 * Raspberry Pi 4 Model B — Dual Potentiometer MCP3008 ADC → Dual Adafruit Mini DC Motor PWM
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Potentiometer 1 wiper
 *   MCP3008 CH1  -> Potentiometer 2 wiper
 *   Motor 1 +   -> GPIO18 (PWM0)
 *   Motor 1 -   -> GPIO24 (PWM1)
 *   Motor 1 Dir  -> GPIO23 (Direction)
 *   Motor 2 +   -> GPIO24 (PWM1)
 *   Motor 2 -   -> GPIO25 (Direction)
 *   Motor 2 Dir  -> GPIO25 (Direction)
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MOTOR1_PWM     18         /* GPIO18 — PWM0 */
#define MOTOR2_PWM     24         /* GPIO24 — PWM1 */
#define MOTOR1_DIR     23         /* GPIO23 — Motor 1 direction */
#define MOTOR2_DIR     25         /* GPIO25 — Motor 2 direction */

#define POT1_CHANNEL   0
#define POT2_CHANNEL   1

#define SPEED_MIN      0
#define SPEED_MAX      255
#define SPEED_STEP     5
#define HOLD_SECONDS    2
#define PAUSE_SECONDS   5

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static int  map_speed(int pot1, int pot2);
static void motor_set_speed(int motor, int speed);
static void motor_forward(int motor);
static void motor_backward(int motor);
static void motor_stop(int motor);
static void motor_accelerate(int motor, int speed, int duration_ms);
static void motor_decelerate(int motor, int duration_ms);
static void motor_reverse(int motor);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MCP3008 ----------------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ----------------------------- Speed Mapping ------------------------------ */
static int map_speed(int pot1, int pot2)
{
    int speed = SPEED_MIN + (pot1 * SPEED_STEP) + (pot2 * SPEED_STEP);
    if (speed < SPEED_MIN) speed = SPEED_MIN;
    if (speed > SPEED_MAX) speed = SPEED_MAX;
    return speed;
}

/* ----------------------------- Motor Helpers ------------------------------ */
static void motor_set_speed(int motor, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (motor == 1) {
        gpioPWM(MOTOR1_PWM, speed);
        if (speed > 0) motor_forward(motor);
        else if (speed < 0) motor_backward(motor);
        else motor_stop(motor);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_PWM, speed);
        if (speed > 0) motor_forward(motor);
        else if (speed < 0) motor_backward(motor);
        else motor_stop(motor);
    }
}

static void motor_forward(int motor)
{
    if (motor == 1) {
        gpioWrite(MOTOR1_DIR, 1);
        motor_set_speed(motor, 255);
    } else {
        gpioWrite(MOTOR2_DIR, 1);
        motor_set_speed(motor, 255);
    }
}

static void motor_backward(int motor)
{
    if (motor == 1) {
        gpioWrite(MOTOR1_DIR, 0);
        motor_set_speed(motor, 255);
    } else {
        gpioWrite(MOTOR2_DIR, 0);
        motor_set_speed(motor, 255);
    }
}

static void motor_stop(int motor)
{
    if (motor == 1) {
        gpioWrite(MOTOR1_DIR, 0);
        gpioPWM(MOTOR1_PWM, 0);
    } else {
        gpioWrite(MOTOR2_DIR, 0);
        gpioPWM(MOTOR2_PWM, 0);
    }
}

static void motor_accelerate(int motor, int speed, int duration_ms)
{
    motor_set_speed(motor, speed);
    gpioDelay(duration_ms * 1000);
    motor_set_speed(motor, 0);
    gpioDelay(100 * 1000); /* brief pause after stop */
}

static void motor_decelerate(int motor, int duration_ms)
{
    motor_set_speed(motor, 0);
    gpioDelay(duration_ms * 1000);
}

static void motor_reverse(int motor)
{
    if (motor == 1) {
        gpioWrite(MOTOR1_DIR, 0); /* forward */
        motor_set_speed(motor, 0);
        gpioDelay(100 * 1000);
        gpioWrite(MOTOR1_DIR, 1); /* backward */
        motor_set_speed(motor, 255);
        gpioDelay(100 * 1000);
    } else {
        gpioWrite(MOTOR2_DIR, 0); /* forward */
        motor_set_speed(motor, 0);
        gpioDelay(100 * 1000);
        gpioWrite(MOTOR2_DIR, 1); /* backward */
        motor_set_speed(motor, 255);
        gpioDelay(100 * 1000);
    }
}

/* ----------------------------- Cleanup / Signals -------------------------- */
static void cleanup(void)
{
    motor_stop(1);
    motor_stop(2);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor PWM pins */
    if (gpioSetMode(MOTOR1_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR1_DIR, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_DIR, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to configure motor GPIO pins\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 */
    gpioSetPWMrange(MOTOR1_PWM, 255);
    gpioSetPWMrange(MOTOR2_PWM, 255);

    /* Open SPI bus */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pot1 = read_mcp3008(POT1_CHANNEL);
        int pot2 = read_mcp3008(POT2_CHANNEL);

        if (pot1 < 0 || pot2 < 0) {
            fprintf(stderr, "Error reading potentiometer(s). Skipping cycle.\n");
            gpioDelay(PAUSE_SECONDS * 1000000);
            continue;
        }

        int speed = map_speed(pot1, pot2);
        printf("Pot1=%4d Pot2=%4d Speed=%3d\n", pot1, pot2, speed);

        motor_set_speed(1, speed);
        motor_set_speed(2, speed);

        motor_accelerate(1, speed, HOLD_SECONDS * 1000);
        motor_accelerate(2, speed, HOLD_SECONDS * 1000);

        motor_reverse(1);
        motor_reverse(2);

        gpioDelay(PAUSE_SECONDS * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

