#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_noise_level(int *baseline) {
    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_TIME);
    int sum = 0;
    int valid_samples = 0;

    for (int i = 0; i < CALIBRATION_TIME * 1000 && running; i++) {
        int val = read_mcp3008(0);
        if (val >= 0) {
            sum += val;
            valid_samples++;
        }
        if (i < CALIBRATION_TIME * 1000 - 1) {
            gpioDelay(1000);
        }
    }

    if (!running) {
        fprintf(stderr, "Calibration interrupted by signal\n");
        return -1;
    }

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    *baseline = sum / valid_samples;
    printf("Calibration complete. Baseline: %d\n", *baseline);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(17, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int baseline = 0;
    if (calibrate_noise_level(&baseline) != 0) {
        fprintf(stderr, "Failed to calibrate noise level\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int led_state = 0;
    uint32_t last_toggle_time = 0;

    while (running) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Failed to read sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int diff = sample - baseline;
        uint32_t now = gpioTick();

        if (diff > 0 && (now - last_toggle_time) > DEBOUNCE_DELAY_US) {
            led_state = !led_state;
            gpioWrite(LED_PIN, led_state);
            last_toggle_time = now;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

