#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "airflow_log.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3f / 1024.0f;
}

static float voltage_to_airflow(float voltage) {
    // Calibration curve: AWM720P datasheet
    // Example linear calibration: 0.0 V -> 0.0 CFM, 3.3 V -> 100.0 CFM
    float slope = 100.0f / 3.3f;
    float intercept = 0.0f;
    return slope * voltage + intercept;
}

static void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float airflow = voltage_to_airflow(voltage);
        log_data(airflow);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

