#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       8          /* BCM 8 = physical pin 24, CE0 */
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_PERIOD_NS 1000000L  /* 1 ms -> 1000 Hz */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on error. */
static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then
     * a dummy byte to clock out the 10-bit result. */
    uint8_t tx[3] = {
        0x01,                       /* start bit */
        (uint8_t)((0x08 | channel) << 4), /* SGL/DIFF=1, channel */
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* rx[1] low nibble + rx[2] form the 10-bit result */
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request CS line --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, cs_line, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, continuing...\n");
            next_deadline.tv_nsec = SAMPLE_PERIOD_NS;
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        long long timestamp_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (fprintf(log_file, "%lld|%d\n", timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            break;
        }

        next_deadline.tv_nsec = SAMPLE_PERIOD_NS;
        struct timespec rem;
        while (nanosleep(&next_deadline, &rem) < 0 && errno == EINTR) {
            if (!g_running) break;
            next_deadline = rem;
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    printf("Audio logging stopped.\n");
    return EXIT_SUCCESS;
}

