#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define VREF 3.3
#define VOUT_MIN 0.0
#define VOUT_MAX VREF
#define MIN_MAG  -100.0
#define MAX_MAG   100.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double voltage_to_magnetic_field(double voltage) {
    if (voltage < VOUT_MIN) voltage = VOUT_MIN;
    if (voltage > VOUT_MAX) voltage = VOUT_MAX;
    return (voltage / VREF) * 1000.0;  /* 1 V -> 1000 mT */
}

static int read_sensor(int pin, double *magnetic_field) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    *magnetic_field = voltage_to_magnetic_field((double)state);
    return 0;
}

static int log_data(double s1, double s2, double s3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    printf("Starting magnetic field logging. Press Ctrl+C to stop.\n");

    while (running) {
        double s1, s2, s3;
        int ok = 1;

        if (read_sensor(SENSOR1_PIN, &s1) != 0) ok = 0;
        if (read_sensor(SENSOR2_PIN, &s2) != 0) ok = 0;
        if (read_sensor(SENSOR3_PIN, &s3) != 0) ok = 0;

        if (ok) {
            if (s1 < MIN_MAG || s1 > MAX_MAG ||
                s2 < MIN_MAG || s2 > MAX_MAG ||
                s3 < MIN_MAG || s3 > MAX_MAG) {
                fprintf(stderr, "Warning: sensor reading out of range (s1=%.2f, s2=%.2f, s3=%.2f)\n",
                        s1, s2, s3);
            } else {
                if (log_data(s1, s2, s3) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

