/*
 * Soil Moisture Monitor & Automated Watering System
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 (CE0), 500 kHz, mode 0, single-ended channel 0
 * Pump:   Relay on GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO          17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE           "watering.log"
#define SAMPLE_INTERVAL_S  60
#define SPI_CHANNEL        0
#define SPI_SPEED          500000
#define ADC_CHANNEL        0
#define ADC_MAX            1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log_file)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read (single-ended, channel 0-7)                           */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

/* ------------------------------------------------------------------ */
/* Pump control                                                        */
/* ------------------------------------------------------------------ */
static void pump_on(void)
{
    if (gpioWrite(PUMP_GPIO, 1) != 0) {
        log_event("ERROR: failed to set pump GPIO high");
        return;
    }
    log_event("Pump turned ON");
}

static void pump_off(void)
{
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        log_event("ERROR: failed to set pump GPIO low");
        return;
    }
    log_event("Pump turned OFF");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* start with pump off */

    /* ---- SPI init ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);   /* mode 0 */
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("=== Watering system started ===");
    printf("Watering system started. Sampling every %d s. Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    /* ---- main loop ---- */
    while (g_running) {
        int moisture = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (moisture < 0) {
            log_event("ERROR: ADC read failed on channel 0");
            /* keep pump in current state on transient SPI errors */
        } else {
            int pct = (moisture * 100) / ADC_MAX;

            if (pct < MOISTURE_THRESHOLD) {
                pump_on();
            } else if (pct > MOISTURE_THRESHOLD) {
                pump_off();
            }
        }

        /* sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* ---- graceful shutdown ---- */
    log_event("=== Watering system stopping ===");
    pump_off();
    spiClose(g_spi_handle);
    gpioTerminate();
    log_event("=== Watering system terminated ===");
    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

