#define MQTT_CLIENT_ID     "rpi_led_control"
#define MQTT_QOS           0
#define LED_GPIO           17
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_ATTEMPTS 10

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_mqtt_connected = 0;
static volatile sig_atomic_t g_mqtt_subscribed = 0;

/* ------------------------------------------------------------------ */
