#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_DELAY_US    100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n", ALARM_LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_alarm(void)
{
    if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn on alarm LED.\n");
        return;
    }
    gpioDelay(1000000); /* 1 second */
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off alarm LED.\n");
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int level = gpioRead(SOUND_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SOUND_SENSOR_PIN);
            break;
        }

        /* KY-038 DO pin: LOW (0) when sound exceeds onboard pot threshold */
        if (level == 0) {
            printf("Sound detected!\n");
            trigger_alarm();
        } else {
            printf("No sound.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up GPIO resources */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

