#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define CONSUMER "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
    }

    if (fclose(fp) != 0) {
        perror("fclose log file");
    }
}

static int shutdown_system(const char *message) {
    char log_buf[256];
    snprintf(log_buf, sizeof(log_buf), "Vibration detected! %s", message);
    log_event(log_buf);

    printf("%s\n", log_buf);

    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("system");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd == -1) {
        perror("open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpio_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIO_REQUEST_EVENT_FALLING_EDGE;
    config.flags = 0;

    if (ioctl(fd, GPIOCHIP_REQUEST_LINE, &config) == -1) {
        perror("ioctl GPIOCHIP_REQUEST_LINE");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (program_running) {
        struct gpio_event event;
        ssize_t ret = read(fd, &event, sizeof(event));
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read gpio_event");
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (event.event_type == GPIO_EVENT_FALLING_EDGE) {
            if (shutdown_system("Vibration detected!") == 0) {
                break;
            }
        }
    }

    if (close(fd) == -1) {
        perror("close GPIO chip");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

