    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd == -1) {
        perror("open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpio_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIO_REQUEST_EVENT_FALLING_EDGE;
    config.flags = 0;

    if (ioctl(fd, GPIOCHIP_REQUEST_LINE, &config) == -1) {
        perror("ioctl GPIOCHIP_REQUEST_LINE");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (program_running) {
        struct gpio_event event;
        ssize_t ret = read(fd, &event, sizeof(event));
        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read gpio_event");
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (event.event_type == GPIO_EVENT_FALLING_EDGE) {
            if (shutdown_system("Vibration detected!") == 0) {
                break;
            }
        }
    }

    if (close(fd) == -1) {
        perror("close GPIO chip");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

