#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float convert_to_celsius(int adc_value) {
    return (float)adc_value * 0.01f;
}

static void log_data(float data[], int size) {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temp_log.dat: %s\n", strerror(errno));
        return;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in temp_log.dat: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    long file_size = ftell(fp);
    if (file_size < (long)size) {
        fprintf(stderr, "File too small to write all data\n");
        fclose(fp);
        return;
    }

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking in temp_log.dat: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    size_t written = fwrite(data, sizeof(float), size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to temp_log.dat: %s\n", strerror(errno));
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing temp_log.dat: %s\n", strerror(errno));
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    float data[BUFFER_SIZE];
    int idx = 0;
    int error_count = 0;

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            error_count++;
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            if (error_count > 10) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        error_count = 0;

        float temperature = convert_to_celsius(adc_value);
        data[idx] = temperature;
        idx = (idx + 1) % BUFFER_SIZE;

        printf("Temperature: %.2f °C\n", temperature);

        log_data(data, BUFFER_SIZE);
        sleep(SAMPLE_INTERVAL);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    return 0;
}

