                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }
        sleep(1);
    }

    printf("\nCleaning up and exiting...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return EXIT_SUCCESS;
}

