#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int activate_relay(int pin) {
    return set_relay(pin, 1);
}

static int deactivate_relay(int pin) {
    return set_relay(pin, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < num_pins && running; i++) {
            if (activate_relay(pins[i]) != 0) break;
            sleep(1);
            if (!running) break;
            if (deactivate_relay(pins[i]) != 0) break;
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

