#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CLAP_GPIO 26
#define LED_GPIO 16
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000
#define ADC_MAX 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int read_adc(int gpio) {
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;
    if (gpioSetPullUpDown(gpio, PI_PUD_UP) < 0) return -1;
    int val = gpioRead(gpio);
    if (val < 0) return -1;
    return val;
}

static void clap_detected(void) {
    log_event("Clap detected!");
    if (gpioWrite(LED_GPIO, 1) < 0) {
        log_event("Error: failed to turn on LED");
        return;
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(LED_GPIO, 0) < 0) {
        log_event("Error: failed to turn off LED");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CLAP_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", CLAP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_clap_tick = 0;
    bool clap_pending = false;

    while (running) {
        int adc = read_adc(CLAP_GPIO);
        if (adc < 0) {
            fprintf(stderr, "ADC read error on GPIO%d\n", CLAP_GPIO);
            gpioDelay(100000);
            continue;
        }

        uint32_t now_tick = gpioTick();
        if (adc > 500) {
            if (!clap_pending) {
                clap_pending = true;
                last_clap_tick = now_tick;
            } else if (now_tick - last_clap_tick >= DEBOUNCE_MS * 1000) {
                clap_detected();
                clap_pending = false;
            }
        } else {
            clap_pending = false;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

