        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static double adc_to_amperes(int adc_value)
{
    double voltage = (adc_value / (double)ADC_MAX) * ADC_VREF;
    return voltage / ADC_MV_PER_A;
}

static void log_current(double current)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s,%.4f\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    if (gpio_set_direction(g_spi_fd, "out") < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    if (gpio_write(g_spi_fd, "0") < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen("current_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(current_log.txt): %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            double current = adc_to_amperes(adc_value);
            log_current(current);
            printf("Current: %.4f A\n", current);
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

