#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define ADC_CHANNEL 0
#define LOG_FILE    "current_log.txt"
#define SAMPLE_US   100000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value) {
    /* MLX91211: 10 mV per LSB, 16-bit signed */
    double voltage = (double)adc_value * 0.01;
    if (voltage < 0.0) voltage = 0.0;
    return voltage / 0.1;
}

static void log_current(double current) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    } else {
        fflush(g_log);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (current < 0.0 || current > 5.0) {
            fprintf(stderr, "Warning: current %.2f A out of range [0,5]V\n", current);
        }

        log_current(current);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_log) fclose(g_log);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

