#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR "/home/pi/security_cam"
#define CAPTURE_FILENAME_LEN 256
#define MAX_FILE_NAME_LEN 256
#define MAX_COMMAND_LEN 512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_capture_directory(void)
{
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "%s exists but is not a directory", CAPTURE_DIR);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s): %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s): %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    char command[MAX_COMMAND_LEN];
    int ret = snprintf(command, sizeof(command),
                       "fork; execvp libcamera-still --nopreview --timeout 2000 --width 640 --height 480 --encoding jpeg %s 2>/dev/null",
                       filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small for filename");
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        execvp("libcamera-still", (char *const *)command);
        /* If we get here, execvp failed */
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }

    /* Parent process */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
    return -1;
}

static int generate_filename(char *buf, size_t buflen, const char *prefix, const char *suffix)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }

    char date_str[32];
    if (strftime(date_str, sizeof(date_str), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }

    if (snprintf(buf, buflen, "%s%s%s", prefix, date_str, suffix) >= (int)buflen) {
        syslog(LOG_ERR, "Filename too long, truncating");
        return -1;
    }
    return 0;
}

static int log_event(const char *event)
{
    syslog(LOG_INFO, "%s", event);
    return 0;
}

int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_capture_directory() != 0) {
        syslog(LOG_ERR, "Cannot use capture directory");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on GPIO%d, capture dir: %s)",
           PIR_GPIO, CAPTURE_DIR);

    int last_pir_state = -1;
    int ret = EXIT_SUCCESS;

    while (g_running) {
        int pir_state = gpioRead(PIR_GPIO);
        if (pir_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed: %s", PIR_GPIO, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (pir_state != last_pir_state) {
            if (pir_state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);
                char filename[MAX_FILE_NAME_LEN];
                if (generate_filename(filename, sizeof(filename),
                                     CAPTURE_DIR, ".jpg") == 0) {
                    if (capture_image(filename) == 0) {
                        log_event("Motion detected and image captured");
                    } else {
                        log_event("Motion detected but image capture failed");
                    }
                } else {
                    log_event("Motion detected but filename generation failed");
                }
            }
            last_pir_state = pir_state;
            usleep(DEBOUNCE_DELAY_MS * 1000);
            pir_state = gpioRead(PIR_GPIO);
            if (pir_state < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed: %s", PIR_GPIO, strerror(errno));
                ret = EXIT_FAILURE;
                break;
            }
            if (pir_state == last_pir_state)
                usleep(POLL_INTERVAL_MS * 1000);
        } else {
            usleep(POLL_INTERVAL_MS * 1000);
        }
    }

    syslog(LOG_INFO, "Security camera stopped");
    closelog();
    return ret;
}

