            perror("VIDIOC_DQBUF");
            break;
        }

        unsigned char *frame = (unsigned char *)buf.map;
        unsigned char *fragment = malloc(MAX_FRAGMENT_SIZE);
        if (!fragment) {
            perror("malloc");
            buf.unmap();
            ioctl(fd, VIDIOC_QBUF, &buf);
