        }

        size_t frame_size = buf.length;
        size_t fragment_size = (frame_size > MAX_FRAGMENT_SIZE) ? MAX_FRAGMENT_SIZE : frame_size;
        memcpy(fragment, frame, fragment_size);

        int sent = send_fragment(sockfd, fragment, fragment_size);
        free(fragment);

        if (sent < 0) {
            fprintf(stderr, "Failed to send fragment\n");
            break;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].memory == V4L2_MEMORY_MMAP) {
                if (munmap(buffers[i].map, buffers[i].length) < 0) {
                    perror("munmap");
                }
            }
        }
        close(fd);
    }

