#define VIDEO_DEVICE "/dev/video0"
#define MAX_FRAME_SIZE 4096
#define MAX_FRAGMENT_SIZE 65000
#define NUM_BUFFERS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_buffer *buffers, size_t *buf_sizes) {
    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open video device");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV\n");
        close(*fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(*fd);
            return -1;
        }

        size_t buf_size = buf.length;
        buffers[i].length = buf_size;
        buffers[i].memory = V4L2_MEMORY_MMAP;

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            close(*fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(*fd);
        return -1;
    }

    return 0;
}

static int map_buffer(int fd, struct v4l2_buffer *buf, void **map) {
    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *map = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (*map == MAP_FAILED) {
        perror("mmap");
        xioctl(fd, VIDIOC_QBUF, buf);
        return -1;
    }

    return 0;
}

static int send_fragment(int sockfd, const unsigned char *fragment, size_t size) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(12345);
    if (inet_pton(AF_INET, "192.168.1.100", &addr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }

    size_t total_sent = 0;
    while (total_sent < size) {
        ssize_t sent = sendto(sockfd, fragment + total_sent, size - total_sent, 0, (struct sockaddr *)&addr, sizeof(addr));
        if (sent < 0) {
            perror("sendto");
            return -1;
        }
        total_sent += sent;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <init_camera> <send_frame>\n", argv[0]);
        return 1;
    }

    const char *init_camera = argv[1];
    const char *send_frame = argv[2];

    int fd = -1;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    size_t buf_sizes[NUM_BUFFERS] = {0};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_camera == "init_camera") {
        if (init_camera(fd, buffers, buf_sizes) < 0) {
            fprintf(stderr, "Failed to initialize camera\n");
            return 1;
        }
    } else if (init_camera == "send_frame") {
        fd = open(VIDEO_DEVICE, O_RDWR);
        if (fd < 0) {
            perror("open video device");
            return 1;
        }
        struct v4l2_format fmt;
        memset(&fmt, 0, sizeof(fmt));
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
        fmt.fmt.pix.field = V4L2_FIELD_NONE;

        if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
            perror("VIDIOC_S_FMT");
            close(fd);
            return 1;
        }

        struct v4l2_requestbuffers req;
        memset(&req, 0, sizeof(req));
        req.count = NUM_BUFFERS;
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
            perror("VIDIOC_REQBUFS");
            close(fd);
            return 1;
        }

        if (req.count < 1) {
            fprintf(stderr, "Insufficient buffer memory\n");
            close(fd);
            return 1;
        }

        for (int i = 0; i < req.count; i++) {
            struct v4l2_buffer buf;
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
                perror("VIDIOC_QUERYBUF");
                close(fd);
                return 1;
            }

            size_t buf_size = buf.length;
            buffers[i].length = buf_size;
            buffers[i].memory = V4L2_MEMORY_MMAP;

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                close(fd);
                return 1;
            }
        }

        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
            perror("VIDIOC_STREAMON");
            close(fd);
            return 1;
        }
    } else {
        fprintf(stderr, "Invalid init_camera value\n");
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        close(fd);
        return 1;
    }

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            break;
        }

        unsigned char *frame = (unsigned char *)buf.map;
        unsigned char *fragment = malloc(MAX_FRAGMENT_SIZE);
        if (!fragment) {
            perror("malloc");
            buf.unmap();
            ioctl(fd, VIDIOC_QBUF, &buf);
            break;
        }

        size_t frame_size = buf.length;
        size_t fragment_size = (frame_size > MAX_FRAGMENT_SIZE) ? MAX_FRAGMENT_SIZE : frame_size;
        memcpy(fragment, frame, fragment_size);

        int sent = send_fragment(sockfd, fragment, fragment_size);
        free(fragment);

        if (sent < 0) {
            fprintf(stderr, "Failed to send fragment\n");
            break;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].memory == V4L2_MEMORY_MMAP) {
                if (munmap(buffers[i].map, buffers[i].length) < 0) {
                    perror("munmap");
                }
            }
        }
        close(fd);
    }

    return 0;
}

