/*
 * camera_pantilt.c — Raspberry Pi camera pan-tilt control via software PWM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o camera_pantilt camera_pantilt.c -lpigpio -lrt
 * Run:    sudo ./camera_pantilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin map (BCM numbering) ---- */
#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

/* ---- Servo parameters ---- */
#define SERVO_MIN_PULSE_US  1000   /* 50 % duty  */
#define SERVO_MAX_PULSE_US  500    /* 100 % duty  */
#define SERVO_MID_PULSE_US  750    /* 75 % duty  */
#define SERVO_PERIOD_US     20000  /* 50 Hz */
#define SERVO_RANGE         100    /* 0..100 duty steps */

/* ---- Button parameters ---- */
#define BUTTON_MIN_PULSE_US  500
#define BUTTON_MAX_PULSE_US  1000
#define BUTTON_MIN_PULSE     50
#define BUTTON_MAX_PULSE     100
#define BUTTON_PULSE_STEP    10

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Servo write: maps duty 0..100 to pulse width 500..1500 us ---- */
static int servo_write(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    int pulse = (int)((long)duty * SERVO_PERIOD_US / 100);
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse);
        return -1;
    }
    return 0;
}

/* ---- Button write: maps button press to duty 50..100 ---- */
static int button_write(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    int pulse = (int)((long)duty * SERVO_PERIOD_US / 100);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse);
        return -1;
    }
    return 0;
}

/* ---- Map a pulse width to a duty value (0..100) ---- */
static int pulse_to_duty(int pulse_us)
{
    if (pulse_us < BUTTON_MIN_PULSE) return 0;
    if (pulse_us > BUTTON_MAX_PULSE) return 100;
    return (int)(((long)(pulse_us - BUTTON_MIN_PULSE) *
                  (BUTTON_MAX_PULSE - BUTTON_MIN_PULSE)) /
                 (BUTTON_MAX_PULSE - BUTTON_MIN_PULSE));
}

/* ---- Map a duty value to a pulse width (500..1500 us) ---- */
static int duty_to_pulse(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    return (int)(((long)duty * SERVO_PERIOD_US) / 100);
}

/* ---- Clamp a value to [min, max] ---- */
static int clamp(int v, int min, int max)
{
    if (v < min) return min;
    if (v > max) return max;
    return v;
}

/* ---- Read a button state: 1 = pressed, 0 = released ---- */
static int read_button(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(pin=%d) failed\n", pin);
        return -1;
    }
    return level;
}

/* ---- Set both servos to mid-position ---- */
static int init_servos(void)
{
    if (servo_write(PAN_SERVO_PIN, SERVO_MID_PULSE_US) < 0) return -1;
    if (servo_write(TILT_SERVO_PIN, SERVO_MID_PULSE_US) < 0) return -1;
    return 0;
}

/* ---- Move a servo to a given duty value ---- */
static int move_servo(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    int pulse = duty_to_pulse(duty);
    if (servo_write(pin, duty) < 0) return -1;
    return 0;
}

/* ---- Move a servo by a given amount (clamped) ---- */
static int move_servo_by(int pin, int amount)
{
    int duty = pulse_to_duty(SERVO_MID_PULSE_US + amount);
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;
    return move_servo(pin, duty);
}

/* ---- Cleanup: stop servos and release pigpio ---- */
static void cleanup(void)
{
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* ---- Install signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure button pins as inputs with pull-ups ---- */
    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) < 0 ||
        gpioSetMode(TILT_DOWN_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_LEFT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize servos to mid-position ---- */
    if (init_servos() < 0) {
        fprintf(stderr, "Servo initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Camera pan-tilt control ready.\n");
    printf("  Pan servo : BCM%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: BCM%d\n", TILT_SERVO_PIN);
    printf("  Tilt up  : BCM%d\n", TILT_UP_PIN);
    printf("  Tilt down: BCM%d\n", TILT_DOWN_PIN);
    printf("  Pan left : BCM%d\n", PAN_LEFT_PIN);
    printf("  Pan right: BCM%d\n", PAN_RIGHT_PIN);
    printf("  PWM period: %d us (50 Hz)\n", SERVO_PERIOD_US);
    printf("  Mid pos : %d/%d\n", SERVO_MID_PULSE_US, SERVO_RANGE);
    printf("  Step    : %d us\n", BUTTON_PULSE_STEP);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int pan  = 75;
        int tilt = 75;
        int pan_left = 0;
        int pan_right = 0;
        int tilt_up  = 0;
        int tilt_down = 0;

        /* Read button states */
        int p = read_button(PAN_LEFT_PIN);
        int r = read_button(PAN_RIGHT_PIN);
        int t = read_button(TILT_UP_PIN);
        int d = read_button(TILT_DOWN_PIN);

        if (p < 0 || r < 0 || t < 0 || d < 0) {
            fprintf(stderr, "Button read error — continuing\n");
            gpioDelay(50000);
            continue;
        }

        /* Tilt up / down */
        if (t == 1) {
            if (tilt_up == 0) tilt = move_servo_by(TILT_SERVO_PIN, 5);
            tilt_up = 1;
        } else if (t == 0) {
            if (tilt_up == 1) tilt = move_servo_by(TILT_SERVO_PIN, -5);
            tilt_up = 0;
        }

        /* Tilt down / up */
        if (d == 1) {
            if (tilt_down == 0) tilt = move_servo_by(TILT_SERVO_PIN, 5);
            tilt_down = 1;
        } else if (d == 0) {
            if (tilt_down == 1) tilt = move_servo_by(TILT_SERVO_PIN, -5);
            tilt_down = 0;
        }

        /* Pan left / right */
        if (p == 1) {
            if (pan_left == 0) pan = move_servo_by(PAN_SERVO_PIN, -5);
            pan_left = 1;
        } else if (p == 0) {
            if (pan_left == 1) pan = move_servo_by(PAN_SERVO_PIN, 5);
            pan_left = 0;
        }

        if (r == 1) {
            if (pan_right == 0) pan = move_servo_by(PAN_SERVO_PIN, 5);
            pan_right = 1;
        } else if (r == 0) {
            if (pan_right == 1) pan = move_servo_by(PAN_SERVO_PIN, -5);
            pan_right = 0;
        }

        /* Clamp positions */
        pan  = clamp(pan, 25, 125);
        tilt = clamp(tilt, 25, 125);

        printf("Pan: %3d  Tilt: %3d\n", pan, tilt);
        gpioDelay(50000); /* 50 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

