#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_TIMEOUT_SEC 2
#define JPEG_QUALITY 75
#define BLUR_RADIUS 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int open_camera(void) {
    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }
    return fd;
}

static int request_buffers(int fd, uint32_t width, uint32_t height, uint32_t *buf_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *buf_size = buf.length;
    return 0;
}

static int request_buffers_mmap(int fd, uint32_t width, uint32_t height, uint32_t *buf_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *buf_size = buf.length;
    return 0;
}

static int mmap_buffers(int fd, uint32_t width, uint32_t height, uint32_t *buf_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *buf_size = buf.length;
    if (*buf_size == 0) {
        fprintf(stderr, "Invalid buffer size: %u\n", *buf_size);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        uint32_t buf_size = buf.length;
        if (buf_size == 0) {
            fprintf(stderr, "Invalid buffer size: %u\n", buf_size);
            return -1;
        }

        void *start = mmap(NULL, buf_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        *buf_size = buf_size;
        buffers[i] = start;
    }

    return 0;
}

static int queue_buffer(int fd, uint32_t width, uint32_t height, uint32_t *buf_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int start_streaming(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_STREAMON, &buf) == -1) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int stop_streaming(int fd) {
    struct v4l2_buffer buf;
