/*
 * camera_summary.c — Summarise a CSI camera's capabilities on a Raspberry Pi.
 *
 * Build:  gcc -O2 -Wall -Wextra -o camera_summary camera_summary.c
 * Run:    ./camera_summary
 *
 * Requires libv4l2-dev (or v4l2-dev on some older kernels).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_summary(const struct v4l2_frmsize_step *frms,
                         const struct v4l2_frameinterval *intvls,
                         int nfrms, int nintvls,
                         int autofocus_supported)
{
    printf("Summary:\n");
    printf("  Resolution: %dx%d\n", frms[0].type.numerator, frms[0].type.denominator);
    printf("  Frame rate: %dx%d/%d\n", intvls[0].type.numerator, intvls[0].type.denominator, intvls[0].denominator);
    printf("  Autofocus: %s\n", autofocus_supported ? "yes" : "no");
    printf("  Frame sizes: %d supported\n", nfrms);
    printf("  Frame intervals: %d supported\n", nintvls);
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsize_step *frms = NULL;
    struct v4l2_frameinterval *intvls = NULL;
    unsigned int nfrms = 0, nintvls = 0;
    int autofocus_supported = 0;

    /* Enumerate frame sizes */
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frms) < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        goto cleanup;
    }
    nfrms = (unsigned int)(frms ? frms->type.numerator : 0);
    if (frms) free(frms);

    /* Enumerate frame intervals */
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &intvls) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        goto cleanup;
    }
    nintvls = (unsigned int)(intvls ? intvls->type.numerator : 0);
    if (intvls) free(intvls);

    /* Check if autofocus is supported */
    struct v4l2_ctrl *ctrl = NULL;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "Error querying control interface: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ctrl && ctrl->command == V4L2_CID_FOCUS_AUTO) {
        autofocus_supported = 1;
    }

    print_summary(NULL, NULL, nfrms, nintvls, autofocus_supported);

cleanup:
    if (fd >= 0) close(fd);
    return EXIT_SUCCESS;
}

