#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pw=%d) failed\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static int adjust_servo(int pin, int direction, int amount) {
    int current = gpioGetMode(pin);
    if (current < 0) {
        fprintf(stderr, "Error: gpioGetMode(pin=%d) failed\n", pin);
        return -1;
    }
    if (current != PI_OUTPUT) {
        fprintf(stderr, "Error: pin %d is not output\n", pin);
        return -1;
    }

    int new_pulse = gpioGetMode(pin) == PI_OUTPUT
                   ? gpioRead(pin)
                   : gpioRead(pin);

    if (new_pulse < 0) {
        fprintf(stderr, "Error: gpioRead(pin=%d) failed\n", pin);
        return -1;
    }

    int new_pulse_width = new_pulse ? 0 : 1;

    if (direction > 0) {
        new_pulse_width += amount;
    } else if (direction < 0) {
        new_pulse_width -= amount;
    }

    if (new_pulse_width < MIN_PULSE_WIDTH) {
        new_pulse_width = MIN_PULSE_WIDTH;
    } else if (new_pulse_width > MAX_PULSE_WIDTH) {
        new_pulse_width = MAX_PULSE_WIDTH;
    }

    if (set_servo(pin, new_pulse_width) < 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PAN=%d, OUTPUT) failed\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TILT=%d, OUTPUT) failed\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(button pins) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(button pins) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Camera pan-tilt control started.\n");
    printf("  Pan servo: GPIO%d (BCM)\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d (BCM)\n", TILT_SERVO_PIN);
    printf("  UP: GPIO%d\n", UP_BUTTON_PIN);
    printf("  DOWN: GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  LEFT: GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  RIGHT: GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("  Center pulse width: %d us\n", CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    int pan_pulse = CENTER_PULSE_WIDTH;
    int tilt_pulse = CENTER_PULSE_WIDTH;

    while (running) {
        int up_pressed = gpioRead(UP_BUTTON_PIN);
        int down_pressed = gpioRead(DOWN_BUTTON_PIN);
        int left_pressed = gpioRead(LEFT_BUTTON_PIN);
        int right_pressed = gpioRead(RIGHT_BUTTON_PIN);

        if (up_pressed == 0) {
            adjust_servo(PAN_SERVO_PIN, 1, 10);
        }
        if (down_pressed == 0) {
            adjust_servo(PAN_SERVO_PIN, -1, 10);
        }
        if (left_pressed == 0) {
            adjust_servo(TILT_SERVO_PIN, 1, 10);
        }
        if (right_pressed == 0) {
            adjust_servo(TILT_SERVO_PIN, -1, 10);
        }

        gpioDelay(50000);
    }

    printf("\nShutting down...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

