#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_MS 100
#define IMAGE_DIR "motion_captures"
#define HTTP_PORT 80
#define HTTP_HOST "http://<IP>:<PORT>/upload"
#define MAX_FILENAME 256
#define MAX_JSON 512

static volatile sig_atomic_t g_running = 1;
static int g_http_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -q 85 -o %s", filename);
    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error: system() failed to launch raspistill: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Error: raspistill exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }
    return 0;
}

static int compose_json_payload(char *payload, size_t payload_size,
                                const char *filename, int motion_detected,
                                int gpio_pin) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    int written = snprintf(payload, payload_size,
                           "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"gpio_pin\":%d}",
                           filename, timestamp, motion_detected, gpio_pin);
    if (written < 0 || (size_t)written >= payload_size) {
        fprintf(stderr, "Error: JSON payload formatting failed\n");
        return -1;
    }
    return 0;
}

static int send_http_request(const char *payload, const char *filename) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Error: socket() failed: %s\n", strerror(errno));
        return -1;
    }
    int reuse = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        fprintf(stderr, "Warning: setsockopt(SO_REUSEADDR) failed: %s\n", strerror(errno));
    }
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_HOST, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Error: inet_pton() failed for '%s'\n", HTTP_HOST);
        close(sock);
        return -1;
    }
    if (connect(sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error: connect() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    if (send(sock, payload, strlen(payload), 0) < 0) {
        fprintf(stderr, "Error: send() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    if (send(sock, filename, strlen(filename), 0) < 0) {
        fprintf(stderr, "Error: send() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    int ret = recv(sock, NULL, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: recv() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <PORT>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *ip_address = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }
    const char *http_host = "http://" ip_address ":" port "/upload";

    if (ensure_directory(IMAGE_DIR) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (g_http_fd >= 0) {
        close(g_http_fd);
        g_http_fd = -1;
    }

    if (ghttp_init() != 0) {
        fprintf(stderr, "Error: ghttp_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        int motion_detected = 0;
        int last_state = gpioRead(PIR_GPIO);
        if (last_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        for (int i = 0; i < DEBOUNCE_MS / POLL_MS && g_running; i++) {
            gpioDelay(POLL_MS * 1000);
            int current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
                break;
            }
            if (current_state != last_state) {
                last_state = current_state;
                if (current_state == 1) {
                    motion_detected = 1;
                }
            }
        }

        if (motion_detected) {
            char filename[MAX_FILENAME];
            snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", IMAGE_DIR, (long)time(NULL));

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Error: Failed to capture image\n");
            } else {
                char payload[MAX_JSON];
                if (compose_json_payload(payload, sizeof(payload),
                                        filename, motion_detected, PIR_GPIO) != 0) {
                    fprintf(stderr, "Error: Failed to compose JSON payload\n");
                } else {
                    if (send_http_request(payload, filename) != 0) {
                        fprintf(stderr, "Error: Failed to send HTTP request\n");
                    } else {
                        printf("Motion detected on GPIO %d. Image saved to %s/motion_%ld.jpg\n",
                               PIR_GPIO, IMAGE_DIR, (long)time(NULL));
                    }
                }
            }
        }

        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_http_fd >= 0) {
        ghttp_cleanup();
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

