    if (sock < 0) {
        fprintf(stderr, "Error: socket() failed: %s\n", strerror(errno));
        return -1;
    }
    int reuse = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        fprintf(stderr, "Warning: setsockopt(SO_REUSEADDR) failed: %s\n", strerror(errno));
    }
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_HOST, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Error: inet_pton() failed for '%s'\n", HTTP_HOST);
        close(sock);
        return -1;
    }
    if (connect(sock, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Error: connect() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    if (send(sock, payload, strlen(payload), 0) < 0) {
        fprintf(stderr, "Error: send() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    if (send(sock, filename, strlen(filename), 0) < 0) {
        fprintf(stderr, "Error: send() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    int ret = recv(sock, NULL, 0, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: recv() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <PORT>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *ip_address = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }
    const char *http_host = "http://" ip_address ":" port "/upload";

    if (ensure_directory(IMAGE_DIR) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (g_http_fd >= 0) {
        close(g_http_fd);
        g_http_fd = -1;
    }

    if (ghttp_init() != 0) {
        fprintf(stderr, "Error: ghttp_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        int motion_detected = 0;
        int last_state = gpioRead(PIR_GPIO);
        if (last_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        for (int i = 0; i < DEBOUNCE_MS / POLL_MS && g_running; i++) {
            gpioDelay(POLL_MS * 1000);
            int current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                fprintf(stderr, "Error: gpioRead failed for GPIO %d\n", PIR_GPIO);
                break;
            }
            if (current_state != last_state) {
                last_state = current_state;
                if (current_state == 1) {
                    motion_detected = 1;
                }
            }
        }

        if (motion_detected) {
            char filename[MAX_FILENAME];
            snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", IMAGE_DIR, (long)time(NULL));

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Error: Failed to capture image\n");
            } else {
                char payload[MAX_JSON];
                if (compose_json_payload(payload, sizeof(payload),
                                        filename, motion_detected, PIR_GPIO) != 0) {
                    fprintf(stderr, "Error: Failed to compose JSON payload\n");
                } else {
                    if (send_http_request(payload, filename) != 0) {
                        fprintf(stderr, "Error: Failed to send HTTP request\n");
                    } else {
                        printf("Motion detected on GPIO %d. Image saved to %s/motion_%ld.jpg\n",
                               PIR_GPIO, IMAGE_DIR, (long)time(NULL));
                    }
                }
            }
        }

        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_http_fd >= 0) {
        ghttp_cleanup();
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

