#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN 17
#define IMAGES_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define DEBOUNCE_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 -n -p",
                       filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        log_message("Error: command buffer too small");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        log_message("Error: system() failed to launch raspistill");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "Error: raspistill failed with status %d", status);
        log_message(msg);
        return -1;
    }
    return 0;
}

static void generate_filename(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    snprintf(buf, len, "%04d%02d%02d_%02d%02d%02d_mmm.jpg",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_message("Error: gpiod_chip_open_by_name failed");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message("Error: gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "pir-motion-capture") < 0) {
        log_message("Error: gpiod_line_request_falling_edge_events failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        struct timespec ts = {0, DEBOUNCE_TIMEOUT_MS * 1000000L};
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            log_message("Error: gpiod_line_event_wait failed");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            log_message("Error: gpiod_line_event_read failed");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char filename[64];
            generate_filename(filename, sizeof(filename));
            char command[512];
            int rc = snprintf(command, sizeof(command),
                               "capture_image %s", filename);
            if (rc < 0 || (size_t)rc >= sizeof(command)) {
                log_message("Error: command buffer too small");
                continue;
            }
            int status = system(command);
            if (status == -1) {
                log_message("Error: system() failed to launch capture_image");
            } else if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "Error: capture_image failed with status %d", status);
                log_message(msg);
            } else {
                printf("Motion detected. Captured: %s\n", filename);
            }
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

