#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define WIDTH 200
#define HEIGHT 150

static volatile sig_atomic_t stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    printf("Streaming started. Waiting for frame...\n");

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            if (stop) {
                printf("Interrupted by signal.\n");
                goto cleanup;
            }
            continue;
        }
        perror("select");
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused < (int)WIDTH * (int)HEIGHT * 2) {
        fprintf(stderr, "Short frame: %d bytes\n", buf.bytesused);
        goto cleanup;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Frame dimensions mismatch: got %ux%u, expected %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height, WIDTH, HEIGHT);
        goto cleanup;
    }

    printf("Captured %ux%u YUYV frame\n", fmt.fmt.pix.width, fmt.fmt.pix.height);

    unsigned char *y = (unsigned char *)buffer;
    unsigned char *u = (unsigned char *)(buffer + WIDTH * HEIGHT);
    unsigned char *v = (unsigned char *)(buffer + WIDTH * HEIGHT + WIDTH * HEIGHT / 2);

    for (int i = 0; i < WIDTH * HEIGHT / 2; i++) {
        int y0 = y[i * 2];
        int u0 = u[i * 2];
        int y1 = y[i * 2 + 1];
        int v0 = v[i * 2];
        int v1 = v[i * 2 + 1];

        y[i * 2] = y1;
        u[i * 2] = u0;
        v[i * 2] = v0;
        v[i * 2 + 1] = v1;
    }

    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen");
        goto cleanup;
    }

    size_t written = fwrite(y, 1, WIDTH * HEIGHT, fp);
    if (written != (size_t)(WIDTH * HEIGHT)) {
        fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fclose(fp) == EOF) {
        perror("fclose");
        goto cleanup;
    }

    printf("Cropped frame written to %s\n", OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        if (buffer) {
            munmap(buffer, buf.length);
        }
        close(fd);
    }
    return ret;
}

