#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int duty_cycle = (int)(((float)angle / (float)SERVO_MAX_ANGLE) * (float)PWM_RANGE);
    if (gpioServo(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d (duty=%d)\n", pin, duty_cycle);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(PAN_SERVO_PIN, SERVO_MIN_ANGLE) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, SERVO_MIN_ANGLE) != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    int pan_angle = SERVO_MIN_ANGLE;
    int tilt_angle = SERVO_MIN_ANGLE;

    while (running) {
        int ch = getchar();
        if (ch == 'q' || ch == 'Q') {
            running = 0;
            break;
        }
        if (ch == '\n' || ch == '\r') continue;

        if (ch == 'w' || ch == 'W') {
            pan_angle += STEP_SIZE;
            if (pan_angle > SERVO_MAX_ANGLE) pan_angle = SERVO_MAX_ANGLE;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
                running = 0;
                break;
            }
        } else if (ch == 's' || ch == 'S') {
            pan_angle -= STEP_SIZE;
            if (pan_angle < SERVO_MIN_ANGLE) pan_angle = SERVO_MIN_ANGLE;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
                running = 0;
                break;
            }
        } else if (ch == 'a' || ch == 'A') {
            tilt_angle += STEP_SIZE;
            if (tilt_angle > SERVO_MAX_ANGLE) tilt_angle = SERVO_MAX_ANGLE;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                running = 0;
                break;
            }
        } else if (ch == 'd' || ch == 'D') {
            tilt_angle -= STEP_SIZE;
            if (tilt_angle < SERVO_MIN_ANGLE) tilt_angle = SERVO_MIN_ANGLE;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
                running = 0;
                break;
            }
        }

        gpioDelay(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

