static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_nibble(uint8_t nibble, uint8_t mode) {
    uint8_t high = (nibble & 0xF0) | mode;
    uint8_t low = ((nibble << 4) & 0xF0) | mode;
    gpioWrite(1, high);
    gpioWrite(2, low);
    gpioDelay(1);
    gpioWrite(1, low);
    gpioWrite(2, high);
    gpioDelay(1);
    return 0;
}

static int lcd_send_byte(uint8_t val, uint8_t mode) {
    gpioWrite(1, mode);
    gpioWrite(2, (val & 0xF0) | mode);
    gpioDelay(1);
    gpioWrite(1, mode);
    gpioWrite(2, ((val << 4) & 0xF0) | mode);
    gpioDelay(1);
    return 0;
}

