#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_EN 0x04
#define LCD_RW 0x02
#define LCD_RS 0x01

#define FLOW_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_PULSES 100000
#define PULSE_THRESHOLD 5
#define NO_FLOW_TIMEOUT_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int gpio_initialized = 0;
static int pulse_count = 0;
static uint32_t last_pulse_tick = 0;
static uint32_t last_sample_tick = 0;
static uint32_t last_alert_tick = 0;
static uint32_t last_alert_time = 0;
static bool alert_active = false;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_pulse_enable(uint8_t data) {
    if (i2c_handle < 0) return;
    i2cWriteByteData(i2c_handle, LCD_EN | LCD_RW | LCD_RS, data | LCD_BACKLIGHT);
    gpioDelay(1);
    i2cWriteByteData(i2c_handle, LCD_EN | LCD_RW | LCD_RS, data | LCD_BACKLIGHT);
    gpioDelay(100);
}

static void lcd_send_byte(uint8_t value) {
    if (i2c_handle < 0) return;
    i2cWriteByteData(i2c_handle, LCD_EN | LCD_RW | LCD_RS, value | LCD_BACKLIGHT);
    gpioDelay(1);
    i2cWriteByteData(i2c_handle, LCD_EN | LCD_RW | LCD_RS, value | LCD_BACKLIGHT);
    gpioDelay(100);
}

static void lcd_send_command(uint8_t cmd) {
    lcd_send_byte(cmd);
    gpioDelay(2000);
}

static void lcd_send_data(uint8_t data) {
    lcd_send_byte(data);
    gpioDelay(2000);
}

static void lcd_init(void) {
    if (i2c_handle < 0) return;
    gpioDelay(50000);
    lcd_send_byte(0x30);
    gpioDelay(5000);
    lcd_send_byte(0x30);
    gpioDelay(1000);
    lcd_send_byte(0x30);
    gpioDelay(1000);
    lcd_send_byte(0x20);
    gpioDelay(1000);
    lcd_send_byte(0x28);
    gpioDelay(1000);
    lcd_send_byte(0x08);
    gpioDelay(1000);
    lcd_send_byte(0x01);
    gpioDelay(2000);
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    lcd_send_command(LCD_CMD | LCD_LINE_1);
    lcd_send_byte(0x01);
    gpioDelay(2000);
    lcd_send_command(LCD_CMD | LCD_LINE_2);
    lcd_send_byte(0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(int line, int col) {
    if (i2c_handle < 0) return;
    uint8_t addr = (line == 0) ? (LCD_LINE_1 | col) : (LCD_LINE_2 | col);
    lcd_send_command(LCD_CMD | addr);
}

static void lcd_write_string(const char *str) {
    if (i2c_handle < 0) return;
    while (*str) {
        lcd_send_data((uint8_t)*str++);
    }
}

static void lcd_write_flow_rate(float flow_rate) {
    if (i2c_handle < 0) return;
    char buf[20];
    int len = snprintf(buf, sizeof(buf), "Flow Rate: %.2f L/min", flow_rate);
    lcd_set_cursor(0, 0);
    lcd_send_command(LCD_CMD | LCD_LINE_1);
    lcd_send_data((uint8_t)len);
    lcd_send_data('\n');
    lcd_send_data('\r');
    lcd_send_data(' ');
