#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_row(struct gpiod_line *line, int row, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error: failed to set row %d to %d: %s\n", row, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int set_col(struct gpiod_line *line, int col, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error: failed to set col %d to %d: %s\n", col, val, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(struct gpiod_chip *chip) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_set_value(chip->line_row[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_set_value(chip->line_col[i], 0);
    }
    gpiod_chip_close(chip);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *row_lines[NUM_ROWS];
    struct gpiod_line *col_lines[NUM_COLS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = NULL;
    }
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = NULL;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error: failed to get row line %u: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Error: failed to request row line %u as output: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error: failed to get col line %u: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Error: failed to request col line %u as output: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        for (int col = 0; col < NUM_COLS; col++) {
            for (int row = 0; row < NUM_ROWS; row++) {
                if (!running) break;
                if (set_row(row_lines[row], row, 1) < 0) goto cleanup;
                if (set_col(col_lines[col], col, 0) < 0) goto cleanup;
                usleep(800);
            }
        }

        for (int col = 0; col < NUM_COLS; col++) {
            for (int row = NUM_ROWS - 1; row >= 0; row--) {
                if (!running) break;
                if (set_row(row_lines[row], row, 1) < 0) goto cleanup;
                if (set_col(col_lines[col], col, 0) < 0) goto cleanup;
                usleep(800);
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip);
    return ret;
}

