/*
 * wave8.c — 8x8 common-anode LED matrix wave animation (v2 API)
 *
 * Build:  gcc -O2 -Wall -Wextra -o wave8 wave8.c -lgpiod
 * Run:    sudo ./wave8   (or ensure gpiochip0 access)
 *
 * Wiring (BCM numbering):
 *   Row anodes -> GPIO2,3,4,17,27,22,10,9
 *   Column cathodes -> GPIO14,15,18,23,24,25,8,7
 *   Common ground -> Pi GND
 *   Common supply -> 3.3 V (or 5 V if your matrix is 5 V)
 *
 * Common-anode:  HIGH = OFF, LOW = ON.
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define NUM_ROWS  8
#define NUM_COLS  8

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_all_rows(struct gpiod_line *rows, int all_high)
{
    for (int i = 0; i < NUM_ROWS; i++)
        if (gpiod_line_set_value(rows[i], all_high ? 1 : 0) < 0) {
            fprintf(stderr, "set_row failed: %s\n", strerror(errno));
            return -1;
        }
    return 0;
}

static int clear_matrix(struct gpiod_line *rows)
{
    return set_all_rows(rows, 0);
}

static int light_column(struct gpiod_line *cols, struct gpiod_line *rows,
                        int col, int wave)
{
    if (gpiod_line_set_value(cols[col], 0) < 0) {
        fprintf(stderr, "set_col failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(rows[wave], 1) < 0) {
        fprintf(stderr, "set_row failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rows = NULL;
    struct gpiod_line *cols = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    rows = gpiod_chip_get_line(chip, row_pins[0]);
    if (!rows) {
        fprintf(stderr, "get_row_line: %s\n", strerror(errno));
        goto cleanup;
    }
    for (int i = 1; i < NUM_ROWS; i++)
        rows[i] = gpiod_chip_get_line(chip, row_pins[i]);
    if (!rows) {
        fprintf(stderr, "get_row_lines: %s\n", strerror(errno));
        goto cleanup;
    }

    cols = gpiod_chip_get_line(chip, col_pins[0]);
    if (!cols) {
        fprintf(stderr, "get_col_line: %s\n", strerror(errno));
        goto cleanup;
    }
    for (int i = 1; i < NUM_COLS; i++)
        cols[i] = gpiod_chip_get_line(chip, col_pins[i]);
    if (!cols) {
        fprintf(stderr, "get_col_lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(rows, "wave8", 0) < 0) {
        fprintf(stderr, "request_rows: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(cols, "wave8", 1) < 0) {
        fprintf(stderr, "request_cols: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Wave animation started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int col = 0; col < NUM_COLS && running; col++) {
            if (clear_matrix(rows) < 0)
                goto cleanup;
            if (light_column(cols, rows, col, 0) < 0)
                goto cleanup;
            usleep(150000);
            if (light_column(cols, rows, col, 1) < 0)
                goto cleanup;
            usleep(150000);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (rows) gpiod_line_release_array(rows);
    if (cols) gpiod_line_release_array(cols);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

