/*
 * VL53L3CX multi-target Time-of-Flight distance reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L3CX SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   VL53L3CX SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   VL53L3CX VDD  -> 3.3 V
 *   VL53L3CX GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX constants (from ST datasheet) ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x29          /* default I2C address (SDO tied to GND) */

#define REG_MODEL_ID         0x010F
#define REG_SYSRANGE_START   0x0000
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE  0x0096

#define EXPECTED_MODEL_ID    0xEA          /* expected model ID for VL53L3CX */

/* ---- Program state ---- */
typedef struct {
    int  i2c_handle;
    int  pigpio_initialized;
    volatile sig_atomic_t terminate;
} ProgramState;

static ProgramState g_state = { .i2c_handle = -1, .pigpio_initialized = 0, .terminate = 0 };

/* ---- Helpers ---- */

static void timestamp_iso8601(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

static void signal_handler(int sig)
{
    (void)sig;
    g_state.terminate = 1;
}

/* ---- I2C helpers ---- */

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- Sensor initialization ---- */

static int vl53l3cx_init(int handle)
{
    uint8_t model_id = 0;

    /* Read model ID to verify sensor presence */
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "[ERROR] Unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("[INFO] VL53L3CX detected (model ID 0x%02X).\n", model_id);

