#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

/* MLX75031 register addresses (example values - adjust per datasheet) */
#define MLX75031_REG_DEVICE_ID 0x00
#define MLX75031_REG_DISTANCE 0x04
#define MLX75031_REG_CONFIG 0x08

#define MLX75031_DEVICE_ID_EXPECTED 0x1234

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x1234) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x1234: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint16_t device_id = 0;
    if (i2c_read_reg16(i2c_fd, MLX75031_REG_DEVICE_ID, &device_id) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (device_id != MLX75031_DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, MLX75031_DEVICE_ID_EXPECTED);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (i2c_write_reg8(i2c_fd, MLX75031_REG_CONFIG, 0x01) < 0) {
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance) {
    if (i2c_read_reg16(i2c_fd, MLX75031_REG_DISTANCE, distance) < 0) {
        return -1;
    }
    return 0;
}

static void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%u\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_sensor() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    printf("Starting MLX75031 distance logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        uint16_t distance = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_distance(&distance) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                usleep(10000);
            }
        }

        if (success) {
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    return 0;
}

