    running = 0;
}

static int log_proximity_detection(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED pin %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial sensor state on pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read sensor pin %d\n", SENSOR_PIN);
            break;
        }

        if (current_state == 0 && last_state == 1) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            if (!timeinfo) {
                fprintf(stderr, "Failed to get UTC time\n");
                break;
            }
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
                fprintf(stderr, "Failed to format timestamp\n");
                break;
            }

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED on pin %d\n", LED_PIN);
                break;
            }
            gpioDelay(LED_ON_TIME_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED on pin %d\n", LED_PIN);
                break;
            }

            if (log_proximity_detection(timestamp) != 0) {
                fprintf(stderr, "Failed to log proximity detection\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

