/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi Zero W.
 *
 * TRIGGER -> GPIO17 (BCM)
 * ECHO    -> GPIO27 (BCM) via 1k/2k voltage divider (3.3 V tolerant)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_logger hcsr04_logger.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdbool.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define ECHO_HALF_PERIOD  15      /* 15 us half-period => 30 us full */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define LOG_INTERVAL_S   60
#define DISTANCE_THRESHOLD_CM 15.0f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN LOW\n");
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure trigger is left LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  : distance in cm (valid reading)
 *   -1.0f : echo never went HIGH (sensor absent or wiring fault)
 *   -2.0f : echo stayed HIGH too long (timeout)
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Echo never went HIGH (timeout)\n");
            return -1.0f;
        }
        gpioDelay(100); /* 100 us granularity */
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Echo stayed HIGH too long (timeout)\n");
            return -2.0f;
        }
        gpioDelay(100);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us / 58.0f; /* cm */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance, bool water)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (distance < 0.0f) {
        fprintf(g_log, "%s, ERROR: sensor read failed\n", ts);
    } else {
        fprintf(g_log, "%s, Distance: %.2f cm, Water: %s\n",
                ts, distance, water ? "YES" : "NO");
    }
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* GPIO init */
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen("distance_log.txt", "a");
    if (g_log == NULL) {
        fprintf(stderr, "Failed to open distance_log.txt: %s\n", strerror(errno));
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 logger started. TRIGGER=GPIO%d, ECHO=GPIO%d. Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            log_distance(distance, false);
        } else {
            bool water = (distance < DISTANCE_THRESHOLD_CM);
            log_distance(distance, water);
            printf("Distance: %.2f cm  Water: %s\n",
                   distance, water ? "YES" : "NO");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpio_cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

