#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x5C
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

#define REG_ENABLE 0x80
#define REG_ATIME 0x81
#define REG_WTIME 0x83
#define REG_PTIME 0x84
#define REG_PDATA0 0x85
#define REG_PDATA1 0x86
#define REG_PDATA2 0x87
#define REG_RDATA0 0x88
#define REG_RDATA1 0x89
#define REG_GDATA0 0x8A
#define REG_GDATA1 0x8B
#define REG_BDATA0 0x8C
#define REG_BDATA1 0x8D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int apds9960_init(int handle) {
    if (i2cWriteByteData(handle, REG_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ENABLE register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, REG_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ATIME register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, REG_WTIME, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write WTIME register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, REG_PTIME, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PTIME register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, REG_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write ENABLE register\n");
        return -1;
    }
    return 0;
}

static int apds9960_read_proximity(int handle, int *proximity) {
    int p0 = i2cReadByteData(handle, REG_PDATA0);
    int p1 = i2cReadByteData(handle, REG_PDATA1);
    int p2 = i2cReadByteData(handle, REG_PDATA2);
    if (p0 < 0 || p1 < 0 || p2 < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }
    *proximity = (p0 << 16) | (p1 << 8) | p2;
    return 0;
}

static int apds9960_read_rgb(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    int r0 = i2cReadByteData(handle, REG_RDATA0);
    int r1 = i2cReadByteData(handle, REG_RDATA1);
    int g0 = i2cReadByteData(handle, REG_GDATA0);
    int g1 = i2cReadByteData(handle, REG_GDATA1);
    int b0 = i2cReadByteData(handle, REG_BDATA0);
    int b1 = i2cReadByteData(handle, REG_BDATA1);
    if (r0 < 0 || r1 < 0 || g0 < 0 || g1 < 0 || b0 < 0 || b1 < 0) {
        fprintf(stderr, "Error: Failed to read RGB data\n");
        return -1;
    }
    *r = (r0 << 8) | r1;
    *g = (g0 << 8) | g1;
    *b = (b0 << 8) | b1;
    return 0;
}

static void log_data(FILE *fp, int proximity, uint16_t r, uint16_t g, uint16_t b) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            r, g, b, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, APDS9960_ADDR);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,R,G,B,Proximity\n");
        fflush(log_file);
    }

    printf("APDS9960 proximity logger started. Press Ctrl+C to exit.\n");

    while (running) {
        int proximity = 0;
        uint16_t r = 0, g = 0, b = 0;

        if (apds9960_read_proximity(i2c_handle, &proximity) < 0) {
            fprintf(stderr, "Error: Failed to read proximity data. Re-initializing sensor.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to reopen I2C bus. Exiting.\n");
                break;
            }
            if (apds9960_init(i2c_handle) < 0) {
                fprintf(stderr, "Error: APDS9960 re-initialisation failed. Exiting.\n");
                break;
            }
            continue;
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            if (apds9960_read_rgb(i2c_handle, &r, &g, &b) < 0) {
                fprintf(stderr, "Error: Failed to read RGB data. Continuing.\n");
            } else {
                log_data(log_file, proximity, r, g, b);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

