#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define REG_PART_ID     0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE  0x08
#define REG_PS1_DATA0  0x22
#define REG_PS1_DATA1  0x23
#define REG_PS1_DATA2  0x24
#define REG_PS1_DATA3  0x25
#define HW_KEY_VAL     0x17

#define SAMPLE_PERIOD_MS 100
#define CSV_FILE_NAME    "heartrate.csv"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1182(int fd)
{
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != 0x82) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_HW_KEY, HW_KEY_VAL) < 0)
        return -1;

    /* Si1182-A-GMR: 100 ms measurement rate */
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x0A) < 0)
        return -1;

    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, REG_PS1_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA1, &hi) < 0)
        return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int calculate_bpm(uint16_t prox)
{
    /* Placeholder: replace with a real heart-rate algorithm */
    return (int)(prox * 2);
}

static int log_bpm(FILE *fp, int bpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        goto cleanup;
    }

    fp = fopen(CSV_FILE_NAME, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("Logging heart rate to %s. Press Ctrl+C to stop.\n", CSV_FILE_NAME);

    while (g_running) {
        uint16_t prox = 0;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        } else {
            int bpm = calculate_bpm(prox);
            if (log_bpm(fp, bpm) < 0) {
                fprintf(stderr, "Error logging BPM\n");
                break;
            }
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

