#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define CH101_I2C_ADDR 0x60
#define TRIGGER_PIN 8
#define SAMPLE_INTERVAL_US 200000
#define TRIGGER_DELAY_US 50000
#define LOG_FILE "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

static int init_sensor(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write trigger pin low\n");
        return -1;
    }
    if (i2cOpen(I2C_BUS, CH101_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X)\n", CH101_I2C_ADDR);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    char buf[2];
    int rc;

    rc = i2cWriteByte(i2c_handle, 0x01);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C trigger write failed (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(TRIGGER_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void log_data(uint16_t distance_mm) {
    char timestamp[20];
    get_timestamp(timestamp, sizeof(timestamp));

    if (log_file) {
        fprintf(log_file, "%s, %u\n", timestamp, distance_mm);
        fflush(log_file);
    }
    printf("%s, %u\n", timestamp, distance_mm);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_sensor() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        uint16_t distance_mm;
        if (read_distance(&distance_mm) == 0) {
            log_data(distance_mm);
        } else {
            fprintf(stderr, "Warning: distance read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

