/*
 * Raspberry Pi Zero W - TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 *
 * Reads distance from the ICU-20201 on I2C bus 1, samples every 100 ms,
 * lights an LED on GPIO 17 when distance < 20 cm, and logs to
 * distance_log.txt.
 *
 * Build: gcc -O2 -Wall -o distance_monitor distance_monitor.c -lpigpio -lrt
 * Run:   sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define I2C_ADDR             0x29
#define LED_GPIO             17
#define DISTANCE_THRESHOLD   20.0f   /* cm */
#define SAMPLE_INTERVAL_US   100000  /* 100 ms */
#define LOG_FILE             "distance_log.txt"

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE         0x00
#define REG_RANGE_CONFIG     0x01
#define REG_MODE_CONFIG      0x02
#define REG_SYSTEM_CONFIG    0x03
#define REG_INT_CONFIG       0x04
#define REG_INT_STATUS       0x05
#define REG_RESET            0x07

/* Range config: 0x0000 = 1 cm to 3 m, 0x0001 = 1 cm to 6 m */
#define RANGE_CONFIG_1CM6M  0x0001
#define RANGE_CONFIG_1CM3M  0x0000

/* Mode config: 0x00 = continuous measurement */
#define MODE_CONFIG_CONTINUOUS 0x00

/* System config: 0x00 = normal operation */
#define SYSTEM_CONFIG_NORMAL   0x00

/* Interrupt config: 0x00 = no interrupt on new sample */
#define INT_CONFIG_NO_INTERRUPT 0x00

/* Expected interrupt status: bit 0 = new sample ready */
#define INT_STATUS_NEW_SAMPLE  0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_gpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_i2c_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring and sensor presence.\n",
                g_i2c_handle);
        return -1;
    }

    /* Reset the sensor */
    if (i2c_write_reg16(g_i2c_handle, REG_RESET, 0x0001) != 0) {
        fprintf(stderr, "Error: Sensor reset failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset delay */

    /* Configure range: 1 cm to 6 m */
    if (i2c_write_reg16(g_i2c_handle, REG_RANGE_CONFIG, RANGE_CONFIG_1CM6M) != 0) {
        fprintf(stderr, "Error: Range config failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Configure mode: continuous measurement */
    if (i2c_write_reg16(g_i2c_handle, REG_MODE_CONFIG, MODE_CONFIG_CONTINUOUS) != 0) {
        fprintf(stderr, "Error: Mode config failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Configure system: normal operation */
    if (i2c_write_reg16(g_i2c_handle, REG_SYSTEM_CONFIG, SYSTEM_CONFIG_NORMAL) != 0) {
        fprintf(stderr, "Error: System config failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Configure interrupt: no interrupt on new sample */
    if (i2c_write_reg16(g_i2c_handle, REG_INT_CONFIG, INT_CONFIG_NO_INTERRUPT) != 0) {
        fprintf(stderr, "Error: Interrupt config failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (cm)                                                  */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint16_t raw;
    int16_t distance_raw;

    if (i2c_read_reg16(g_i2c_handle, REG_DISTANCE, &raw) != 0) {
        return -1.0f;
    }

    /* Distance is returned in 16-bit units; convert to cm */
    distance_raw = (int16_t)raw;
    return (float)distance_raw / 100.0f;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                         */
/* ------------------------------------------------------------------ */
static int init_gpio_led(void)
{
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", LED_GPIO);
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for GPIO %d\n", LED_GPIO);
        return -1;
    }
    g_gpio_initialized = 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_gpio_initialized) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        g_gpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio_led() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];

        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        printf("%s  Distance: %.2f cm\n", timestamp, distance);

        if (distance < DISTANCE_THRESHOLD) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed for LED\n");
            }
        } else {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed for LED\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

