    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio_led() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];

        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        printf("%s  Distance: %.2f cm\n", timestamp, distance);

        if (distance < DISTANCE_THRESHOLD) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed for LED\n");
            }
        } else {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed for LED\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

