#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define MAX_DISTANCE_MM 2000
#define POLL_DELAY_US 50000

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define ICU20201_REG_WHO_AM_I 0x00
#define ICU20201_REG_DISTANCE 0x04
#define ICU20201_REG_MODE    0x08
#define ICU20201_REG_RANGE   0x0A
#define ICU20201_REG_POWER   0x0C
#define ICU20201_REG_RESET   0x0E

#define ICU20201_WHO_AM_I_VAL 0x82

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, 0x63, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x63: %d\n", I2C_BUS, i2c_handle);
        return -1;
    }
    return 0;
}

static int verify_sensor(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg16(i2c_handle, ICU20201_REG_WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, ICU20201_WHO_AM_I_VAL);
        return -1;
    }
    printf("ICU-20201 detected (WHO_AM_I = 0x%02X)\n", who_am_i);
    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    uint8_t buf[2];
    if (i2c_read_reg16(i2c_handle, ICU20201_REG_DISTANCE, buf, 2) < 0) {
        fprintf(stderr, "Error reading distance register\n");
        return -1;
    }
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_distance(uint16_t distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    }
    fclose(fp);
}

static void control_led(uint16_t distance_mm) {
    if (distance_mm < DEFAULT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }
    printf("Using distance threshold: %d mm\n", threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("Starting distance monitoring (threshold=%d mm)...\n", threshold);

    while (running) {
        uint16_t distance_mm = 0;
        if (read_distance(&distance_mm) == 0) {
            log_distance(distance_mm);
            control_led(distance_mm);
            printf("Distance: %u mm\n", distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

