    if (i2c_read_reg16(i2c_handle, ICU20201_REG_DISTANCE, buf, 2) < 0) {
        fprintf(stderr, "Error reading distance register\n");
        return -1;
    }
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_distance(uint16_t distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    }
    fclose(fp);
}

static void control_led(uint16_t distance_mm) {
    if (distance_mm < DEFAULT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }
    printf("Using distance threshold: %d mm\n", threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return 1;
    }

    printf("Starting distance monitoring (threshold=%d mm)...\n", threshold);

    while (running) {
        uint16_t distance_mm = 0;
        if (read_distance(&distance_mm) == 0) {
            log_distance(distance_mm);
            control_led(distance_mm);
            printf("Distance: %u mm\n", distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

