#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "intrusion_log.txt"
#define SAMPLES_PER_CYCLE 10
#define CYCLE_DELAY_MS  100
#define MEAS_DELAY_MS   10
#define DISTANCE_THRESHOLD_MM 1000
#define MAX_DISTANCE_MM  2000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm)
{
    uint8_t cmd[4] = {0x01, 0x02, 0x03, 0x04};
    uint8_t data[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_data(fd, data, sizeof(data)) != 0)
        return -1;

    if (data[0] != 0x01) {
        fprintf(stderr, "Sensor not responding (header mismatch: 0x%02X)\n", data[0]);
        return -1;
    }

    uint16_t dist_raw = ((uint16_t)data[11] << 8) | data[12];
    *distance_mm = dist_raw;
    return 0;
}

static float calculate_average_distance(int fd, int num_samples)
{
    float sum = 0.0f;
    int valid = 0;

    for (int i = 0; i < num_samples && g_running; i++) {
        int dist;
        if (read_distance(fd, &dist) == 0) {
            sum += dist;
            valid++;
        }
        usleep(CYCLE_DELAY_MS * 1000);
    }

    if (valid == 0)
        return -1.0f;

    return sum / (float)valid;
}

static int log_intrusion(float avg_distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", ts, avg_distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, 0x50) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x50: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float avg = calculate_average_distance(fd, SAMPLES_PER_CYCLE);

        if (avg < 0.0f) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else if (avg < DISTANCE_THRESHOLD_MM) {
            printf("Intrusion detected! Average distance: %.2f mm\n", avg);
            if (log_intrusion(avg) != 0) {
                fprintf(stderr, "Failed to log intrusion.\n");
            }
        } else {
            printf("Distance: %.2f mm (within %d mm threshold)\n", avg, DISTANCE_THRESHOLD_MM);
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    if (log_fp)
        fclose(log_fp);
    return ret;
}

