static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

