 * Detects a sensor-absent condition (NACK on the initial write).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60

/* Si1182 register addresses (example subset) */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to a Si1182 register.
 * Returns 0 on success, -1 on error.
 */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1182 register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si1182_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg, &lo) < 0)
        return -1;
    if (si1182_read_reg(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Initialize the Si1182 sensor.
 * Returns 0 on success, -1 on error.
 */
static int si1182_init(int fd)
{
    /* Example initialization sequence (replace with your specific
     * application-specific configuration). */
    if (si1182_write_reg(fd, SI1182_REG_HW_KEY, 0x00) < 0)
        return -1;
    if (si1182_write_reg(fd, SI1182_REG_PART_ID, 0x00) < 0)
        return -1;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si1182 slave address */
    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe the sensor: a NACK on the initial write indicates the device
     * is not present or not responding. */
    if (si1182_write_reg(fd, SI1182_REG_PART_ID, 0x00) < 0) {
        fprintf(stderr, "Si1182 not responding on 0x%02X (NACK).\n",
                SI1182_ADDR);
        goto cleanup;
    }

    /* Initialize the sensor */
    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        goto cleanup;
    }

    printf("Si1182 proximity logger started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t prox = 0;
        if (si1182_read_word(fd, SI1182_REG_ALS_VIS_DATA0, &prox) < 0) {
            fprintf(stderr, "Error reading proximity data.\n");
        } else {
            printf("Proximity: %u\n", prox);
        }
        usleep(500000); /* 500 ms */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

