#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x1E
#define READ_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit big-endian value from the MLX75030.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_distance(int fd, uint16_t *out)
{
    uint8_t buf[2];

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, sizeof(buf));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    /* Verify the sensor is present by reading the device ID register (0x00). */
    uint8_t id_buf[1];
    ssize_t n = read(fd, id_buf, sizeof(id_buf));
    if (n != (ssize_t)sizeof(id_buf)) {
        if (n < 0)
            fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                    MLX75030_ADDR, strerror(errno));
        else
            fprintf(stderr, "Sensor not responding at 0x%02X: short read\n",
                    MLX75030_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 detected at 0x%02X\n", MLX75030_ADDR);
    fflush(stdout);

    while (g_running) {
        uint16_t distance;

        if (read_distance(fd, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        /* Sleep 500 ms in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 5 && g_running; i++)
            usleep(100000);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

