#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3101_I2C_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_MS 500

/* OPT3101 register addresses */
#define REG_DEVICE_ID 0x00
#define REG_MEAS_RATE 0x01
#define REG_CH0_DATA 0x0C
#define REG_CH0_DATA_LSB 0x0D
#define REG_CH0_DATA_MSB 0x0E
#define REG_CH0_DATA_ERROR 0x0F
#define REG_AMBIENT_DATA 0x10
#define REG_AMBIENT_DATA_LSB 0x11
#define REG_AMBIENT_DATA_MSB 0x12
#define REG_AMBIENT_DATA_ERROR 0x13

#define OPT3101_DEVICE_ID 0x3101

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int opt3101_init(int fd) {
    uint8_t device_id = 0;
    if (i2c_read_reg8(fd, REG_DEVICE_ID, &device_id) != 0) {
        return -1;
    }
    if (device_id != OPT3101_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", device_id, OPT3101_DEVICE_ID);
        return -1;
    }
    printf("OPT3101 detected (device ID: 0x%02X)\n", device_id);

    /* Set measurement rate to 100 ms (0x0A) */
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x0A) != 0) {
        return -1;
    }
    return 0;
}

static int opt3101_read_distance(int fd, uint16_t *distance, uint16_t *ambient, bool *error) {
    uint8_t ch0_lsb = 0, ch0_msb = 0, ch0_err = 0, amb_lsb = 0, amb_msb = 0, amb_err = 0;

    if (i2c_read_reg8(fd, REG_CH0_DATA_LSB, &ch0_lsb) != 0) return -1;
    if (i2c_read_reg8(fd, REG_CH0_DATA_MSB, &ch0_msb) != 0) return -1;
    if (i2c_read_reg8(fd, REG_CH0_DATA_ERROR, &ch0_err) != 0) return -1;
    if (i2c_read_reg8(fd, REG_AMBIENT_DATA_LSB, &amb_lsb) != 0) return -1;
    if (i2c_read_reg8(fd, REG_AMBIENT_DATA_MSB, &amb_msb) != 0) return -1;
    if (i2c_read_reg8(fd, REG_AMBIENT_DATA_ERROR, &amb_err) != 0) return -1;

    *error = (ch0_err != 0) || (amb_err != 0);

    if (*error) {
        *distance = 0;
        *ambient = 0;
        return -1;
    }

    *distance = (uint16_t)((ch0_msb << 8) | ch0_lsb);
    *ambient = (uint16_t)((amb_msb << 8) | amb_lsb);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3101_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OPT3101_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (opt3101_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting distance measurements (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0, ambient = 0;
        bool error = false;

        if (opt3101_read_distance(g_i2c_fd, &distance, &ambient, &error) != 0) {
            fprintf(stderr, "Error reading distance/ambient data\n");
        } else {
            printf("Distance: %u mm, Ambient: %u, Error: %s\n",
                   distance, ambient, error ? "true" : "false");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

