/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   GPIO17 (BCM) -> HC-SR04 TRIG pin (pin 11)
 *   GPIO18 (BCM) -> HC-SR04 ECHO pin (pin 13)
 *
 * Note: HC-SR04 operates at 5 V; the Pi GPIO is only 3.3 V tolerant.
 *       A 1 kΩ resistor is required on the echo line to provide
 *       microsecond-precision timing.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait           */
#define ECHO_TIMEOUT_US2 200000      /* 200 ms max echo wait (2nd edge) */
#define SAMPLE_PERIOD_US 1000000     /* 1 s between samples            */
#define MIN_DISTANCE_CM  2.0f         /* HC-SR04 minimum range          */
#define MAX_DISTANCE_CM  400.0f       /* HC-SR04 maximum range          */
#define MAX_PULSE_US     38000       /* ~400 cm round-trip timeout    */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_us(unsigned us)
{
    while (us > 0 && g_running) {
        unsigned chunk = (us > 100000) ? 100000 : us;
        gpioDelay(chunk);
        us -= chunk;
    }
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on invalid pulse.
 */
static int measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* --- Wait for echo rising edge (timeout) --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (g_running) {
        int level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on echo pin\n");
            return -1;
        }
        if (level == 1) {
            start_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Echo rising-edge timeout\n");
            return -1;
        }
        sleep_us(10);
    }

    if (!g_running) return -1;

    /* --- Wait for echo falling edge (timeout) --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US2;
    while (g_running) {
        int level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on echo pin\n");
            return -1;
        }
        if (level == 0) {
            end_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Echo falling-edge timeout\n");
            return -1;
        }
        sleep_us(10);
    }

    if (!g_running) return -1;

    /* --- Validate pulse duration --- */
    if (end_tick == 0 || start_tick == 0) {
        fprintf(stderr, "Invalid echo tick (0) — pulse not received\n");
        return -2;
    }
    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Pulse duration %.0f µs exceeds max (%d µs) — out of range\n",
                pulse_us, MAX_PULSE_US);
        return -2;
    }
    return (int)pulse_us;
}

static float calculate_distance_cm(int pulse_us)
{
    if (pulse_us <= 0) {
        return -1.0f;
    }
    return (float)pulse_us / 58.0f;
}

static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance_cm < 0.0f) {
        printf("[%s] ERROR: Invalid distance reading\n", timestamp);
    } else {
        printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* pigpio API call                                                      */
/* ------------------------------------------------------------------ */
static int trigger_pulse(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on trigger pin\n");
        return -1;
    }
    sleep_us(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed on trigger pin\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed on trigger pin (init)\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    sleep_us(500000);

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: BCM GPIO%d | Echo: BCM GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (trigger_pulse() < 0) {
            fprintf(stderr, "Trigger pulse failed — continuing\n");
            sleep_us(SAMPLE_PERIOD_US);
            continue;
        }

        int pulse_us = measure_echo_us();
        if (pulse_us < 0) {
            if (pulse_us == -1) {
                fprintf(stderr, "Echo timeout — sensor absent or not responding\n");
            } else {
                fprintf(stderr, "Invalid pulse duration — out of range\n");
            }
        } else {
            float distance = calculate_distance_cm(pulse_us);
            log_distance(distance);
        }

        sleep_us(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

