#define LOG_FILE "intrusion_log.csv"
#define BUFFER_SIZE 256
#define FRAME_HEADER_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define RANGE_BINS 64

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_frame(int fd, uint8_t *buffer, size_t max_len) {
    size_t total = 0;
    while (total < max_len) {
        ssize_t n = read(fd, buffer + total, max_len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return 0;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            return 0;
        }
        total += (size_t)n;
    }
    return 1;
}

static int log_intrusion(FILE *fp, float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void activate_alert(int gpio_pin, int duration_ms) {
    if (gpio_pin < 0 || duration_ms <= 0) {
        return;
    }
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error activating alert LED on GPIO %d\n", gpio_pin);
        return;
    }
    usleep(duration_ms * 1000);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error deactivating alert LED on GPIO %d\n", gpio_pin);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        close(uart_fd);
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        close(uart_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        close(uart_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
        fflush(log_file);
    }

    uint8_t frame_buffer[FRAME_HEADER_SIZE + RANGE_PROFILE_SIZE];
    memset(frame_buffer, 0, sizeof(frame_buffer));

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_uart_frame(uart_fd, frame_buffer, sizeof(frame_buffer)) != 1) {
            if (!running) {
                break;
            }
            usleep(10000);
            continue;
        }

        if (frame_buffer[0] != 0x01 || frame_buffer[1] != 0x02 || frame_buffer[2] != 0x03 || frame_buffer[3] != 0x04) {
            fprintf(stderr, "Invalid magic word: 0x%02X 0x%02X 0x%02X 0x%02X\n", frame_buffer[0], frame_buffer[1], frame_buffer[2], frame_buffer[3]);
            continue;
        }

        if (frame_buffer[4] != 0x05 || frame_buffer[5] != 0x06 || frame_buffer[6] != 0x07 || frame_buffer[7] != 0x08) {
            fprintf(stderr, "Invalid magic word: 0x%02X 0x%02X 0x%02X 0x%02X\n", frame_buffer[4], frame_buffer[5], frame_buffer[6], frame_buffer[7]);
            continue;
        }

        size_t data_length = RANGE_PROFILE_SIZE;
        memcpy(frame_buffer + FRAME_HEADER_SIZE, frame_buffer + 8, data_length);

        uint16_t distance_bins[RANGE_BINS];
        for (int i = 0; i < RANGE_BINS; i++) {
            distance_bins[i] = (uint16_t)((frame_buffer[8 + i * 2] << 8) | frame_buffer[8 + i * 2 + 1]);
        }

        for (int i = 0; i < RANGE_BINS; i++) {
            if (distance_bins[i] > 0 && distance_bins[i] < DISTANCE_THRESHOLD) {
                printf("Target detected at distance: %.2f meters\n", (float)distance_bins[i]);
                if (log_intrusion(log_file, (float)distance_bins[i]) != 0) {
                    fprintf(stderr, "Error logging intrusion\n");
                }
                activate_alert(GPIO_PIN, ALERT_DURATION_MS);
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

