/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic ToF sensor monitor
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   Alert LED     -> GPIO 17 (BCM) via ~330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o chirp_monitor chirp_monitor.c -lpigpio -lrt
 *   (or with pigpio daemon if running in production environment)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x29          /* ICU-20201 default I2C address */
#define ALERT_GPIO           17            /* BCM pin for alert output */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define LOG_FILE             "distance_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  init_i2c(void);
static int  read_distance(float *distance_cm);
static int  log_distance(float distance_cm);
static void trigger_alert(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Read distance (raw bytes) ------------------- */
/*
 * The ICU-20201 returns a 16-bit big-endian distance measurement.
 * A zero value typically indicates a read error or sensor absence.
 */
static int read_distance(float *distance_cm)
{
    char buf[2] = {0, 0};

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_cm = (float)raw / 10.0f;   /* cm per datasheet */
    return 0;
}

/* --------------------------- Log distance with timestamp ----------------- */
static int log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

/* --------------------------- Trigger alert (GPIO) ------------------------- */
static void trigger_alert(void)
{
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(ALERT, 1) failed\n");
    }
    gpioDelay(500000);   /* 500 ms alert pulse */
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(ALERT, 0) failed\n");
    }
}

/* --------------------------- Cleanup / signal ----------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* gpioTerminate is safe to call even if pigpio was not loaded */
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);   /* start with alert off */

    /* --- I2C init --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("Chirp ICU-20201 monitoring started.\n");
    printf("  I2C bus %d, address 0x%02X, alert GPIO %d, threshold %.1f cm\n",
           I2C_BUS, I2C_ADDR, ALERT_GPIO, DISTANCE_THRESHOLD);
    printf("  Logging to %s every 100 ms. Press Ctrl-C to exit.\n\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }

            if (distance < DISTANCE_THRESHOLD) {
                trigger_alert();
            }
        } else {
            fprintf(stderr, "[WARN] Distance read failed; skipping alert.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

