static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int read_reg16_u16(int handle, uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (read_reg16(handle, reg, buf) < 0) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

