/*
 * CH201 ultrasonic distance reader with LED blink frequency control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: TDK InvenSense CH201
 * LED:    GPIO18 (BCM) via 330 ohm resistor to 3.3 V
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x60          /* CH201 default I2C address (ADDR pin low) */
#define LED_GPIO             18            /* BCM pin for the LED */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000          /* 10 ms between retries */
#define LED_HALF_CYCLE_US    50000          /* 50 ms half-cycle per iteration */
#define LED_ON_TIME_US       25000          /* 25 ms on time */
#define LED_OFF_TIME_US      25000          /* 25 ms off time */
#define MAX_DISTANCE_CM      100.0f         /* CH201 rated max range ~100 cm */
#define MIN_DISTANCE_CM      2.0f           /* CH201 minimum measurable ~2 cm */
#define I2C_READ_LEN         2
#define I2C_WRITE_LEN        1

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE         0x00
#define REG_MODE             0x01
#define REG_RANGE            0x02
#define REG_POWER            0x03
#define REG_INT_EN           0x04
#define REG_INT_CFG          0x05
#define REG_INT_STATUS       0x06
#define REG_INT_CLEAR        0x07

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg(uint8_t reg, uint8_t val);
static int  i2c_read_reg(uint8_t reg, uint8_t *buf, uint8_t len);
static int  ch201_init(void);
static int  ch201_read_distance(float *distance_cm);
static void led_blink(void);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[I2C_WRITE_LEN];
    buf[0] = (char)reg;
    buf[1] = (char)val;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteDevice(g_i2c_handle, buf, I2C_WRITE_LEN);
        if (rc == I2C_WRITE_DEVICE_SUCCESS)
            return 0;
        fprintf(stderr, "[WARN] I2C write 0x%02X -> 0x%02X failed (attempt %d/%d): %s\n",
                reg, val, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint8_t len)
{
    char cmd[I2C_WRITE_LEN];
    char data[I2C_READ_LEN];

    cmd[0] = (char)reg;
    cmd[1] = 0x00;                 /* dummy write to set register pointer */

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteDevice(g_i2c_handle, cmd, I2C_WRITE_LEN) != I2C_WRITE_DEVICE_SUCCESS) {
            fprintf(stderr, "[WARN] I2C write pointer 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (i2cReadDevice(g_i2c_handle, data, I2C_READ_LEN) != I2C_READ_DEVICE_SUCCESS) {
            fprintf(stderr, "[WARN] I2C read 0x%02X (%u bytes) failed (attempt %d/%d): %s\n",
                    reg, len, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        memcpy(buf, data, len);
        return 0;
    }
    return -1;
}

/* ----------------------------- Sensor driver ------------------------------ */
static int ch201_init(void)
{
    /* Power on and enter standby mode */
    if (i2c_write_reg(REG_POWER, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: power write failed\n");
        return -1;
    }
    gpioDelay(10000);                 /* 10 ms settle */

    /* Clear any pending interrupts */
    if (i2c_write_reg(REG_INT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: clear interrupt failed\n");
        return -1;
    }

    /* Set measurement mode */
    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: mode write failed\n");
        return -1;
    }

    /* Set range to 1 cm (0x00 = 1 cm resolution) */
    if (i2c_write_reg(REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: range write failed\n");
        return -1;
    }

    /* Disable interrupts */
    if (i2c_write_reg(REG_INT_EN, 0x00) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: interrupt enable failed\n");
        return -1;
    }

    /* Clear any pending interrupts */
    if (i2c_write_reg(REG_INT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: clear interrupt failed\n");
        return -1;
    }

    return 0;
}

static int ch201_read_distance(float *distance_cm)
{
    uint8_t data[I2C_READ_LEN];

    /* Trigger a single measurement */
    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 read: mode write failed\n");
        return -1;
    }

    /* Poll for data ready (INT_STATUS bit 0) */
    for (int i = 0; i < 50; ++i) {
        if (i2c_read_reg(REG_INT_STATUS, &data[0], I2C_READ_LEN) != 0) {
            fprintf(stderr, "[ERROR] CH201 read: data-ready poll failed\n");
            return -1;
        }
        if (data[0] & 0x01) {
            break;
        }
        gpioDelay(2000);                 /* 2 ms */
    }

    if (!(data[0] & 0x01)) {
        fprintf(stderr, "[ERROR] CH201 read: measurement timeout\n");
        return -1;
    }

    /* Read 2-byte distance result (big-endian) */
    if (i2c_read_reg(REG_DISTANCE, data, I2C_READ_LEN) != 0) {
        fprintf(stderr, "[ERROR] CH201 read: distance read failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *distance_cm = (float)raw / 100.0f;   /* raw is in mm */
    return 0;
}

/* ----------------------------- LED helpers -------------------------------- */
static void led_blink(void)
{
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_TIME_US);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(LED_OFF_TIME_US);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (ch201_init() != 0) {
        fprintf(stderr, "[FATAL] CH201 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started. Press Ctrl+C to exit.\n");
    printf("I2C bus %d, address 0x%02X, LED on GPIO%d\n", I2C_BUS, I2C_ADDR, LED_GPIO);

    while (g_running) {
        float distance;

        if (ch201_read_distance(&distance) == 0) {
            int led_freq = (int)(1.0f / distance);
            if (led_freq < 1) led_freq = 1;
            if (led_freq > 100) led_freq = 100;

            printf("Distance: %.2f cm  ->  LED blink frequency: %d Hz\n", distance, led_freq);

            led_blink();
        } else {
            fprintf(stderr, "[WARN] Read failed; continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

