    gpioDelay(10000);                 /* 10 ms settle */

    /* Clear any pending interrupts */
    if (i2c_write_reg(REG_INT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: clear interrupt failed\n");
        return -1;
    }

    /* Set measurement mode */
    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: mode write failed\n");
        return -1;
    }

    /* Set range to 1 cm (0x00 = 1 cm resolution) */
    if (i2c_write_reg(REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: range write failed\n");
        return -1;
    }

    /* Disable interrupts */
    if (i2c_write_reg(REG_INT_EN, 0x00) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: interrupt enable failed\n");
        return -1;
    }

    /* Clear any pending interrupts */
    if (i2c_write_reg(REG_INT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 init: clear interrupt failed\n");
        return -1;
    }

    return 0;
}

static int ch201_read_distance(float *distance_cm)
{
    uint8_t data[I2C_READ_LEN];

    /* Trigger a single measurement */
    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "[ERROR] CH201 read: mode write failed\n");
        return -1;
    }

    /* Poll for data ready (INT_STATUS bit 0) */
    for (int i = 0; i < 50; ++i) {
        if (i2c_read_reg(REG_INT_STATUS, &data[0], I2C_READ_LEN) != 0) {
            fprintf(stderr, "[ERROR] CH201 read: data-ready poll failed\n");
            return -1;
        }
        if (data[0] & 0x01) {
            break;
        }
        gpioDelay(2000);                 /* 2 ms */
    }

    if (!(data[0] & 0x01)) {
        fprintf(stderr, "[ERROR] CH201 read: measurement timeout\n");
        return -1;
    }

    /* Read 2-byte distance result (big-endian) */
    if (i2c_read_reg(REG_DISTANCE, data, I2C_READ_LEN) != 0) {
        fprintf(stderr, "[ERROR] CH201 read: distance read failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *distance_cm = (float)raw / 100.0f;   /* raw is in mm */
    return 0;
}

/* ----------------------------- LED helpers -------------------------------- */
static void led_blink(void)
{
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_TIME_US);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(LED_OFF_TIME_US);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (ch201_init() != 0) {
        fprintf(stderr, "[FATAL] CH201 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started. Press Ctrl+C to exit.\n");
    printf("I2C bus %d, address 0x%02X, LED on GPIO%d\n", I2C_BUS, I2C_ADDR, LED_GPIO);

    while (g_running) {
        float distance;

        if (ch201_read_distance(&distance) == 0) {
            int led_freq = (int)(1.0f / distance);
            if (led_freq < 1) led_freq = 1;
            if (led_freq > 100) led_freq = 100;

            printf("Distance: %.2f cm  ->  LED blink frequency: %d Hz\n", distance, led_freq);

            led_blink();
        } else {
            fprintf(stderr, "[WARN] Read failed; continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

