                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_read_distance(int fd, int *distance_mm)
{
    uint8_t status;
    if (i2c_read_reg8(fd, MEAS_STATUS_REG, &status) < 0)
