#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static int read_distance(int handle, uint16_t *distance) {
    char cmd[2] = {0x80, 0x00};
    char data[2] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(10000);

        if (i2cReadDevice(handle, data, 2) != 2) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        *distance = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        return 0;
    }

    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 distance reader started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("%s Distance: %u mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

