/*
 * Parking Assist System — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   HC-SR04 ultrasonic sensor
 *     VCC  -> 5 V (Pin 2)
 *     GND  -> GND (Pin 6)
 *     TRIG -> GPIO 23 (BCM 23, Pin 16)
 *     ECHO -> GPIO 24 (BCM 24, Pin 18)
 *   SG90 servo
 *     VCC  -> 5 V (Pin 2)
 *     GND  -> GND (Pin 6)
 *     Signal -> GPIO 17 (BCM 17, Pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:
 *   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define TRIGGER_PIN        23          /* BCM 23 — HC-SR04 trigger  */
#define ECHO_PIN           24          /* BCM 24 — HC-SR04 echo     */
#define SERVO_PIN          17          /* BCM 17 — SG90 control     */
#define LOG_FILE           "sensor_data.log"
#define TRIGGER_PULSE_US   10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US    50000       /* 50 ms timeout for echo      */
#define LOOP_DELAY_US      200000      /* 200 ms between readings     */
#define MIN_DISTANCE_CM    2.0f
#define MAX_DISTANCE_CM    400.0f
#define SERVO_MIN_ANGLE    (-90.0f)
#define SERVO_MAX_ANGLE    (90.0f)

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_gpio(void);
static void trigger_sensor(void);
static float read_distance_cm(void);
static int  map_distance_to_angle(float distance_cm);
static int  set_servo_angle(int angle);
static void log_data(float distance_cm, int angle);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Logging to %s\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        float distance = read_distance_cm();
        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error — skipping cycle.\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Servo angle set failed.\n");
            }
            log_data(distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise trigger pin LOW\n");
        return -1;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set servo pin %d as output\n", SERVO_PIN);
        return -1;
    }

    /* Set servo to a safe default angle (0) */
    if (set_servo_angle(0) != 0) {
        fprintf(stderr, "Failed to set initial servo angle\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/*
 * Reads the distance from the HC-SR04 sensor.
 * Returns the distance in cm, or -1.0f on timeout/error.
 */
static float read_distance_cm(void)
{
    uint32_t start_tick, echo_start, echo_end;

    /* Issue a 10 us trigger pulse */
    trigger_sensor();

    /* Wait for echo to go HIGH (with timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0f; /* Timeout waiting for echo start */
        }
    }
    echo_start = gpioTick();

    /* Wait for echo to go LOW (with timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            return -1.0f; /* Timeout waiting for echo end */
        }
    }
    echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    /* distance = (pulse_width * speed_of_sound) / 2 */
    /* speed_of_sound = 343 m/s = 0.0343 cm/us */
    float distance = (float)pulse_width * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0f; /* Out of range */
    }

    return distance;
}

/* ------------------------------------------------------------------ */
static int map_distance_to_angle(float distance_cm)
{
    float normalized = (distance_cm - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float angle = SERVO_MIN_ANGLE +
                  normalized * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE);
    return (int)angle;
}

/* ------------------------------------------------------------------ */
static int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    /* pigpio servo pulse width: 500 us minimum, 2000 us maximum */
    int pulse_width = 500 + (angle * 1500 / 180); /* 0-180 degrees */
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float distance_cm, int angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log, "%s, Distance: %.2f cm, Angle: %d\n",
            timestamp, distance_cm, angle);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo pulses */
    gpioServo(SERVO_PIN, 0);

    /* Release pigpio resources */
    gpioTerminate();

    /* Close log file */
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
}

