#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GPIO_PIN 23
#define DISTANCE_THRESHOLD 100
#define MSG_QUEUE_NAME "/my_queue"
#define POLL_INTERVAL_MS 50

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int mq_fd = -1;
static int gpio_fd = -1;
static pthread_mutex_t mq_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write to reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed: %s", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        syslog(LOG_ERR, "I2C read from reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint16_t status = 0;
    int timeout = 0;
    while (timeout < 100) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(1000);
        timeout++;
    }
    if (timeout >= 100) {
        syslog(LOG_ERR, "VL53L1X timeout");
        return -1;
    }
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) return -1;
    return 0;
}

static void *queue_message(void *arg) {
    (void)arg;
    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_fd, &distance) == 0) {
            char buffer[32];
            snprintf(buffer, sizeof(buffer), "Distance: %u mm", distance);
            if (mq_send(mq_fd, buffer, strlen(buffer), 0) == -1) {
                syslog(LOG_ERR, "mq_send failed: %s", strerror(errno));
            }
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
    return NULL;
}

static void *buzzer_thread(void *arg) {
    (void)arg;
    while (running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_fd, &distance) == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                if (gpio_fd >= 0) {
                    if (gpioWrite(gpio_fd, 1) == 0) {
