        syslog(LOG_ERR, "I2C write to reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed: %s", reg, strerror(errno));
        return -1;
    }
