#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define DISTANCE_THRESHOLD_CM 30.0
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio's interrupt callback runs in a dedicated thread.
 * Keep it short and only update the distance variable.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        uint32_t duration = tick - start_tick;
        start_tick = 0;
        distance = (duration * SPEED_OF_SOUND_CM_PER_US) / 2.0;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW.\n");
        gpioTerminate();
        return -1;
    }

    /* Allow sensor to settle */
    gpioDelay(100000);

    return 0;
}

static int read_distance(void) {
    /* Generate 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger HIGH.\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger LOW.\n");
        return -1;
    }

    /* Wait for echo with timeout */
    uint32_t start_tick = 0;
    uint32_t elapsed = 0;
    while (running) {
        if (gpioRead(ECHO_PIN) == 1) {
            start_tick = gpioTick();
            break;
        }
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo start timeout (sensor absent or not responding).\n");
            return -1;
        }
    }

    if (!running) {
        return -1;
    }

    /* Wait for echo to go LOW with timeout */
    elapsed = 0;
    while (running) {
        if (gpioRead(ECHO_PIN) == 0) {
            break;
        }
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo end timeout (sensor absent or stuck).\n");
            return -1;
        }
    }

    if (!running) {
        return -1;
    }

    uint32_t duration = gpioTick() - start_tick;
    double distance = (duration * SPEED_OF_SOUND_CM_PER_US) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.1f, %.1f].\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1;
    }

    return (int)distance;
}

static void control_buzzer(int distance) {
    static int buzzer_active = 0;
    if (distance < DISTANCE_THRESHOLD_CM && !buzzer_active) {
        if (gpioWrite(BUZZER_PIN, 1) == 0) {
            buzzer_active = 1;
            printf("Buzzer ON (distance: %d cm)\n", distance);
        } else {
            fprintf(stderr, "Error: failed to activate buzzer.\n");
        }
    } else if (distance >= DISTANCE_THRESHOLD_CM && buzzer_active) {
        if (gpioWrite(BUZZER_PIN, 0) == 0) {
            buzzer_active = 0;
            printf("Buzzer OFF (distance: %d cm)\n", distance);
        } else {
            fprintf(stderr, "Error: failed to deactivate buzzer.\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register echo interrupt.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: failed to read distance.\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

