    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register echo interrupt.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: failed to read distance.\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

