#define VL53L1X_RANGE_STATUS_ERROR 0x01
#define VL53L1X_RANGE_STATUS_BOOTING 0x02
#define VL53L1X_RANGE_STATUS_RANGE_ERROR 0x03

#define SERVO_OPEN 1500
#define SERVO_CLOSE 500

