static int i2c_write16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int i2c_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(data_buf[0] << 8)) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t status = 0;
    if (i2c_read16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
