/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TRIG -> GPIO23 (physical pin 16)
 *   ECHO -> GPIO24 (physical pin 18)  [ECHO is 5 V; level-shift or divide to 3.3 V]
 *   VCC  -> 5 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN      23
#define ECHO_PIN      24

#define TRIG_PULSE_US 10
#define SAMPLE_PERIOD_US 200000   /* 5 Hz */
#define ECHO_TIMEOUT_US  30000    /* 30 ms */
#define ECHO_TIMEOUT_MS  60       /* 60 ms */
#define MIN_PULSE_US    100      /* 100 us  */
#define MAX_PULSE_US    30000    /* 30 ms  */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Monotonic microseconds (32-bit tick wraparound handled internally). */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

/* Append a timestamped distance reading to stdout and the log file. */
static void log_reading(double distance, const char *filename)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("%s  Distance: %.2f cm\n", ts, distance);
    fflush(stdout);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    fprintf(fp, "%s,%.2f\n", ts, distance);
    fclose(fp);
}

/*
 * Alert callback for the ECHO line.
 * Captures both rising and falling edge timestamps in microseconds.
 */
static void echo_callback(struct gpiod_line *line, int event, uint64_t tick, void *user)
{
    (void)event;
    (void)user;

    static uint64_t last_rise = 0;
    static bool      have_rise = false;

    if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
        have_rise = true;
        last_rise = tick;
    } else if (event == GPIOD_LINE_EVENT_FALLING_EDGE) {
        if (have_rise) {
            uint64_t dur = tick - last_rise;
            if (dur >= MIN_PULSE_US && dur <= MAX_PULSE_US) {
                double dist = (dur / 2.0) / 0.00125; /* speed of sound 343 m/s */
                log_reading(dist, LOG_FILE);
            } else {
                fprintf(stderr,
                        "Warning: pulse out of range (%llu us) [trig=%llu us, echo=%llu us]\n",
                        dur, tick, last_rise);
            }
            have_rise = false;
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* --- Request TRIG as output, initial LOW --- */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    /* --- Request ECHO as input with pull-down --- */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* --- Request ECHO alert callback --- */
    if (gpiod_line_request_falling_edge_events(echo, echo_callback) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    printf("HC-SR04 measurement started. TRIG=GPIO%d, ECHO=GPIO%d. Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Reset have_rise flag before triggering. */
        have_rise = false;

        /* 10 us trigger pulse. */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig HIGH)");
            break;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig LOW)");
            break;
        }

        /* Wait for echo with timeout. */
        uint64_t start = now_us();
        while (!have_rise && g_running) {
            if (now_us() - start > ECHO_TIMEOUT_US) {
                fprintf(stderr,
                        "Warning: echo timeout (no object within %llu us)\n",
                        ECHO_TIMEOUT_US);
                break;
            }
            usleep(100);
        }

        /* Reset have_rise flag after echo callback. */
        have_rise = false;

        if (g_running) {
            uint64_t now = now_us();
            if (have_rise) {
                uint64_t dur = now - last_rise;
                if (dur >= MIN_PULSE_US && dur <= MAX_PULSE_US) {
                    double dist = (dur / 2.0) / 0.00125;
                    log_reading(dist, LOG_FILE);
                } else {
                    fprintf(stderr,
                            "Warning: pulse out of range (%llu us) [trig=%llu us, echo=%llu us]\n",
                            dur, now, last_rise);
                }
            }
        }

        /* Sleep for the remainder of the 5 Hz period. */
        usleep(SAMPLE_PERIOD_US - (now_us() - start));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release resources --- */
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);

    printf("\nExiting cleanly.\n");
    return ret;
}

