                        "Warning: pulse out of range (%llu us) [trig=%llu us, echo=%llu us]\n",
                        dur, tick, last_rise);
            }
            have_rise = false;
        }
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* --- Request TRIG as output, initial LOW --- */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    /* --- Request ECHO as input with pull-down --- */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* --- Request ECHO alert callback --- */
    if (gpiod_line_request_falling_edge_events(echo, echo_callback) < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    printf("HC-SR04 measurement started. TRIG=GPIO%d, ECHO=GPIO%d. Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (g_running) {
        /* Reset have_rise flag before triggering. */
        have_rise = false;

        /* 10 us trigger pulse. */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig HIGH)");
            break;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig LOW)");
            break;
        }

        /* Wait for echo with timeout. */
        uint64_t start = now_us();
        while (!have_rise && g_running) {
            if (now_us() - start > ECHO_TIMEOUT_US) {
                fprintf(stderr,
                        "Warning: echo timeout (no object within %llu us)\n",
                        ECHO_TIMEOUT_US);
                break;
            }
            usleep(100);
        }

        /* Reset have_rise flag after echo callback. */
        have_rise = false;

        if (g_running) {
            uint64_t now = now_us();
            if (have_rise) {
                uint64_t dur = now - last_rise;
                if (dur >= MIN_PULSE_US && dur <= MAX_PULSE_US) {
                    double dist = (dur / 2.0) / 0.00125;
                    log_reading(dist, LOG_FILE);
                } else {
                    fprintf(stderr,
                            "Warning: pulse out of range (%llu us) [trig=%llu us, echo=%llu us]\n",
                            dur, now, last_rise);
                }
            }
        }

        /* Sleep for the remainder of the 5 Hz period. */
        usleep(SAMPLE_PERIOD_US - (now_us() - start));
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release resources --- */
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);

    printf("\nExiting cleanly.\n");
    return ret;
}

