/*
 * Smart Parking Gate for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - VL53L1X shutdown pin tied to GPIO23 (BCM)
 *   - VL53L1X interrupt pin tied to GPIO24 (BCM)
 *   - Servo motor on GPIO18 (BCM) via hardware PWM
 *
 * Behavior:
 *   - Opens gate when object detected within 50 cm
 *   - Closes gate when object detected beyond 60 cm
 *   - Logs state changes with timestamp and distance to parking_log.txt
 *   - Clean shutdown on SIGINT/SIGTERM
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29

#define SERVO_PIN            18
#define SHUTDOWN_PIN         23
#define INTERRUPT_PIN        24

#define DISTANCE_THRESHOLD_OPEN  50   /* cm */
#define DISTANCE_THRESHOLD_CLOSE 60   /* cm */

#define LOG_FILE_NAME         "parking_log.txt"

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK   0x0096
#define VL53L1X_REG_RESULT_FINAL_DISTANCE    0x0096

#define VL53L1X_MODEL_ID_EXPECTED  0xEA

/* ----------------------------- Globals ---------------------------------- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes ------------------------------- */
static int  initialize_i2c(void);
static int  verify_sensor_model(void);
static int  read_distance(uint16_t *distance_mm);
static void control_servo(int pulse_width);
static void log_event(int gate_state, uint16_t distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------ */
static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        return -1;
    }

    /* Verify sensor identity */
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Start ranging */
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

static int verify_sensor_model(void)
{
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    return 0;
}

/* ----------------------------- Distance read ----------------------------- */
static int read_distance(uint16_t *distance_mm)
{
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    /* Wait for data ready (poll RESULT_RANGE_STATUS) */
    for (int i = 0; i < 100; i++) {
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading range status: %d\n", status);
            return -1;
        }
        if ((status & 0x01) == 0x01) {
            break; /* Data ready */
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_DISTANCE) < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    int16_t raw = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_DISTANCE);
    if (raw < 0) {
        fprintf(stderr, "Error reading distance raw: %d\n", raw);
        return -1;
    }

    /* Convert to millimetres */
    *distance_mm = (uint16_t)raw;
    return 0;
}

/* ----------------------------- Servo control ----------------------------- */
static void control_servo(int pulse_width)
{
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Invalid servo pulse width: %d\n", pulse_width);
        return;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int gate_state, uint16_t distance)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s - Gate: %s, Distance: %u mm\n",
                timestamp, gate_state ? "OPEN" : "CLOSED", distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initial gate state: closed */
    int gate_state = 0;
    control_servo(1500); /* 50% pulse width -> closed */

    printf("Smart Parking Gate started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        if (read_distance((uint16_t *)NULL) == 0) {
            uint16_t distance = *distance_mm;
            int new_state = (distance < DISTANCE_THRESHOLD_OPEN) ? 1 : 0;

            if (new_state != gate_state) {
                if (new_state) {
                    printf("Object detected within %d cm. Opening gate.\n",
                           DISTANCE_THRESHOLD_OPEN);
                    control_servo(2000); /* 80% pulse width -> open */
                    gate_state = 1;
                    log_event(gate_state, distance);
                } else {
                    printf("Object detected beyond %d cm. Closing gate.\n",
                           DISTANCE_THRESHOLD_CLOSE);
                    control_servo(1000); /* 50% pulse width -> close */
                    gate_state = 0;
                    log_event(gate_state, distance);
                }
            }
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    control_servo(1500); /* Close gate */
    cleanup();
    return EXIT_SUCCESS;
}

