/*
 * Raspberry Pi 4 Model B – VL53L1X Time-of-Flight Gate Controller
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   - Gate actuator: GPIO18 (HIGH) = gate OPEN, GPIO19 (LOW) = gate CLOSE
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_controller gate_controller.c \
 *       -lpigpio -lrt -lm
 *
 * Run:
 *   sudo ./gate_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29

#define GATE_OPEN_PIN        18
#define GATE_CLOSE_PIN       19

#define DISTANCE_THRESHOLD   200   /* mm  – 20 cm */
#define POLL_INTERVAL_US     500000 /* 500 ms */

/* VL53L1X 16-bit register addresses (pigpio i2cReadI2CBlockData / i2cWriteI2CBlockData
 * uses a 16-bit register address followed by a 1-byte write/read data byte. */
#define VL53L1X_SOFT_RESET      0x0000
#define VL53L1X_SYSTEM_MODE     0x0080
#define VL53L1X_RANGE_START     0x0086
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE  0x0096
#define VL53L1X_RESULT_PHASE     0x0098
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG 0x0084
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG 0x0086
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG_REG 0x0084
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_BIT 0x01
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG_BIT 0x01
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_TIMEOUT 0x00
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG_TIMEOUT 0x00

#define VL53L1X_RANGE_TIMEOUT_MS  100
#define VL53L1X_RANGE_MAX_RANGE_MM 1000

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write_reg16(uint16_t reg, uint8_t value);
static int  vl53l1x_read_reg16(uint16_t reg, uint8_t *value);
static int  vl53l1x_init(void);
static int  vl53l1x_start_ranging(void);
static int  vl53l1x_read_distance(uint16_t *distance_mm);
static void log_event(const char *event_type);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers -------------------------------- */
static int vl53l1x_write_reg16(uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 2);
}

static int vl53l1x_read_reg16(uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data[1];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteI2CBlockData(i2c_handle, addr[0], addr + 1, 1) < 0)
        return -1;

    if (i2cReadI2CBlockData(i2c_handle, addr[0], data, 1) != 1)
        return -1;

    *value = (uint8_t)data[0];
    return 0;
}

/* ----------------------------- Sensor init -------------------------------- */
static int vl53l1x_init(void)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(VL53L1X_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write_reg16(VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
        fprintf(stderr, "[ERROR] Clear interrupt failed\n");
        return -1;
    }

    /* Set timing budget to ~33 ms (0x00 = 33 ms) */
    if (vl53l1x_write_reg16(VL53L1X_SYSTEM_INTERRUPT_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Timing budget config failed\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write_reg16(VL53L1X_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "[ERROR] Range start failed\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Ranging ------------------------------------ */
static int vl53l1x_start_ranging(void)
{
    return vl53l1x_write_reg16(VL53L1X_RANGE_START, 0x01);
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist   = 0;
    uint8_t phase  = 0;

    /* Poll for data ready (bit 0 of RANGE_STATUS) */
    for (int i = 0; i < 50; i++) {
        if (vl53l1x_read_reg16(VL53L1X_RESULT_RANGE_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "[WARN] Ranging timeout (data not ready)\n");
        return -1;
    }

    /* Read distance (16-bit, little-endian) */
    if (vl53l1x_read_reg16(VL53L1X_RESULT_DISTANCE, &dist) < 0)
        return -1;

    /* Read phase (16-bit, little-endian) */
    if (vl53l1x_read_reg16(VL53L1X_RESULT_PHASE, &phase) < 0)
        return -1;

    /* Clear interrupt so next measurement can trigger */
    if (vl53l1x_write_reg16(VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0)
        return -1;

    *distance_mm = (uint16_t)((dist << 8) | phase);
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_event(const char *event_type)
{
    if (!log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(log_file, "%s - %s\n", ts, event_type);
    fflush(log_file);
}

/* ----------------------------- GPIO --------------------------------------- */
static void control_gate(bool open)
{
    if (gpioWrite(GATE_OPEN_PIN, open ? 1 : 0) < 0)
        fprintf(stderr, "[WARN] gpioWrite(GATE_OPEN_PIN) failed\n");
    if (gpioWrite(GATE_CLOSE_PIN, open ? 0 : 1) < 0)
        fprintf(stderr, "[WARN] gpioWrite(GATE_CLOSE_PIN) failed\n");
}

/* ----------------------------- Signal / cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gate_events.log", "a");
    if (!log_file) {
        perror("[FATAL] fopen(gate_events.log)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    control_gate(false); /* start closed */

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate controller started");

    /* Main polling loop */
    while (!terminate) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(&distance);

        if (rc == 0) {
            if (distance < DISTANCE_THRESHOLD)
                log_event("Object detected – gate OPEN");
            else
                log_event("No object – gate CLOSE");
            control_gate(distance < DISTANCE_THRESHOLD);
        } else {
            log_event("Sensor read error – gate state unchanged");
            control_gate(false);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Gate controller shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

