code:
/*
 * Raspberry Pi 4 Model B – VL53L1X distance-controlled DC motor
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Motor +      -> GPIO17 (BCM)
 *   Motor -      -> GPIO18 (BCM)
 *   Distance     -> GPIO24 (BCM)  – rising edge triggers a measurement
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / bus definitions (BCM numbering) ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x29          /* VL53L1X default 7-bit I2C address */
#define MOTOR_FORWARD  17
#define MOTOR_BACKWARD 18
#define DISTANCE_PIN   24

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_SOFT_RESET              0x000B
#define VL53L1X_SYSTEM_START            0x0000
#define VL53L1X_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_RESULT_DISTANCE         0x0096
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR  0x0086

/* ---- Distance thresholds (mm) ---- */
#define DISTANCE_FORWARD_THRESHOLD   100
#define DISTANCE_BACKWARD_THRESHOLD  300

/* ---- Timing ---- */
#define POLL_TIMEOUT_MS              100
#define MEASUREMENT_DELAY_MS         20
#define I2C_RETRY_DELAY_MS           10
#define I2C_RETRY_MAX_MS             100
#define LOOP_DELAY_MS                10

/* ---- Globals for ISR access ---- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_distance_ready = 0;
static volatile sig_atomic_t g_motor_state = 0;   /* 0 = stopped, 1 = forward, 2 = backward */

static int g_i2c_handle = -1;
static bool g_pigpio_initialized = false;

/* ------------------------------------------------------------------ */
/*  Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  VL53L1X low-level register access                                   */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg(uint8_t reg, uint8_t *value)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c_handle, wbuf, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char rbuf[1];
    if (i2cReadDevice(g_i2c_handle, rbuf, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rbuf[0];
    return 0;
}

static int vl53l1x_read_reg16(uint8_t reg, uint16_t *value)
{
    char wbuf[1] = { (char)reg };
    if (i2cWriteDevice(g_i2c_handle, wbuf, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char rbuf[2];
    if (i2cReadDevice(g_i2c_handle, rbuf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read16 from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint16_t)(((uint8_t)rbuf[0] << 8) | (uint8_t)rbuf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  VL53L1X initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(void)
{
    uint8_t status;

    /* Soft reset */
    if (vl53l1x_write_reg(VL53L1X_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);                       /* 1 ms */

    if (vl53l1x_write_reg(VL53L1X_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    /* Start measurement */
    if (vl53l1x_write_reg(VL53L1X_SYSTEM_START, 0x01) != 0) return -1;

    /* Clear any pending interrupt */
    if (vl53l1x_write_reg(VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read distance (mm) – returns -1 on error                              */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status;
    uint16_t raw;

    for (int attempt = 0; attempt < 10; attempt++) {
        /* Poll data-ready bit (bit 0 of RESULT_RANGE_STATUS) */
        if (vl53l1x_read_reg(VL53L1X_RESULT_RANGE_STATUS, &status) != 0)
            return -1;

        if (status & 0x01) {
            if (vl53l1x_read_reg16(VL53L1X_RESULT_DISTANCE, &raw) != 0)
                return -1;
            *distance_mm = raw;
            return 0;
        }

        gpioDelay(1000);                       /* 1 ms */
        if (attempt < 9) {
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); /* exponential backoff */
        }
    }

    fprintf(stderr, "[ERROR] VL53L1X data-ready timeout\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/*  Motor control                                                      */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    if (g_motor_state == 1) {
        gpioWrite(MOTOR_FORWARD, 0);
        g_motor_state = 0;
    }
    if (g_motor_state == 2) {
        gpioWrite(MOTOR_BACKWARD, 0);
        g_motor_state = 0;
    }
}

static void motor_forward(void)
{
    if (g_motor_state == 0) {
        gpioWrite(MOTOR_FORWARD, 1);
        g_motor_state = 1;
    }
}

static void motor_backward(void)
{
    if (g_motor_state == 0) {
        gpioWrite(MOTOR_BACKWARD, 1);
        g_motor_state = 2;
    }
}

/* ------------------------------------------------------------------ */
/*  ISR – rising edge of distance pin                                    */
/* ------------------------------------------------------------------ */
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    g_distance_ready = 1;
}

/* ------------------------------------------------------------------ */
/*  Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();

    if (g_i2c_handle >= 0) {
        vl53l1x_write_reg(VL53L1X_SYSTEM_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = false;
    }
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = true;

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    motor_stop();

    /* Configure distance pin as input with pull-down */
    if (gpioSetMode(DISTANCE_PIN, PI_INPUT) != 0 ||
        gpioSetPullUpDown(DISTANCE_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure distance pin\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(DISTANCE_PIN, RISING_EDGE, 0, distance_isr, NULL) != 0) {
        fprintf(stderr, "[FATAL] Failed to register ISR on GPIO%d\n", DISTANCE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance-controlled motor running. Ctrl+C to exit.\n");
    printf("  Distance threshold forward: %d mm | backward: %d mm\n",
           DISTANCE_FORWARD_THRESHOLD, DISTANCE_BACKWARD_THRESHOLD);
    printf("  Distance pin: GPIO%d (rising edge)\n", DISTANCE_PIN);
    printf("  Motor: GPIO17 (forward) | GPIO18 (backward)\n");
    printf("Press Ctrl+C to stop.\n");

    uint32_t last_tick = gpioTick();

    while (g_running) {
        if (g_distance_ready) {
            uint16_t distance = 0;
            g_distance_ready = 0;

            if (vl53l1x_read_distance(&distance) == 0) {
                printf("Distance: %u mm\n", distance);

                if (distance < DISTANCE_FORWARD_THRESHOLD) {
                    motor_forward();
                    g_motor_state = 1;
                } else if (distance > DISTANCE_BACKWARD_THRESHOLD) {
                    motor_backward();
                    g_motor_state = 2;
                } else {
                    motor_stop();
                    g_motor_state = 0;
                }
            } else {
                fprintf(stderr, "[WARN] Distance read failed – stopping motor\n");
                motor_stop();
                g_motor_state = 0;
            }
        }

        /* Poll for distance-ready with timeout */
        uint32_t now = gpioTick();
        if ((now - last_tick) >= (uint32_t)(POLL_TIMEOUT_MS * 1000)) {
            last_tick = now;
            if (g_distance_ready) {
                g_distance_ready = 0;
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

