/*
 * Proximity-based interactive art installation using an MPR121 capacitive
 * touch sensor on a Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   MPR121 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   MPR121 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   MPR121 VDD  -> 3.3 V
 *   MPR121 GND  -> GND
 *   LED bits     -> GPIO 17 (bit 0), GPIO 18 (bit 1), GPIO 27 (bit 2), GPIO 22 (bit 3)
 *
 * Build:  gcc -O2 -Wall -o proximity_art proximity_art.c -lpigpio -lrt
 * Run:    sudo ./proximity_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x5D

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_MHD_F          0x2F
#define MPR121_NHD_F          0x30
#define MPR121_NCL_F          0x31
#define MPR121_FDL_F          0x32
#define MPR121_ELE0_TTH       0x41
#define MPR121_ELE0_RTH       0x42
#define MPR121_ELECONFIG_BASE 0x5E

#define LED_B1 17
#define LED_B2 18
#define LED_B3 27
#define LED_B4 22

#define POLL_DELAY_US 50000   /* 50 ms */
#define MAX_PROXIMITY 12      /* 12 electrodes */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_write_reg(uint8_t reg, uint8_t val);
static int  mpr121_read_reg(uint8_t reg, uint8_t *val);
static int  mpr121_init(void);
static int  mpr121_read_touch_status(uint16_t *status);
static void log_event(uint16_t status);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers -------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t val)
{
    if (g_i2c_fd < 0)
        return -1;
    if (i2cWriteByteData(g_i2c_fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *val)
{
    if (g_i2c_fd < 0)
        return -1;
    int n = i2cReadByteData(g_i2c_fd, reg);
    if (n < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)n;
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Verify sensor presence by reading back the default ELECONFIG */
    uint8_t econfig = 0xFF;
    if (mpr121_read_reg(MPR121_ELECONFIG_BASE, &econfig) < 0)
        return -1;
    if (econfig != 0xFF) {
        fprintf(stderr, "MPR121 not detected (ELECONFIG=0x%02X, expected 0xFF)\n",
                econfig);
        return -1;
    }

    /* Rising / falling filter settings (R=0.5 uF, F=0.5 uF) */
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        uint8_t tth = 0x0F;  /* touch threshold */
        uint8_t rth = 0x0A;  /* release threshold */
        if (mpr121_write_reg(MPR121_ELE0_TTH + i * 2, tth) < 0) return -1;
        if (mpr121_write_reg(MPR121_ELE0_RTH + i * 2, rth) < 0) return -1;
    }

    /* Enable all 12 electrodes, baseline tracking, 16 samples */
    if (mpr121_write_reg(MPR121_ELECONFIG_BASE, 0x0C) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Touch status -------------------------------- */
static int mpr121_read_touch_status(uint16_t *status)
{
    uint8_t lo = 0, hi = 0;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Logging ------------------------------------- */
static void log_event(uint16_t status)
{
    if (!g_log_fp)
        return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s - Proximity detected: 0x%04X\n", ts, status);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Turn off LEDs */
    gpioWrite(LED_B1, 0);
    gpioWrite(LED_B2, 0);
    gpioWrite(LED_B3, 0);
    gpioWrite(LED_B4, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* GPIO setup */
    if (gpioSetMode(LED_B1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_B2, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_B3, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_B4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_B1, 0);
    gpioWrite(LED_B2, 0);
    gpioWrite(LED_B3, 0);
    gpioWrite(LED_B4, 0);

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n",
                I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("proximity_art.log", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity art installation running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t status = 0;
        if (mpr121_read_touch_status(&status) < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (status & 0x0FFF) {
            log_event(status);
            /* LED pattern: bit 0 = B1, bit 1 = B2, bit 2 = B3, bit 3 = B4 */
            gpioWrite(LED_B1, (status & 0x01) ? 1 : 0);
            gpioWrite(LED_B2, (status & 0x02) ? 1 : 0);
            gpioWrite(LED_B3, (status & 0x04) ? 1 : 0);
            gpioWrite(LED_B4, (status & 0x08) ? 1 : 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

