#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_NHDF 0x2F
#define MPR121_NCLF 0x30
#define MPR121_FDLF 0x31
#define MPR121_E0L 0x32
#define MPR121_E0H 0x33
#define MPR121_E1L 0x34
#define MPR121_E1H 0x35
#define MPR121_E2L 0x36
#define MPR121_E2H 0x37
#define MPR121_E3L 0x38
#define MPR121_E3H 0x39
#define MPR121_NFL 0x3A
#define MPR121_FFL 0x3B
#define MPR121_ECR2 0x5F
#define MPR121_ECR3 0x60
#define MPR121_ECR4 0x61
#define MPR121_ECR5 0x62
#define MPR121_ECR6 0x63
#define MPR121_ECR7 0x64
#define MPR121_ECR8 0x65
