#define MPR121_ECR14 0x6B
#define MPR121_ECR15 0x6C
#define MPR121_ECR16 0x6D

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_E0L, 0x0F) < 0) return -1;
    if (mpr121_write(MPR121_E0H, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E1L, 0x0F) < 0) return -1;
    if (mpr121_write(MPR121_E1H, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E2L, 0x0F) < 0) return -1;
    if (mpr121_write(MPR121_E2H, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E3L, 0x0F) < 0) return -1;
    if (mpr121_write(MPR121_E3H, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_NFL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FFL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_ECR2, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR3, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR4, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR5, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR6, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR7, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR8, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR9, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR10, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR11, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR12, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR13, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR14, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR15, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR16, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_proximity_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Proximity detected\n", timestamp);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != 0x51) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x51)\n", device_id);
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x0001) {
            gpioWrite(LED_PIN, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(10000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

