#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define TRIGGER_HOLD_US 5
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Measure distance in cm.
 * Returns distance on success, or -1.0 on error/timeout.
 */
static double measure_distance(void)
{
    uint32_t start_tick, echo_start, echo_end, pulse_width;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_HOLD_US);

    /* 10 us high pulse to start the measurement */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising edge timeout (sensor absent?)\n");
            return -1.0;
        }
    }
    echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling edge timeout\n");
            return -1.0;
        }
    }
    echo_end = gpioTick();

    pulse_width = echo_end - echo_start;
    if (pulse_width == 0) {
        fprintf(stderr, "Error: zero pulse width\n");
        return -1.0;
    }

    /* distance = (pulse_width_us * speed_of_sound) / 2 / 1e6 */
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

static void log_distance(FILE *fp, double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (distance < 0.0) {
        fprintf(fp, "%s, ERROR\n", timestamp);
    } else {
        fprintf(fp, "%s, %.2f\n", timestamp, distance);
    }
    fflush(fp);
}

int main(void)
{
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        goto cleanup_gpio;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        goto cleanup_gpio;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler\n");
        goto cleanup_all;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            log_distance(fp, distance);
        } else {
            log_distance(fp, distance);
        }

        /* Sleep for 1 second, checking program_running every 100 ms */
        for (int i = 0; i < 10 && program_running; i++) {
            gpioDelay(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_gpio:
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return ret;
}

