/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO17 (physical pin 11)
 *   ECHO -> GPIO18 (physical pin 12) via 1k/2k voltage divider -> Pi input ~3.3 V
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18

#define TRIG_PULSE_US 10          /* 10 us trigger pulse            */
#define SAMPLE_PERIOD_US 1000000 /* 1 second between measurements */
#define ECHO_TIMEOUT_US 500000    /* 500 ms timeout for echo       */
#define MIN_PULSE_US    58        /* ~1 cm                          */
#define MAX_PULSE_US    25000     /* ~4 m                          */

#define LOG_FILE "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                            */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile uint32_t start_tick;   /* 32-bit microsecond counter      */
    volatile uint32_t end_tick;     /* 32-bit microsecond counter      */
    volatile bool      echo_seen;  /* whether a valid echo was      */
                                    /* captured (wraps correctly)        */
} echo_state_t;

static echo_state_t g_echo;
static FILE      *g_log = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread context                         */
/* ------------------------------------------------------------------ */

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_echo.start_tick = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_echo.end_tick = tick;
        g_echo.echo_seen = true;
    }
    /* level == 2 indicates a timeout; ignore it */
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                               */
/* ------------------------------------------------------------------ */

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 min.
 * Handle the wrap-around correctly so a 500 ms timeout is treated
 * as a valid echo pulse width of 500000 us.
 */
static double tick_to_us(uint32_t tick)
{
    return (double)tick;
}

static double pulse_width_us(uint32_t start, uint32_t end)
{
    return (double)(end - start);
}

static double distance_cm(uint32_t pulse_us)
{
    if (pulse_us <= MIN_PULSE_US)
        return -1.0;          /* out of range / invalid */
    if (pulse_us >= MAX_PULSE_US)
        return 4000.0;       /* beyond practical range */
    return 0.0343 * pulse_us;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(double distance_cm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (g_log) {
        fprintf(g_log, "%s, %.2f cm\n", timestamp, distance_cm);
        fflush(g_log);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable ISR before closing */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }

    /* pigpio cleanup is optional but good practice */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Register ISR ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        fclose(g_log);
        g_log = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset echo state */
        g_echo.echo_seen = false;
        g_echo.start_tick = 0;
        g_echo.end_tick  = 0;

        /* Trigger a 10 us pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for echo or timeout */
        uint32_t waited = 0;
        while (g_running && !g_echo.echo_seen && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100);  /* 100 us granularity */
            waited += 100;
        }

        if (!g_running)
            break;

        if (!g_echo.echo_seen) {
            fprintf(stderr, "Warning: echo timeout — sensor may be absent or out of range.\n");
        } else {
            uint32_t pulse = g_echo.end_tick - g_echo.start_tick;
            double dist = distance_cm(pulse);

            if (dist < 0.0) {
                fprintf(stderr, "Warning: distance out of range (%u us).\n", pulse);
            } else {
                log_distance(dist);
                printf("Distance: %.2f cm\n", dist);
            }
        }

        /* Sleep for the remainder of the 1 s period */
        uint32_t remaining = SAMPLE_PERIOD_US - (uint32_t)waited;
        if (remaining > 0)
            gpioDelay(remaining);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

