#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define POLL_INTERVAL_MS 100

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write to reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select 0x%04X) failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        syslog(LOG_ERR, "I2C read from reg 0x%04X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        syslog(LOG_ERR, "Cannot read model ID - sensor may be absent or unresponsive");
        return -1;
    }
    syslog(LOG_INFO, "VL53L1X detected (model ID = 0x%02X)", model_id);

    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to clear interrupt");
        return -1;
    }

    /* Start ranging (bit 0 = start) */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X initialized and ranging started");
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm) {
    uint8_t status = 0;
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
        return -1;
    }

    if (status & 0x01) {
        uint8_t dist_buf[2] = {0};
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
            return -1;
        }
        *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
        if (*distance_mm == 0) {
            syslog(LOG_ERR, "VL53L1X returned 0 distance - sensor may be malfunctioning");
            return -1;
        }
    } else {
        syslog(LOG_ERR, "VL53L1X data not ready (status=0x%02X)", status);
        return -1;
    }

    /* Clear interrupt to allow next measurement */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        syslog(LOG_ERR, "Failed to clear interrupt");
        return -1;
    }

    return 0;
}

static void log_reading(uint16_t distance_mm, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s - Distance: %u mm, Status: %s", timestamp, distance_mm, status);
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure XSHUT pin as output, initially high (sensor disabled) */
    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", XSHUT_PIN);
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(XSHUT_PIN, 1);

    syslog(LOG_INFO, "VL53L1X sensor ready. Logging distance readings every %d ms.", POLL_INTERVAL_MS);

    while (g_running) {
        uint16_t distance = 0;
        const char *status = "OK";

        if (vl53l1x_read_distance(g_i2c_fd, &distance) != 0) {
            status = "READ_ERROR";
        }

        log_reading(distance, status);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean shutdown */
    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(XSHUT_PIN, 0); /* Disable sensor */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

