#define POLL_INTERVAL_US 100000
#define LOG_FILE "gate_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int i2c_write_reg16(uint8_t reg, uint16_t val) {
    char buf[3] = { (char)reg, (char)(val >> 8), (char)(val & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(uint8_t reg, uint16_t *val) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 1) return -1;
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

