#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SAMPLE_DELAY_US  100000
#define MOVING_AVG_SIZE 5

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_pulse_width = 0;
static volatile bool g_new_pulse = false;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        g_pulse_width = tick;
        g_new_pulse = true;
    }
}

static double moving_average(double new_value, double *buffer, int size, double *sum) {
    *sum -= buffer[size - 1];
    buffer[size - 1] = new_value;
    *sum += new_value;
    return *sum / size;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN) angle = SERVO_ANGLE_MIN;
    if (angle > SERVO_ANGLE_MAX) angle = SERVO_ANGLE_MAX;
    int pulse_width = (int)(((float)(angle - SERVO_ANGLE_MIN) / (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int read_distance(void) {
    trigger_sensor();
    uint32_t start_tick = gpioTick();
    uint32_t elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        if (g_new_pulse) {
            g_new_pulse = false;
            return (int)moving_average((double)g_pulse_width, g_buffer, MOVING_AVG_SIZE, &g_sum);
        }
        if (gpioRead(ECHO_PIN) == 0) {
            uint32_t now = gpioTick();
            if ((now - start_tick) > ECHO_TIMEOUT_US) {
                return -1;
            }
        }
        gpioDelay(100);
        elapsed = gpioTick() - start_tick;
    }
    return -1;
}

static void log_data(double distance, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
    fflush(g_log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN mode\n");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN mode\n");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set SERVO_PIN mode\n");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot set alert function for ECHO_PIN\n");
        fclose(g_log_file);
        gpioTerminate();
        return 1;
    }

    double g_buffer[MOVING_AVG_SIZE] = {0};
    double g_sum = 0.0;
    int servo_angle = 90;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (g_running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: no echo or out of range\n");
            set_servo_angle(servo_angle);
        } else if (distance > 400) {
            fprintf(stderr, "Error: distance out of range (%d cm)\n", distance);
            set_servo_angle(servo_angle);
        } else {
            servo_angle = (int)moving_average((double)distance, g_buffer, MOVING_AVG_SIZE, &g_sum);
            if (set_servo_angle(servo_angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            }
            log_data((double)distance, servo_angle);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    set_servo_angle(0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    gpioTerminate();
    return 0;
}

