static int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, unsigned char reg, unsigned int *value) {
    unsigned char buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error (0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (unsigned int)buf[0] | ((unsigned int)buf[1] << 8);
    return 0;
}

