static void *proximity_interrupt_handler(void *arg) {
    (void)arg;
    int proximity_value;
    if (i2c_read_word(i2c_fd, 0x00, &proximity_value) < 0) {
        return NULL;
    }
    if (proximity_value > MAX_PROXIMITY_VALUE) {
        fprintf(stderr, "Proximity value out of range: %d\n", proximity_value);
        return NULL;
    }
    if (proximity_value <= threshold) {
        fprintf(log_file, "%ld, %d, SAFE\n", (long)time(NULL), proximity_value);
    } else {
        fprintf(log_file, "%ld, %d, ALERT\n", (long)time(NULL), proximity_value);
    }
    fflush(log_file);
    return NULL;
}

