/*
 * Raspberry Pi Zero W – HC-SR04 ultrasonic distance sensor →
 * hardware-timed PWM on GPIO18 (BCM) as a theremin-like instrument.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V (Pin 2 or 4)
 *   HC-SR04 GND  -> GND  (Pin 6)
 *   HC-SR04 TRIG -> GPIO23 (BCM 23, Pin 16)
 *   HC-SR04 ECHO -> GPIO24 (BCM 24, Pin 18)  [use a voltage divider if ECHO is 5 V]
 *   Speaker     -> 8 Ω load on GPIO18 (BCM 18, Pin 12) via a transistor/buffer
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define TRIGGER_PULSE_US 10
#define PWM_DUTY_50      500000   /* 50 % of 1 000 000 */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm.  Returns -1.0 on timeout or out-of-range.
 * Uses a 50 % duty-cycle square wave on PWM0 for the echo pulse.
 */
static float measure_distance(void)
{
    uint32_t start_tick, echo_start, echo_end;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance = (float)pulse_us / 58.0f;   /* cm */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f–%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance;
}

/*
 * Map distance (cm) to frequency (Hz) on a logarithmic scale.
 * Returns -1.0 on invalid input.
 */
static float distance_to_frequency(float distance)
{
    if (distance <= 0.0f) {
        return -1.0f;
    }
    if (distance <= MIN_DISTANCE_CM) {
        return (float)MIN_FREQUENCY_HZ;
    }
    if (distance >= MAX_DISTANCE_CM) {
        return (float)MAX_FREQUENCY_HZ;
    }
    float ratio = (distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float log_ratio = (float)log10f(ratio);
    return (float)MIN_FREQUENCY_HZ +
           (float)MAX_FREQUENCY_HZ * (1.0f - powf(10.0f, log_ratio));
}

/*
 * Drive PWM0 with a 50 % duty cycle for a given frequency.
 * Returns 0 on success, -1 on error.
 */
static int set_frequency(int frequency)
{
    if (frequency < 0) {
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", PWM_PIN, PWM_DUTY_50);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 1 000 000 (pigpio default) */
    if (gpioSetPWMrange(PWM_PIN, 1000000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin ready.  Trigger=BCM23  Echo=BCM24  PWM=BCM18\n");
    printf("Press Ctrl+C to exit.\n");

    int prev_frequency = 0;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Error already reported; preserve previous frequency */
            prev_frequency = 0;
        } else {
            float frequency = distance_to_frequency(distance);
            if (frequency < 0.0f) {
                prev_frequency = 0;
            } else {
                prev_frequency = (int)frequency;
                if (set_frequency(prev_frequency) != 0) {
                    prev_frequency = 0;
                }
            }
        }

        printf("Distance: %.2f cm  Frequency: %d Hz\n", distance, prev_frequency);

        /* Sleep 100 ms; gpioDelay is interruptible by signals */
        gpioDelay(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

