#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SPEED_OF_SOUND 34300.0
#define TIMEOUT_US  50000
#define LOOP_DELAY_US 500000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define CLOSE_THRESHOLD_CM 10.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using HC-SR04.
 * Returns -1.0 on timeout or out-of-range reading.
 */
static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_us * SPEED_OF_SOUND) / 2000000.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance_cm;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("HC-SR04 distance measurement started (trigger=GPIO%d, echo=GPIO%d)\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < CLOSE_THRESHOLD_CM) {
                printf("  (Too close!)");
            }
            printf("\n");
        }
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

