#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define LOG_FILE        "distance_log.csv"
#define SAMPLE_DELAY_US 100000  /* 100 ms */

/* ICU-20201 register addresses (16-bit, big-endian on SPI) */
#define REG_CHIP_ID     0x00
#define REG_RANGE_CONFIG 0x01
#define REG_DISTANCE    0x02

/* Range config: 200-5000 mm, 1x resolution, 10-bit */
#define RANGE_CONFIG_VAL 0x0000

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sensor_init(void)
{
    uint8_t tx[2] = { REG_CHIP_ID, 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0) {
        fprintf(stderr, "Error reading chip ID (sensor absent or bus error)\n");
        return -1;
    }

    uint16_t chip_id = ((uint16_t)rx[0] << 8) | rx[1];
    if (chip_id != 0x2020) {
        fprintf(stderr, "Unexpected chip ID: 0x%04X (expected 0x2020)\n", chip_id);
        return -1;
    }

    if (spi_transfer(tx, rx, 2) < 0) {
