    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    *distance_mm = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static void log_data(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
