    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (sensor_init() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    fprintf(g_log_fp, "# timestamp,distance_mm\n");
    fflush(g_log_fp);

    printf("Starting distance logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm = 0;

        if (read_distance(&distance_mm) < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
        } else {
            log_data(distance_mm);
            printf("Distance: %u mm\n", distance_mm);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return 0;
}

