    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1175(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1175_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1175_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1175_REG_HW_KEY, SI1175_HW_KEY_VAL) < 0) {
        return -1;
    }

    /* Reset the device */
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, 0x01) < 0) {
        return -1;
    }
    usleep(10000); /* 10 ms reset delay */

    /* Start autonomous ALS measurement */
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, 0x0F) < 0) {
        return -1;
    }
    usleep(10000); /* 10 ms for command to take effect */

    return 0;
}

static int read_als_value(int fd, uint16_t *als_value) {
    return i2c_read_reg16(fd, SI1175_REG_ALS_VIS_DATA0, als_value);
}

static int log_data(FILE *fp, uint16_t als_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_si1175(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,als_visible\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_value = 0;

        if (read_als_value(g_i2c_fd, &als_value) < 0) {
            fprintf(stderr, "Failed to read ALS value, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        } else {
            if (log_data(g_log_fp, als_value) < 0) {
                fprintf(stderr, "Failed to log data, continuing...\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

