#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 100000

/* Si1182-A-GM register addresses (from datasheet) */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_MEAS_RATE    0x08
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_PS1_DATA0    0x24

#define SI1182_PART_ID_EXPECTED 0x82

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 Part ID: 0x%02X\n", part_id);

    /* Measurement rate: 0x0F = 100 ms measurement rate (0x00 = 1 ms, 0x0F = 100 ms) */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE, 0x0F) != 0) {
        return -1;
    }
    usleep(10000); /* allow first measurement to complete */

    return 0;
}

static int read_sensor_data(int fd, float *lux, uint16_t *prox) {
    uint8_t als_vis[2], ps1[2];
    if (i2c_read_reg16(fd, SI1182_REG_ALS_VIS_DATA0, als_vis) != 0) return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PS1_DATA0, ps1) != 0) return -1;

    uint16_t als_vis_raw = (uint16_t)als_vis[0] | ((uint16_t)als_vis[1] << 8);
    *lux = (float)als_vis_raw * 0.01f; /* 0.01 lux per LSB */

    *prox = (uint16_t)ps1[0] | ((uint16_t)ps1[1] << 8);
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static int log_data(FILE *fp, const char *timestamp, float lux, uint16_t proximity) {
    if (fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x18) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x18: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    char timestamp[32];
    float lux;
    uint16_t proximity;

    while (g_running) {
        if (read_sensor_data(g_i2c_fd, &lux, &proximity) == 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            if (log_data(g_log_fp, timestamp, lux, proximity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            printf("%s, Lux: %.2f, Proximity: %u\n", timestamp, lux, proximity);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

