#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define SERVO_MIN_PULSE_US        500
#define SERVO_MAX_PULSE_US        2500
#define SERVO_ANGLE_MIN           0
#define SERVO_ANGLE_MAX           180
#define SERVO_ANGLE_PROPORTION    90
#define SERVO_ANGLE_PROPORTION_MIN 0
#define SERVO_ANGLE_PROPORTION_MAX 180
#define SERVO_ANGLE_PROPORTION_DISTANCE 110
#define SERVO_ANGLE_PROPORTION_DISTANCE_MIN 200
#define SERVO_ANGLE_PROPORTION_DISTANCE_MAX 500
#define SERVO_ANGLE_PROPORTION_DISTANCE_MIN_CM 20
#define SERVO_ANGLE_PROPORTION_DISTANCE_MAX_CM 200
#define ECHO_TIMEOUT_US           30000
#define LOOP_DELAY_US             100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimeters using the HC-SR04.
 * Returns distance on success, -1.0 on timeout, -2.0 on sensor error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -2.0;
    }
    gpioDelay(2);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -2.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -2.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;

    /* distance = (pulse_width * speed_of_sound) / 2 */
    float distance = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance out of range (%.1f cm)\n", distance);
        return -1.0;
    }

    return distance;
}

/*
 * Set servo angle using the pigpio hardware PWM.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle)
{
    if (angle < SERVO_ANGLE_MIN || angle > SERVO_ANGLE_MAX) {
        fprintf(stderr, "Error: servo angle %d out of range [%d, %d]\n",
                angle, SERVO_ANGLE_MIN, SERVO_ANGLE_MAX);
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE_US +
        (int)((float)angle / (float)(SERVO_ANGLE_MAX - SERVO_ANGLE_MIN) *
              (float)(SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

