/*
 * VL53L1X Time-of-Flight Gate Controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - VL53L1X sensor on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   - Servo gate on GPIO18 (BCM), hardware PWM-capable
 *
 * Behavior:
 *   - Polls the 16-bit distance register every 100 ms.
 *   - When distance < 200 mm, pulses GPIO18 2000 us (gate open).
 *   - When distance > 250 mm, pulses GPIO18 1000 us (gate closed).
 *   - Hysteresis: once open, stays open; once closed, stays closed.
 *   - Every gate transition is logged with a timestamp to gate_log.txt.
 *   - SIGINT shuts down cleanly.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define SERVO_PIN      18
#define DISTANCE_THRESHOLD_OPEN  200   /* mm */
#define DISTANCE_THRESHOLD_CLOSED 250   /* mm */
#define LOG_FILE        "gate_log.txt"
#define POLL_DELAY_US   100000       /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID   0x010F
#define VL53L1X_REG_SYSTEM_RANGE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0089
#define VL53L1X_REG_RESULT_DISTANCE           0x0096

#define VL53L1X_MODEL_ID_EXPECTED              0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log_file) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, event);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;

    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }

    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Software reset via register 0x0000 */
    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: failed to send software reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set timing budget to 100 ms (0x0000 = 100 ms default) */
    if (i2c_write_reg16(handle, 0x001C, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set timing budget.\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet */
        return 1;
    }

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo control                                                      */
/* ------------------------------------------------------------------ */
static void set_servo_pulse_width(int pin, uint16_t pulse_us)
{
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Warning: gpioServo failed for pin %d.\n", pin);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0); /* stop PWM pulses */
    gpioTerminate();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t distance_mm = 0;
    int      gate_open   = 0;
    int      rc         = EXIT_FAILURE;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- servo pin setup --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", SERVO_PIN);
        goto cleanup;
    }
    gpioServo(SERVO_PIN, 0); /* start with gate closed */

    /* --- log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        goto cleanup;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        goto cleanup;
    }

    /* --- sensor init --- */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        goto cleanup;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate controller started.");

    /* --- main loop --- */
    while (g_running) {
        int ret = vl53l1x_read_distance(g_i2c_handle, &distance_mm);
        if (ret == 0) {
            printf("Distance: %u mm\n", distance_mm);

            if (distance_mm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                set_servo_pulse_width(SERVO_PIN, 2000);
                log_event("Gate opened.");
                gate_open = 1;
            } else if (distance_mm > DISTANCE_THRESHOLD_CLOSED && gate_open) {
                set_servo_pulse_width(SERVO_PIN, 1000);
                log_event("Gate closed.");
                gate_open = 0;
            }
        } else if (ret < 0) {
            fprintf(stderr, "Warning: I2C read error.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Gate controller shutting down.");
    rc = EXIT_SUCCESS;

cleanup:
    cleanup();
    return rc;
}

