/*
 * Raspberry Pi 4 Model B – HC-SR04 ultrasonic distance measurement
 * with SG90 servo control.  BCM GPIO mapping:
 *   GPIO23  – HC-SR04 TRIG  (output, 3.3 V)
 *   GPIO24  – HC-SR04 ECHO  (input, 3.3 V, 10 kΩ divider)
 *   GPIO18  – SG90 servo control (5 V, common ground)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000   /* 50 ms */
#define SERVO_MIN_US     500     /* 0°   */
#define SERVO_MAX_US     2500    /* 180° */
#define SERVO_MIN_ANGLE  0
#define SERVO_MAX_ANGLE  180
#define SERVO_MIN_DIST   20.0    /* cm */
#define SERVO_MAX_DIST   200.0   /* cm */

#define SAMPLE_PERIOD_US 100000 /* 100 ms between measurements */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Servo API (pigpio-compatible pulse widths)                          */
/* ------------------------------------------------------------------ */
typedef struct {
    uint32_t min_pulse_us;
    uint32_t max_pulse_us;
    int      min_angle;
    int      max_angle;
} servo_config_t;

static int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }

    int pulse_us = SERVO_MIN_US +
                   (int)((long)(angle - SERVO_MIN_ANGLE) *
                         (SERVO_MAX_US - SERVO_MIN_US) /
                         (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));

    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %u) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                  */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);                       /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    /* speed of sound ~343 m/s => 1 µs = 0.0343 cm */
    float distance = (float)diff * 0.0343f;

    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [2, 400]\n",
                distance);
        return -1.0f;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ------------------------------------------ */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initial trigger pulse -------------------------------------- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Servo config ----------------------------------------------- */
    servo_config_t servo = {
        .min_pulse_us = SERVO_MIN_US,
        .max_pulse_us = SERVO_MAX_US,
        .min_angle   = SERVO_MIN_ANGLE,
        .max_angle   = SERVO_MAX_ANGLE
    };

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Sensor timeout or out-of-range – keep servo at 0° */
            if (set_servo_angle(SERVO_MIN_ANGLE) < 0) {
                fprintf(stderr, "Error: failed to set servo angle during measurement\n");
            }
        } else {
            int angle = (int)((distance - SERVO_MIN_DIST) *
                              (float)(SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) /
                              (SERVO_MAX_DIST - SERVO_MIN_DIST) +
                     SERVO_MIN_ANGLE);

            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle to %d\n", angle);
            }
        }

        printf("Distance: %.2f cm  |  Angle: %d°\n", distance, angle);
        fflush(stdout);

        /* 100 ms between measurements */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    set_servo_angle(SERVO_MIN_ANGLE);   /* stop servo pulses */
    gpioDelay(50000);                    /* allow servo to stop */
    gpioTerminate();
    return EXIT_SUCCESS;
}

