#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SHT40_ADDR        0x5D
#define SHT40_CMD_MEASURE  0x2C
#define SHT40_MEASURE_MS  10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per SHT40 datasheet */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int sht40_read(float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEASURE;
    uint8_t buf[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(SHT40_MEASURE_MS * 1000); /* 10 ms */

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht40_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (sht40_init() != 0) {
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C bus.\n");
            if (g_i2c_handle >= 0) {
                i2cClose(g_i2c_handle);
                g_i2c_handle = -1;
            }
            gpioDelay(100000); /* 100 ms back-off */
            if (sht40_init() != 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

