#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int read_temperature(int fd, float *ambient, float *object) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Failed to read temperature data");
        return -1;
    }
    uint16_t raw_amb = (data[0] << 8) | data[1];
    uint16_t raw_obj = (data[3] << 8) | data[4];
    *ambient = -45.0f + 175.0f * (float)raw_amb / 65535.0f;
    *object = -45.0f + 175.0f * (float)raw_obj / 65535.0f;
    return 0;
}

int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = i2c_init(I2C_BUS, MLX90614_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient, object;
        if (read_temperature(i2c_fd, &ambient, &object) == 0) {
            if (log_temperature(log_file, ambient, object) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        sleep(READ_INTERVAL);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

