#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define STS30_ADDR 0x71
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    char buf[3];
    int result;

    /* Read 3 bytes: MSB, LSB, CRC */
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        log_error("I2C read failed: expected 3 bytes, got " + (result < 0 ? "error" : (char)result));
        return -1;
    }

    /* CRC check */
    uint8_t crc = 0;
    for (int i = 0; i < 2; i++) {
        crc ^= (uint8_t)buf[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != (uint8_t)buf[2]) {
        log_error("CRC check failed");
        return -1;
    }

    /* Convert raw data to temperature (°C) */
    int16_t raw_temp = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    printf("STS30-DIS temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            log_error("Failed to read temperature");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    /* Clean resource release on exit */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

