/*
 * SDP810-125Pa differential pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x41 (SDP810-125Pa variant)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x41          /* SDP810-125Pa variant */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0           /* seconds between samples */
#define MEAS_DELAY_US  2000          /* 2 ms measurement delay */

/* SDP810 continuous measurement command (0x36, 0x2C) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2C };

/* SDP810 scale factors (from datasheet) */
static const float PRESSURE_SCALE  = 0.125f;   /* Pa per LSB */
static const float TEMP_SCALE      = 0.25f;     /* °C per LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, const uint8_t *cmd, size_t len)
{
    if (i2cWriteDevice(handle, (char *)cmd, len) != 0) {
        fprintf(stderr, "[I2C] write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[I2C] read failed: expected %zu, got %d (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data parsing                                                */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa */
    float temperature;  /* °C */
} sensor_data_t;

static sensor_data_t parse_sdp810(const uint8_t *data)
{
    sensor_data_t d;
    uint16_t raw_p = ((uint16_t)(data[0] << 8)) | data[1];
    uint16_t raw_t = ((uint16_t)(data[3] << 8)) | data[4];
    uint16_t scale_p = ((uint16_t)(data[6] << 8)) | data[7];
    uint16_t scale_t = ((uint16_t)(data[8] << 8)) | data[9];

    if (scale_p == 0 || scale_t == 0) {
        fprintf(stderr, "[SDP810] scale factor is zero (p=%u t=%u)\n",
                scale_p, scale_t);
        return d;
    }

    d.pressure    = (float)raw_p / (float)scale_p * PRESSURE_SCALE;
    d.temperature = (float)raw_t / (float)scale_t * TEMP_SCALE;
    return d;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const sensor_data_t *d)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, d->pressure, d->temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed (addr 0x%02X): %s\n",
                I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure sensor --- */
    if (i2c_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
        fprintf(stderr, "[SDP810] failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 logger started. Logging to %s every %.1f s. "
           "Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_PERIOD);

    /* --- main loop --- */
    while (g_running) {
        /* Trigger a measurement */
        if (i2c_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "[SDP810] measurement trigger failed; retrying\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for conversion (datasheet: typ 1 ms, max 2 ms) */
        time_sleep(MEAS_DELAY_US / 1000.0);

        /* Read 9 bytes: pressure(2+1), temperature(2+1), scale(2+1) */
        uint8_t raw[9];
        if (i2c_read_data(g_i2c_handle, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "[SDP810] read failed; retrying next cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* CRC validation */
        if (crc8(&raw[0], 2) != raw[2]) {
            fprintf(stderr, "[SDP810] pressure CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }
        if (crc8(&raw[3], 2) != raw[5]) {
            fprintf(stderr, "[SDP810] temperature CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }
        if (crc8(&raw[6], 2) != raw[8]) {
            fprintf(stderr, "[SDP810] scale-factor CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        sensor_data_t data = parse_sdp810(raw);
        if (data.pressure < -100.0f || data.pressure > 200.0f ||
            data.temperature < -50.0f || data.temperature > 150.0f) {
            fprintf(stderr, "[SDP810] out-of-range reading: p=%.2f t=%.2f\n",
                    data.pressure, data.temperature);
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(&data) != 0) {
            fprintf(stderr, "[LOG] failed to write data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
               data.pressure, data.temperature);

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

