    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, d->pressure, d->temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] open failed (addr 0x%02X): %s\n",
                I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure sensor --- */
    if (i2c_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
        fprintf(stderr, "[SDP810] failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 logger started. Logging to %s every %.1f s. "
           "Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_PERIOD);

    /* --- main loop --- */
    while (g_running) {
        /* Trigger a measurement */
        if (i2c_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "[SDP810] measurement trigger failed; retrying\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for conversion (datasheet: typ 1 ms, max 2 ms) */
        time_sleep(MEAS_DELAY_US / 1000.0);

        /* Read 9 bytes: pressure(2+1), temperature(2+1), scale(2+1) */
        uint8_t raw[9];
        if (i2c_read_data(g_i2c_handle, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "[SDP810] read failed; retrying next cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        /* CRC validation */
        if (crc8(&raw[0], 2) != raw[2]) {
            fprintf(stderr, "[SDP810] pressure CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }
        if (crc8(&raw[3], 2) != raw[5]) {
            fprintf(stderr, "[SDP810] temperature CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }
        if (crc8(&raw[6], 2) != raw[8]) {
            fprintf(stderr, "[SDP810] scale-factor CRC mismatch\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        sensor_data_t data = parse_sdp810(raw);
        if (data.pressure < -100.0f || data.pressure > 200.0f ||
            data.temperature < -50.0f || data.temperature > 150.0f) {
            fprintf(stderr, "[SDP810] out-of-range reading: p=%.2f t=%.2f\n",
                    data.pressure, data.temperature);
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(&data) != 0) {
            fprintf(stderr, "[LOG] failed to write data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
               data.pressure, data.temperature);

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

