#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sht40_read(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x2C, 0x06};
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[6];
    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (buf[0] << 8) | buf[1];
    uint16_t h_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SHT40 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature, humidity;
        if (sht40_read(i2c_fd, &temperature, &humidity) == 0) {
            log_data(log_fp, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_S);
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

