#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x31
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define TRIGGER_DELAY  1000     /* 1 ms  */
#define MAX_RETRIES    3
#define RETRY_BASE_US  1000
#define RETRY_MAX_US   5000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write cmd 0x%02X failed (rc=%d)\n", cmd, rc);
    }
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read %u bytes failed (rc=%d)\n", len, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* SDP31 read                                                         */
/* ------------------------------------------------------------------ */
static int sdp31_read(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t data[6];

    /* Trigger continuous measurement */
    if (i2c_write_cmd(handle, 0x3605) < 0)
        return -1;

    gpioDelay(TRIGGER_DELAY);

    /* Read 6 bytes: pressure(2)+crc, temp(2)+crc */
    if (i2c_read_bytes(handle, data, 6) < 0)
        return -1;

    /* CRC check */
    if (data[2] != (uint8_t)(0xC0 + data[0] + data[1])) {
        fprintf(stderr, "[SDP31] pressure CRC mismatch\n");
        return -1;
    }
    if (data[5] != (uint8_t)(0xC0 + data[3] + data[4])) {
        fprintf(stderr, "[SDP31] temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    *pressure_pa = (float)raw_pressure;
    *temp_c      = (float)raw_temp / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure_pa, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure_pa, temp_c);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "[INFO] SDP31 logging started -> %s  (bus=%d, addr=0x%02X)\n",
            LOG_FILE, I2C_BUS, SDP31_ADDR);

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temp_c      = 0.0f;

        int ok = 0;
        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (sdp31_read(g_i2c_handle, &pressure_pa, &temp_c) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES) {
                gpioDelay(RETRY_BASE_US * attempt);
            }
        }

        if (!ok) {
            fprintf(stderr, "[ERROR] SDP31 read failed after %d attempts\n", MAX_RETRIES);
        } else {
            log_data(g_log_file, pressure_pa, temp_c);
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stdout, "\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

