#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define TRIGGER_CMD    0x3605
#define READ_LEN       9
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp800_read(int fd, float *pressure, float *temperature) {
    if (i2c_write(fd, TRIGGER_CMD) < 0)
        return -1;

    usleep(45000);

    uint8_t data[READ_LEN];
    if (i2c_read(fd, data, READ_LEN) < 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale = (int16_t)((data[6] << 8) | data[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor\n");
        return -1;
    }

    *pressure = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / 200.0f;
    return 0;
}

static int log_data(const char *filename, float pressure, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SDP800_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int need_header = (fp == NULL);
    if (fp) {
        fclose(fp);
    }

    if (need_header) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Failed to create %s: %s\n", LOG_FILE, strerror(errno));
            close(fd);
            return 1;
        }
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
        fclose(fp);
    }

    while (running) {
        float pressure, temperature;
        if (sdp800_read(fd, &pressure, &temperature) == 0) {
            if (log_data(LOG_FILE, pressure, temperature) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    if (fd >= 0)
        close(fd);
    return 0;
}

