#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x71
#define MEASURE_CMD_HIGH_REP 0x2C
#define CONVERSION_DELAY_US 15000
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int log_error(const char *msg) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (err_fp) {
        fprintf(err_fp, "%04d-%02d-%02dT%02d:%02d:%02d - ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(err_fp);
    }
    return -1;
}

static int log_data(float temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (log_fp) {
        fprintf(log_fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
        fflush(log_fp);
    }
    return 0;
}

static int read_temperature(float *temp) {
    uint8_t cmd = MEASURE_CMD_HIGH_REP;
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch");
        return -1;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    *temp = (float)raw / 100.0f;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (err_fp) {
        fclose(err_fp);
        err_fp = NULL;
    }
    gpioTerminate();
