/*
 * Si7021 humidity/temperature monitor with hysteresis fan control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Si7021 at address 0x48 (A0 tied to GND)
 * Fan:    Active-cool cooling fan on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define SI7021_ADDR        0x48
#define FAN_GPIO           18
#define TEMP_HIGH          28.0f
#define TEMP_LOW           27.0f
#define BUFFER_SIZE        60
#define SAMPLE_INTERVAL_S  2
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000   /* 10 ms */
#define FAN_SETTLE_US      10000   /* 10 ms */
#define SENSOR_SETTLE_US   10000   /* 10 ms */

/* Si7021 commands (16-bit, big-endian on the bus) */
#define CMD_MEAS_TEMP_HOLD  0xE3   /* 0x3E << 8 | 0x03 */
#define CMD_MEAS_HUMIDITY   0xE5   /* 0x5E << 8 | 0x05 */

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static int      fan_state    = 0;   /* 0 = off, 1 = on */
static int      i2c_handle   = -1;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[I2C] read %d bytes failed (got %d): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    uint8_t data[6];

