    *humidity    = 100.0f * (float)raw_h / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[Sensor] temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[Sensor] humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
