static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t scd40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SCD40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ SCD40_CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd40_write_command(uint8_t cmd) {
    char buf[1] = { (char)cmd };
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%02X to SCD40\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_measurement(uint8_t *buf, size_t len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "Error: Failed to read %zu bytes from SCD40\n", len);
        return -1;
    }
    return 0;
}

static int scd40_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X (pigpio error %d)\n",
                SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (scd40_write_command(SCD40_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int scd40_stop(void) {
    if (scd40_write_command(SCD40_CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        return -1;
    }
    return 0;
}

static int scd40_data_ready(uint8_t *ready) {
    if (scd40_write_command(SCD40_CMD_GET_DATA_READY) != 0) {
        return -1;
    }
    gpioDelay(1000);
    if (scd40_read_measurement((uint8_t *)ready, 1) != 0) {
        return -1;
    }
    return 0;
}

static int scd40_read_measurement_data(uint8_t *buf, size_t len) {
    if (scd40_write_command(SCD40_CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(SCD40_MEASUREMENT_DELAY_US);
    if (scd40_read_measurement(buf, len) != 0) {
        return -1;
    }
    return 0;
}

static int scd40_crc_check(const uint8_t *data, size_t len, uint8_t expected) {
    uint8_t calc = scd40_crc8(data, len);
    return (calc == expected);
}

static int scd40_parse_measurement(const uint8_t *buf, uint16_t *co2, float *temp, float *rh) {
    if (scd40_crc_check(&buf[0], 2, buf[2]) != 0) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }
    if (scd40_crc_check(&buf[3], 2, buf[5]) != 0) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (scd40_crc_check(&buf[6], 2, buf[8]) != 0) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t rh_raw = (buf[6] << 8) | buf[7];

    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *rh = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (scd40_init() != 0) {
        return 1;
    }

    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        scd40_stop();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "# SCD40 air quality log started\n");
    fflush(log_file);

    while (running) {
        uint8_t ready = 0;
        if (scd40_data_ready(&ready) != 0) {
            fprintf(stderr, "Error: Failed to check data ready status\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        if ((ready & SCD40_DATA_READY_MASK) == 0) {
            gpioDelay(SCD40_MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        uint8_t data[9];
        if (scd40_read_measurement_data(data, 9) != 0) {
            fprintf(stderr, "Error: Failed to read measurement data\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd40_parse_measurement(data, &co2, &temp, &rh) != 0) {
            fprintf(stderr, "Error: Failed to parse measurement data\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        log_data(co2, temp, rh);
        printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);

        gpioDelay(SCD40_MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    fprintf(stderr, "\nShutting down...\n");
    scd40_stop();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

