/*
 * SCD40 CO2 monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   CO2 LED   -> GPIO17 (BCM) via 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 *   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_I2C_ADDR       0x40   /* SCD40 default I2C address (SDO tied to GND) */

#define GPIO_LED             17     /* BCM GPIO17 for CO2 warning LED */
#define CO2_THRESHOLD        1000   /* ppm */
#define SAMPLE_INTERVAL_S    5      /* seconds between readings */
#define BUFFER_SIZE          20     /* circular buffer entries */

/* SCD40 command words (16-bit, big-endian on the bus) */
#define CMD_READ_MEASUREMENT  0x3600
#define CMD_START_MEASUREMENT 0x0200
#define CMD_STOP_MEASUREMENT  0x0300
#define CMD_RESET            0x0001

/* ----------------------------- Data Types ------------------------------- */
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ----------------------------- Globals ---------------------------------- */
static int            i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static circular_buffer_t co2_buffer;

/* ----------------------------- Prototypes ------------------------------- */
static int  initialize_i2c(void);
static int  initialize_sensor(void);
static int  read_sensor_data(uint16_t *co2, float *temperature, float *humidity);
static void add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data);
static void print_circular_buffer(const circular_buffer_t *cb);
static void control_led(uint16_t co2);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C / Sensor ------------------------------ */

/*
 * CRC-8 polynomial 0x31, init 0xFF, as per Sensirion SCD40 datasheet.
 * Returns 0 on success, -1 on failure.
 */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Write a 16-bit command word to the SCD40.
 * Returns 0 on success, -1 on failure.
 */
static int scd40_write_command(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a 3-byte measurement word from the SCD40.
 * Returns 0 on success, -1 on failure.
 */
static int scd40_read_measurement(uint8_t *buf, int len)
{
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/*
 * Initialize the SCD40 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_sensor(void)
{
    if (scd40_write_command(CMD_RESET) != 0) {
        fprintf(stderr, "[ERROR] Sensor reset failed\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle after reset */

    if (scd40_write_command(CMD_START_MEASUREMENT) != 0) {
        fprintf(stderr, "[ERROR] Failed to start measurement\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement to be ready */

    return 0;
}

/*
 * Read CO2, temperature, and humidity from the SCD40.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(uint16_t *co2, float *temperature, float *humidity)
{
    uint8_t buf[6];

    if (scd40_write_command(CMD_READ_MEASUREMENT) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms measurement conversion time */

    if (scd40_read_measurement(buf, 6) != 0)
        return -1;

    /* Validate CRC-8 for each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CO2 CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    uint16_t raw_co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    int16_t  raw_temp = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t  raw_hum  = (int16_t)((buf[5] << 8) | buf[4]);

    *co2          = raw_co2;
    *temperature  = (float)raw_temp / 100.0f;
    *humidity     = (float)raw_hum  / 100.0f;

    return 0;
}

/* ----------------------------- Circular Buffer --------------------------- */

static void add_to_circular_buffer(circular_buffer_t *cb, sensor_data_t data)
{
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void print_circular_buffer(const circular_buffer_t *cb)
{
    printf("\n--- Circular Buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&cb->data[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("  [%2d] %s  CO2=%u ppm  T=%.2f C  RH=%.2f %%\n",
               i, ts, cb->data[idx].co2, cb->data[idx].temperature, cb->data[idx].humidity);
    }
    printf("---------------------------------------\n");
}

/* ----------------------------- LED Control ------------------------------ */

static void control_led(uint16_t co2)
{
    if (co2 > CO2_THRESHOLD)
        gpioWrite(GPIO_LED, 1);
    else
        gpioWrite(GPIO_LED, 0);
}

/* ----------------------------- Signal / Cleanup -------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        scd40_write_command(CMD_STOP_MEASUREMENT);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&co2_buffer, 0, sizeof(co2_buffer));

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t co2;
        float    temperature, humidity;

        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data = {
                .timestamp = time(NULL),
                .co2       = co2,
                .temperature = temperature,
                .humidity    = humidity
            };

            add_to_circular_buffer(&co2_buffer, data);
            print_circular_buffer(&co2_buffer);
            control_led(co2);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing...\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && !terminate; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

