/*
 * TMP05 digital temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMP05 VCC  -> 3.3 V (physical pin 1)
 *   TMP05 GND  -> GND   (physical pin 9)
 *   TMP05 OUT  -> GPIO4 (BCM, physical pin 7)
 *
 * The TMP05 output is a PWM-style digital signal: a high pulse width
 * (TW) on the rising edge, a low pulse width (TL) on the falling edge.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_reader tmp05_reader.c -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/time.h>
#include <pthread.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"   /* BCM GPIO4 on Pi 4B */
#define GPIO_LINE_OFFSET    4             /* BCM 4 */
#define LOG_FILE            "temperature_log.txt"
#define SAMPLE_INTERVAL_S   5
#define EDGE_TIMEOUT_US     50000         /* 50 ms */
#define MIN_TEMP_C          (-40.0f)
#define MAX_TEMP_C          (150.0f)
#define MAX_READINGS        3
#define POLL_TIMEOUT_MS     1000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (ISO 8601)                                       */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    if (gettimeofday(&tv, NULL) != 0) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }
    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    pthread_mutex_lock(&g_log_mutex);
    if (g_log) {
        fprintf(g_log, "%s: %s\n", ts, msg);
        fflush(g_log);
    }
    pthread_mutex_unlock(&g_log_mutex);
}

/* ------------------------------------------------------------------ */
/* TMP05 temperature read                                              */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores temperature in *out_temp.
 * Returns -1 on timeout, -2 on division by zero, -3 on out-of-range.
 */
static int read_temperature(float *out_temp)
{
    struct timespec tw, tl;
    struct timespec deadline;
    int rc;

    /* ---- Wait for rising edge (high pulse starts) ---- */
    deadline.tv_sec  = 0;
    deadline.tv_nsec = (long)EDGE_TIMEOUT_US * 1000L;
    rc = nanosleep(&deadline, &tw);
    if (rc != 0) {
        if (errno == EINTR) return -1;
        return -1;
    }
    if (tw.tv_sec == 0 && tw.tv_nsec < 0) return -1;   /* timeout */

    if (clock_gettime(CLOCK_MONOTONIC, &tl) != 0) return -1;
    if (tl.tv_sec == 0 && tl.tv_nsec < 0) return -1;   /* timeout */

    /* ---- Wait for falling edge (high ends) ---- */
    deadline.tv_sec  = 0;
    deadline.tv_nsec = (long)EDGE_TIMEOUT_US * 1000L;
    rc = nanosleep(&deadline, &tw);
    if (rc != 0) {
        if (errno == EINTR) return -1;
        return -1;
    }
    if (tw.tv_sec == 0 && tw.tv_nsec < 0) return -1;

    uint64_t tw_us = (uint64_t)tw.tv_sec * 1000000ULL + (uint64_t)tw.tv_nsec / 1000ULL;
    uint64_t tl_us = (uint64_t)tl.tv_sec * 1000000ULL + (uint64_t)tl.tv_nsec / 1000ULL;

    if (tl_us == 0 || tw_us == 0) return -1;   /* zero low-time */

    float tw_c = (float)tw_us / 1000000.0f;
    float tl_c = (float)tl_us / 1000000.0f;

    if (tw_c == 0.0f || tl_c == 0.0f) return -2;

    float temp = (tw_c - tl_c) * 0.5f;

    if (temp < MIN_TEMP_C || temp > MAX_TEMP_C) return -3;

    *out_temp = temp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int consecutive_failures = 0;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request line ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        fclose(g_log);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "tmp05_reader") < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    printf("TMP05 reader started on GPIO%d. Logging to %s.\n",
           GPIO_LINE_OFFSET, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temp;
        int rc = read_temperature(&temp);

        if (rc == 0) {
            consecutive_failures = 0;
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp);
            log_message(msg);
            printf("%s\n", msg);
        } else {
            consecutive_failures++;
            char msg[128];
            snprintf(msg, sizeof(msg), "Sensor read failed (rc=%d), failures=%d",
                     rc, consecutive_failures);
            log_message(msg);
            if (consecutive_failures >= MAX_READINGS) {
                log_message("SENSOR MALFUNCTION");
                printf("SENSOR MALFUNCTION\n");
                consecutive_failures = 0;   /* reset to avoid spam */
            }
        }

        /* Sleep SAMPLE_INTERVAL_S seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(g_log);
    pthread_mutex_destroy(&g_log_mutex);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

