        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(MEASURE_CMD_HIGH_REP_DELAY_MS * 1000);

    result = i2cReadDevice(handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: expected 6 bytes, got %d\n", result);
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void add_greenhouse_offset(float *temperature, float *humidity) {
    float greenhouse_offset_temp = 2.0f * (float)sinf((float)time(NULL) / GREENHOUSE_PERIOD_S);
    float greenhouse_offset_hum = 5.0f * (float)sinf((float)time(NULL) / GREENHOUSE_PERIOD_S);

    *temperature += greenhouse_offset_temp;
    *humidity += greenhouse_offset_hum;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

int main(void) {
    float temperature, humidity;
    int retry;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        temperature = NAN;
        humidity = NAN;
        retry = 0;

        while (retry < RETRY_COUNT && running) {
            if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
                break;
            }
            retry++;
            if (retry < RETRY_COUNT) {
                fprintf(stderr, "Retry %d/%d...\n", retry, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor after %d retries. Logging NaN values.\n", RETRY_COUNT);
        }

        add_greenhouse_offset(&temperature, &humidity);
        log_data(log_file, temperature, humidity);

        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

