/*
 * SHT35 temperature & humidity logger for Raspberry Pi Zero W
 * I2C bus 1, sensor address 0x38-0x3A (SDO tied to GND)
 * Build: gcc -O2 -Wall -o sht35_logger sht35_logger.c -lsht3x
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SHT35_ADDR        0x38
#define SHT35_CMD_MEASURE  0x2C   /* single-shot, clock-stretching disabled */
#define SHT35_MEAS_DELAY  20000   /* microseconds (20 ms) */
#define SAMPLE_INTERVAL   5       /* seconds */
#define CSV_FILENAME      "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (poly 0x31, init 0xFF, no final XOR) as per SHT3x datasheet ---- */
static uint8_t sht3x_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_csv(void)
{
    FILE *fp = fopen(CSV_FILENAME, "r");
    if (fp == NULL) {
        /* File does not exist yet — create it with header */
        fp = fopen(CSV_FILENAME, "w");
        if (fp == NULL) {
            perror("fopen(CSV, write)");
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fclose(fp);
    } else {
        /* Check if file is empty */
        if (fseek(fp, 0, SEEK_END) != 0) {
            perror("fseek");
            fclose(fp);
            return -1;
        }
        long sz = ftell(fp);
        if (sz < 0) {
            perror("ftell");
            fclose(fp);
            return -1;
        }
        if (sz == 0) {
            fclose(fp);
            fp = fopen(CSV_FILENAME, "w");
            if (fp == NULL) {
                perror("fopen(CSV, write)");
                return -1;
            }
            fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
            fclose(fp);
        }
        fclose(fp);
    }
    return 0;
}

static int read_sht35(float *temperature, float *humidity)
{
    uint8_t cmd = SHT35_CMD_MEASURE;
    uint8_t buf[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "i2cWriteDevice (command 0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    gpioDelay(SHT35_MEAS_DELAY);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRCs */
    if (sht3x_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht3x_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen(CSV, append)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (open_csv() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("%s  T=%.2f C  RH=%.2f %%\n",
                       "reading", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

