        fp = fopen(CSV_FILENAME, "w");
        if (fp == NULL) {
            perror("fopen(CSV, write)");
            return -1;
        }
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
        fclose(fp);
    } else {
        /* Check if file is empty */
        if (fseek(fp, 0, SEEK_END) != 0) {
            perror("fseek");
            fclose(fp);
            return -1;
        }
        long sz = ftell(fp);
        if (sz < 0) {
            perror("ftell");
            fclose(fp);
            return -1;
        }
        if (sz == 0) {
            fclose(fp);
            fp = fopen(CSV_FILENAME, "w");
            if (fp == NULL) {
                perror("fopen(CSV, write)");
                return -1;
            }
            fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
            fclose(fp);
        }
        fclose(fp);
    }
    return 0;
}

static int read_sht35(float *temperature, float *humidity)
{
    uint8_t cmd = SHT35_CMD_MEASURE;
    uint8_t buf[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "i2cWriteDevice (command 0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    gpioDelay(SHT35_MEAS_DELAY);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRCs */
    if (sht3x_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht3x_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen(CSV, append)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (open_csv() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("%s  T=%.2f C  RH=%.2f %%\n",
                       "reading", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

