#define SI7021_ADDR        0x41
#define SI7021_CMD_MEASURE  0xE3
#define SI7021_CMD_RESET    0xFE
#define SI7021_MEAS_DELAY_US  10000
#define LOG_FILE            "environment.log"
#define POLL_TIMEOUT_US     100000
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t msb, uint8_t lsb, uint8_t crc)
{
    if (crc8((uint8_t[]){msb, lsb}, 2) != crc) {
        fprintf(stderr, "CRC mismatch: msb=0x%02X lsb=0x%02X crc=0x%02X\n",
                msb, lsb, crc);
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp)
{
    if (i2c_write_cmd(fd, SI7021_CMD_MEASURE) < 0)
        return -1;
    usleep(SI7021_MEAS_DELAY_US);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;

    if (read_measurement(buf[0], buf[1], buf[2], buf[2]) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw / 1656.0f;
    return 0;
}

static int read_humidity(int fd, float *hum)
{
    if (i2c_write_cmd(fd, SI7021_CMD_MEASURE) < 0)
        return -1;
    usleep(SI7021_MEAS_DELAY_US);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0)
        return -1;

    if (read_measurement(buf[0], buf[1], buf[2], buf[2]) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *hum = (float)raw / 1024.0f;
    return 0;
}

static int reset_sensor(int fd)
{
    if (i2c_write_cmd(fd, SI7021_CMD_RESET) < 0)
        return -1;
    usleep(15000);
    return 0;
}

static int log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (temp < 0.0f || hum < 0.0f) {
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    }

    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (reset_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Warning: sensor reset failed; continuing anyway.\n");
    }

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (read_temperature(g_i2c_fd, &temp) == 0 &&
                read_humidity(g_i2c_fd, &hum) == 0) {
                ok = 1;
                break;
            }
            if (attempt < 2) {
                fprintf(stderr, "Read failed; attempting reset...\n");
                if (reset_sensor(g_i2c_fd) < 0) {
                    fprintf(stderr, "Reset failed; will retry next cycle.\n");
                }
                usleep(100000);
            }
        }

        if (ok) {
            if (log_data(temp, hum) < 0)
                fprintf(stderr, "Logging failed.\n");
        } else {
            fprintf(stderr, "All read attempts failed; resetting sensor.\n");
            if (reset_sensor(g_i2c_fd) < 0)
                fprintf(stderr, "Reset failed; will retry next cycle.\n");
        }

        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

