#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

static int read_sensor(float *pressure) {
    char buf[6];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: expected 6 bytes, got %d\n", bytes_read);
        return -1;
    }
    uint16_t raw_pressure = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw_pressure * 0.1f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    /* Placeholder linear mapping; replace with sensor-specific calibration */
    return pressure * 0.5f;
}

static void control_fan(float flow_rate) {
    int duty = (int)(flow_rate * 10.0f);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(FAN_GPIO, duty);
}

static void log_data(float pressure, float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Airflow control system started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_sensor(&pressure) == 0) {
            float flow_rate = calculate_flow_rate(pressure);
            control_fan(flow_rate);
            log_data(pressure, flow_rate);
            printf("Pressure: %.2f Pa, Flow: %.2f m/s\n", pressure, flow_rate);
        } else {
            fprintf(stderr, "Sensor read error, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

