    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    raw_pressure = (int16_t)((buf[1] << 8) | buf[0]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[2]);

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime_r(&now, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f C\n",
                timestamp, pressure, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }

    while (!terminate) {
        float pressure, temperature;
        if (read_lps33hw(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error: Sensor read failed\n");
            log_data(0.0f, 0.0f);
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

