/*
 * Raspberry Pi Zero W – STLM75 temperature monitor with LED threshold.
 *
 * Wiring:
 *   STLM75 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   STLM75 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   STLM75 VDD  -> 3.3 V
 *   STLM75 GND  -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o stlm75_monitor stlm75_monitor.c -lpigpio -lrt
 *   sudo ./stlm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* STLM75 default I2C address (ADDR pin low) */
#define LED_GPIO       17
#define TEMP_THRESHOLD 28.0f        /* °C */
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  1            /* seconds */

/* STLM75 register addresses */
#define STLM75_REG_TEMP_L  0x00
#define STLM75_REG_TEMP_H  0x01
#define STLM75_REG_CONFIG  0x0E

/* Config register bits */
#define STLM75_CFG_TEMP_EN  (1u << 0)  /* temperature measurement enabled */
#define STLM75_CFG_MEAS_MS  (0u << 1)  /* measurement time 0 ms (default) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);          /* MSB first */
    buf[2] = (char)((value >> 8) & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2] = { 0, 0 };

    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;

    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* STLM75 temperature read                                              */
/* ------------------------------------------------------------------ */
static int read_stlm75_temperature(int handle, float *temperature)
{
    uint16_t raw;

    if (i2c_read_reg16(handle, STLM75_REG_TEMP_L, &raw) != 0) {
        fprintf(stderr, "[ERROR] I2C read failed (reg 0x%02X)\n", STLM75_REG_TEMP_L);
        return -1;
    }

    /* STLM75: 12-bit two's-complement, LSB = 0.0625 °C */
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.0625f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- STLM75 config: enable temperature measurement, 0 ms period ---- */
    if (i2c_write_reg16(g_i2c_handle, STLM75_REG_CONFIG,
                         STLM75_CFG_TEMP_EN | STLM75_CFG_MEAS_MS) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure STLM75 (config reg 0x%02X)\n",
                STLM75_REG_CONFIG);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete */
    time_sleep(0.1);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    /* ---- Main loop ---- */
    while (g_running) {
        float temperature;

        if (read_stlm75_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "[WARN] Temperature read failed; skipping cycle\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        cb_add(&temp_buffer, temperature);
        float avg = cb_average(&temp_buffer);

        printf("Temperature: %.2f °C  |  Average: %.2f °C\n", temperature, avg);

        if (avg > TEMP_THRESHOLD)
            gpioWrite(LED_GPIO, 1);
        else
            gpioWrite(LED_GPIO, 0);

        time_sleep(SAMPLE_PERIOD);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

