    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    return i2cWriteDevice(handle, buf, 2);
}

static int read_bytes(int handle, char *buf, int len) {
    int bytes_read = i2cReadDevice(handle, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d, got %d): %s\n",
                len, bytes_read, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_scd30_data(int handle, float *co2, float *temperature, float *humidity) {
    char data[8];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write_cmd(handle, SCD30_CMD_READ_DATA) != 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(10000);

        if (read_bytes(handle, data, 8) != 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint32_t co2_raw = ((uint32_t)(uint8_t)data[0] << 24) |
                           ((uint32_t)(uint8_t)data[1] << 16) |
                           ((uint32_t)(uint8_t)data[2] << 8)  |
                           ((uint32_t)(uint8_t)data[3]);

