        fprintf(stderr, "Error: SCD30 reset failed\n");
        cleanup();
        return 1;
    }
    gpioDelay(200000);

    if (write_cmd(i2c_handle, SCD30_CMD_STOP) != 0) {
        fprintf(stderr, "Error: SCD30 stop command failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    while (running) {
        float co2, temperature, humidity;

        if (read_scd30_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
            ventilation_control(co2);
        } else {
            fprintf(stderr, "Error: Failed to read SCD30 data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

