/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:    sudo ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP32_ADDR     0x28
#define READ_LEN       9
#define DEFAULT_INTERVAL_MS 1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF, no final XOR)           */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] ", ts);
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte frame and verify CRCs                             */
/* ------------------------------------------------------------------ */
static bool read_sdp32(int handle, float *pressure, float *temperature, float *scale_factor)
{
    uint8_t buf[READ_LEN];

    int n = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n", READ_LEN, n);
        return false;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return false;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return false;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return false;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t raw_scale   = (uint16_t)((buf[6] << 8) | buf[7]);

    *pressure    = (float)raw_pressure / (float)raw_scale;
    *temperature = (float)raw_temp / 200.0f;
    *scale_factor = (float)raw_scale;

    return true;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 3600000) {
            fprintf(stderr, "Invalid interval: '%s'\n", argv[1]);
            return EXIT_FAILURE;
        }
        interval_ms = (int)val;
    }

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SDP32_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started (bus %d, addr 0x%02X, interval %d ms)\n",
           I2C_BUS, SDP32_ADDR, interval_ms);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature, scale_factor;

        if (read_sdp32(g_i2c_handle, &pressure, &temperature, &scale_factor)) {
            print_timestamp();
            printf("Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.2f\n",
                   pressure, temperature, scale_factor);
        } else {
            print_timestamp();
            fprintf(stderr, "Sensor read failed; check wiring and sensor presence.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

