#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x41
#define READ_INTERVAL  1
#define CONVERSION_MS  45

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as per Sensirion SDP8x datasheet: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read differential pressure and temperature from an SDP810-125Pa.
 * Returns 0 on success, -1 on any error.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {0x36, 0x2B};   /* trigger continuous mode */
    uint8_t buf[9];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(CONVERSION_MS * 1000);   /* 45 ms conversion time */

    rc = i2cReadDevice(handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "i2cReadDevice returned %d: %s\n", rc, strerror(errno));
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor word\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_p      = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_t      = (int16_t)((buf[8] << 8) | buf[8]);

    if (scale_p == 0 || scale_t == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_p;
    *temperature = (float)raw_temp / (float)scale_t;

    return 0;
}

int main(void)
{
    int handle = -1;
    float pressure, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa differential pressure sensor reader\n");
    printf("I2C bus %d, address 0x%02X, logging every %d s\n",
           I2C_BUS, I2C_ADDR, READ_INTERVAL);

    while (g_running) {
        if (read_sdp810(handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle\n");
        }
        sleep(READ_INTERVAL);
    }

    if (handle >= 0)
        i2cClose(handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

