#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x38
#define TEMP_REG       0x00
#define HUM_REG        0x01
#define CONV_DELAY_MS  20
#define LOOP_DELAY_S   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity)
{
    if (i2c_write_reg8(fd, TEMP_REG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, HUM_REG, 0x00) < 0) return -1;

    usleep(CONV_DELAY_MS * 1000);

    int16_t raw_temp, raw_hum;
    if (i2c_read_reg16(fd, TEMP_REG, &raw_temp) < 0) return -1;
    if (i2c_read_reg16(fd, HUM_REG, &raw_hum) < 0) return -1;

    *temperature = (float)raw_temp / 16.0f;
    *humidity    = (float)raw_hum / 16.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 sensor reader started on %s (addr 0x%02X).\n", I2C_BUS, HDC1000_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        if (read_hdc1000(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(LOOP_DELAY_S);
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

