#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7051_ADDR 0x76

#define REG_TEMP_LOW  0x00
#define REG_TEMP_HIGH 0x01
#define REG_MEAS_CFG  0x0E
#define REG_INT_CFG   0x0F
#define REG_INT_EN    0x10
#define REG_INT_STATUS 0x11

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature) {
    uint8_t low, high;

    if (i2c_read_reg8(fd, REG_TEMP_LOW, &low) < 0) return -1;
    if (i2c_read_reg8(fd, REG_TEMP_HIGH, &high) < 0) return -1;

    int16_t raw = (int16_t)((high << 8) | low);
    *temperature = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7051_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg8(fd, REG_MEAS_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure Si7051 measurement.\n");
        goto cleanup;
    }

    if (i2c_write_reg8(fd, REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure Si7051 interrupt.\n");
        goto cleanup;
    }

    if (i2c_write_reg8(fd, REG_INT_EN, 0x01) < 0) {
        fprintf(stderr, "Failed to enable Si7051 interrupt.\n");
        goto cleanup;
    }

    while (running) {
        if (read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

