#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP10101_ADDR 0x71
#define MEASURE_CMD 0x0F
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US 5000000
#define DEFAULT_PRESSURE 101325.0f
#define DEFAULT_TEMPERATURE 22.45f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_sensor_data(int handle, float *temperature, float *pressure) {
    char cmd = MEASURE_CMD;
    char buf[6];
    int result;

    result = i2cWriteDevice(handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    result = i2cReadDevice(handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: read %d bytes\n", result);
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)(uint8_t)buf[0] << 16) |
                           ((uint32_t)(uint8_t)buf[1] << 8)  |
                           ((uint32_t)(uint8_t)buf[2]);
    uint32_t raw_temperature = ((uint32_t)(uint8_t)buf[3] << 16) |
                               ((uint32_t)(uint8_t)buf[4] << 8)  |
                               ((uint32_t)(uint8_t)buf[5]);

    if (raw_pressure == 0x00000000 || raw_temperature == 0x00000000) {
        fprintf(stderr, "Sensor absent or not responding (default values)\n");
        return -1;
    }

    *pressure = (float)raw_pressure;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void print_sensor_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    float temperature, pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_sensor_data(i2c_handle, &temperature, &pressure) == 0) {
            print_sensor_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

