#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x1E
#define PRESSURE_REG 0x00
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] ", ts);
}

int main(void) {
    int fd = -1;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n", I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_pressure = 0;
        bool read_ok = (i2c_read_reg16(fd, PRESSURE_REG, &raw_pressure) == 0);

        if (read_ok) {
            print_timestamp();
            printf("Pressure: %d Pa\n", raw_pressure);
        } else {
            print_timestamp();
            fprintf(stderr, "Error: Failed to read pressure from sensor.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret_code;
}

