/*
 * SDP800 differential pressure logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_log sdp800_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_PERIOD_US 1000000   /* 1 second */
#define TRIGGER_DELAY_US 10000     /* 10 ms */
#define MEAS_DELAY_US   8000       /* 8 ms  */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp800_trigger(int fd)
{
    return i2c_write_byte(fd, 0x36);   /* trigger continuous measurement */
}

static int sdp800_read(int fd, float *pressure)
{
    uint8_t buf[3];

    if (sdp800_trigger(fd) != 0)
        return -1;

    usleep(TRIGGER_DELAY_US);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 100.0f;   /* Pa */
    return 0;
}

static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
        fflush(fp);
    }
    return 0;
}

static int log_write(const char *path, const char *ts, float pressure)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f\n", ts, pressure);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 airflow logger started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure;
        if (sdp800_read(fd, &pressure) == 0) {
            char ts[32];
            time_t now = time(NULL);
            struct tm tmv;
            if (localtime_r(&now, &tmv)) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
            } else {
                snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
            }
            if (log_write(LOG_FILE, ts, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; continuing\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (close(fd) != 0)
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

