code:
/*
 * MLX90821 relative pressure sensor logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90821_log mlx90821_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* MLX90821 default I2C address (7-bit) */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0           /* seconds between samples */
#define SAMPLE_DELAY   0.1            /* microseconds between I2C retries */
#define PRESSURE_LOW   200.0          /* kPa  — below this = warning */
#define PRESSURE_HIGH  250.0          /* kPa  — above this = warning */
#define MAX_RETRIES    3
#define RETRY_DELAY    1.0            /* seconds between retries */

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and verify the sensor driver library is loaded  */
/* ------------------------------------------------------------------ */
static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n",
                g_i2c_handle);
        gpioTerminate();
        g_i2c_handle = -1;
        return -1;
    }

    /* Verify the sensor is present by reading a known register. */
    int reg = 0x00;
    int val = i2cReadByteData(g_i2c_handle, reg);
    if (val < 0) {
        fprintf(stderr, "Error: MLX90821 not responding on bus %d addr 0x%02X.\n",
                I2C_BUS, I2C_ADDR);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one pressure sample from the MLX90821.                        */
/* Returns 0 on success and stores pressure in *out_kPa.             */
/* Returns -1 on any I2C error.                                       */
/* ------------------------------------------------------------------ */
static int read_pressure(float *out_kPa)
{
    if (out_kPa == NULL) {
        return -1;
    }

    /*
     * The MLX90821 provides a raw 16-bit big-endian signed value
     * representing relative pressure in kPa.  A typical read
     * sequence involves reading two bytes and converting them
     * to a signed 16-bit value.
     */
    int raw = i2cReadWordData(g_i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (pigpio error %d).\n",
                raw);
        return -1;
    }

    /*
     * pigpio returns the word as (high_byte << 8) | low_byte.
     * The MLX90821 sends MSB first, so the value is already
     * correctly assembled as a big-endian 16-bit word.
     */
    int16_t signed_raw = (int16_t)raw;

    *out_kPa = (float)signed_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a pressure reading to the CSV file.                             */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure_kPa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Check if the log file is newly created (size == 0) and write a    */
/* header row so CSV parsing is straightforward.                       */
/* ------------------------------------------------------------------ */
static int ensure_csv_header(void)
{
    long file_size = 0;
    FILE *check = fopen(LOG_FILE, "r");
    if (check == NULL) {
        /* File does not exist yet — create it and write the header. */
        file_size = 0;
    } else {
        fseek(check, 0, SEEK_END);
        file_size = ftell(check);
        fclose(check);
    }

    if (file_size == 0) {
        g_log_file = fopen(LOG_FILE, "w");
        if (g_log_file == NULL) {
            fprintf(stderr, "Error: cannot create log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header: %s\n",
                    strerror(errno));
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources — safe to call multiple times.                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90821 pressure logger started.  Logging to '%s' every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_failures = 0;

    while (g_running) {
        float pressure_kPa = 0.0f;

        if (read_pressure(&pressure_kPa) == 0) {
            consecutive_failures = 0;

            log_pressure(pressure_kPa);

            if (pressure_kPa < PRESSURE_LOW || pressure_kPa > PRESSURE_HIGH) {
                fprintf(stderr,
