/*
 * MLX90821 relative pressure sensor logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90821_log mlx90821_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* MLX90821 default I2C address (7-bit) */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0           /* seconds between samples */
#define SAMPLE_DELAY   0.1            /* microseconds between I2C retries */
#define PRESSURE_LOW   200.0          /* kPa  — below this = warning */
#define PRESSURE_HIGH  250.0          /* kPa  — above this = warning */
#define MAX_RETRIES    3
#define RETRY_DELAY    1.0            /* seconds between retries */

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and verify the sensor driver library is loaded  */
/* ------------------------------------------------------------------ */
static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n",
                g_i2c_handle);
        gpioTerminate();
        g_i2c_handle = -1;
        return -1;
    }

    /* Verify the sensor is present by reading a known register. */
    int reg = 0x00;
    int val = i2cReadByteData(g_i2c_handle, reg);
    if (val < 0) {
        fprintf(stderr, "Error: MLX90821 not responding on bus %d addr 0x%02X.\n",
                I2C_BUS, I2C_ADDR);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one pressure sample from the MLX90821.                        */
/* Returns 0 on success and stores pressure in *out_kPa.             */
/* Returns -1 on any I2C error.                                       */
/* ------------------------------------------------------------------ */
static int read_pressure(float *out_kPa)
{
    if (out_kPa == NULL) {
        return -1;
    }

    /*
     * The MLX90821 provides a raw 16-bit big-endian signed value
     * representing relative pressure in kPa.  A typical read
     * sequence involves reading two bytes and converting them
     * to a signed 16-bit value.
     */
    int raw = i2cReadWordData(g_i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (pigpio error %d).\n",
                raw);
        return -1;
    }

    /*
     * pigpio returns the word as (high_byte << 8) | low_byte.
     * The MLX90821 sends MSB first, so the value is already
     * correctly assembled as a big-endian 16-bit word.
     */
    int16_t signed_raw = (int16_t)raw;

    *out_kPa = (float)signed_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a pressure reading to the CSV file.                             */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure_kPa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Check if the log file is newly created (size == 0) and write a    */
/* header row so CSV parsing is straightforward.                       */
/* ------------------------------------------------------------------ */
static int ensure_csv_header(void)
{
    long file_size = 0;
    FILE *check = fopen(LOG_FILE, "r");
    if (check == NULL) {
        /* File does not exist yet — create it and write the header. */
        file_size = 0;
    } else {
        fseek(check, 0, SEEK_END);
        file_size = ftell(check);
        fclose(check);
    }

    if (file_size == 0) {
        g_log_file = fopen(LOG_FILE, "w");
        if (g_log_file == NULL) {
            fprintf(stderr, "Error: cannot create log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header: %s\n",
                    strerror(errno));
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources — safe to call multiple times.                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90821 pressure logger started.  Logging to '%s' every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_failures = 0;

    while (g_running) {
        float pressure_kPa = 0.0f;

        if (read_pressure(&pressure_kPa) == 0) {
            consecutive_failures = 0;

            log_pressure(pressure_kPa);

            if (pressure_kPa < PRESSURE_LOW || pressure_kPa > PRESSURE_HIGH) {
                fprintf(stderr,
                        "Warning: pressure %.2f kPa out of safe range "
                        "(%.0f–%.0f kPa).\n",
                        pressure_kPa, PRESSURE_LOW, PRESSURE_HIGH);
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Error: pressure read failed (attempt %d/%d).\n",
                    consecutive_failures, MAX_RETRIES);

            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Fatal: %d consecutive failures. "
                                "Reopening I2C bus.\n", consecutive_failures);
                if (g_i2c_handle >= 0) {
                    i2cClose(g_i2c_handle);
                    g_i2c_handle = -1;
                }
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "Fatal: I2C re-initialization failed.\n");
                    return EXIT_FAILURE;
                }
                consecutive_failures = 0;
            }

            /* Sleep SAMPLE_DELAY microseconds before retrying. */
            gpioDelay(SAMPLE_DELAY * 1000);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi Zero W – Honeywell HIH6130 I2C environmental logger
 *
 * Wiring:
 *   HIH6130 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   HIH6130 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   HIH6130 VDD  -> 3.3 V
 *   HIH6130 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o env_logger env_logger.c
 * Run:    ./env_logger   (requires r/w access to the log file)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576          /* 1 MiB */
#define SAMPLE_INTERVAL 5                /* seconds */
#define MEAS_DELAY_MS  40               /* HIH6130 conversion time */

/* HIH6130 register addresses */
#define HIH6130_REG_STATUS 0x00
#define HIH6130_REG_HUMIDITY 0x01
#define HIH6130_REG_TEMPERATURE 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a single byte to a HIH6130 register.
 * Returns 0 on success, -1 on error.
 */
static int hih6130_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from a HIH6130 register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int hih6130_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read(reg 0x%02X): %s\n",
                reg, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read temperature and humidity from the HIH6130.
 * Returns 0 on success and stores T_celsius and RH_percent in *out;
 * -1 on error.
 */
static int hih6130_read(int fd, float *T_celsius, float *RH_percent)
{
    uint16_t status;
    uint16_t raw_h;
    uint16_t raw_t;

    /* Trigger a new measurement by writing the power-on reset byte (0x00). */
    if (hih6130_write_reg(fd, HIH6130_REG_STATUS, 0x00) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    /* Read status register (0x00) to confirm the conversion is complete. */
    if (hih6130_read_reg16(fd, HIH6130_REG_STATUS, &status) < 0)
        return -1;

    /* Bit 0 of the status register indicates whether the conversion is
     * complete and the data is valid. */
    if ((status & 0x01) == 0) {
        fprintf(stderr, "HIH6130 conversion not complete (status=0x%02X)\n",
                status);
        return -1;
    }

    /* Read humidity (2 bytes, big-endian). */
    if (hih6130_read_reg16(fd, HIH6130_REG_HUMIDITY, &raw_h) < 0)
        return -1;

    /* Read temperature (2 bytes, big-endian). */
    if (hih6130_read_reg16(fd, HIH6130_REG_TEMPERATURE, &raw_t) < 0)
        return -1;

    /* Convert raw values to physical units. */
    *RH_percent = (float)raw_h / 65535.0f * 100.0f;
    *T_celsius  = (float)raw_t / 65535.0f * 165.0f - 40.0f;

    /* Sanity-check ranges. */
    if (*RH_percent < 0.0f || *RH_percent > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f%%\n", *RH_percent);
        return -1;
    }
    if (*T_celsius < -40.0f || *T_celsius > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *T_celsius);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return fd;
}

static int log_write(int fd, const char *data)
{
    size_t len = strlen(data);
    ssize_t n = write(fd, data, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "write(log): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus and set the slave address. */
    g_i2c_fd = i2c_open(I2C_BUS, 0x63);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* Open the log file. */
    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float T_celsius = 0.0f;
        float RH_percent = 0.0f;

        if (hih6130_read(g_i2c_fd, &T_celsius, &RH_percent) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            char ts[32];
            log_timestamp(ts, sizeof(ts));

            char line[128];
            int len = snprintf(line, sizeof(line),
                              "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                              ts, T_celsius, RH_percent);
            if (len > 0 && len < (int)sizeof(line)) {
                if (log_write(log_fd, line) < 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                } else {
                    printf("%s", line);
                }
            }

            /* Roll the log file when it exceeds 1 MiB. */
            if (fstat(log_fd, &errno) == 0) {
                long size = (long)errno;
                if (size >= 0 && size >= LOG_SIZE_LIMIT) {
                    if (fsync(log_fd) < 0) {
                        fprintf(stderr, "fsync: %s\n", strerror(errno));
                    }
                    if (ftruncate(log_fd, LOG_SIZE_LIMIT) < 0) {
                        fprintf(stderr, "ftruncate: %s\n", strerror(errno));
                    }
                }
            }
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

