/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return fd;
}

static int log_write(int fd, const char *data)
{
    size_t len = strlen(data);
    ssize_t n = write(fd, data, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "write(log): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus and set the slave address. */
    g_i2c_fd = i2c_open(I2C_BUS, 0x63);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* Open the log file. */
    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float T_celsius = 0.0f;
        float RH_percent = 0.0f;

        if (hih6130_read(g_i2c_fd, &T_celsius, &RH_percent) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            char ts[32];
            log_timestamp(ts, sizeof(ts));

            char line[128];
            int len = snprintf(line, sizeof(line),
                              "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                              ts, T_celsius, RH_percent);
            if (len > 0 && len < (int)sizeof(line)) {
                if (log_write(log_fd, line) < 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                } else {
                    printf("%s", line);
                }
            }

            /* Roll the log file when it exceeds 1 MiB. */
            if (fstat(log_fd, &errno) == 0) {
                long size = (long)errno;
                if (size >= 0 && size >= LOG_SIZE_LIMIT) {
                    if (fsync(log_fd) < 0) {
                        fprintf(stderr, "fsync: %s\n", strerror(errno));
                    }
                    if (ftruncate(log_fd, LOG_SIZE_LIMIT) < 0) {
                        fprintf(stderr, "ftruncate: %s\n", strerror(errno));
                    }
                }
            }
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

