/*
 * MLX90824 SENT pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for GPIO timing and level detection.
 *
 * Wiring:
 *   MLX90824 VCC  -> 3.3 V (Pin 1)
 *   MLX90824 GND  -> GND   (Pin 9)
 *   MLX90824 SCL  -> GPIO4 (Pin 7, BCM 4)
 *   MLX90824 SDA  -> GPIO4 (Pin 7, BCM 4)  [SENT uses SCL/SDA]
 *
 * Build: gcc -O2 -Wall -o brake_pressure brake_pressure.c -lpigpio -lrt
 * Run:   sudo ./brake_pressure
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO        4
#define LOG_FILE         "pressure_log.txt"
#define SAMPLE_PERIOD_US 10000          /* 10 ms between samples */
#define SYNC_TIMEOUT_US  1000000        /* 1 s for synchronization */
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define NIBBLES_PER_DATA 4
#define MAX_PULSE_TICKS  1000          /* guard against runaway sensor */

/* ------------------------------------------------------------------ */
/* Globals for signal handler                                          */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep                                                  */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned ms)
{
    while (ms > 0) {
        unsigned chunk = (ms > 1000) ? 1000 : ms;
        gpioDelay(chunk * 1000);
        ms -= chunk;
    }
}

/* ------------------------------------------------------------------ */
/* Read one SENT nibble: returns 0..15 or -1 on error                  */
/* ------------------------------------------------------------------ */
static int read_nibble(void)
{
    uint32_t start_tick = gpioTick();
    int level = gpioRead(SENT_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", SENT_GPIO);
        return -1;
    }
    if (level != 0 && level != 1) {
        fprintf(stderr, "Error: unexpected GPIO level %d on GPIO%d\n",
                level, SENT_GPIO);
        return -1;
    }

    /* Wait for falling edge (end of nibble) */
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > SYNC_TIMEOUT_US) {
            fprintf(stderr, "Error: SENT nibble timeout (sensor absent?)\n");
            return -1;
        }
        sleep_ms(1);
    }

    uint32_t end_tick = gpioTick();
    uint32_t pulse_us = end_tick - start_tick;
    int ticks = (int)(pulse_us / 3);          /* 3 us per tick */

    if (ticks < NIBBLE_MIN_TICKS || ticks > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "Error: pulse width %u us out of range (%d-%d)\n",
                pulse_us, NIBBLE_MIN_TICKS, NIBBLE_MAX_TICKS);
        return -1;
    }

    return (ticks - NIBBLE_MIN_TICKS) / 4;     /* 0..15 */
}

/* ------------------------------------------------------------------ */
/* Read all 4 data nibbles and compute checksum                     */
/* ------------------------------------------------------------------ */
static int read_data_nibbles(uint16_t *status, uint16_t *data)
{
    for (int i = 0; i < NIBBLES_PER_DATA; i++) {
        int nibble = read_nibble();
        if (nibble < 0)
            return -1;
        if (nibble > 15) {
            fprintf(stderr, "Error: nibble %d out of range\n", nibble);
            return -1;
        }
        if (i < 3)
            *data = (*data << 4) | (uint16_t)nibble;
        else
            *status = (uint16_t)nibble;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading                                                    */
/* ------------------------------------------------------------------ */
static void log_reading(float pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- configure GPIO ---- */
    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);   /* SCL is open-drain */

    printf("MLX90824 SENT pressure sensor reader started.\n");
    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        uint16_t status = 0;
        uint16_t data = 0;
        int rc = read_data_nibbles(&status, &data);

        if (rc == 0) {
            /* Validate status nibble (should be 0 or 1) */
            if (status != 0 && status != 1) {
                fprintf(stderr, "Error: invalid status nibble %u\n", status);
                continue;
            }

            /* Validate data nibbles (each 0..15) */
            for (int i = 0; i < NIBBLES_PER_DATA; i++) {
                if (data & (1 << i)) {
                    fprintf(stderr, "Error: data nibble %d indicates fault\n", i);
                    continue;
                }
            }

            /* Compute checksum: nibble 0 + nibble 1 + nibble 2 + nibble 3 */
            uint8_t calc = (uint8_t)(status + data + data + data);
            uint8_t recv = (uint8_t)(status + data + data + data);

            if (calc != recv) {
                fprintf(stderr, "Error: checksum mismatch (calc=0x%02X recv=0x%02X)\n",
                        calc, recv);
                continue;
            }

            /* Convert 16-bit data to pressure (Pa) */
            /* Placeholder: replace with actual sensor calibration */
            float pressure = (float)data * 0.1f;
            log_reading(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Error: failed to read SENT data\n");
        }

        sleep_ms(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

