/*
 * greenhouse_monitor.c — Raspberry Pi Zero W
 *
 * Monitors the Adafruit TMP117 high-precision temperature sensor over I2C
 * and logs 32-bit little-endian float readings to greenhouse_temps.dat every
 * 60 seconds.  Graceful shutdown on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c -lpigpio -lrt
 * Run:    sudo ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x1D
#define LOG_FILE       "greenhouse_temps.dat"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define ERROR_SAMPLE   5           /* consecutive failures before abort */

/* TMP117 register addresses (from Adafruit TMP117 datasheet) */
#define TMP117_REG_TEMP_L  0x00
#define TMP117_REG_TEMP_H  0x01
#define TMP117_REG_ID      0x0C

#define TMP117_ID_EXPECTED 0x1D   /* 'T' + 0x1D = 0x1D */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 32-bit little-endian float into the binary log file.        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_temperature(float temperature)
{
    uint32_t u;
    if (fwrite(&u, sizeof(u), 1, g_log_file) != 1) {
        fprintf(stderr, "Error writing temperature to log file: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 32-bit temperature register from the TMP117.                */
/* Returns 0 on success and stores the temperature in *out_temp.      */
/* Returns -1 on I2C error.                                            */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *out_temp)
{
    char buf[2];

    /* Read 2 bytes starting at TMP117_REG_TEMP_L (0x00). */
    if (i2cReadI2CBlockData(handle, TMP117_REG_TEMP_L, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature register: %s\n",
                strerror(errno));
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buf[1] << 24) |
                   ((uint32_t)(uint8_t)buf[0] << 16) |
                   ((uint32_t)(uint8_t)buf[1] << 8)  |
                   ((uint32_t)(uint8_t)buf[0]);

    /* TMP117: 16-bit two's-complement, LSB = 0.1 °C. */
    *out_temp = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Verify sensor identity. */
    int id = i2cReadByteData(g_i2c_handle, TMP117_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading TMP117 ID register: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }
    if (id != TMP117_ID_EXPECTED) {
        fprintf(stderr, "Unexpected TMP117 ID 0x%02X (expected 0x%02X)\n",
                id, TMP117_ID_EXPECTED);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE, "ab");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Greenhouse temperature monitor started.  Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            consecutive_errors = 0;
            printf("Temperature: %.2f °C\n", temperature);

            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading temperature (attempt %d/%d).\n",
                    consecutive_errors, ERROR_SAMPLE);

            if (consecutive_errors >= ERROR_SAMPLE) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Greenhouse temperature monitor stopped.\n");
    return EXIT_SUCCESS;
}

