#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR 0x40
#define SHT40_CMD_TEMP 0x2C00
#define SHT40_CMD_HUM 0x2C10
#define SHT40_CONV_MS 9
#define SAMPLE_INTERVAL_S 5
#define DATA_FILE "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sht40_read(int handle, float *temperature, float *humidity) {
    uint8_t cmd;
    uint8_t buf[6];

    if (i2cWriteWordData(handle, SHT40_CMD_TEMP, 0x0000) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(SHT40_CONV_MS * 1000);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT40\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (buf[0] << 8) | buf[1];
    uint16_t h_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                ts, temperature, humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed on log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(DATA_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(g_i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(g_log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: SHT40 read failed\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return 0;
}

