#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x1D
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(double *temperature) {
    char reg = 0x00;
    char data[2];
    int result;

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature register address.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1;
    }

    int16_t raw_temp = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (double)raw_temp / 100.0;
    return 0;
}

static void add_temperature(double temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void flush_buffer(void) {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file for writing.\n");
        return;
    }

    size_t items_written = fwrite(temperature_buffer, sizeof(double), buffer_count, fp);
    if (items_written != buffer_count) {
        fprintf(stderr, "Error: Failed to write all buffer entries to file.\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file.\n");
    }
}

static void cleanup(void) {
    flush_buffer();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n", TMP117_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (running) {
        double temperature;
        if (read_temperature(&temperature) == 0) {
            add_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Warning: Failed to read temperature, skipping sample.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

