#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x1E
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* Si7202 register addresses */
#define REG_TEMP_LSB 0x00
#define REG_TEMP_MSB 0x01
#define REG_ROTATION_LSB 0x02
#define REG_ROTATION_MSB 0x03
#define REG_CONFIG 0x0F
#define REG_INT_CFG 0x10
#define REG_INT_STATUS 0x11
#define REG_REV_ID 0x12

#define REV_ID_EXPECTED 0x1E

static volatile sig_atomic_t g_running = 1;
