    uint8_t lsb, msb;
    if (read_reg8(handle, reg_lsb, &lsb) < 0) return -1;
    if (read_reg8(handle, reg_lsb + 1, &msb) < 0) return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_rev_id(int handle, uint8_t *rev_id) {
    uint8_t id;
    if (read_reg8(handle, REG_REV_ID, &id) < 0) return -1;
    if (id != REV_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected revision ID 0x%02X (expected 0x%02X)\n",
                id, REV_ID_EXPECTED);
        return -1;
    }
    *rev_id = id;
    return 0;
}

static int init_si7202(int handle) {
    uint8_t rev_id = 0;
