#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_i2c(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *flow_rate, float *temperature) {
    char buf[4];
    int bytes_read = i2cReadDevice(g_i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C device: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }

    uint32_t raw_flow = ((uint32_t)(uint8_t)buf[0] << 24) |
                        ((uint32_t)(uint8_t)buf[1] << 16) |
                        ((uint32_t)(uint8_t)buf[2] << 8)  |
                        ((uint32_t)(uint8_t)buf[3]);

    uint32_t raw_temp = ((uint32_t)(uint8_t)buf[0] << 16) |
                        ((uint32_t)(uint8_t)buf[1] << 8)  |
                        ((uint32_t)(uint8_t)buf[2]);

    /* HAFUHH0025PA3: 14-bit flow, 12-bit temperature */
    *flow_rate = (float)((raw_flow >> 8) & 0x3FFF) / 100.0f;
    *temperature = (float)(raw_temp & 0x0FFF) / 10.0f;

    return 0;
}

static void log_data(float flow_rate, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

