#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT_US 1000000
#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 40
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_HIGH_US 26
#define DHT11_BIT_TIMEOUT_US 100
#define DHT11_MAX_BITS 40
#define DHT11_MIN_INTERVAL_S 1
#define DHT11_READ_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg, int status) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - ERROR: %s (status=%d)\n", ts, msg, status);
        fflush(log_file);
    }
    fprintf(stderr, "%s - ERROR: %s (status=%d)\n", ts, msg, status);
}

static void log_data(uint16_t hum, uint16_t temp, uint8_t chk) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - DHT11: Humidity=%u%%, Temperature=%uC, Checksum=%u\n",
                ts, hum, temp, chk);
        fflush(log_file);
    }
    printf("%s - DHT11: Humidity=%u%%, Temperature=%uC, Checksum=%u\n",
           ts, hum, temp, chk);
}

static void log_timeout(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - TIMEOUT: %s\n", ts, msg);
        fflush(log_file);
    }
    fprintf(stderr, "%s - TIMEOUT: %s\n", ts, msg);
}

static void log_stuck(const char *state) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - STUCK: %s\n", ts, state);
        fflush(log_file);
    }
    fprintf(stderr, "%s - STUCK: %s\n", ts, state);
}

static void log_sensor_absent(void) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s - SENSOR_ABSENT: No response from DHT11 on GPIO%d\n",
                ts, DHT11_GPIO);
        fflush(log_file);
    }
    fprintf(stderr, "%s - SENSOR_ABSENT: No response from DHT11 on GPIO%d\n",
            ts, DHT11_GPIO);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (gpioTick() - start > timeout_us) {
            return -1;
        }
    }
    return 0;
}

static int wait_level_high(uint32_t timeout_us) {
    return wait_level(DHT11_GPIO, 1, timeout_us);
}

static int wait_level_low(uint32_t timeout_us) {
    return wait_level(DHT11_GPIO, 0, timeout_us);
}

static int wait_level_high_timeout(uint32_t timeout_us) {
    return wait_level_high(timeout_us);
}

static int wait_level_low_timeout(uint32_t timeout_us) {
    return wait_level_low(timeout_us);
}

static int read_dht11(uint16_t *hum, uint16_t *temp) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int bit_count = 0;
    uint32_t last_tick = 0;
    uint32_t last_level = 0;
    uint32_t start_tick = 0;
    uint32_t start_level = 0;

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, 0) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(DHT11_GPIO, 1) < 0) return -1;
    gpioDelay(DHT11_START_HIGH_US);

    /* Switch to input; sensor will pull low after response */
    if (gpioSetMode(DHT11_GPIO, PI_INPUT) < 0) return -1;

    /* --- Sensor response: 80 us low + 80 us high --- */
    if (wait_level_low_timeout(DHT11_TIMEOUT_US) < 0) {
        log_timeout("DHT11: No response low pulse");
        return -1;
    }
    if (wait_level_high_timeout(DHT11_TIMEOUT_US) < 0) {
        log_timeout("DHT11: No response high pulse");
        return -1;
    }
    last_level = 1;
    start_tick = gpioTick();
    start_level = 1;

    /* --- Read 40 data bits --- */
    for (bit_idx = 0; bit_idx < DHT11_MAX_BITS; bit_idx++) {
        /* Low period for this bit */
        if (wait_level_low_timeout(DHT11_BIT_LOW_US) < 0) {
            log_timeout("DHT11: Bit low timeout");
            return -1;
        }

        /* High period: ~26-28 us = '0', ~70 us = '1' */
        uint32_t high_start = gpioTick();
        if (wait_level_high_timeout(DHT11_BIT_HIGH_US) < 0) {
            log_timeout("DHT11: Bit high timeout");
            return -1;
        }
        uint32_t high_duration = gpioTick() - high_start;

        /* If high exceeds typical range, it is a '1' */
        if (high_duration > DHT11_BIT_HIGH_US * 1.5) {
            data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
        }
        bit_count++;

        /* Wait for next low to start the next bit */
        if (wait_level_low_timeout(DHT11_BIT_LOW_US) < 0) {
            log_timeout("DHT11: Bit low timeout (end of bit)");
            return -1;
        }
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) {
        log_error("DHT11: Checksum mismatch", checksum);
        return -1;
    }

    /* --- Parse --- */
    *hum = (uint16_t)((data[0] << 8) | data[1]);
    *temp = (uint16_t)((data[2] << 8) | data[3]);

    /* --- Sanity range checks --- */
    if (*hum > 100 || *hum < 0 || *temp > 100 || *temp < -40) {
        log_error("DHT11: Out-of-range values", *hum, *temp);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("dht11_readings.txt", "a");
    if (!log_file) {
        perror("fopen dht11_readings.txt");
        gpioTerminate();
        return 1;
    }

    printf("DHT11 reader started on GPIO%d. Press Ctrl+C to exit.\n", DHT11_GPIO);

    while (running) {
        uint16_t hum = 0, temp = 0;
        int rc = read_dht11(&hum, &temp);

        if (rc == 0) {
            log_data(hum, temp, 0);
        } else {
            log_error("DHT11: Read failed", rc);
        }

        /* Sleep DHT11_MIN_INTERVAL_S between readings */
        for (int i = 0; i < DHT11_READ_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

