#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT31_ADDR 0x28
#define LOG_FILE "sht31d_data.log"
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define READ_INTERVAL_SEC 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x2C, 0x06};
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): expected 6 bytes, got %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(100000);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SHT31_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,ERROR,READ_FAILED\n", timestamp);
            fflush(log_file);
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

