#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD105_ADDR 0x29

#define ADPD105_REG_CONFIG 0x00
#define ADPD105_REG_DATA0 0x04
#define ADPD105_REG_DATA1 0x05

#define ADPD105_CONFIG_DEFAULT 0x0000
#define ADPD105_DATA0_DEFAULT 0x0000
#define ADPD105_DATA1_DEFAULT 0x0000

#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd105_init(int fd) {
    if (i2c_write_reg16(fd, ADPD105_REG_CONFIG, ADPD105_CONFIG_DEFAULT) < 0) {
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, uint16_t *data0, uint16_t *data1) {
    if (i2c_read_reg16(fd, ADPD105_REG_DATA0, data0) < 0) return -1;
    if (i2c_read_reg16(fd, ADPD105_REG_DATA1, data1) < 0) return -1;
    return 0;
}

static float calculate_cct(uint16_t data0, uint16_t data1) {
    // Placeholder calculation; replace with actual ADPD105 algorithm
    return (float)(data0 + data1) / 2.0f;
}

static int log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD105_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (adpd105_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD105 initialization failed\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Average_CCT\n");
        fflush(log_fp);
    }

    printf("Starting CCT logging. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t data0 = 0, data1 = 0;
        int ret = read_sensor_data(i2c_fd, &data0, &data1);

        if (ret == 0) {
            float cct = calculate_cct(data0, data1);
            if (log_cct(cct) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read error, skipping cycle.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

