#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x50
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB   0x02
#define REG_TEMP_LSB   0x03
#define REG_CONFIG     0x04
#define REG_ID         0x0F

#define CONFIG_DEFAULT 0x0000
#define ID_EXPECTED    0x50

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        mlx90824_close(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_error(const char *msg) {
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        return -1;
    }
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
    return -1;
