    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data, 6) != 6) {
        return -1;
    }

    *pressure = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    *temperature = ((uint16_t)(uint8_t)data[3] << 8) | (uint8_t)data[4];
    return 0;
}

static int configure_sensor(int handle) {
    char config[2] = { (char)(CONFIG_DEFAULT >> 8), (char)(CONFIG_DEFAULT & 0xFF) };
    if (i2cWriteDevice(handle, config, 2) != 0) {
