    uint16_t id_val = ((uint16_t)(uint8_t)id[0] << 8) | (uint8_t)id[1];
    if (id_val != ID_EXPECTED) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%04X, got 0x%04X\n", ID_EXPECTED, id_val);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
