#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75_ADDR      0x4D
#define LM75_REG_TEMP  0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static float temperature_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LM75_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, LM75_REG_TEMP, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature from LM75: %d\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *temp_out = (float)raw / 100.0f;
    return 0;
}

static float calculate_average(void)
{
    if (buffer_count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++)
        sum += temperature_buffer[i];
    return sum / (float)buffer_count;
}

static void control_fan(float avg_temp)
{
    static bool fan_on = false;

    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error writing GPIO %d HIGH\n", FAN_GPIO);
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error writing GPIO %d LOW\n", FAN_GPIO);
        }
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LM75 temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            temperature_buffer[buffer_index] = temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE)
                buffer_count++;

            float avg = calculate_average();
            printf("Temp: %.2f C  Avg: %.2f C  Fan: %s\n",
                   temp, avg, fan_on ? "ON" : "OFF");

            control_fan(avg);
        } else {
            fprintf(stderr, "Read error; will retry next cycle.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

