/*
 * Raspberry Pi Zero W – Sensirion SDP810-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lsensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sensor/sensor.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define PRESSURE_THRESHOLD 5.0f   /* Pa – warn below this */
#define MEAS_DELAY_MS   45        /* first conversion time */
#define READ_LEN        9         /* 3 words × (2 data + 1 CRC) */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF) – as per SDP8x datasheet */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int fd, float *pressure, float *temperature)
{
    uint8_t raw[READ_LEN];

    if (i2c_write_cmd(fd, 0x3605) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, raw, READ_LEN) < 0)
        return -1;

    /* CRC checks: words 0–2 (pressure), 3–5 (temperature) */
    if (sensirion_crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (sensirion_crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }

    int16_t dp_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t t_raw  = (int16_t)((raw[3] << 8) | raw[4]);

    *pressure    = (float)dp_raw;
    *temperature = (float)t_raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    sensor_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, 0x40);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,differential_pressure_pa,temperature_c\n");

    printf("SDP810 airflow logger started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(g_i2c_fd, &pressure, &temperature) == 0) {
            log_data(g_log_fp, pressure, temperature);
            printf("Pressure: %.2f Pa  |  Temperature: %.2f C\n",
                   pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD)
                fprintf(stderr, "WARNING: pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
        } else {
            fprintf(stderr, "Sensor read failed – continuing.\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

