#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x1D
#define LED_GPIO       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *temp_out)
{
    int16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) != 0)
        return -1;
    *temp_out = (float)raw / 100.0f;
    return 0;
}

static void control_led(int gpio, int state)
{
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", gpio, state);
    }
}

int main(void)
{
    int fd = -1;
    int led_state = 0;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        goto cleanup_gpio;
    }
    gpioWrite(LED_GPIO, 0);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup_gpio;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup_fd;
    }

    while (g_running) {
        float temp;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_temperature(fd, &temp) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Temperature read failed after %d attempts\n", MAX_RETRIES);
            break;
        }

        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);

        if (temp > TEMP_HIGH && led_state == 0) {
            control_led(LED_GPIO, 1);
            led_state = 1;
        } else if (temp < TEMP_LOW && led_state == 1) {
            control_led(LED_GPIO, 0);
            led_state = 0;
        }

        usleep(POLL_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup_fd:
    if (fd >= 0)
        close(fd);
cleanup_gpio:
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return rc;
}

