code:
/*
 * Raspberry Pi 4 Model B - Sensirion SDP800-500Pa Differential Pressure & Temperature Logger
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SDP800 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SDP800 VDD  -> 3.3 V (pin 1)
 *   SDP800 GND  -> GND  (pin 6)
 *
 * Build: gcc -O2 -Wall -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:   sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define MEASUREMENT_MS  45
#define LOG_FILE       "flow_data.txt"
#define SAMPLE_PERIOD_S 1

/* SDP800-500Pa: differential pressure range ±500 Pa, temperature range -40 °C to +125 °C */
#define SDP800_Differential_PRESSURE_SCALE 500.0f
#define SDP800_TEMPERATURE_SCALE           165.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion (polynomial 0x31, init 0xFF)              */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one measurement from the SDP800-500Pa.                        */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.           */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *differential_pressure,
                       float *temperature)
{
    uint8_t buf[9];

    /* Trigger a measurement by writing 0x3600 (0x00 0x00 0x36 0x00) */
    if (i2cWriteByteData(handle, 0x00, 0x00) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData (trigger) failed\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x01, 0x00) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData (command) failed\n");
        return -1;
    }

    /* Wait for the measurement to complete */
    gpioDelay(MEASUREMENT_MS * 1000);

    /* Read 9 bytes: DP(2) + CRC, T(2) + CRC, scale(3) + CRC */
    int bytes_read = i2cReadDevice(handle, (char *)buf, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9)\n",
                bytes_read);
        return -1;
    }

    /* Validate CRC for differential pressure */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on differential pressure\n");
        return -2;
    }

    /* Validate CRC for temperature */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature\n");
        return -2;
    }

    /* Validate CRC for scale factor */
    if (crc8(&buf[6], 3) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on scale factor\n");
        return -2;
    }

    /* Convert raw values to physical units */
    int16_t dp_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t temp_raw = (int16_t)((buf[3] << 8) | buf[4]);

    *differential_pressure = (float)dp_raw / SDP800_Differential_PRESSURE_SCALE;
    *temperature = (float)temp_raw / SDP800_TEMPERATURE_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a measurement to the CSV file.                                 */
/* ------------------------------------------------------------------ */
static void log_data(float differential_pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                differential_pressure, temperature);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n",
                differential_pressure, temperature);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("SDP800-500Pa logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
