static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_reset(int handle) {
    if (i2cWriteByteData(handle, HDC1080_RESET, HDC1080_RESET_CMD) < 0) {
        fprintf(stderr, "Error: failed to send reset command\n");
        return -1;
    }
    gpioDelay(HDC1080_RESET_DELAY_MS * 1000);
    return 0;
}

static int hdc1080_init(int handle) {
    if (hdc1080_reset(handle) < 0) return -1;
    if (i2cWriteByteData(handle, HDC1080_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure HDC1080\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read_raw(int handle, uint8_t reg, uint16_t *value) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
