    if (hdc1080_trigger(handle) < 0) return -1;
    gpioDelay(CONVERSION_DELAY_MS * 1000);
    uint16_t raw_t, raw_h;
    if (hdc1080_read_raw(handle, HDC1080_TEMP_LOW, &raw_t) < 0) return -1;
    if (hdc1080_read_raw(handle, HDC1080_HUMID_LOW, &raw_h) < 0) return -1;
    *temp = (float)raw_t / 65536.0f * 165.0f - 40.0f;
    *hum = (float)raw_h / 65536.0f * 100.0f;
    return 0;
}

