    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("HDC1080 logging started. Press Ctrl+C to stop.\n");
    while (running) {
        float temp, hum;
        if (hdc1080_read(i2c_handle, &temp, &hum) == 0) {
            log_data(temp, hum);
            printf("Logged: %.2f C, %.2f %%\n", temp, hum);
