#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x40
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_INTERVAL 5
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC8: polynomial 0x31, init 0xFF, no reflection */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_temperature(int fd, float *temperature)
{
    uint8_t cmd = 0x2E;                       /* Read temperature */
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x2E): %s\n", strerror(errno));
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != 3) {
        fprintf(stderr, "Error: I2C read failed (expected 3 bytes): got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int log_temperature(FILE *fp, float temperature)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STS40_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Temperature logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(fd, &temperature) == 0) {
            if (log_temperature(fp, temperature) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample\n");
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping sample\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose() failed: %s\n", strerror(errno));
    }
    if (close(fd) != 0) {
        fprintf(stderr, "Warning: close() failed: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

