 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_driver scd40_driver.c \
 *       -lpigpio -lpthread -lrt
 *
 * Run:
 *   sudo ./scd40_driver
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x38
#define LOG_DIR        "/var/log/scd40_data"
#define ERROR_LOG      "/var/log/scd40_error.log"
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  5          /* seconds between sensor reads */
#define LOG_PERIOD     60         /* seconds between CSV writes */
#define START_DELAY    1          /* seconds after start-periodic command */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT  0x3604
#define CMD_STOP_PERIODIC_MEASUREMENT   0x3605
#define CMD_READ_MEASUREMENT            0x3606

/* CRC-8 parameters for SCD40 (polynomial 0x31, init 0xFF) */
#define CRC8_POLYNOMIAL  0x31
#define CRC8_INIT       0xFF

typedef struct {
    time_t timestamp;
    float  co2;
    float  temperature;
    float  humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static circular_buffer_t g_buffer;
static pthread_t g_logging_thread;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->tail  = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE)
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;   /* overwrite */
    else
        buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static sensor_data_t buffer_get(circular_buffer_t *buf, int index)
{
    sensor_data_t v;
    pthread_mutex_lock(&buf->mutex);
    int actual = (buf->head - buf->tail + buf->count) % BUFFER_SIZE;
    if (index < 0 || index >= actual) {
        pthread_mutex_unlock(&buf->mutex);
        return v;
    }
    int idx = (buf->head - buf->tail + index) % BUFFER_SIZE;
    v = buf->data[idx];
    pthread_mutex_unlock(&buf->mutex);
    return v;
}

/* ------------------------------------------------------------------ */
/* Logging thread                                                      */
/* ------------------------------------------------------------------ */
static void *logging_thread_fn(void *arg)
{
    (void)arg;
    while (g_running) {
        for (int i = 0; i < LOG_PERIOD && g_running; i++) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "time() failed in logging thread\n");
                break;
            }
            pthread_mutex_lock(&g_buffer.mutex);
            int count = g_buffer.count;
            pthread_mutex_unlock(&g_buffer.mutex);

            if (count == 0)
                break;

            char filename[256];
            snprintf(filename, sizeof(filename), "%s/scd40_data_%04d.csv",
                     LOG_DIR, (int)now);

            FILE *fp = fopen(filename, "a");
            if (!fp) {
                fprintf(stderr, "fopen(%s) failed: %m\n", filename);
                pthread_mutex_lock(&g_buffer.mutex);
                g_buffer.data[g_buffer.tail].timestamp = now;
                g_buffer.data[g_buffer.tail].co2      = 0.0f;
                g_buffer.data[g_buffer.tail].temperature = 0.0f;
                g_buffer.data[g_buffer.tail].humidity    = 0.0f;
                g_buffer.tail = (g_buffer.tail + 1) % BUFFER_SIZE;
                g_buffer.count--;
                pthread_mutex_unlock(&g_buffer.mutex);
                continue;
            }

            fprintf(fp, "Timestamp,CO2_ppm,Temperature_C,Humidity %%\n");

            pthread_mutex_lock(&g_buffer.mutex);
            int written = 0;
            for (int j = 0; j < count && g_running; j++) {
                int idx = (g_buffer.tail + j) % BUFFER_SIZE;
                if (fprintf(fp, "%ld,%.2f,%.2f,%.2f\n",
                            (long)g_buffer.data[idx].timestamp,
                            g_buffer.data[idx].co2,
                            g_buffer.data[idx].temperature,
                            g_buffer.data[idx].humidity) < 0) {
                    fprintf(stderr, "fprintf to CSV failed\n");
                    break;
                }
                written++;
            }
            pthread_mutex_unlock(&g_buffer.mutex);

            if (written > 0)
                fclose(fp);
        }
    }
    return NULL;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "i2cReadDevice: expected %d bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, sensor_data_t *data)
{
    uint8_t buf[9];

    /* Read 9 bytes: CO2(2)+CRC(1)+T(2)+CRC(1)+H(2)+CRC(1) */
    if (i2c_read_data(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error: CO2\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error: Temperature\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error: Humidity\n");
        return -1;
    }

    uint16_t co2_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    int16_t  temp_raw = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t  hum_raw  = (int16_t)((buf[6] << 8) | buf[7]);

    data->co2 = (float)co2_raw;
    data->temperature = (float)temp_raw / 100.0f;
    data->humidity = (float)hum_raw / 100.0f;
    data->timestamp = time(NULL);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_cmd(g_i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    pthread_join(g_logging_thread, NULL);
    pthread_mutex_destroy(&g_buffer.mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SCD40 start periodic measurement --- */
    if (i2c_write_cmd(g_i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Wait for first sample --- */
    sleep(START_DELAY);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Buffer & logging thread --- */
    buffer_init(&g_buffer);
    if (pthread_create(&g_logging_thread, NULL, logging_thread_fn, NULL) != 0) {
        fprintf(stderr, "pthread_create failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        sleep(SAMPLE_PERIOD);
    }

    /* --- Final flush & cleanup --- */
    pthread_join(g_logging_thread, NULL);
    cleanup();
    return EXIT_SUCCESS;
}

