#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x38
#define TRIGGER_CMD 0x0000
#define READ_CMD 0x0001
#define READ_LEN 6
#define SAMPLE_INTERVAL_US 5000000
#define TRIGGER_DELAY_US 10000

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_cmd(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    if (i2c_write_cmd(READ_CMD) != 0) return -1;
    gpioDelay(1000);

    uint8_t data[READ_LEN];
    if (i2c_read_data(data, READ_LEN) != 0) return -1;

    uint32_t raw_pressure = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t raw_temperature = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open environmental_data.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        if (i2c_write_cmd(TRIGGER_CMD) != 0) {
            fprintf(stderr, "Error: Trigger command failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        gpioDelay(TRIGGER_DELAY_US);

        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) != 0) {
            fprintf(stderr, "Error: Sensor read failed, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(pressure, temperature);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

