    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open environmental_data.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        if (i2c_write_cmd(TRIGGER_CMD) != 0) {
            fprintf(stderr, "Error: Trigger command failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        gpioDelay(TRIGGER_DELAY_US);

        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) != 0) {
            fprintf(stderr, "Error: Sensor read failed, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(pressure, temperature);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

