#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x29
#define LED_PIN        17
#define POLL_INTERVAL  1
#define TRIGGER_DELAY  20
#define PRESSURE_THRESHOLD 95000
#define PRESSURE_MAX     95000
#define PRESSURE_MIN     95000
#define PRESSURE_ERROR   100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_sensor(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature) {
    uint8_t data[6];
    if (i2c_read_sensor(fd, data, 6) < 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure = (int32_t)((data[0] << 8) | data[1]);
    *temperature = (int32_t)((data[3] << 8) | data[4]);
    return 0;
}

static void control_led(int pin, int pressure) {
    static int led_state = 0;
    static struct timespec last_time = {0, 0};
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (pressure < PRESSURE_THRESHOLD) {
        led_state = 1;
        gpioWrite(pin, 1);
    } else {
        led_state = 0;
        gpioWrite(pin, 0);
    }

    long elapsed_ms = (now.tv_sec - last_time.tv_sec) * 1000L +
                      (now.tv_nsec - last_time.tv_nsec) / 1000000L;

    if (led_state == 1) {
        if (elapsed_ms >= 500) {
            led_state = 0;
            gpioWrite(pin, 0);
        }
    } else {
        if (elapsed_ms >= 500) {
            led_state = 1;
            gpioWrite(pin, 1);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    while (running) {
        int32_t pressure = 0, temperature = 0;
        if (read_sensor_data(i2c_fd, &pressure, &temperature) == 0) {
            if (pressure < PRESSURE_ERROR) {
                fprintf(stderr, "Sensor read error: pressure=%d Pa\n", pressure);
            } else {
                control_led(LED_PIN, pressure);
                printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        struct timespec delay = {0, TRIGGER_DELAY * 1000000L};
        nanosleep(&delay, NULL);

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            struct timespec sleep_time = {0, 100000000L};
            nanosleep(&sleep_time, NULL);
        }
    }

    gpioWrite(LED_PIN, 0);
    if (i2c_fd >= 0)
        close(i2c_fd);
    gpioTerminate();
    return 0;
}

