#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x95
#define MLX90614_TEMP_OUT_L 0x2D
#define MLX90614_TEMP_OUT_H 0x2E
#define MLX90614_STATUS 0x00
#define MLX90614_STATUS_MASK 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mlx90614_temp(int handle, float *temp_out) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(handle, MLX90614_TEMP_OUT_L, buf, 2) == 2) {
            int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
            int status = i2cReadByteData(handle, MLX90614_STATUS);
            if (status >= 0 && (status & MLX90614_STATUS_MASK) == 0) {
                *temp_out = (float)raw * 0.02 - 273.15;
                return 0;
            }
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    }
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object Temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object Temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, MLX90614_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient = 0.0, object = 0.0;
        int ok = 0;

        if (read_mlx90614_temp(i2c_handle, &ambient) == 0) {
            ok = 1;
        }

        if (ok && read_mlx90614_temp(i2c_handle, &object) == 0) {
            log_temperature(ambient, object);
            control_fan(object);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(2000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

