/*
 * Raspberry Pi 4 Model B — SHT40 temperature/humidity HTTP server
 *
 * Reads the Sensirion SHT40 sensor on I2C bus 1, issues a measurement
 * command, and streams the live temperature/humidity data to a local
 * HTTP server on port 8080.  The server serves an HTML page that displays
 * the current temperature and humidity while clamping humidity to the
 * range 0–100 %.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_server sht40_server.c -lpigpio -lrt
 * Run:    sudo ./sht40_server
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28          /* SHT40 default I2C address (SDO tied to GND) */
#define PORT           8080
#define MEAS_DELAY_US  15000         /* 15 ms — well above the 10 ms max for SHT40 */
#define MAX_RETRIES    3
#define READ_LEN       6             /* SHT40 measurement: T(2) + RH(2) + CRC(2) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SHT40 read with retry                                               */
/* ------------------------------------------------------------------ */
static int sht40_read(int handle, float *temperature, float *humidity)
{
    unsigned char data[READ_LEN];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        /* Issue a single-shot measurement command (0x2C, 0x06) */
        rc = i2cWriteByteData(handle, 0x2C, 0x06);
        if (rc < 0) {
            fprintf(stderr, "[SHT40] write command failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(10000);  /* 10 ms back-off */
            continue;
        }

        gpioDelay(MEAS_DELAY_US);  /* 15 ms conversion time */

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
        rc = i2cReadDevice(handle, (char *)data, READ_LEN);
        if (rc != READ_LEN) {
