static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Read the 16-bit raw temperature from the TMP102.
 * The TMP102 is a 16-bit ADC; the MSB is read first, then the LSB.
 * Returns 0 on success and stores the temperature in *out_temp.
 */
static int read_temperature(int i2c_handle, float *out_temp)
{
    char buf[2];
    int  rc;

    /* Point to the temperature register (0x00). */
    rc = i2cWriteByte(i2c_handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByte (reg select) failed: %s\n", pigpio_error(rc));
        return -1;
    }

    /* Read two bytes: MSB first, then LSB. */
    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "i2cReadDevice failed: expected 2 bytes, got %d (%s)\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *out_temp = (float)raw / 16.0f;
    return 0;
}

static int log_temperature(float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int i2c_handle = -1;
    int rc;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, TMP102_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP102 temperature logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        rc = i2cClose(i2c_handle);
        if (rc < 0) {
            fprintf(stderr, "i2cClose() failed: %s\n", pigpio_error(rc));
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

