#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SDP800_I2C_ADDR 0x25
#define I2C_BUS 1
#define MEASUREMENT_DELAY_US 45000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800(int handle, int32_t *pressure, int32_t *temperature) {
    uint8_t cmd[1] = {0x36};
    int rc = i2cWriteDevice(handle, (char *)cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    uint8_t buf[6];
    rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "Error: short read (%d bytes)\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure = (int32_t)((buf[0] << 8) | buf[1]);
    *temperature = (int32_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int32_t pressure, temperature;
    while (running) {
        if (read_sdp800(handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

