#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SSR_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL_US 1000000
#define LOOP_PERIOD_S 1.0

#define MAX_TEMP 100.0
#define MIN_TEMP -40.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static FILE *profile_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int load_profile(float *profile, int *num_points) {
    profile_file = fopen(PROFILE_FILE, "r");
    if (!profile_file) {
        perror("fopen profile");
        return -1;
    }
    int count = 0;
    if (fscanf(profile_file, "%d", &count) != 1) {
        fprintf(stderr, "Invalid profile format\n");
        fclose(profile_file);
        profile_file = NULL;
        return -1;
    }
    if (count <= 0) {
        fprintf(stderr, "Invalid profile count\n");
        fclose(profile_file);
        profile_file = NULL;
        return -1;
    }
    *num_points = count;
    if (fscanf(profile_file, "%*d") != 1) {
        fprintf(stderr, "Invalid profile format\n");
        fclose(profile_file);
        profile_file = NULL;
        return -1;
    }
    float t;
    for (int i = 0; i < *num_points; i++) {
        if (fscanf(profile_file, "%f", &t) != 1) {
            fprintf(stderr, "Invalid profile format\n");
            fclose(profile_file);
            profile_file = NULL;
            return -1;
        }
        profile[i] = t;
    }
    fclose(profile_file);
    profile_file = NULL;
    return 0;
}

static int read_max6675(float *temperature) {
    char tx[4] = {0x00, 0x00, 0x00, 0x00};
    char rx[4] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)rx[0] << 24) |
                       ((unsigned int)(unsigned char)rx[1] << 16) |
                       ((unsigned int)(unsigned char)rx[2] << 8)  |
                       (unsigned int)(unsigned char)rx[3];
    raw >>= 4;
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX6675 fault bit set\n");
        return -1;
    }
    *temperature = (float)raw * 0.25f;
    return 0;
}

static void set_ssr(float duty) {
    if (gpioWrite(SSR_PIN, duty > 0.0f ? 1 : 0) != 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", SSR_PIN);
    }
}

static void log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", ts, temperature);
    fflush(log_file);
}

static float pid_control(float current_temp, float target_temp, float *integral, float *prev_error) {
    float error = target_temp - current_temp;
    *integral += error;
    float derivative = error - *prev_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SSR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SSR_PIN, 0);

    if (load_profile(NULL, NULL) != 0) {
        fprintf(stderr, "Failed to load profile\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "# timestamp,temperature_c\n");
    fflush(log_file);

    float target_temp = 80.0f;
    float integral = 0.0f;
    float prev_error = 0.0f;
    float current_temp = 0.0f;
    float duty = 0.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_max6675(&current_temp) != 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            set_ssr(duty);
            time_sleep(LOOP_PERIOD_S);
            continue;
        }
        if (current_temp < MIN_TEMP) current_temp = MIN_TEMP;
        if (current_temp > MAX_TEMP) current_temp = MAX_TEMP;

        duty = pid_control(current_temp, target_temp, &integral, &prev_error);
        set_ssr(duty);
        log_data(current_temp);
        time_sleep(LOOP_PERIOD_S);
    }

    set_ssr(0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

