    float target_temp = 80.0f;
    float integral = 0.0f;
    float prev_error = 0.0f;
    float current_temp = 0.0f;
    float duty = 0.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_max6675(&current_temp) != 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            set_ssr(duty);
            time_sleep(LOOP_PERIOD_S);
            continue;
        }
        if (current_temp < MIN_TEMP) current_temp = MIN_TEMP;
        if (current_temp > MAX_TEMP) current_temp = MAX_TEMP;

        duty = pid_control(current_temp, target_temp, &integral, &prev_error);
        set_ssr(duty);
        log_data(current_temp);
        time_sleep(LOOP_PERIOD_S);
    }

    set_ssr(0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

