        return -1;
    }
    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

static int read_temperature(float *temperature) {
    char line1[256], line2[256];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_file(SENSOR_DEVICE_PATH, line1, sizeof(line1)) == 0 &&
            read_file(SENSOR_DEVICE_PATH, line2, sizeof(line2)) == 0) {
            if (strstr(line1, "YES") != NULL) {
                char *temp_str = strstr(line2, "t=");
                if (temp_str != NULL) {
                    long raw_temp = strtol(temp_str + 2, NULL, 10);
                    *temperature = (float)raw_temp / 1000.0f;
                    return 0;
                }
            }
            fprintf(stderr, "Error: Invalid temperature data format\n");
            retries++;
            sleep(1);
        } else {
            retries++;
            sleep(1);
        }
    }
    fprintf(stderr, "Error: Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1;
}

static float calculate_pid(float setpoint, float actual, float *integral, float *previous_error, float Kp, float Ki, float Kd, float dt) {
    float error = setpoint - actual;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
