        fclose(log_file);
        return 1;
    }

    float integral = 0.0f, previous_error = 0.0f;
    float temperature, pid_output;
    int pwm_duty_cycle = 0;

    while (running) {
        if (read_temperature(&temperature) == 0) {
            pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error, Kp, Ki, Kd, 1.0f);
            pwm_duty_cycle = (int)(pid_output * 100.0f);
            if (set_pwm(pwm_duty_cycle) != 0) {
                fprintf(stderr, "Error setting PWM duty cycle\n");
            }
            if (set_relay(1) != 0) {
                fprintf(stderr, "Error setting relay state\n");
            }
            log_data(temperature, setpoint, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping control loop\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    set_relay(0);
    set_pwm(0);
    if (log_file) fclose(log_file);
    return 0;
}

