/*
 * AHT20 humidity monitor with dehumidifier control on Raspberry Pi 5.
 *
 * Wiring:
 *   AHT20 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   AHT20 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   AHT20 VDD  -> 3.3 V
 *   AHT20 GND  -> GND
 *   Relay IN   -> GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_dehum aht20_dehum.c -lpigpio -lrt
 * Run:    sudo ./aht20_dehum
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38          /* AHT20 default I2C address (SDO low) */
#define GPIO_RELAY     17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5             /* seconds between readings */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  80000        /* 80 ms measurement wait */
#define RETRY_DELAY_US 10000        /* 10 ms between retries */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read 6 bytes from the AHT20.
 * Returns 0 on success and fills *humidity; returns -1 on error.
 */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t buf[6];

    /* Trigger a measurement: write 0x00 to the sensor */
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "AHT20 write trigger: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the measurement to complete */
    usleep(MEAS_DELAY_US);

    /* Read 6 bytes: [status, hum_msb, hum_lsb, hum_x2, hum_x3, crc] */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "AHT20 read: expected 6 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Verify status byte: bit 0 = calibrated, bit 1 = busy */
    if (buf[0] & 0x02) {
        fprintf(stderr, "AHT20 status error (calibrated=0x%02X busy=0x%02X)\n",
                buf[0] & 0x01, buf[0] & 0x02);
        return -1;
    }

    /* Humidity is 16-bit, LSB = 0.1 %RH */
    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[2];
    *humidity = (float)raw / 100.0f;

    /* Sanity range check */
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "AHT20 humidity out of range: %.2f%%\n", *humidity);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", GPIO_RELAY);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void gpio_control(float humidity)
{
    int level = (humidity > HUMIDITY_HIGH) ? 1 : 0;
    if (gpioWrite(GPIO_RELAY, level) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", GPIO_RELAY, level);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AHT20 humidity monitor started.  Polling every %d s.\n",
           POLL_INTERVAL);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        float humidity = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying (%d/%d)...\n",
                        attempt + 1, MAX_RETRIES);
                usleep(RETRY_DELAY_US);
            }
        }

        if (ok) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            } else {
                snprintf(ts, sizeof(ts), "unknown-time");
            }

            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            gpio_control(humidity);
        } else {
            fprintf(stderr, "Failed to read humidity after %d attempts.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

