#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x36
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t status;
    uint16_t temp_raw;
    uint16_t hum_raw;

    if (i2c_read_reg8(fd, 0xF7, &status) < 0) {
        syslog(LOG_ERR, "Failed to read status register");
        return -1;
    }
    if ((status & 0x20) == 0) {
        syslog(LOG_ERR, "Sensor not ready");
        return -1;
    }

    if (i2c_read_reg16(fd, 0xFA, &temp_raw) < 0) {
        syslog(LOG_ERR, "Failed to read temperature");
        return -1;
    }

    if (i2c_read_reg16(fd, 0x04, &hum_raw) < 0) {
        syslog(LOG_ERR, "Failed to read humidity");
        return -1;
    }

    uint8_t crc_hum = 0xFF;
    for (int i = 0; i < 16; i++) {
        crc_hum ^= hum_raw >> (7 - i);
        for (int j = 0; j < 8; j++) {
            if (crc_hum & 0x80) crc_hum = (crc_hum << 1) ^ 0x31;
            else crc_hum <<= 1;
        }
    }
    if (crc_hum != hum_raw) {
        syslog(LOG_ERR, "Humidity CRC mismatch");
        return -1;
    }

    *humidity = (float)((hum_raw & 0x7FFF) / 0x40000.0f) * 100.0f;
    return 0;
}

static int post_data(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, API_ENDPOINT, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", API_ENDPOINT);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection to %s failed: %s", API_ENDPOINT, strerror(errno));
        close(sockfd);
        return -1;
    }

    char json_string[256];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char time_buf[80];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
    snprintf(json_string, sizeof(json_string), "{\"timestamp\":\"%s\",\"humidity\":%.2f}", time_buf, humidity);

    char request[512];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s", strlen(json_string), json_string);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    int status = 0;
    while (status < 0 && running) {
        status = recv(sockfd, NULL, 0, 0);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
            close(sockfd);
            return -1;
        }
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started");

    while (running) {
        float humidity = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_humidity(fd, &humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                syslog(LOG_WARNING, "Retrying humidity read (%d/%d)", retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (success) {
            if (post_data(humidity) == 0) {
                syslog(LOG_INFO, "Data posted successfully");
            } else {
                syslog(LOG_ERR, "Failed to post data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "HTU21D monitor stopping");
    close(fd);
    closelog();
    return 0;
}

