#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6
#define BMP280_OVERSAMPLING_1 0x01
#define BMP280_T_SB_1 0x02
#define BMP280_POWER_DOWN 0x20
#define BMP280_RESET_CMD_VAL 0xB6
#define BMP280_CHIP_ID_VAL 0x58
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int bmp280_read_calibration(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2c_read_block(handle, reg, buf, len) != (int)len) {
        fprintf(stderr, "Failed to read calibration data from reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int bmp280_init(int handle) {
    uint8_t chip_id = 0;
    if (i2c_read_block(handle, BMP280_REG_ID, &chip_id, 1) != 1) {
        fprintf(stderr, "Failed to read chip ID\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID_VAL) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID_VAL);
        return -1;
    }

    if (i2c_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD_VAL) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(2000);

    uint8_t calib[24];
    if (bmp280_read_calibration(handle, BMP280_REG_CALIB_00, calib, 24) != 0) {
        return -1;
    }

    uint8_t config = (BMP280_T_SB_1 << 5) | (BMP280_OVERSAMPLING_1 << 2) | 0x03;
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_1 << 5) | (BMP280_T_SB_1 << 2) | 0x03;
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register\n");
        return -1;
    }

    return 0;
}

static int bmp280_read_pressure(int handle, float *pressure_hpa) {
    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        return -1;
    }

    int32_t raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    int32_t raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    uint32_t t_fine = (uint32_t)raw_temp - (uint32_t)0x40000000;
    uint32_t var1 = (t_fine * 2) / 4 - 64000;
    uint32_t var2 = ((var1 / 2) * (var1 / 2)) / 2;
    uint32_t var3 = (t_fine * var2) / 4;
    uint32_t var4 = 1048576 - raw_pressure;
    uint32_t p = (var3 * 2) / 4 + var4;
    var3 = (p / 4) * (p / 4) * (p / 4) / 3;
    var4 = (p * 2 + 3) / 4;
    p = (p + var3 + var4) / 4;

    *pressure_hpa = (float)p / 100.0f;
    return 0;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

static int open_i2c(void) {
    int handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        return -1;
    }
    return handle;
}

static int bmp280_reinit(int handle) {
    if (handle < 0) return -1;
    i2cClose(handle);
    handle = open_i2c();
    if (handle < 0) return -1;
    if (bmp280_init(handle) != 0) {
        fprintf(stderr, "BMP280 reinit failed\n");
        return -1;
    }
    return handle;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = open_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    if (bmp280_init(i2c_handle) != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (bmp280_read_pressure(i2c_handle, &pressure) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                i2c_handle = bmp280_reinit(i2c_handle);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Reinit failed, exiting\n");
                    running = 0;
                    break;
                }
                gpioDelay(100000);
            }
        }

        if (success) {
            if (pressure > 1020.0f || pressure < 980.0f) {
                log_pressure(pressure);
                printf("Pressure %.2f hPa out of range\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US - CONVERSION_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

