/*
 * Raspberry Pi 4B Environmental Logger
 *
 * Reads temperature from TMP117 (I2C addr 0x1D), humidity from AHT20
 * (I2C addr 0xE0), and motion from a PIR sensor on GPIO17.
 * Logs daily timestamped CSV rows to /tmp/Environmental_YYYYMMDD.csv.
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 * Run:   sudo ./logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR        0x1D
#define AHT20_ADDR         0xE0
#define PIR_GPIO_CHIP      "gpiochip4"
#define PIR_GPIO_LINE      17
#define I2C_BUS            "/dev/i2c-1"
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     10
#define SAMPLE_INTERVAL_S  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d", &tm);
}

static int i2c_write_byte(int fd, unsigned char addr, unsigned char val) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, &val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char addr, unsigned char *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_temperature(int fd) {
    unsigned char cmd = 0x2C;
    if (i2c_write_byte(fd, TMP117_ADDR, cmd) < 0) return -1;
    usleep(10000);
    unsigned char buf[2];
    if (i2c_read_bytes(fd, TMP117_ADDR, buf, 2) < 0) return -1;
    int raw = (buf[0] << 8) | buf[1];
    if (raw & 0x8000) raw |= 0xFFFFC000;
    return (int)((raw >> 12) / 4.0);
}

static int read_humidity(int fd) {
    unsigned char cmd = 0x2C;
    if (i2c_write_byte(fd, AHT20_ADDR, cmd) < 0) return -1;
    usleep(10000);
    unsigned char buf[7];
    if (i2c_read_bytes(fd, AHT20_ADDR, buf, 7) < 0) return -1;
    if (buf[0] != 0xB6) return -1;
    int raw = ((buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4)) & 0x1FFF;
    if (raw == 0) return -1;
    raw >>= 8;
    return (int)(raw / 1024.0);
}

static int read_motion(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) return -1;
    return (val == 1) ? 1 : 0;
}

static int log_data(const char *filename, float temp, float hum, int motion) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

static int create_log_file(const char *filename) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char date[16];
    strftime(date, sizeof(date), "%Y%m%d", &tm);
    char path[64];
    snprintf(path, sizeof(path), "/tmp/Environmental_%s.csv", date);
    if (access(path, F_OK) == 0) return 0;
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error creating %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int tmp_fd = open(I2C_BUS, O_RDWR);
    if (tmp_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    int aht_fd = open(I2C_BUS, O_RDWR);
    if (aht_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        close(tmp_fd);
        return 1;
    }

    if (ioctl(aht_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Warning: AHT20 not detected at 0xE0\n");
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", PIR_GPIO_CHIP, strerror(errno));
        close(tmp_fd);
        close(aht_fd);
        return 1;
    }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(tmp_fd);
        close(aht_fd);
        return 1;
    }
    if (gpiod_line_request_input(pir, "logger") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(tmp_fd);
        close(aht_fd);
        return 1;
    }

    while (g_running) {
        char filename[64];
        get_timestamp(filename, sizeof(filename));
        snprintf(filename, sizeof(filename), "/tmp/Environmental_%s.csv", filename);

        if (create_log_file(filename) < 0) {
            sleep(1);
            continue;
        }

        int tmp_ok = 0, aht_ok = 0;
        int tmp_retries = 0, aht_retries = 0;
        while (tmp_retries < MAX_RETRIES && g_running) {
            int t = read_temperature(tmp_fd);
            if (t >= 0) { tmp_ok = 1; break; }
            fprintf(stderr, "TMP117 read failed (attempt %d/%d)\n", tmp_retries + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
            tmp_retries++;
        }
        while (aht_retries < MAX_RETRIES && g_running) {
            int h = read_humidity(aht_fd);
            if (h >= 0) { aht_ok = 1; break; }
            fprintf(stderr, "AHT20 read failed (attempt %d/%d)\n", aht_retries + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
            aht_retries++;
        }

        int motion = read_motion(pir);
        if (motion < 0) motion = 0;

        if (tmp_ok && aht_ok) {
            if (log_data(filename, (float)t / 100.0, (float)h, motion) < 0) {
                fprintf(stderr, "Logging failed for %s\n", filename);
            }
        } else {
            fprintf(stderr, "Sensor read failure; skipping log entry for %s\n", filename);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    close(tmp_fd);
    close(aht_fd);
    return 0;
}

