static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_gpio_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Error: gpioWrite(%u, %u) failed", gpio, level);
        log_message(buf);
        return -1;
    }
    return 0;
}

