{
    if (safe_gpio_write(MOTOR_ENA_GPIO, 1) < 0)
        return -1;
    if (safe_gpio_write(MOTOR_IN1_GPIO, 1) < 0)
        return -1;
    if (safe_gpio_write(MOTOR_IN2_GPIO, 0) < 0)
        return -1;
    return 0;
}

static int motor_stop(void)
{
    if (safe_gpio_write(MOTOR_ENA_GPIO, 0) < 0)
        return -1;
    if (safe_gpio_write(MOTOR_IN1_GPIO, 0) < 0)
        return -1;
    if (safe_gpio_write(MOTOR_IN2_GPIO, 0) < 0)
        return -1;
    return 0;
}

