#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_26 0xE1
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_HUM 0xF2
#define BMP280_REG_HUM_MSB 0xFD

#define I2C_BUS 1
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int udp_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bmp280_read_calibration(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int bmp280_init(int handle) {
    uint8_t id;
    if (i2cReadByteData(handle, BMP280_REG_ID) < 0) {
        fprintf(stderr, "Error: Failed to read BMP280 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Error: BMP280 ID mismatch (0x%02X). Expected 0x58.\n", id);
        return -1;
    }

    uint8_t calib[26];
    if (bmp280_read_calibration(handle, BMP280_REG_CALIB_00, calib, 24) < 0) return -1;
    if (bmp280_read_calibration(handle, BMP280_REG_CALIB_26, calib + 24, 2) < 0) return -1;

    uint16_t dig_T1 = (calib[1] << 8) | calib[0];
    uint16_t dig_T2 = (calib[3] << 8) | calib[2];
    uint16_t dig_T3 = (calib[5] << 8) | calib[4];
    uint16_t dig_P1 = (calib[7] << 8) | calib[6];
    uint16_t dig_P2 = (calib[9] << 8) | calib[8];
    uint16_t dig_P3 = (calib[11] << 8) | calib[10];
    uint16_t dig_P4 = (calib[13] << 8) | calib[12];
    uint16_t dig_P5 = (calib[15] << 8) | calib[14];
    uint16_t dig_P6 = (calib[17] << 8) | calib[16];
    uint16_t dig_P7 = (calib[19] << 8) | calib[18];
    uint16_t dig_P8 = (calib[21] << 8) | calib[20];
    uint16_t dig_P9 = (calib[23] << 8) | calib[22];

    uint8_t config = (0x04 << 2) | (0x02 << 1) | 0x01;
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, config) < 0) return -1;

    uint8_t ctrl_meas = (0x01 << 5) | (0x01 << 2) | 0x03;
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, ctrl_meas) < 0) return -1;

    return 0;
}

static int bmp280_read(int handle, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;

    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read BMP280 data block: %s\n", strerror(errno));
        return -1;
    }

    raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    int32_t var1, var2;
    int32_t t_fine;

    var1 = ((((raw_temperature >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temperature >> 4) - ((int32_t)dig_T1)) * ((raw_temperature >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temperature = (float)((t_fine * 5 + 128) >> 8) / 100.0f;

    int64_t v1 = ((int64_t)t_fine) - 128000;
    int64_t v2 = v1 * v1 * (int64_t)dig_P6;
    v2 = v2 + ((v1 * (int64_t)dig_P5) << 17);
    v2 = v2 + (((int64_t)dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)dig_P3) >> 8) + ((v1 * (int64_t)dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)dig_P1) >> 33;
    if (v1 == 0) return -1;
    int64_t p = 1048576 - raw_pressure;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    v2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + v1 + v2) >> 8) + (((int64_t)dig_P7) << 4);
    *pressure = (float)p / 256.0f;

    return 0;
}

static int send_udp(const char *json_string) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid UDP address: %s\n", UDP_IP);
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error: Failed to send UDP data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    float temperature, pressure;
    char json_string[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n", I2C_BUS, BMP280_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (bmp280_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error: Failed to create UDP socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (bmp280_read(i2c_handle, &temperature, &pressure) == 0) {
            snprintf(json_string, sizeof(json_string), "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);
            if (send_udp(json_string) < 0) {
                fprintf(stderr, "Warning: UDP send failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Warning: BMP280 read failed, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

