    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %s\n", I2C_BUS, BMP280_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (bmp280_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error: Failed to create UDP socket: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (bmp280_read(i2c_handle, &temperature, &pressure) == 0) {
            snprintf(json_string, sizeof(json_string), "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);
            if (send_udp(json_string) < 0) {
                fprintf(stderr, "Warning: UDP send failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Warning: BMP280 read failed, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

