#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define SPI_FLAGS   0
#define FAN_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

#define TEMP_MIN 25.0
#define TEMP_MAX 60.0

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty_cycle;
} TemperatureData;

static TemperatureData temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_spi(void) {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return spi_handle;
}

static int read_max31855(int spi_handle, float *temperature) {
    char rx_buf[4] = {0};
    int ret = spiRead(spi_handle, rx_buf, 4);
    if (ret != 4) {
        fprintf(stderr, "Error reading from SPI: %s\n", pigpio_error(ret));
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: 0x%08X\n", raw);
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_temp & 0x2000) {
        thermocouple_temp |= 0xC000;
    }
    *temperature = thermocouple_temp * 0.25f;
    return 0;
}

static int calculate_pwm_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) {
        return 0;
    } else if (temperature < TEMP_MAX) {
        float fraction = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN);
        if (fraction < 0.0f) fraction = 0.0f;
        if (fraction > 1.0f) fraction = 1.0f;
        return (int)(fraction * 50.0f);
    } else {
        return 255;
    }
}

static void update_fan_pwm(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", gpio);
    }
}

static void log_temperature_data(float temperature, int pwm_duty_cycle) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].pwm_duty_cycle = pwm_duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Temperature Log ---\n");
    int start = (buffer_count == BUFFER_SIZE) ? buffer_index : 0;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&temperature_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Temp: %.2f C, PWM: %d\n",
               time_str, temperature_buffer[idx].temperature,
               temperature_buffer[idx].pwm_duty_cycle);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = initialize_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) == 0) {
            int pwm_duty_cycle = calculate_pwm_duty_cycle(temperature);
            update_fan_pwm(FAN_GPIO, pwm_duty_cycle);
            log_temperature_data(temperature, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

