#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x55
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define OSS 3
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t logging_active = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int read_calibration_data(void) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];
    return 0;
}

static int read_raw_temperature(int32_t *raw_temp) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_pressure(int32_t *raw_pressure) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(5000);
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

static int read_bmp180_data(float *temperature, float *pressure) {
    int32_t raw_temperature, raw_pressure;
    if (read_raw_temperature(&raw_temperature) != 0) return -1;
    if (read_raw_pressure(&raw_pressure) != 0) return -1;
    int32_t x1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *temperature = ((b5 + 8) >> 4) / 10.0f;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (uint32_t)(50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    logging_active = !logging_active;
    printf("Logging %s\n", logging_active ? "active" : "inactive");
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    while (running) {
        if (logging_active) {
            float temperature, pressure;
            if (read_bmp180_data(&temperature, &pressure) == 0) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
                fflush(log_file);
            } else {
                fprintf(stderr, "Error reading BMP180 data\n");
            }
        }
        gpioDelay(1000000);
    }
    printf("Cleaning up...\n");
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

