/*
 * MAX31865 RTD Temperature Logger for Raspberry Pi 5
 *
 * Wiring:
 *   MAX31865 VCC  -> 3.3V (Pin 1)
 *   MAX31865 GND  -> GND  (Pin 9)
 *   MAX31865 SCLK -> GPIO11 (SPI0 SCLK)
 *   MAX31865 CS   -> GPIO8  (SPI0 CE0)
 *   MAX31865 DO   -> GPIO9  (SPI0 MISO)
 *
 * Build: gcc -O2 -Wall -o rtd_logger rtd_logger.c -lpigpio -lrt
 * Run:   sudo ./rtd_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LOG_FILE       "rtd_log.csv"
#define SAMPLE_INTERVAL 5         /* seconds */
#define MAX_RETRIES    3

/* MAX31865 register addresses */
#define REG_TEMP_L    0x00
#define REG_TEMP_H    0x01
#define REG_FAULT     0x02
#define REG_CONFIG    0x03

/* Configuration register bits */
#define CFG_RTD_3WIRE  0x80      /* Enable 3-wire RTD mode */
#define CFG_BIAS_V    0x40      /* Enable bias voltage */
#define CFG_3WRTD      0x20      /* 3-wire RTD mode */
#define CFG_FAULT_EN  0x01      /* Enable fault status */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the MAX31865                 */
/* ------------------------------------------------------------------ */
static int read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };   /* MSB = 1 for read */
    char rx[2] = { 0, 0 };

    if (spiXfer(fd, tx, rx, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian register to the MAX31865                   */
/* ------------------------------------------------------------------ */
static int write_reg16(int fd, uint8_t reg, uint16_t val)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(val & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(fd, tx, rx, 2) != 2) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from MAX31865 in 3-wire RTD mode                     */
/* Returns 0 on success, -1 on SPI error, -2 on sensor-absent fault    */
/* ------------------------------------------------------------------ */
static int read_temperature(int fd, float *temperature)
{
    uint16_t raw;
    uint16_t fault;

    /* Read fault status */
    if (read_reg16(fd, REG_FAULT, &fault) != 0) {
        return -1;
    }
    if (fault & CFG_FAULT_EN) {
        fprintf(stderr, "[ERROR] MAX31865 fault detected: 0x%04X\n", fault);
        return -2;
    }

    /* Read temperature registers */
    if (read_reg16(fd, REG_TEMP_L, &raw) != 0) {
        return -1;
    }

    /* Extract 14-bit signed temperature (bits 15:2) */
    int16_t temp_raw = (int16_t)(raw >> 2);
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000;          /* Sign-extend 14-bit to 16-bit */
    }

    /* Callendar-Van Dusen RTD temperature conversion */
    float rtd_resistance = (float)temp_raw * 100.0f;   /* 100 ohms per count */
    float rtd_alpha = 0.0039083f;   /* MAX31865 alpha */
    float rtd_b = 0.000000577f;   /* MAX31865 beta */
    float rtd_c = 0.0000000001f;  /* MAX31865 c */

    float rtd_temp = rtd_alpha * rtd_resistance + rtd_b;
    *temperature = rtd_temp - rtd_c;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log temperature to CSV file                                          */
/* ------------------------------------------------------------------ */
static int log_temperature(FILE *fp, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_fd < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel=%d, speed=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature_C\n");
        fflush(g_log_fp);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX31865 RTD logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f;

        int rc = read_temperature(g_spi_fd, &temperature);
        if (rc == 0) {
            if (log_temperature(g_log_fp, temperature) != 0) {
                fprintf(stderr, "[WARN] Failed to log temperature\n");
            }
            printf("Temperature: %.2f C\n", temperature);
        } else if (rc == -1) {
            fprintf(stderr, "[ERROR] SPI communication failure\n");
            log_temperature(g_log_fp, -999.0f);
        } else {
            /* rc == -2: sensor-absent fault */
            fprintf(stderr, "[ERROR] MAX31865 sensor-absent or not responding\n");
            log_temperature(g_log_fp, -999.0f);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

