#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

#define BME280_CHIP_ID 0x60

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_calibration_data(int fd, uint8_t *calib) {
    uint8_t buf[26];
    if (i2c_read_burst(fd, BME280_REG_CALIB_00, buf, 26) < 0) return -1;
    for (int i = 0; i < 26; i++) calib[i] = buf[i];
    return 0;
}

static int init_bme280(int fd, uint8_t *calib) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &chip_id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280.\n");
        return -1;
    }
    usleep(10000);

    if (read_calibration_data(fd, calib) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set humidity oversampling.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error: Failed to set config register.\n");
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to set control measurement register.\n");
        return -1;
    }
    return 0;
}

static int read_bme280_data(int fd, uint8_t *calib, float *temp, float *hum, float *press) {
    uint8_t buf[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, buf, 8) < 0) {
        fprintf(stderr, "Error: Failed to read data register.\n");
        return -1;
    }

    int32_t raw_press = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t raw_temp = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    int32_t raw_hum = (buf[6] << 8) | buf[7];

    int32_t var1, var2, t_fine;
