static int read_bmp180_data(int handle, int32_t *raw_temp, int32_t *raw_pressure, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
