#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB_00    0x88
#define BMP280_REG_CALIB_26    0xE1

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "weather_data.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(int fd, const char *addr) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: failed to read BMP280 ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x58 && id != 0x59) {
        fprintf(stderr, "Error: unexpected BMP280 ID 0x%02X (expected 0x58 or 0x59)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: failed to reset BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    uint8_t calib[26];
    if (i2c_read_block(fd, BMP280_REG_CALIB_00, calib, 24) < 0) {
        fprintf(stderr, "Error: failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    bmp280_calib_t cal;
    cal.dig_T1 = (uint16_t)(calib[1]  << 8 | calib[0]);
    cal.dig_T2 = (int16_t)(calib[3]  << 8 | calib[2]);
    cal.dig_T3 = (int16_t)(calib[5]  << 8 | calib[4]);
    cal.dig_P1 = (uint16_t)(calib[7]  << 8 | calib[6]);
    cal.dig_P2 = (int16_t)(calib[9]  << 8 | calib[8]);
    cal.dig_P3 = (int16_t)(calib[11] << 8 | calib[10]);
    cal.dig_P4 = (int16_t)(calib[13] << 8 | calib[12]);
    cal.dig_P5 = (int16_t)(calib[15] << 8 | calib[14]);
    cal.dig_P6 = (int16_t)(calib[17] << 8 | calib[16]);
    cal.dig_P7 = (int16_t)(calib[19] << 8 | calib[18]);
    cal.dig_P8 = (int16_t)(calib[21] << 8 | calib[20]);
    cal.dig_P9 = (int16_t)(calib[23] << 8 | calib[22]);
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error: failed to read pressure/temperature data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw_p = (int32_t)((uint32_t)data[0] << 12 | (uint32_t)data[1] << 4 | (uint32_t)data[2] >> 4);
    int32_t raw_t = (int32_t)((uint32_t)data[3] << 12 | (uint32_t)data[4] << 4 | (uint32_t)data[5] >> 4);
    int32_t var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    int32_t var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    int32_t t_fine = var1 + var2;
    *temp = ((t_fine * 5 + 128) >> 8) / 100.0f;
    int64_t v1 = ((int64_t)t_fine) - 128000;
    int64_t v2 = v1 * v1 * (int64_t)cal->dig_P6;
    v2 = v2 + ((v1 * (int64_t)cal->dig_P5) << 17);
    v2 = v2 + (((int64_t)cal->dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)cal->dig_P3) >> 8) + ((v1 * (int64_t)cal->dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)cal->dig_P1) >> 33;
    if (v1 == 0) return -1;
    int64_t p = 1048576 - raw_p;
    p = (((p << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    v2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + v1 + v2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    *press = (float)p / 100.0f;
    return 0;
}

static int log_data(const char *filename, float temp, float press) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR_DEFAULT, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd, BMP280_I2C_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed at address 0x%02X\n", BMP280_I2C_ADDR_DEFAULT);
        close(fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", BMP280_I2C_ADDR_DEFAULT);

    while (g_running) {
        float temp, press;
        if (bmp280_read(fd, NULL, &temp, &press) < 0) {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        } else {
            if (log_data(LOG_FILE, temp, press) < 0) {
                fprintf(stderr, "Warning: log write failed\n");
            } else {
                printf("Logged: %.2f °C, %.2f hPa\n", temp, press);
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

