/*
 * LM75 temperature monitor with alert LED on Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - LM75 sensor on I2C bus 1, address 0x4D (default).
 *   - Alert LED on GPIO18 (BCM).
 *
 * Behavior:
 *   - Reads temperature once per second.
 *   - Stores readings in a 60-sample circular buffer.
 *   - Drives the alert LED in a background thread: on  > 28.0 °C, on < 20.0 °C, off otherwise.
 *   - On any I2C or GPIO error, logs to stderr and attempts to re-initialize.
 *   - On SIGINT, cleanly releases all resources.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x4D
#define LM75_REG_TEMP  0x00
#define LM75_REG_CONFIG 0x01
#define LM75_CONFIG    0x00
#define LM75_TEMP_MSB  0x80
#define LM75_TEMP_LSB  0x40
#define LM75_ERROR     0xFF
#define BUFFER_SIZE    60
#define ALERT_THRESHOLD_HIGH  28.0f
#define ALERT_THRESHOLD_LOW   20.0f
#define SAMPLE_PERIOD_SEC  1
#define LED_PIN           18
#define LED_CONSUMER      "lm75-alert"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float g_running_avg = 0.0f;
static int g_avg_index = 0;
static int g_avg_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (i2c_write_byte(g_i2c_fd, LM75_REG_CONFIG, LM75_CONFIG) < 0) {
        fprintf(stderr, "Failed to configure LM75 (sensor may be absent).\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out)
{
    uint8_t msb, lsb;
    if (i2c_read_byte(g_i2c_fd, LM75_REG_TEMP, &msb) < 0) return -1;
    if (i2c_read_byte(g_i2c_fd, LM75_REG_TEMP + 1, &lsb) < 0) return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    if (raw == LM75_ERROR) {
        fprintf(stderr, "LM75 error code returned (0x%04X).\n", raw);
        return -1;
    }
    *temp_out = (float)((raw & 0x0FFF) * 0.0625f);
    return 0;
}

static void buffer_add(float temp)
{
    pthread_mutex_lock(&g_buffer_mutex);
    g_running_avg -= g_running_avg[g_avg_index];
    g_running_avg += temp;
    g_running_avg[g_avg_index] = temp;
    g_avg_index = (g_avg_index + 1) % BUFFER_SIZE;
    if (g_avg_count < BUFFER_SIZE) g_avg_count++;
    pthread_mutex_unlock(&g_buffer_mutex);
}

static float buffer_average(void)
{
    pthread_mutex_lock(&g_buffer_mutex);
    if (g_avg_count == 0) {
        pthread_mutex_unlock(&g_buffer_mutex);
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_avg_count; i++) sum += g_running_avg[i];
    pthread_mutex_unlock(&g_buffer_mutex);
    return sum / (float)g_avg_count;
}

static void *alert_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            buffer_add(temp);
            if (temp > ALERT_THRESHOLD_HIGH) {
                if (gpiod_line_set_value(gpiod_line, LED_PIN) < 0) {
                    fprintf(stderr, "Failed to set LED on: %s\n", strerror(errno));
                }
            } else if (temp < ALERT_THRESHOLD_LOW) {
                if (gpiod_line_set_value(gpiod_line, LED_PIN) < 0) {
                    fprintf(stderr, "Failed to set LED off: %s\n", strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(gpiod_line, LED_PIN) < 0) {
                    fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Temperature read failed; attempting re-initialization.\n");
            if (init_i2c() < 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
            }
        }
        sleep(SAMPLE_PERIOD_SEC);
    }
    return NULL;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Initial I2C init failed. Exiting.\n");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led, LED_CONSUMER, 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "pthread_create failed: %s\n", strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }

    printf("LM75 monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            printf("Temperature: %.2f °C\n", temp);
            buffer_add(temp);
            float avg = buffer_average();
            printf("Average: %.2f °C\n", avg);
        } else {
            fprintf(stderr, "Read failed; re-initializing I2C.\n");
            if (init_i2c() < 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
            }
        }
        sleep(SAMPLE_PERIOD_SEC);
    }

    printf("\nShutting down...\n");
    g_running = 0;
    pthread_join(alert_tid, NULL);
    gpiod_line_set_value(led, LED_PIN);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(g_i2c_fd);
    pthread_mutex_destroy(&g_buffer_mutex);
    printf("Done.\n");
    return 0;
}

