/*
 * Raspberry Pi 4 Model B — PT100 RTD Heater PID Controller
 *
 * Hardware:
 *   - MAX31865 on SPI0 CE0 (mode 1, 500 kHz)
 *   - PT100 RTD on MAX31865 channel 1
 *   - 430 ohm reference resistor
 *   - Heater MOSFET on GPIO18 (hardware PWM, 1 kHz, 1000 steps)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_pid heater_pid.c -lpigpio -lrt
 *   sudo ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_SPEED        500000     /* 500 kHz — MAX31865 max 5 MHz */
#define SPI_FLAGS        0          /* mode 1, active-low CE */

#define HEATER_GPIO      18         /* hardware PWM0 on GPIO18 */
#define PWM_FREQUENCY    1000       /* 1 kHz driver */
#define PWM_RANGE        1000       /* 0-1000 duty steps */

#define LOG_FILE         "heater_pid.log"
#define CONFIG_FILE      "heater_pid_config.json"

/* PID gains (defaults) */
#define DEFAULT_KP        1.0
#define DEFAULT_KI        0.1
#define DEFAULT_KD        0.01
#define DEFAULT_TARGET    25.0

/* Failsafe */
#define FAULT_TEMP        80.0

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static int  g_pigpio_initialized = 0;
static bool g_pigpio_ready = false;

/* PID state */
static double g_integral = 0.0;
static double g_prev_error = 0.0;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static void log_message(const char *msg);
static int  read_rtd_temperature(double *temp);
static double calculate_pid(double setpoint, double actual, double kp, double ki, double kd);
static int  load_configuration(const char *filename, double *target, double *kp, double *ki, double *kd);
static int  initialize(void);
static void cleanup(void);
static void set_heater_pwm(int duty);

/* ----------------------------- Signal / Logging -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        }
        fclose(fp);
    }
    fprintf(stderr, "[%s] %s\n", __TIME__, msg);
}

/* ----------------------------- RTD Read --------------------------------- */
/*
 * MAX31865 32-bit SPI frame (MSB first):
 *   D[31:18]  Temperature (0.0625 °C / count)
 *   D[17:16]  Fault bit
 *   D[15:4]   Resistance (0.25 °C / count, 0.25 °C/°C)
 *   D[3:0]    Unknown
 *
 * PT100:  R = 100.0 °C / (T - 0.0 °C)  =>  T = 100.0 °C / (R - 0.25)
 */
static int read_rtd_temperature(double *temp)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes = spiRead(g_spi_handle, rx, 4);
    if (bytes != 4) {
        log_message("SPI read failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit (D[17:16]) */
    if (raw & 0x00010000) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "MAX31865 fault detected (raw=0x%08X)", raw);
        log_message(msg);
        return -2;
    }

    /* D[31:18] = 14-bit temperature */
    int16_t t_raw = (int16_t)(raw >> 18);
    if (t_raw & 0x2000) {
        t_raw |= 0xC000;  /* sign-extend 14 -> 16 */
    }
    *temp = (double)t_raw * 0.0625;
    return 0;
}

/* ----------------------------- PID --------------------------------------- */
static double calculate_pid(double setpoint, double actual, double kp, double ki, double kd)
{
    double error = setpoint - actual;
    g_integral += error;
    double derivative = error - g_prev_error;
    g_prev_error = error;

    double output = kp * error + ki * g_integral + kd * derivative;
    return output;
}

/* ----------------------------- Config / Init ---------------------------- */
static int load_configuration(const char *filename, double *target, double *kp, double *ki, double *kd)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        log_message("Cannot open config file; using defaults");
        *target = DEFAULT_TARGET;
        *kp    = DEFAULT_KP;
        *ki    = DEFAULT_KI;
        *kd    = DEFAULT_KD;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *name = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!name || !value) continue;

        if (strcmp(name, "target_temperature") == 0) *target = atof(value);
        else if (strcmp(name, "kp") == 0) *kp = atof(value);
        else if (strcmp(name, "ki") == 0) *ki = atof(value);
        else if (strcmp(name, "kd") == 0) *kd = atof(value);
    }
    fclose(fp);

    if (*target < -50.0 || *target > 150.0) {
        log_message("Invalid target temperature; using default 25.0 C");
        *target = DEFAULT_TARGET;
    }
    return 0;
}

static int initialize(void)
{
    /* pigpio */
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    g_pigpio_initialized = true;
    g_pigpio_ready = true;

    /* SPI0 CE0, mode 1, 500 kHz */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        log_message("spiOpen failed");
        return -1;
    }

    /* Heater PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        log_message("gpioSetMode failed");
        return -1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        log_message("gpioSetPWMfrequency failed");
        return -1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        log_message("gpioSetPWMrange failed");
        return -1;
    }
    if (gpioPWM(HEATER_GPIO, 0) < 0) {
        log_message("gpioPWM init failed");
        return -1;
    }

    /* Load config */
    double target = DEFAULT_TARGET, kp = DEFAULT_KP, ki = DEFAULT_KI, kd = DEFAULT_KD;
    if (load_configuration(CONFIG_FILE, &target, &kp, &ki, &kd) != 0) {
        log_message("Configuration load failed; using defaults");
    }

    log_message("Initialization complete");
    return 0;
}

static void cleanup(void)
{
    if (g_pigpio_ready) {
        gpioPWM(HEATER_GPIO, 0);
        gpioSetMode(HEATER_GPIO, PI_INPUT);
        g_pigpio_ready = false;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = false;
    }
}

/* ----------------------------- Heater Control ---------------------------- */
static void set_heater_pwm(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) < 0) {
        log_message("gpioPWM failed");
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize() != 0) {
        log_message("Initialization failed");
        return EXIT_FAILURE;
    }

    double target = DEFAULT_TARGET, kp = DEFAULT_KP, ki = DEFAULT_KI, kd = DEFAULT_KD;
    double temp = 0.0;
    double pid_out = 0.0;
    bool failsafe_active = false;

    while (g_running) {
        if (read_rtd_temperature(&temp) != 0) {
            log_message("Temperature read failed; failsafe");
            set_heater_pwm(0);
            failsafe_active = true;
            break;
        }

        pid_out = calculate_pid(target, temp, kp, ki, kd);

        int duty = (int)(pid_out + 500.0);  /* clamp 0-1000 */
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        set_heater_pwm(duty);

        if (temp > FAULT_TEMP) {
            log_message("Temperature exceeds failsafe threshold");
            set_heater_pwm(0);
            failsafe_active = true;
            break;
        }

        if (failsafe_active) {
            log_message("Failsafe triggered; heater off");
            break;
        }

        log_message("Target: 25.0 C, Actual: 25.0 C, PID: 50.0, Duty: 500");
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

