#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   2000000
#define RELAY_PIN   17
#define PWM_RANGE   100
#define PWM_FREQ    1000
#define TARGET_TEMP 25.0
#define MAX_DUTY    80.0
#define LOG_FILE    "heater_log.csv"
#define SAMPLE_US   100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(RELAY_PIN, 0);
    gpioTerminate();
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_max31855(float *temp_c) {
    char rx[4] = {0, 0, 0, 0};
    int ret = spiRead(spi_handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: spiRead returned %d (expected 4)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault (open circuit)\n");
        return -1;
    }
    if (raw & 0x00020000) {
        fprintf(stderr, "Error: MAX31855 fault (short to ground)\n");
        return -1;
    }
    if (raw & 0x00040000) {
        fprintf(stderr, "Error: MAX31855 fault (short to VCC)\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000;
    }
    *temp_c = (float)temp_raw * 0.25;
    return 0;
}

static float calculate_duty(float temp_c) {
    float error = TARGET_TEMP - temp_c;
    if (error > 0.0f) {
        error = error * 0.1f;
    } else if (error < 0.0f) {
        error = -error * 0.1f;
    }
    float duty = (error * 0.1f) / MAX_DUTY;
    if (duty > 1.0f) duty = 1.0f;
    if (duty < 0.0f) duty = 0.0f;
    return duty;
}

static void log_data(float temp_c, float duty) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp_c, duty);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(RELAY_PIN, PWM_RANGE);
    gpioSetPWMfrequency(RELAY_PIN, PWM_FREQ);
    gpioPWM(RELAY_PIN, 0);

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Heater controller started. Target: %.1f C, Max Duty: %.1f%%\n",
           TARGET_TEMP, MAX_DUTY * 100.0);

    while (running) {
        float temp_c;
        if (read_max31855(&temp_c) == 0) {
            float duty = calculate_duty(temp_c);
            gpioPWM(RELAY_PIN, (int)(duty * PWM_RANGE));
            log_data(temp_c, duty);
            printf("Temp: %.2f C, Duty: %.2f%%\n", temp_c, duty);
        } else {
            fprintf(stderr, "Error reading MAX31855. Setting duty to 0%%.\n");
            gpioPWM(RELAY_PIN, 0);
            log_data(-999.0f, 0.0f);
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

