#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE "cpu_temp.txt"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static int read_cpu_temp(float *temp)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int c;
    if (fscanf(fp, "%d", &c) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temp = (float)c / 1000.0f;
    return 0;
}

static void control_led(float temp)
{
    int red, green, blue;

    if (temp < 40.0f) {
        red   = 0;
        green = 0;
        blue  = 255;
    } else if (temp < 60.0f) {
        red   = 0;
        green = 255;
        blue  = 0;
    } else {
        red   = 255;
        green = 0;
        blue  = 0;
    }

    if (set_led_color(red, green, blue) < 0) {
        fprintf(stderr, "Error setting LED color\n");
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Common-anode: duty 0 = off, duty 255 = full on (inverted). */
    if (gpioSetPWMrange(RED_PIN,   255) < 0 ||
        gpioSetPWMrange(GREEN_PIN, 255) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  255) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(RED_PIN,   255)   < 0 ||
        gpioPWM(GREEN_PIN,  255) < 0 ||
        gpioPWM(BLUE_PIN,  255)  < 0) {
        fprintf(stderr, "Error initializing PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CPU Temperature Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_cpu_temp(&temp) < 0) {
            fprintf(stderr, "Skipping temperature update.\n");
        } else {
            control_led(temp);
            printf("Temperature: %.2f m°C, PWM: R=%d G=%d B=%d\n",
                   temp, gpioGetPWMdutycycle(RED_PIN), gpioGetPWMdutycycle(GREEN_PIN), gpioGetPWMdutycycle(BLUE_PIN));
        }
        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown: turn off all channels and release pigpio. */
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

