#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, int timeout_ms) {
    int start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_ms) return -1;
    }
    return 0;
}

static int read_dht22(float *temperature, float *humidity) {
    unsigned char data[5] = {0};
    int i, j;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(2000);

    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, 1000) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, 1000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, 1000) < 0) return -1;
        gpioDelay(1);

        if (wait_for_level(DHT22_GPIO, 0, 1000) < 0) return -1;
        gpioDelay(1);

        int bit = gpioRead(DHT22_GPIO);
        if (bit < 0) return -1;

        if (bit == 1) {
            data[i / 8] <<= 1;
            if ((i + 1) % 8 < 3) data[i / 8] |= 1;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -2;

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

static int send_http_request(const char *url, float temperature, float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connect");
        close(sockfd);
        return -1;
    }

    char request[512];
    snprintf(request, sizeof(request),
             "GET /api/humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Connection: close\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "User-Agent: pigpio/1.9.1\r\n"
             "\r\n"
             "{\"temperature\": %.2f, \"humidity\": %.2f}\r\n",
             url, (int)strlen(url), temperature, humidity);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        perror("send");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
