#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x55
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define BUTTON_GPIO 4
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_S 2

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging_enabled = 0;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) return -1;
    return 0;
}

static int read_calibration(int handle, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                            uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                            int16_t *b1, int16_t *b2, int16_t *mb,
                            int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, 22) < 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    *b1  = (int16_t)((buf[12] << 8) | buf[13]);
    *b2  = (int16_t)((buf[14] << 8) | buf[15]);
    *mb  = (int16_t)((buf[16] << 8) | buf[17]);
    *mc  = (int16_t)((buf[18] << 8) | buf[19]);
    *md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *raw = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int oss, int32_t *raw) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x34 + (oss << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << oss));
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *raw = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - oss);
    return 0;
}

static int32_t compute_b5(int32_t ut, int16_t ac6, int16_t ac5, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, int16_t ac6, int16_t ac5, int16_t b1, int16_t b2, int16_t mb, int16_t mc, int16_t md) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void button_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_US) {
        g_logging_enabled = !g_logging_enabled;
        printf("Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_tick = tick;
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t cal_ac1, cal_ac2, cal_ac3, cal_ac4, cal_ac5, cal_ac6, cal_b1, cal_b2, cal_mb, cal_mc, cal_md;
    if (read_calibration(g_i2c_handle, &cal_ac1, &cal_ac2, &cal_ac3, &cal_ac4, &cal_ac5, &cal_ac6,
                         &cal_b1, &cal_b2, &cal_mb, &cal_mc, &cal_md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", BUTTON_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", BUTTON_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(BUTTON_GPIO, button_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", BUTTON_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 ready. Press button on GPIO %d to toggle logging. Ctrl+C to exit.\n", BUTTON_GPIO);
    fflush(stdout);

    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(g_i2c_handle, &ut) < 0) {
                fprintf(stderr, "Error reading raw temperature\n");
            } else if (read_raw_pressure(g_i2c_handle, BMP180_OSS, &up) < 0) {
                fprintf(stderr, "Error reading raw pressure\n");
            } else {
                int32_t b5 = compute_b5(ut, cal_ac6, cal_ac5, cal_mc, cal_md);
                int32_t pressure = compute_pressure(up, b5, cal_ac6, cal_ac5, cal_b1, cal_b2, cal_mb, cal_mc, cal_md);
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
                FILE *fp = fopen("pressure_log.txt", "a");
                if (fp) {
                    fprintf(fp, "%s, Pressure: %.2f hPa\n", ts, pressure / 100.0);
                    fclose(fp);
                } else {
                    fprintf(stderr, "Error opening pressure_log.txt\n");
                }
                printf("Pressure: %.2f hPa at %s\n", pressure / 100.0, ts);
            }
        } else {
            printf("Logging disabled. Press button to enable.\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

