#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdint.h>
#include <syslog.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define MAX Edges 85
#define READ_INTERVAL 10
#define MAX Edges 85

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-library’s-API-call.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts;
    ts.tv_sec = us / 1000000;
    ts.tv_nsec = (us % 1000000) * 1000;
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000);
}

static void sleep_us_ms(unsigned int ms) {
    sleep_us(ms * 1000);
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static void log_msg_with_data(int priority, const char *msg, ...) {
    syslog(priority, msg, __VA_ARGS__);
}

static int curl_init(void) {
    curl_global_init(CURL_GLOBAL_DEFAULT);
    return 0;
}

static void curl_cleanup(void) {
    curl_global_cleanup();
}

static int curl_post(const char *url, const char *data, size_t size) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        log_msg(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        log_msg(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        log_msg(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        return -1;
    }

    if (http_code < 200 || http_code >= 300) {
        log_msg(LOG_ERR, "HTTP POST returned non-2xx status code: %ld", http_code);
        return -1;
    }

    return 0;
}

static int read_dht22(int gpio, float *humidity, float *temperature) {
    uint8_t data[5] = {0};
    int laststate = 1;
    int counter = 0;
    int j = 0;
    int lastcounter = 0;

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        log_msg(LOG_ERR, "Failed to set GPIO %d as output", gpio);
        return -1;
    }
    if (gpioSetPullUpDown(gpio, PI_PUD_UP) < 0) {
        log_msg(LOG_ERR, "Failed to set pull-up on GPIO %d", gpio);
        return -1;
    }

    sleep_ms(2);
    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        log_msg(LOG_ERR, "Failed to set GPIO %d as input", gpio);
        return -1;
    }

    sleep_us(1000);
    if (gpioSetPullUpDown(gpio, PI_PUD_OFF) < 0) {
        log_msg(LOG_ERR, "Failed to set pull-down on GPIO %d", gpio);
        return -1;
    }

    sleep_us(30);
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        log_msg(LOG_ERR, "Failed to set GPIO %d as output", gpio);
        return -1;
    }
    if (gpioWrite(gpio, 0) < 0) {
        log_msg(LOG_ERR, "Failed to write low to GPIO %d", gpio);
        return -1;
    }
    sleep_us(1000);
    if (gpioWrite(gpio, 1) < 0) {
        log_msg(LOG_ERR, "Failed to write high to GPIO %d", gpio);
        return -1;
    }
    sleep_us(30);

    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        log_msg(LOG_ERR, "Failed to set GPIO %d as input", gpio);
        return -1;
    }

    while (counter < 85) {
        counter = 0;
        for (int i = 0; i < 85; i++) {
            int state = gpioRead(gpio);
            if (state < 0) {
                log_msg(LOG_ERR, "Failed to read GPIO %d", gpio);
                return -1;
            }
            if (state != laststate) {
                counter++;
                lastcounter = counter;
                if (counter == 40) {
                    break;
                }
                sleep_us(1);
                laststate = state;
            }
        }
        if (counter == 40) {
            break;
        }
    }

    if (counter < 40) {
        log_msg(LOG_ERR, "DHT22 timeout or incomplete response");
        return -1;
    }

    for (j = 0; j < 40; j++) {
        if (data[j / 8] & (1 << (7 - (j % 8)))) {
            if (j < 16) {
                data[j] = (data[j] << 1) | 1;
            } else if (j < 32) {
                data[j] = (data[j] << 1) | 0;
            }
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        log_msg(LOG_ERR, "DHT22 checksum error");
        return -1;
    }

    *temperature = (float)(((uint16_t)data[0] << 8) | data[1]) / 10.0;
    *humidity = (float)(((uint16_t)(data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *humidity = -(*humidity);
    }

    return 0;
}

static int read_dht22_with_retry(int gpio, float *humidity, float *temperature) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read_dht22(gpio, humidity, temperature) == 0) {
            return 0;
        }
        log_msg(LOG_WARNING, "DHT22 read failed, retry %d/%d", i + 1, MAX_RETRIES);
        sleep_us(2000000);
    }
    log_msg(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int format_json(float humidity, float temperature, char *json_string, size_t size) {
    int ret = snprintf(json_string, size, "{\"humidity\":%.2f,\"temperature\":%.2f}", humidity, temperature);
    if (ret < 0 || (size_t)ret >= size) {
        log_msg(LOG_ERR, "JSON formatting failed");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        if (opt == 's') {
            api_url = optarg;
        } else {
            fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    log_msg(LOG_INFO, "Starting DHT22 monitor");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (curl_init() != 0) {
        log_msg(LOG_ERR, "curl_init() failed");
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        float humidity = 0.0, temperature = 0.0;
        char json_string[256];
        int post_result = -1;

        if (read_dht22_with_retry(DHT22_GPIO, &humidity, &temperature) == 0) {
            if (format_json(humidity, temperature, json_string, sizeof(json_string)) == 0) {
                post_result = curl_post(api_url, json_string, strlen(json_string));
            } else {
                log_msg(LOG_ERR, "JSON formatting failed");
            }
        } else {
            log_msg(LOG_ERR, "DHT22 read failed after retries");
        }

        if (post_result != 0) {
            log_msg(LOG_ERR, "HTTP POST failed");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep_ms(1000);
        }
    }

    log_msg(LOG_INFO, "Shutting down");
    curl_post(api_url, "shutting_down", 0);
    curl_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

