/*
 * Raspberry Pi 5 Active Cooler Fan Controller
 *
 * Reads CPU temperature from /sys/class/thermal/thermal_zone0/temp
 * and fan state from /sys/class/thermal/cooling_device0/cur_state.
 * Applies a tiered speed map and writes the new state to the
 * cooling_device sysfs entry only when the speed changes.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_control fan_control.c
 * Run:    sudo ./fan_control   (needs write access to /sys/class/thermal)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/stat.h>

#define TEMP_PATH      "/sys/class/thermal/thermal_zone0/temp"
#define FAN_PATH       "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_PATH       "/var/log/fan_control.log"
#define POLL_INTERVAL  5          /* seconds between temperature reads */
#define MAX_TEMP       80000      /* 80 °C in millidegrees */
#define MAX_FAN        3          /* maximum fan state */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_PATH, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_PATH, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Sysfs helpers                                                       */
/* ------------------------------------------------------------------ */
static int sysfs_write(const char *path, const char *value)
{
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    ssize_t n = write(fd, value, strlen(value));
    if (n < 0) {
        fprintf(stderr, "write(%s, %s): %s\n", path, value, strerror(errno));
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        fprintf(stderr, "close(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int sysfs_read(const char *path, char *buf, size_t len)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s, O_RDONLY): %s\n", path, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, len - 1);
    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Temperature reading                                                 */
/* ------------------------------------------------------------------ */
static int read_cpu_temp(int *temp_out)
{
    char buf[16];
