#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMP 50.0
#define LOG_FILE "heater_log.txt"
#define SAMPLE_INTERVAL 1.0
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define MAX_DUTY 100
#define MIN_DUTY 0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double integral = 0.0;
static double previous_error = 0.0;
static double dt = 0.0;
static bool heater_enabled = true;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_max31855(float *temperature) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    if (raw & 0x00010000) {
        uint8_t fault = raw & 0x07;
        if (fault & 0x01) {
            fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        } else if (fault & 0x02) {
            fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        } else if (fault & 0x04) {
            fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 Fault: Unknown\n");
        }
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_temp & 0x2000) {
        thermocouple_temp |= 0xC000;
    }
    *temperature = thermocouple_temp * 0.25;
    return 0;
}

static double calculate_pid(double current_temp) {
    double error = TARGET_TEMP - current_temp;
    integral += error * dt;
    double derivative = (error - previous_error) / dt;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

static void log_data(float temperature, double duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

static void cleanup(void) {
    if (heater_enabled) {
        gpioPWM(HEATER_GPIO, 0);
        heater_enabled = false;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature;
        if (read_max31855(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature, disabling heater for safety\n");
            set_heater_pwm(0.0);
            dt = 0.0;
            integral = 0.0;
            previous_error = 0.0;
            sleep(1);
            continue;
        }

        dt = SAMPLE_INTERVAL;
        double pid_output = calculate_pid(temperature);

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            set_heater_pwm(0.0);
            dt = 0.0;
            integral = 0.0;
            previous_error = 0.0;
            sleep(1);
            continue;
        }

        double duty_cycle = (pid_output + 50.0) / 50.0;
        if (duty_cycle < 0.0) duty_cycle = 0.0;
        if (duty_cycle > 100.0) duty_cycle = 100.0;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        sleep(1);
    }

    cleanup();
    return 0;
}

