    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

static void cleanup(void) {
    if (heater_enabled) {
        gpioPWM(HEATER_GPIO, 0);
        heater_enabled = false;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature;
        if (read_max31855(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature, disabling heater for safety\n");
            set_heater_pwm(0.0);
            dt = 0.0;
            integral = 0.0;
            previous_error = 0.0;
            sleep(1);
            continue;
        }

        dt = SAMPLE_INTERVAL;
        double pid_output = calculate_pid(temperature);

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            set_heater_pwm(0.0);
            dt = 0.0;
            integral = 0.0;
            previous_error = 0.0;
            sleep(1);
            continue;
        }

        double duty_cycle = (pid_output + 50.0) / 50.0;
        if (duty_cycle < 0.0) duty_cycle = 0.0;
        if (duty_cycle > 100.0) duty_cycle = 100.0;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        sleep(1);
    }

    cleanup();
    return 0;
}

