        int duty_cycle;
        if (map_temperature_to_duty_cycle(temperature, &duty_cycle) != 0) {
            fprintf(stderr, "Error mapping temperature to duty cycle, retrying in %d seconds\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
