        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds\n", POLL_INTERVAL);
        }

        sleep(POLL_INTERVAL);
    }

    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Error turning off fan during cleanup\n");
    }
    gpioTerminate();
    return 0;
}

