#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define NUM_SENSORS 2
#define MAX_RETRIES 3
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion sensors */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read a 3-byte measurement frame from a sensor.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor(int handle, float *flow) {
    uint8_t buf[3];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadDevice(handle, (char *)buf, 3);
        if (rc == 3) {
            if (crc8(buf, 2) == buf[2]) {
                int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
                *flow = (float)raw / 100.0f;
                return 0;
            }
            fprintf(stderr, "CRC mismatch on handle %d (attempt %d)\n", handle, attempt + 1);
        } else {
            fprintf(stderr, "I2C read error on handle %d (attempt %d): rc=%d\n", handle, attempt + 1, rc);
        }
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(100000); /* 100 ms backoff */
    }
    return -1;
}

static void log_flow_data(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, f1, f2);
    } else {
        fprintf(fp, "(time-error),%.2f,%.2f\n", f1, f2);
    }

    fclose(fp);
}

int main(void) {
    int handles[NUM_SENSORS];
    int h;
    float f1, f2;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C handles for each sensor */
    for (int i = 0; i < NUM_SENSORS; i++) {
        handles[i] = i2cOpen(I2C_BUS, 0x18 + (i * 2), 0);
        if (handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n", 0x18 + (i * 2), I2C_BUS);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring (Ctrl+C to stop)...\n");

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor(handles[i], &f1) == 0) {
                log_flow_data(f1, 0.0f);
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean shutdown */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (handles[i] >= 0)
            i2cClose(handles[i]);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

