/*
 * TMAG5110A1 Dual Hall-Effect Rotary Encoder Monitor
 * Board:  Raspberry Pi 4 Model B
 * Encoder: Two TMAG5110A1 sensors wired Channel A -> GPIO17 (BCM)
 *         and Channel B -> GPIO18 (BCM).  Open-drain, internal pull-up.
 * Resolution: 360 pulses per revolution, 2-bit quadrature state machine.
 * Output:    encoder_log.txt  (timestamped position changes)
 * Build:     gcc -O2 -Wall -Wextra -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:       sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define GPIO_CHANNEL_A 17
#define GPIO_CHANNEL_B 18

/* TMAG5110A1: 2-bit quadrature, 360 pulses/rev, 1 us period */
#define PULSES_PER_REVOLUTION 360
#define QUAD_BITS_PER_PULSE   2

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void log_position(double position);
static void cleanup(void);
static int  initialize_gpio(void);
static void process_sensor_data(int channel_a, int channel_b, double *position);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* gpioTerminate is safe to call even if pigpio was not initialized. */
    gpioTerminate();
}

/* ----------------------------- GPIO Init --------------------------------- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_CHANNEL_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_CHANNEL_A);
        return -1;
    }
    if (gpioSetMode(GPIO_CHANNEL_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_CHANNEL_B);
        return -1;
    }

    /* TMAG5110A1 is open-drain; internal pull-up keeps the line high when
     * the sensor is absent.  gpioSetPullUpDown is ignored here. */
    if (gpioSetPullUpDown(GPIO_CHANNEL_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", GPIO_CHANNEL_A);
    }
    if (gpioSetPullUpDown(GPIO_CHANNEL_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", GPIO_CHANNEL_B);
    }

    return 0;
}

/* ----------------------------- Sensor Processing -------------------------- */
static void process_sensor_data(int channel_a, int channel_b, double *position)
{
    /* Quadrature: 0 = idle, 1 = rising edge, 2 = falling edge */
    int quad_a = (channel_a == 1) ? 1 : 0;
    int quad_b = (channel_b == 1) ? 1 : 0;

    /* 2-bit state machine: 00 = idle, 01 = rising, 10 = falling, 11 = idle */
    int state = (quad_a << 1) | quad_b;

    /* 2-bit -> 360-degree resolution */
