#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD144RI_ADDR 0x29
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_US 100000

#define ADPD144RI_REG_RED 0x00
#define ADPD144RI_REG_IR  0x04
#define ADPD144RI_REG_CONFIG 0x08

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(fd, ADPD144RI_REG_RED, red) < 0) return -1;
    if (i2c_read_reg16(fd, ADPD144RI_REG_IR, ir) < 0) return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (i2c_write_reg16(i2c_fd, ADPD144RI_REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Failed to configure ADPD144RI\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "timestamp,red,ir\n");
    fflush(log_file);

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(log_file, red, ir) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (ir > IR_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("IR threshold exceeded! Red=%u, IR=%u\n", red, ir);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    gpioWrite(LED_GPIO, 0);
    cleanup();
    return 0;
}

