#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x64
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define TVOC_REG 0x00
#define ECO2_REG 0x01
#define ECO2_CALIB_REG 0x02
#define ECO2_CALIB_VAL 0x0A
#define ECO2_CALIB_MASK 0x0F

#define TVOC_THRESHOLD 100.0f
#define ECO2_THRESHOLD 500.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, float *tvoc, float *eco2) {
    char buf[2];
    int ret;

    ret = i2cReadI2CBlockData(handle, TVOC_REG, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading TVOC register: %d\n", ret);
        return -1;
    }
    *tvoc = (float)((uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);

    ret = i2cReadI2CBlockData(handle, ECO2_REG, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading ECO2 register: %d\n", ret);
        return -1;
    }
    *eco2 = (float)((uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);

    return 0;
}

static float calculate_iaq(float tvoc, float eco2) {
    if (tvoc < 0.0f || eco2 < 0.0f) return -1.0f;
    return (float)(eco2 * 100.0f + tvoc) / 100.0f;
}

static int log_data(FILE *fp, float tvoc, float eco2, float iaq) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, tvoc, eco2, iaq) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int calibrate_eco2(int handle, float *calib) {
    char buf[2];
    int ret;

    ret = i2cReadI2CBlockData(handle, ECO2_CALIB_REG, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading ECO2 calibration data: %d\n", ret);
        return -1;
    }
    *calib = (float)((uint16_t)((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *calib = (*calib & ECO2_CALIB_MASK) / 10.0f;
    return 0;
}

static int initialize_sensor(int handle) {
    char buf[2];
    int ret;

    ret = i2cWriteByteData(handle, ECO2_CALIB_REG, ECO2_CALIB_VAL);
    if (ret < 0) {
        fprintf(stderr, "Error writing ECO2 calibration value: %d\n", ret);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float tvoc, eco2, iaq;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,TVOC (ppb),eCO2 (ppm),IAQ Index\n");
        fflush(log_file);
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        ret = read_sensor_data(i2c_handle, &tvoc, &eco2);
        if (ret == 0) {
            iaq = calculate_iaq(tvoc, eco2);
            if (iaq < 0.0f) {
                fprintf(stderr, "Error calculating IAQ\n");
            } else {
                if (log_data(log_file, tvoc, eco2, iaq) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

