#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BUFFER_SIZE 4096
#define FILENAME "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_pcm_data(int fd, const short *data, int num_samples) {
    size_t total_bytes = (size_t)num_samples * sizeof(short);
    size_t written = 0;
    while (written < total_bytes) {
        ssize_t bytes_written = write(fd, data + written, total_bytes - written);
        if (bytes_written < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        written += bytes_written;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "i2s_audio", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2S device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        perror("Failed to set I2S format");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        perror("Failed to set I2S channels");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        perror("Failed to set I2S sample rate");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int bytes_per_sample = 2;
    if (ioctl(fd, SNDCTL_DSP_SETFIFTSIZE, &bytes_per_sample) < 0) {
        perror("Failed to set I2S bytes per sample");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("Failed to open output file");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    short *buffer = malloc(BUFFER_SIZE * sizeof(short));
    if (!buffer) {
        perror("Failed to allocate buffer");
        fclose(fp);
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        int bytes_to_read = (I2S_DEVICE_SIZE - 4) / 2;
        if (bytes_to_read < 0) bytes_to_read = 0;

        unsigned char *data = malloc(bytes_to_read);
        if (!data) {
            perror("Failed to allocate data buffer");
            running = 0;
            break;
        }

        ssize_t bytes_read = read(fd, data, bytes_to_read);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            perror("Failed to read from I2S device");
            free(data);
            running = 0;
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "I2S device closed unexpectedly\n");
            free(data);
            running = 0;
            break;
        }

        for (ssize_t i = 0; i < bytes_read; i += 2) {
            short sample = (short)((data[i] << 8) | data[i + 1]);
            buffer[i / 2] = sample;
        }

        if (write_pcm_data(fd, buffer, bytes_read / 2) < 0) {
            fprintf(stderr, "Failed to write PCM data\n");
            running = 0;
            break;
        }

        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set GPIO line high");
            running = 0;
            break;
        }

        usleep(1000);
    }

    free(data);
    free(buffer);
    fclose(fp);
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Audio capture stopped.\n");
    return EXIT_SUCCESS;
}

