#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define SENSOR_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_flame_state = 1;
    int flame_active = 0;
    uint32_t last_flame_tick = 0;
    uint32_t last_debounce_tick = 0;
    uint32_t last_read_tick = 0;
    uint32_t last_valid_tick = 0;
    uint32_t last_timeout_tick = 0;

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor\n");
            break;
        }

        uint32_t now = gpioTick();
        if (now - last_read_tick > SENSOR_TIMEOUT_US) {
            fprintf(stderr, "Sensor timeout: no valid reading for %u us\n", now - last_read_tick);
            break;
        }
        last_read_tick = now;

        if (sensor_value == 0) {
            if (last_flame_state == 1) {
                if (now - last_debounce_tick > DEBOUNCE_DELAY_US) {
                    last_flame_state = 0;
                    last_flame_tick = now;
                    last_debounce_tick = now;
                    flame_active = 1;
                    log_event("Flame detected");
                }
            } else {
                last_flame_state = 0;
                last_flame_tick = now;
                last_debounce_tick = now;
                flame_active = 1;
                log_event("Flame detected");
            }
        } else {
            last_flame_state = 1;
            last_flame_tick = now;
            last_debounce_tick = now;
            flame_active = 0;
        }

        if (flame_active) {
            if (gpioPWM(FAN_PIN, 1) != 0) {
                fprintf(stderr, "Failed to start PWM\n");
                break;
            }
        } else {
            if (gpioPWM(FAN_PIN, 0) != 0) {
                fprintf(stderr, "Failed to stop PWM\n");
                break;
            }
        }

        last_valid_tick = now;
    }

    cleanup();
    return EXIT_SUCCESS;
}

