/*
 * Raspberry Pi 4 Model B - TI AWR1642 mmWave Radar Data Logger
 *
 * Hardware:
 *   - SPI0: CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 *   - GPIO23: Hardware trigger (frame trigger)
 *   - GPIO24: Data ready interrupt (active high)
 *
 * Build: gcc -O2 -Wall -o radar_logger radar_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define TRIGGER_PIN     23
#define DATA_READY_PIN  24

#define FRAME_SIZE      32768
#define HEATMAP_WIDTH   64
#define HEATMAP_HEIGHT  256
#define NUM_CHIRPS      64
#define NUM_SAMPLES     256

#define MAGIC_NUMBER    4144

#define LOG_FILE        "radar_data.bin"

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t frame_number;
    uint32_t timestamp;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t range_doppler_width;
    uint32_t range_resolution;
    uint32_t doppler_resolution;
    uint32_t peak_val;
    uint32_t data_offset;
} __attribute__((packed)) ConfigData;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    int16_t  peak_val;
} __attribute__((packed)) HeatmapData;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_header(FILE *fp, const ConfigData *cfg) {
    uint8_t header[40];
    memset(header, 0, sizeof(header));

    header[0] = (uint8_t)(MAGIC_NUMBER & 0xFF);
    header[1] = (uint8_t)((MAGIC_NUMBER >> 8) & 0xFF);
    header[2] = (uint8_t)((MAGIC_NUMBER >> 16) & 0xFF);
    header[3] = (uint8_t)((MAGIC_NUMBER >> 24) & 0xFF);

    memcpy(header + 4, &cfg->magic, 4);
    memcpy(header + 8, &cfg->version, 4);
    memcpy(header + 12, &cfg->frame_number, 4);
    memcpy(header + 16, &cfg->timestamp, 4);
    memcpy(header + 20, &cfg->num_chirps, 4);
    memcpy(header + 24, &cfg->num_samples, 4);
    memcpy(header + 28, &cfg->range_doppler_width, 4);
    memcpy(header + 32, &cfg->range_resolution, 4);
    memcpy(header + 36, &cfg->doppler_resolution, 4);
    memcpy(header + 40, &cfg->peak_val, 4);

    if (fwrite(header, 1, sizeof(header), fp) != sizeof(header)) {
        fprintf(stderr, "Error writing header: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_frame(FILE *fp, const uint8_t *data, size_t len) {
    uint32_t frame_num = (uint32_t)len / FRAME_SIZE;
    uint32_t ts = (uint32_t)time(NULL);

    if (fwrite(&ts, sizeof(ts), 1, fp) != 1) {
        fprintf(stderr, "Error writing timestamp: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&frame_num, sizeof(frame_num), 1, fp) != 1) {
        fprintf(stderr, "Error writing frame number: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(data, 1, len, fp) != len) {
        fprintf(stderr, "Error writing frame data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_config_data(ConfigData *cfg) {
    FILE *fp = fopen(LOG_FILE, "rb");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fread(cfg, sizeof(*cfg), 1, fp) != 1) {
        fprintf(stderr, "Error reading config data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return 0;
}

static int process_data(const uint8_t *data, size_t len, ConfigData *cfg) {
    if (len < (size_t)cfg->data_offset) {
        fprintf(stderr, "Error: Data offset %u exceeds data length %zu\n", cfg->data_offset, len);
        return -1;
    }

    size_t num_frames = len / FRAME_SIZE;
    for (size_t i = 0; i < num_frames; i++) {
        const uint8_t *frame = data + (i * FRAME_SIZE);
        const uint8_t *range_data = frame + 4;
        const uint8_t *doppler_data = range_data + (HEATMAP_WIDTH * HEATMAP_HEIGHT);

        for (int y = 0; y < HEATMAP_HEIGHT; y++) {
            for (int x = 0; x < HEATMAP_WIDTH; x++) {
                HeatmapData hd;
                hd.range_idx = (uint16_t)x;
                hd.doppler_idx = (uint16_t)y;
                hd.peak_val = (int16_t)((uint16_t)range_data[y * HEATMAP_WIDTH + x] << 8 | (uint16_t)doppler_data[y * HEATMAP_WIDTH + x]);
                printf("Range: %d, Doppler: %d, Peak: %d\n", x, y, hd.peak_val);
            }
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting trigger pin mode\n");
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting data ready pin mode\n");
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error writing trigger pin\n");
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    ConfigData cfg;
    if (read_config_data(&cfg) < 0) {
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "ab");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    if (log_header(g_log_file, &cfg) < 0) {
        fclose(g_log_file);
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    while (g_running) {
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error writing trigger pin\n");
            break;
        }

        usleep(1000);

        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error writing trigger pin\n");
            break;
        }

        if (gpioRead(DATA_READY_PIN) == 0) {
            uint8_t tx[FRAME_SIZE];
            uint8_t rx[FRAME_SIZE];
            memset(tx, 0, FRAME_SIZE);
            memset(rx, 0, FRAME_SIZE);

            if (spi_transfer(tx, rx, FRAME_SIZE) < 0) {
                fprintf(stderr, "SPI transfer failed, continuing...\n");
                continue;
            }

            if (log_frame(g_log_file, rx, FRAME_SIZE) < 0) {
                fprintf(stderr, "Error logging frame\n");
            }

            if (process_data(rx, FRAME_SIZE, &cfg) < 0) {
                fprintf(stderr, "Error processing data\n");
            }
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_log_file) fclose(g_log_file);
    if (g_spi_fd >= 0) close(g_spi_fd);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

