/*
 * KY-026 Flame Sensor Monitor — Raspberry Pi Zero W
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND   (Pin 9)
 *   KY-026 OUT  -> GPIO20 (Pin 38, BCM 38)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE          "flame_log.txt"
#define POLL_INTERVAL_US  100000   /* 100 ms */
#define TIMESTAMP_LEN     32

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        perror("gmtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flame_state(int flame_detected)
{
    char timestamp[TIMESTAMP_LEN];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, flame_detected) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the line is defined when the sensor
     * is disconnected (KY-026 OUT is open-collector style). */
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev_flame_detected = -1;   /* unknown initial state */

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        if (flame_detected < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", FLAME_SENSOR_GPIO);
            break;
        }

        if (flame_detected != prev_flame_detected) {
            if (log_flame_state(flame_detected) != 0) {
                fprintf(stderr, "Failed to log flame state\n");
            } else {
                printf("Flame state changed: %s\n",
                       flame_detected ? "DETECTED" : "CLEARED");
            }
            prev_flame_detected = flame_detected;
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup_gpio();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

