#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x00
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MAX_RETRIES     3

/* OPT3001 register addresses */
#define REG_CONFIG     0x01
#define REG_RESULT     0x00

/* Config register bits */
#define CFG_CONTINUOUS  0x80   /* Continuous conversion mode */
#define CFG_AUTOFS      0x40   /* Automatic full-scale range */
#define CFG_1X         0x00   /* 1x gain */
#define CFG_16BIT      0x00   /* 16-bit data */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register.                        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register.                       */
/* Returns 0 on success and stores the value in *out; -1 on failure.  */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the OPT3001 for continuous conversion and 1x gain.       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int opt3001_configure(int handle)
{
    uint16_t config = CFG_CONTINUOUS | CFG_AUTOFS | CFG_1X;

    if (opt3001_write_reg(handle, REG_CONFIG, config) != 0)
        return -1;

    /* Allow the first conversion to complete before first read. */
    gpioDelay(100000);  /* 100 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux from the OPT3001.                                          */
/* Returns 0 on success and stores lux in *lux; -1 on failure.         */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int handle, float *lux)
{
    uint16_t raw;

    if (opt3001_read_reg(handle, REG_RESULT, &raw) != 0)
        return -1;

    /* Clear the 16-bit result register by writing 0x0000. */
    if (opt3001_write_reg(handle, REG_RESULT, 0x0000) != 0)
        return -1;

    /* lux = raw / 100.0 (1x gain, 16-bit). */
    *lux = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                  */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_lux(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — releases all resources.                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x00 (OPT3001 default) */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("OPT3001 logger started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            consecutive_errors = 0;
            if (log_lux(lux) != 0) {
                fprintf(stderr, "[WARN] Logging failed, continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Read failed (attempt %d/%d).\n",
                    consecutive_errors, MAX_RETRIES);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] Max consecutive I2C errors reached, "
                                "attempting sensor reconfiguration.\n");
                if (opt3001_configure(g_i2c_handle) != 0) {
                    fprintf(stderr, "[FATAL] Reconfiguration failed, "
                            "continuing without sensor.\n");
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

