/*
 * flame_detect.c — SainSmart IR Flame Detection Sensor Module reader
 * Target:  Raspberry Pi 3 Model B+
 * Library: libgpiod v2 API (modern GPIO character-device interface)
 *
 * Wiring (BCM numbering):
 *   Sensor DOUT  -> GPIO17 (physical pin 11)
 *   Sensor VCC   -> 3.3 V (physical pin 1)
 *   Sensor GND   -> GND   (physical pin 9)
 *   Sensor OUT   -> GND   (active-low)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 *
 * Run:
 *   ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_S  1           /* seconds between log entries */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

static void log_flame_status(int sensor_value)
{
    char ts[32];

    get_timestamp(ts, sizeof(ts));
    printf("%s Flame Detected: %s\n", ts,
           (sensor_value == 0) ? "YES" : "NO");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure line settings: input, active-low ---- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed\n");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* ---- Configure line config ---- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new() failed\n");
        goto cleanup;
    }

    unsigned int offset = GPIO_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request config ---- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new() failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-sensor");

    /* ---- Request the line ---- */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpiod_line_request_get_value(req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value() failed: %s\n",
                    strerror(errno));
            /* Brief pause before retrying to avoid log spam on persistent errors */
            sleep(1);
            continue;
        }

        log_flame_status(value);

        /* Sleep for the poll interval, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req) {
        gpiod_line_request_release(req);
    }
    if (req_cfg) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings) {
        gpiod_line_settings_free(settings);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

