#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[timestamp error]\n");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[timestamp error]\n");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[timestamp error]\n");
        return;
    }
    printf("[%s] ", buf);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-Channel Touch Sensor Reader\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(gpio_pins[i]);
            if (v < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d (channel %d).\n",
                        gpio_pins[i], i + 1);
                read_ok = 0;
                break;
            }
            values[i] = v;
        }

        if (read_ok) {
            print_timestamp();
            for (int i = 0; i < NUM_CHANNELS; i++) {
                printf("CH%d: %d", i + 1, values[i]);
            }
            printf("\n");
            fflush(stdout);
        }

        /* Sleep for 100 ms using pigpio's microsecond delay */
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

