/*
 * TTP226 8-channel digital touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   TTP226 OUT1 -> GPIO2  (pin 3)
 *   TTP226 OUT2 -> GPIO3  (pin 4)
 *   TTP226 OUT3 -> GPIO4  (pin 5)
 *   TTP226 OUT4 -> GPIO5  (pin 6)
 *   TTP226 OUT5 -> GPIO6  (pin 7)
 *   TTP226 OUT6 -> GPIO7  (pin 8)
 *   TTP226 OUT7 -> GPIO8  (pin 9)
 *   TTP226 OUT8 -> GPIO9  (pin 10)
 *   TTP226 VCC  -> 3.3 V (pin 1)
 *   TTP226 GND  -> GND   (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/*
 * Read the 8-channel state from the TTP226.
 * Returns 0 on success, -1 on failure.
 */
static int read_ttp226(uint8_t *state)
{
    int rc = ttp226_read(state);
    if (rc != 0) {
        fprintf(stderr, "ttp226_read failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure the 8 sensor output pins as inputs with pull-down resistors. */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(i, PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%d) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(i, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Allow the pull-down resistors to settle. */
    gpioDelay(10000); /* 10 ms */

    uint8_t state = 0;
    struct timespec ts_start, ts_end;
    char time_buf[32];

    while (g_running) {
        if (read_ttp226(&state) != 0) {
            fprintf(stderr, "Error reading TTP226 sensor data.\n");
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) != 0) {
            perror("clock_gettime");
            break;
        }

        if (read_ttp226(&state) != 0) {
            fprintf(stderr, "Error reading TTP226 sensor data.\n");
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) != 0) {
            perror("clock_gettime");
            break;
        }

        double elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000.0 +
                            (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000.0;

        if (elapsed_ms > 0.0) {
            struct tm tm_info;
            localtime_r(&ts_start.tv_sec, &tm_info);
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s.%03ld] ", time_buf, elapsed_ms);
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("CH%d=%d ", i + 1, state & (1u << i));
        }
        printf("\n");
        fflush(stdout);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

