/*
 * hall_effect.c — Read two TMAG5110 Hall-Effect Latch sensors on a Raspberry Pi 3 B+
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT  -> BCM GPIO4  (external pull-up recommended)
 *   Sensor 2 OUT  -> BCM GPIO5  (external pull-up recommended)
 *   VCC           -> 3.3 V
 *   GND           -> GND
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe_driver_library -lrt
 *
 * Run:
 *   ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */
typedef struct {
    int  pin;
    bool active;          /* HIGH = magnet detected, LOW = open-drain idle */
} sensor_t;

static void sensor_log(const sensor_t *s)
{
    printf("%s: %s\n", s->pin, s->active ? "HIGH (magnet)" : "LOW (idle)");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* --- Initialize pigpio ------------------------------------------ */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs ----------------------------- */
    rc = gpioSetMode(SENSOR1_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(SENSOR1_PIN) failed (code %d).\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetMode(SENSOR2_PIN, PI_INPUT);
    if (rc != 0) {
