/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   CH1 -> GPIO2 (pin 3)
 *   CH2 -> GPIO3 (pin 5)
 *   CH3 -> GPIO4 (pin 7)
 *   CH4 -> GPIO17 (pin 11)
 *   CH5 -> GPIO27 (pin 13)
 *   CH6 -> GPIO22 (pin 15)
 *   CH7 -> GPIO10 (pin 19)
 *   CH8 -> GPIO9  (pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lpigpio -lrt
 * Run:    sudo ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000   /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static int write_csv_line(const char *timestamp, const int states[NUM_CHANNELS])
{
    char line[256];
    int n = snprintf(line, sizeof(line), "%s,%d,%d,%d,%d,%d,%d,%d\n",
                     timestamp,
                     states[0], states[1], states[2], states[3],
                     states[4], states[5], states[6], states[7]);
    if (n < 0 || (size_t)n >= sizeof(line)) {
        fprintf(stderr, "CSV line formatting failed\n");
        return -1;
    }
    if (fprintf(stdout, "%s", line) < 0) {
        fprintf(stderr, "fprintf to stdout failed\n");
        return -1;
    }
    if (fflush(stdout) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor lines as inputs with bias disabled ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = sensor_pins[i];

        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* TTP226 outputs are open-collector; bias=0 keeps the line low. */
        if (gpioSetPullUpDown(pin, PI_PUD_OFF) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_OFF) failed\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Main polling loop ----------------------------------------- */
    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        int states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(sensor_pins[i]);
            if (v < 0) {
                fprintf(stderr, "gpioRead(%d) failed\n", sensor_pins[i]);
                states[i] = -1;
            } else {
                states[i] = v;
            }
        }

        if (write_csv_line(ts, states) != 0) {
            fprintf(stderr, "CSV write failed; continuing\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ----------------------------------------- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

