#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x51
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "uv_als_log.csv"

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX 0x2D
#define SI1145_REG_COMMAND 0x30

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID from Si1145.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Si1145 not detected (PART_ID=0x%02X, expected 0x%02X).\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY to Si1145.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to start measurement on Si1145.\n");
        return -1;
    }
    usleep(10000);

    return 0;
}

static int read_uv_index(int fd, uint8_t *uv_index) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x0F) < 0) {
        return -1;
    }
    usleep(10000);

    uint8_t vis_data0 = 0, vis_data1 = 0;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &vis_data0) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &vis_data1) < 0) {
        return -1;
    }

    uint16_t als_visible = (vis_data1 << 8) | vis_data0;
    uint16_t uv_raw = als_visible >> 2;
    *uv_index = (uv_raw * 2) / 3;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, 0x0F) < 0) {
        return -1;
    }
    usleep(10000);

    uint8_t vis_data0 = 0, vis_data1 = 0;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &vis_data0) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &vis_data1) < 0) {
        return -1;
    }

