#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x30
#define SENSOR2_ADDR   0x31
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define READ_INTERVAL  1
#define MEAS_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion 8-bit CRC-8 (polynomial 0x31, init 0x00) */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t addr, uint8_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(addr << 1), cmd };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C ioctl (slave 0x%02X) failed: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from 0x%02X failed: got %zd of %zu bytes: %s\n",
                addr, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out)
{
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x80, buf, sizeof(buf)) < 0)
        return -1;

    /* Bytes 0-1: scale factor (2) + CRC */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on scale factor (0x%02X, 0x%02X)\n",
                buf[0], buf[2]);
        return -1;
    }
    /* Bytes 3-4: flow rate (2) + CRC */
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on flow rate (0x%02X, 0x%02X)\n",
                buf[3], buf[5]);
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[3] << 8) | buf[4]);
    *flow_out = (float)raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float f1, float f2, float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Avg: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2, avg);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_cmd(g_i2c_fd, SENSOR1_ADDR, 0x3605) < 0 ||
        i2c_write_cmd(g_i2c_fd, SENSOR2_ADDR, 0x3605) < 0) {
        fprintf(stderr, "Failed to start sensors\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioDelay(MEAS_DELAY_MS * 1000);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int v1 = -1, v2 = -1;
        int ok = 0;

        v1 = read_flow_rate(g_i2c_fd, &f1);
        if (v1 == 0) ok = 1;
        v2 = read_flow_rate(g_i2c_fd, &f2);
        if (v2 == 0) ok = 1;

        if (ok) {
            float avg = (f1 + f2) / 2.0f;
            log_data(g_log_fp, f1, f2, avg);
            if (avg < FLOW_THRESHOLD) {
                gpioWrite(ALARM_GPIO, 1);
            } else {
                gpioWrite(ALARM_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
        }

        gpioDelay(READ_INTERVAL * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

