#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x1D
#define D7S_REG_X_LSB  0x00
#define D7S_REG_X_MSB  0x01
#define D7S_REG_Y_LSB  0x02
#define D7S_REG_Y_MSB  0x03
#define D7S_REG_Z_LSB  0x04
#define D7S_REG_Z_MSB  0x05
#define D7S_MODE_ACCEL 0x00
#define D7S_MODE_VIB  0x01
#define D7S_MODE_SLEEP 0x02
#define D7S_MODE_RESET 0x03
#define D7S_RESET_CMD  0x80
#define D7S_RESET_DELAY_MS 100
#define SAMPLE_DELAY_MS  500
#define ACTIVATION_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu bytes: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_reset(int fd) {
    if (i2c_write_byte(fd, D7S_REG_X_LSB, D7S_RESET_CMD) < 0) return -1;
    usleep(D7S_RESET_DELAY_MS * 1000);
    return 0;
}

static int d7s_set_mode(int fd, uint8_t mode) {
    if (i2c_write_byte(fd, D7S_REG_X_LSB, mode) < 0) return -1;
    usleep(1000);
    return 0;
}

static int d7s_get_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, D7S_REG_X_LSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int write_csv_header_if_new(FILE *f) {
    long pos = ftell(f);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(f, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
        fflush(f);
    }
    return 0;
}

static void cleanup(void) {
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (d7s_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (d7s_set_mode(g_i2c_fd, D7S_MODE_ACCEL) < 0) {
        fprintf(stderr, "Failed to set D7S to accel mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_csv_header_if_new(g_csv) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("D7S fan monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        struct timespec ts = { 0, ACTIVATION_TIMEOUT_MS * 1000000L };
        nanosleep(&ts, NULL);

        if (!g_running) break;

        if (d7s_set_mode(g_i2c_fd, D7S_MODE_VIB) < 0) {
            fprintf(stderr, "Failed to switch to vibration mode\n");
            continue;
        }

        if (d7s_set_mode(g_i2c_fd, D7S_MODE_ACCEL) < 0) {
            fprintf(stderr, "Failed to switch back to accel mode\n");
            continue;
        }

        int16_t x, y, z;
        if (d7s_get_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read accel data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm tmv;
        char ts_str[32];
        if (localtime_r(&now, &tmv) && strftime(ts_str, sizeof(ts_str), "%Y-%m-%dT%H:%M:%S", &tmv) > 0) {
            fprintf(g_csv, "%s,%d,%d,%d\n", ts_str, x, y, z);
        } else {
            fprintf(g_csv, "timestamp_error,%d,%d,%d\n", x, y, z);
        }
        fflush(g_csv);

        printf("X=%d Y=%d Z=%d\n", x, y, z);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

