        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(100000);
            continue;
        }

        if (is_stalled(s1, s2)) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            } else {
                snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
            }

            if (log_stall(timestamp) != 0) {
                fprintf(stderr, "Failed to log stall event\n");
            } else {
                printf("Stall confirmed at %s\n", timestamp);
            }
        }

        gpioDelay(100000);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

