/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170-SCL  -> GPIO3 (I2C bus 1 SCL)
 *   TMAG5170-SDA  -> GPIO2 (I2C bus 1 SDA)
 *   TMAG5170-VDD  -> 3.3 V
 *   TMAG5170-GND  -> GND
 *
 * Build: gcc -O2 -Wall -o mag_log mag_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- TMAG5170-Q1 register map (datasheet rev 1.0) ---- */
#define TMAG5170_REG_X_MSB  0x00
#define TMAG5170_REG_X_LSB  0x01
#define TMAG5170_REG_Y_MSB  0x02
#define TMAG5170_REG_Y_LSB  0x03
#define TMAG5170_REG_Z_MSB  0x04
#define TMAG5170_REG_Z_LSB  0x05
#define TMAG5170_REG_CONFIG 0x0E
#define TMAG5170_REG_INT_CFG 0x0F
#define TMAG5170_REG_INT_EN  0x10
#define TMAG5170_REG_INT_STATUS 0x11
#define TMAG5170_REG_HW_KEY  0x0B
#define TMAG5170_REG_ID      0x0C

#define TMAG5170_ID_VALUE    0x5170
#define TMAG5170_HW_KEY_VAL  0x17

/* Config: 50 mT range, continuous conversion, all axes enabled */
#define TMAG5170_CONFIG_VAL 0x0000

/* INT_CFG: enable all three axes */
#define TMAG5170_INT_CFG_VAL 0x07

/* INT_EN: enable interrupt on new sample ready */
#define TMAG5170_INT_EN_VAL 0x01

/* INT_STATUS: bit 0 = new sample ready */
#define TMAG5170_INT_STATUS_BIT 0x01

#define I2C_BUS 1
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val >> 8);
    buf[2] = (char)(val & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2] = {0, 0};

    if (i2cWriteDevice(handle, reg_buf, 1) != 0)
        return -1;

    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    uint16_t id = 0;

    /* Verify sensor identity */
    if (i2c_read_reg16(handle, TMAG5170_REG_ID, &id) != 0) {
        fprintf(stderr, "Error: failed to read TMAG5170 ID register (sensor absent or bus error).\n");
        return -1;
    }
    if (id != TMAG5170_ID_VALUE) {
        fprintf(stderr, "Error: unexpected TMAG5170 ID 0x%04X (expected 0x%04X).\n",
                id, TMAG5170_ID_VALUE);
        return -1;
    }
    printf("TMAG5170 detected (ID = 0x%04X).\n", id);

    /* Write HW_KEY to enable the device */
    if (i2c_write_reg16(handle, TMAG5170_REG_HW_KEY, TMAG5170_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Error: failed to write HW_KEY register.\n");
        return -1;
    }

    /* Configure: 50 mT range, continuous conversion, all axes enabled */
    if (i2c_write_reg16(handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_VAL) != 0) {
        fprintf(stderr, "Error: failed to write CONFIG register.\n");
        return -1;
    }

    /* Configure interrupt: enable all three axes */
    if (i2c_write_reg16(handle, TMAG5170_REG_INT_CFG, TMAG5170_INT_CFG_VAL) != 0) {
        fprintf(stderr, "Error: failed to write INT_CFG register.\n");
        return -1;
    }

    /* Enable interrupt on new sample ready */
    if (i2c_write_reg16(handle, TMAG5170_REG_INT_EN, TMAG5170_INT_EN_VAL) != 0) {
        fprintf(stderr, "Error: failed to write INT_EN register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetic field (X, Y, Z)                                       */
/* ------------------------------------------------------------------ */
static int read_magnetic_field(int handle, float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(handle, TMAG5170_REG_X_MSB, &raw_x) != 0) {
        fprintf(stderr, "Error: failed to read X axis data.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, TMAG5170_REG_Y_MSB, &raw_y) != 0) {
        fprintf(stderr, "Error: failed to read Y axis data.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, TMAG5170_REG_Z_MSB, &raw_z) != 0) {
        fprintf(stderr, "Error: failed to read Z axis data.\n");
        return -1;
    }

    /* Datasheet: raw values are in mT; scale by 0.5 mT per LSB */
    *x = (float)raw_x * 0.5f;
    *y = (float)raw_y * 0.5f;
    *z = (float)raw_z * 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Datasheet: call TMAG5170_Q1_cleanup() before closing */
        tmag5170_q1_cleanup(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at 0x5170 (7-bit address) */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ID_VALUE & 0x7F, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Logging magnetic field data to '%s'. Press Ctrl-C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        if (read_magnetic_field(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Error: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: read_magnetic_field failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

