        return -1;
    }
    if (i2c_read_reg16(handle, TMAG5170_REG_Y_MSB, &raw_y) != 0) {
        fprintf(stderr, "Error: failed to read Y axis data.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, TMAG5170_REG_Z_MSB, &raw_z) != 0) {
        fprintf(stderr, "Error: failed to read Z axis data.\n");
        return -1;
    }

    /* Datasheet: raw values are in mT; scale by 0.5 mT per LSB */
    *x = (float)raw_x * 0.5f;
    *y = (float)raw_y * 0.5f;
    *z = (float)raw_z * 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Datasheet: call TMAG5170_Q1_cleanup() before closing */
        tmag5170_q1_cleanup(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at 0x5170 (7-bit address) */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ID_VALUE & 0x7F, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Logging magnetic field data to '%s'. Press Ctrl-C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        if (read_magnetic_field(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Error: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: read_magnetic_field failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

