#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[time-error] %s\n", message);
    }
    fclose(fp);
}

static void log_error(const char *message)
{
    char buf[256];
    snprintf(buf, sizeof(buf), "ERROR: %s", message);
    log_event(buf);
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        log_error("Failed to set GPIO pin mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        log_error("Failed to set pull-down resistor");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void)
{
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Flood detection system started");

    while (g_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            log_error("Failed to read sensor value");
            log_event("Sensor read error, re-initializing GPIO");
            sleep(REINIT_DELAY_SEC);
            if (!g_running) {
                break;
            }
            if (initialize_gpio() != 0) {
                log_error("GPIO re-initialization failed");
            }
            continue;
        }

        if (level == 1) {
            log_event("ALERT: Water detected");
            printf("ALERT: Water detected\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Flood detection system shutting down");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

