#include <pthread.h>
#include <stdatomic.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define PULSE_WINDOW_SEC 1

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static atomic_uint g_pulse_count = 0;
static pthread_mutex_t g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

static double calculate_rpm(int pulses, double interval_sec)
{
    if (interval_sec <= 0.0) {
        return 0.0;
    }
    return ((double)pulses / interval_sec) * 60.0;
}

static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (g_running) {
        struct timespec ts;
        ts.tv_sec = SAMPLE_INTERVAL_SEC;
        ts.tv_nsec = 0;

        if (nanosleep(&ts, NULL) != 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }

        int pulses = atomic_exchange(&g_pulse_count, 0);
        double rpm = calculate_rpm(pulses, (double)SAMPLE_INTERVAL_SEC);

        log_rpm(rpm);
    }

    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_file = NULL;
    }

    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

