/*
 * Quadrature Hall-effect sensor logging for Raspberry Pi Zero W.
 *
 * Sensors : 2 x MLX90217 (unipolar, unidirectional)
 *   Sensor A -> GPIO17 (BCM)
 *   Sensor B -> GPIO27 (BCM)
 *   Pull-up resistors on both sensors to create a 90° electrical offset.
 *
 * Library : MLX90217 driver (no external dependency).
 *
 * Build   : gcc -O2 -Wall -Wextra -o rotation_log rotation_log.c -lm
 * Run     : ./rotation_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <stdbool.h>

/* ----------------------------- Configuration ----------------------------- */

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

#define LOG_FILE_NAME "rotation_log.txt"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_state_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Quadrature state machine: 0 = no sensor, 1 = A, 2 = B, 3 = both */
static volatile int g_quadrature_state = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void log_event(int direction);
static void quadrature_isr(int gpio, int level, uint32_t tick, void *user);
static void *main_thread(void *arg);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_event(int direction)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s.%03ld: Direction: %d\n",
                timestamp, ts.tv_nsec / 1000000L, direction) < 0) {
        perror("fprintf");
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
    }
}

/* ----------------------------- Quadrature ISR ------------------------------ */

/*
 * MLX90217 edge-triggered alert callback.
 * level: 0 = rising, 1 = falling, 2 = timeout
 * tick:  32-bit microsecond counter (wraps every ~71.6 min)
 * user:  NULL (no user data)
 */
static void quadrature_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)user;

    if (gpio != SENSOR_A_PIN && gpio != SENSOR_B_PIN) {
        return;
    }

    if (level == 1) {            /* falling edge = rising output */
        if (gpio == SENSOR_A_PIN) {
            g_quadrature_state = 1;
        } else {
            g_quadrature_state = 2;
        }
    } else if (level == 0) {      /* rising edge = falling output */
        if (gpio == SENSOR_A_PIN) {
            g_quadrature_state = 0;
        } else {
            g_quadrature_state = 3;
        }
    }
    /* level == 2 (timeout) is ignored */
}

/* ----------------------------- Main thread -------------------------------- */

static void *main_thread(void *arg)
{
    (void)arg;

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        return NULL;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    /* Initialize quadrature state machine */
    g_quadrature_state = 0;

    /* Initialize GPIO pins as inputs with pull-up resistors */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_A_PIN) failed\n");
        goto fail;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_B_PIN) failed\n");
        goto fail;
    }
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_A_PIN) failed\n");
        goto fail;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_B_PIN) failed\n");
        goto fail;
    }

    /* Register ISR for both pins (MLX90217 alerts on falling edge) */
    if (gpioSetISRFuncEx(SENSOR_A_PIN, FALLING_EDGE, 0, quadrature_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx(SENSOR_A_PIN) failed\n");
        goto fail;
    }
    if (gpioSetISRFuncEx(SENSOR_B_PIN, FALLING_EDGE, 0, quadrature_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx(SENSOR_B_PIN) failed\n");
        goto fail;
    }

    printf("Monitoring MLX90217 sensors on GPIO%d and GPIO%d.\n",
           SENSOR_A_PIN, SENSOR_B_PIN);
    printf("Logging direction changes to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* Main loop: wait for ISR to update the state machine */
    while (g_running) {
        pthread_mutex_lock(&g_state_mutex);
        int current_state = g_quadrature_state;
        int previous_state = g_quadrature_state;
        pthread_mutex_unlock(&g_state_mutex);

        if (current_state != previous_state) {
            int direction = (current_state == previous_state) ? 0 : 1;
            log_event(direction);
        }

        /* Sleep 10 ms to reduce CPU usage */
        usleep(10000);
    }

    printf("\nShutting down...\n");

fail:
    /* Disable ISR */
    gpioSetISRFuncEx(SENSOR_A_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_PIN, FALLING_EDGE, 0, NULL, NULL);

    /* Close log file */
    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            perror("fclose");
        }
        g_log_file = NULL;
    }

    /* Destroy mutex */
    pthread_mutex_destroy(&g_state_mutex);

    return NULL;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize main thread */
    if (pthread_create(&g_main_thread, NULL, main_thread, NULL) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    /* Wait for main thread to finish */
    pthread_join(g_main_thread, NULL);

    return EXIT_SUCCESS;
}

