#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    if (setup_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting touch LED application (GPIO%d = touch, GPIO%d = LED)");

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line (GPIO%d): %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line (GPIO%d): %s", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_led") < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "touch_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");

    int led_state = 0;
    int prev_touch = 0;

    while (running) {
        int touch = gpiod_line_get_value(touch_line);
        if (touch < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (touch == 1 && prev_touch == 0) {
            led_state = 1;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                syslog(LOG_ERR, "Failed to set LED state: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch detected, LED turned ON");
            }
        } else if (touch == 0 && led_state == 1) {
            led_state = 0;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                syslog(LOG_ERR, "Failed to set LED state: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch released, LED turned OFF");
            }
        }

        prev_touch = touch;
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down application");

    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn off LED during shutdown: %s", strerror(errno));
    }

    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    closelog();
    return EXIT_SUCCESS;
}

