#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 17
#define LED_PIN          18
#define DEBOUNCE_US     50000   /* 50 ms debounce window */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort cleanup; ignore errors during shutdown. */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Register a rising-edge event handler for the touch sensor. */
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, rising_edge_alert, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO%d. LED on GPIO%d.\n",
           TOUCH_SENSOR_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

/*
 * Rising-edge alert callback (runs in a pigpio thread).
 * Debounces by sleeping for DEBOUNCE_US microseconds.
 */
static void rising_edge_alert(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;

    if (level != 1) {
        return; /* Only act on rising edges. */
    }

    /* Debounce: sleep for 50 ms. */
    gpioDelay(DEBOUNCE_US);

    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn LED on.\n");
    } else {
        printf("Touch detected on GPIO%d — LED turned ON.\n", TOUCH_SENSOR_PIN);
    }
}

