    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_log(void) {
    printf("\n--- Log Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&touch_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }
        printf("  [%3d] Sensor %d: %s (state=%d)\n",
               i + 1, touch_buffer[idx].sensor_pin, ts, touch_buffer[idx].state);
    }
    printf("  Overflow: %d events recorded\n", buffer_count);
}

