        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (s1 == 1) {
            gpioWrite(LED_1_PIN, 1);
            log_touch_event(SENSOR_1_PIN, 1);
        } else {
            gpioWrite(LED_1_PIN, 0);
        }

        if (s2 == 1) {
            gpioWrite(LED_2_PIN, 1);
            log_touch_event(SENSOR_2_PIN, 1);
        } else {
            gpioWrite(LED_2_PIN, 0);
        }

        gpioDelay(POLL_MS * 1000);
    }

    print_log();
    cleanup();
    return EXIT_SUCCESS;
}

