#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    int last_state = -1;
    int current_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", RAIN_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d\n", RAIN_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", RAIN_SENSOR_PIN);

    while (program_running) {
        current_state = gpioRead(RAIN_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d\n", RAIN_SENSOR_PIN);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                printf("Rain Detected\n");
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Warning: Failed to log rain event\n");
                }
            } else {
                printf("No Rain\n");
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Warning: Failed to log no rain event\n");
                }
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Error closing log file");
        }
        log_file = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

