        fprintf(fp, "%s,%d,%d\n", timestamp, s1, s2);
    } else {
        fprintf(fp, "timestamp_error,%d,%d\n", s1, s2);
    }
    fclose(fp);
}

static void calculate_rpm(int s1, int s2, int *rpm_out) {
    static int s1_prev = -1;
    static int s2_prev = -1;
    static uint32_t s1_last = 0;
    static uint32_t s2_last = 0;
    uint32_t now = gpioTick();
    uint32_t elapsed;

    if (s1 == s1_prev) {
        elapsed = now - s1_last;
        s1_last = now;
    } else {
        elapsed = now - s1_prev;
        s1_prev = s1;
        s1_last = now;
    }

    if (s2 == s2_prev) {
        elapsed = now - s2_last;
        s2_last = now;
    } else {
        elapsed = now - s2_prev;
        s2_prev = s2;
        s2_last = now;
    }

    if (elapsed > 0) {
        *rpm_out = (int)((60000000.0 / (double)elapsed) * 60.0);
    } else {
        *rpm_out = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    int s1 = read_sensor(SENSOR1_GPIO);
    int s2 = read_sensor(SENSOR2_GPIO);
    if (s1 < 0 || s2 < 0) {
        fprintf(stderr, "Initial sensor read failed\n");
        gpioTerminate();
        return 1;
    }

    printf("Monitoring RPM. Press Ctrl+C to exit.\n");

    while (running) {
        int s1_new = read_sensor(SENSOR1_GPIO);
        int s2_new = read_sensor(SENSOR2_GPIO);

        if (s1_new != s1) {
            s1 = s1_new;
            log_data(s1, s2);
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }

        if (s2_new != s2) {
            s2 = s2_new;
            log_data(s1, s2);
            gpioDelay(DEBOUNCE_DELAY_US);
            continue;
        }

        int rpm;
        calculate_rpm(s1, s2, &rpm);
        printf("RPM: %d\n", rpm);

        gpioDelay(10000);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

