#define READ_INTERVAL_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(0);
}

static int read_si1182_data(int handle, int *heart_rate, int *spo2) {
    char buf[256];
    int result;

    /* Read Heart Rate */
    result = i2cReadI2CBlockData(handle, 0x00, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading heart rate data: %d\n", result);
        return -1;
    }
    *heart_rate = (buf[0] << 8) | buf[1];

    /* Read SpO2 */
    result = i2cReadI2CBlockData(handle, 0x02, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", result);
        return -1;
    }
    *spo2 = (buf[0] << 8) | buf[1];

    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    int heart_rate, spo2;
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        result = read_si1182_data(i2c_handle, &heart_rate, &spo2);
        if (result == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        sleep(READ_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

