#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL_US 100000
#define ALARM_THRESHOLD_S 2

#define TILT_START  1
#define TILT_END    0
#define THRESHOLD   1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(FILE *fp, const char *event) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(fp);
}

static void cleanup(void) {
    if (log_file != NULL) {
        log_event(log_file, "Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(log_file, "Program started");

    int alarm_active = 0;
    time_t alarm_start_time = 0;
    int tilt1_state = 0;
    int tilt2_state = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        if (s1 == THRESHOLD) {
            if (tilt1_state == 0) {
                log_event(log_file, "Tilt start");
                tilt1_state = 1;
            }
        } else {
            tilt1_state = 0;
        }

        if (s2 == THRESHOLD) {
            if (tilt2_state == 0) {
                log_event(log_file, "Tilt start");
                tilt2_state = 1;
            }
        } else {
            tilt2_state = 0;
        }

        if (tilt1_state && tilt2_state) {
            if (!alarm_active) {
                if (gpioWrite(ALARM_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to activate alarm\n");
                    break;
                }
                alarm_active = 1;
                alarm_start_time = time(NULL);
                log_event(log_file, "Alarm activated");
            }
        } else {
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                    break;
                }
                alarm_active = 0;
                log_event(log_file, "Alarm deactivated");
            }
        }

        if (alarm_active) {
            time_t now = time(NULL);
            if (difftime(now, alarm_start_time) >= ALARM_THRESHOLD_S) {
                log_event(log_file, "Threshold exceeded");
                break;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

