#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        fprintf(stderr, "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor input pins */
    int sensor_pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (size_t i = 0; i < sizeof(sensor_pins) / sizeof(sensor_pins[0]); ++i) {
        ret = gpioSetMode(sensor_pins[i], PI_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input (code %d).\n",
                    sensor_pins[i], ret);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED output pin */
    ret = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (code %d).\n",
                LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    ret = gpioWrite(LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO %d (code %d).\n",
                LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection system started.\n");
    printf("  Sensors: GPIO%d, GPIO%d, GPIO%d, GPIO%d\n", SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN);
    printf("  LED:    GPIO%d\n", LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int object_detected = 0;

        for (size_t i = 0; i < sizeof(sensor_pins) / sizeof(sensor_pins[0]); ++i) {
            int level = gpioRead(sensor_pins[i]);
            if (level < 0) {
                fprintf(stderr, "Warning: failed to read GPIO %d (code %d).\n",
                        sensor_pins[i], level);
                continue;
            }
            /* KY-032 is active-low: logic 0 means object detected */
            if (level == 0) {
                object_detected = 1;
            }
        }

        /* Drive LED based on any sensor detection */
        ret = gpioWrite(LED_PIN, object_detected ? 1 : 0);
        if (ret != 0) {
            fprintf(stderr, "Warning: failed to write LED GPIO %d (code %d).\n",
                    LED_PIN, ret);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

