/*
 * flame_monitor.c — Raspberry Pi 3 Model B+ flame sensor monitor
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * On a HIGH -> LOW transition, a 50 ms debounce re-read is performed.
 * A confirmed flame event is appended to /var/log/flame_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_MS          1000
#define CHIP_NAME        "gpiochip0"
#define CONSUMER         "flame_monitor"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char    sensor_ids[NUM_SENSORS]       = {'A', 'B', 'C', 'D', 'E'};

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip       = NULL;
static struct gpiod_line  *g_lines[NUM_SENSORS];
static int                 g_line_req[NUM_SENSORS];

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int flame_detected)
{
    time_t     rawtime;
    struct tm  tm_utc;
    char       ts[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Cannot open %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (fprintf(fp, "%s - Sensor %c (GPIO %u) - %s\n",
                ts, sensor_ids[sensor_id],
                sensor_pins[sensor_id],
                flame_detected ? "Flame Detected" : "Flame NOT Detected") < 0) {
        syslog(LOG_ERR, "fprintf to %s failed: %s", LOG_FILE, strerror(errno));
    } else {
        fflush(fp);
    }

    if (fclose(fp) != 0)
        syslog(LOG_ERR, "fclose(%s) failed: %s", LOG_FILE, strerror(errno));
}

static void log_shutdown(void)
{
    syslog(LOG_INFO, "Shutting down — releasing resources.");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup_resources(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_line_req[i] != 0) {
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }
    if (g_chip != NULL) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0)
        goto fail_log;

    g_chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (g_chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               CHIP_NAME, strerror(errno));
        goto fail_log;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, sensor_pins[i]);
        if (g_lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto fail_chip;
        }
        g_line_req[i] = 0;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(g_lines[i], CONSUMER) != 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto fail_chip;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started on %d pins.",
           NUM_SENSORS);

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(g_lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1 && g_line_req[i] == 0) {
                /* HIGH -> LOW transition — potential flame */
                g_line_req[i] = 1;

                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);

                val = gpiod_line_get_value(g_lines[i]);
                if (val < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (val == 0) {
                    log_event(i, 1);
                }
            } else if (val == 0 && g_line_req[i] == 1) {
                /* LOW -> HIGH transition — no flame */
                g_line_req[i] = 0;
            }
        }
        usleep(POLL_MS * 1000);
    }

    cleanup_resources();
    return 0;

fail_chip:
    syslog(LOG_ERR, "gpiod_chip_close failed: %s", strerror(errno));
fail_log:
    syslog(LOG_ERR, "closelog failed: %s", strerror(errno));
    cleanup_resources();
    return 1;
}

