    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each touch line as an input line */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all lines as inputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Read initial states */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_states[i] = gpiod_line_get_value(lines[i]);
        if (prev_states[i] < 0) {
            fprintf(stderr, "Failed to read initial state of GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Timestamp, Channel, BCM Pin, State\n");

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }

            /* Log only on state change */
            if (val != prev_states[i]) {
                print_timestamp();
                printf("%d, %u, %u, %s\n",
                       i, touch_pins[i],
                       val,
                       (val == 1) ? "Touched" : "Released");
                fflush(stdout);
                prev_states[i] = val;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

