/*
 * OPT3001 ambient light logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3001_logger opt3001_logger.c -lpigpio -lrt
 * Run:    sudo ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define CONFIG_DELAY   0.1   /* seconds (OPT3001 conversion time) */

/* OPT3001 register addresses */
#define REG_CONFIG     0x00
#define REG_RESULT     0x01

/* Config word: 0x0000 = 16-bit resolution, 100 ms conversion, 1 sample */
#define CONFIG_VALUE   0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register (big-endian on the     */
/* wire, but the sensor expects little-endian).                       */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);   /* little-endian on the wire */
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register (big-endian on the    */
/* wire, but the sensor returns little-endian).                        */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2] = { 0, 0 };

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Small delay so the sensor has time to prepare the response */
    gpioDelay(1000);  /* microseconds */

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Swap bytes: OPT3001 sends little-endian, pigpio receives little-endian */
    *out = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the OPT3001 for a single 16-bit resolution sample.        */
/* ------------------------------------------------------------------ */
static int opt3001_configure(int handle)
{
    if (opt3001_write_reg(handle, REG_CONFIG, CONFIG_VALUE) != 0)
        return -1;

    /* Wait for the conversion to complete (100 ms) */
    gpioDelay((uint32_t)(CONFIG_DELAY * 1000000));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit sample from the OPT3001.                        */
/* ------------------------------------------------------------------ */
static int opt3001_read_sample(int handle, uint16_t *lux_out)
{
    uint16_t raw = 0;

    if (opt3001_read_reg(handle, REG_RESULT, &raw) != 0)
        return -1;

    *lux_out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Format a timestamped lux reading into a human-readable string.     */
/* ------------------------------------------------------------------ */
static void format_timestamped_lux(uint16_t lux, char *buf, size_t buflen)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, buflen, "1970-01-01 00:00:00, %u", lux);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, buflen, "1970-01-01 00:00:00, %u", lux);
        return;
    }

    strftime(buf, buflen, "%Y-%m-%d %H:%M:%S, %u", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                   */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, uint16_t lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %u\n", timestamp, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[WARN] fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("OPT3001 logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t lux = 0;

        if (opt3001_read_sample(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "[ERROR] Failed to read OPT3001 sample; "
                            "continuing.\n");
        } else {
            char timestamp[32];
            format_timestamped_lux(lux, timestamp, sizeof(timestamp));

            printf("%s, %u lux\n", timestamp, lux);

            if (log_data(timestamp, lux) != 0) {
                fprintf(stderr, "[ERROR] Failed to log data.\n");
            }
        }

        /* Sleep for the remainder of the sample period */
        double elapsed = 0.0;
        while (g_running && elapsed < SAMPLE_PERIOD) {
            gpioDelay(1000000);  /* 1 s */
            elapsed += 1.0;
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

