#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int format_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_touch_event(const char *timestamp, const char *event) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int last_state = 0;
    int current_state;
    char timestamp[32];
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (format_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_touch_event(timestamp, current_state == 1 ? "Touch Detected" : "Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch event\n");
                }
            } else {
                fprintf(stderr, "Error formatting timestamp\n");
            }
            last_state = current_state;
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Touch sensor logging stopped.\n");
    return EXIT_SUCCESS;
}

