#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x35
#define LOG_FILE "cooling_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 2000
#define FLOW_MIN 0.0f
#define FLOW_MAX 100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t cmd = 0x36; /* Start continuous measurement */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    uint8_t buf[3];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error reading from I2C: got %d bytes, expected 3\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_data(float flow_rate, int flags, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_file == NULL) {
