    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: sensor read failed, exiting\n");
            break;
        }

        if (log_data(fp, left, middle, right) != 0) {
            fprintf(stderr, "Error: logging failed, exiting\n");
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

