/*
 * touch_lamp.c — Raspberry Pi 5 touch-activated lamp simulator
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lgpiod
 * Run:    sudo ./touch_lamp   (or ensure user is in the 'gpio' group)
 *
 * Wiring (BCM numbering):
 *   TTP223 OUT  -> GPIO23 (physical pin 16)
 *   LED anode   -> GPIO24 (physical pin 18) via ~330 Ω resistor
 *   LED cathode -> GND
 *   TTP223 VCC -> 3.3 V, GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_LINE_OFFSET  23
#define LED_LINE_OFFSET    24
#define GPIO_CHIP_NAME     "/dev/gpiochip4"
#define LOG_FILE           "touch_log.txt"
#define POLL_TIMEOUT_MS    1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
