/*
 * Flame detection safety system — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 Flame Sensor (digital output, active-low)
 *   DO  -> GPIO17 (BCM, physical pin 11)
 * Buzzer: Active buzzer on GPIO18 (BCM, physical pin 12)
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run  : sudo ./flame_alert   (or ensure gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18   /* BCM 18, physical pin 12 */
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define BUZZER_SLICE_MS   100
#define LOG_FILE          "alert_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *log, const char *message)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log, "[%s] %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                       */
/* ------------------------------------------------------------------ */
static int buzzer_set(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) != 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open log file ---- */
    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        fclose(log);
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    /* ---- Get lines ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    /* ---- System started ---- */
    if (log_event(log, "System started") != 0) {
        fprintf(stderr, "Failed to log system start\n");
        goto cleanup;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int prev_flame = 0;   /* 0 = LOW (no flame), 1 = HIGH (flame) */
    int first_poll = 1;

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Detect HIGH -> LOW transition: flame just went out */
        if (val == 1 && prev_flame == 0) {
            if (log_event(log, "FLAME DETECTED") != 0) {
                fprintf(stderr, "Failed to log flame detection\n");
            }

            /* Activate buzzer for 2 seconds (100 ms slices) */
            for (int i = 0; i < BUZZER_DURATION_S * 10 && g_running; i++) {
                if (buzzer_set(buzzer_line, 1) != 0) {
                    break;
                }
                usleep(BUZZER_SLICE_MS * 1000);
            }

            /* Ensure buzzer is off */
            if (buzzer_set(buzzer_line, 0) != 0) {
                break;
            }

            /* Wait for flame to re-stabilize (poll every 100 ms) */
            for (int i = 0; i < POLL_INTERVAL_MS * 10 && g_running; i++) {
                usleep(BUZZER_SLICE_MS * 1000);
            }
        }

        prev_flame = val;
        first_poll = 0;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* ---- System stopped ---- */
    if (log_event(log, "System stopped") != 0) {
        fprintf(stderr, "Failed to log system stop\n");
    }

    printf("Flame detection system stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release resources ---- */
    if (buzzer_line != NULL) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log != NULL) {
        fclose(log);
    }

    return ret;
}

