/*
 * TMAG5110A1 Hall-Effect Latch Monitor — Raspberry Pi 4 Model B
 *
 * The TMAG5110A1 is an open-drain latch sensor.  Its OUT pin is driven
 * open-drain: it pulls the line LOW when a south pole is present (magnet
 * present) and HIGH when the magnet is removed (magnet removed).
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 has an internal pull-up on its OUT pin, so the
 * library's internal pull-up is disabled.  The sensor's open-drain
 * output is left floating, and the pin is configured as input with
 * the pull-up enabled so that the line reads HIGH when the magnet is
 * removed and LOW when a south pole is present.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE    "magnet_log.txt"
#define POLL_US     100000          /* 100 ms between polls */
#define INIT_READ   1               /* first read after power-on  */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (tm == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log != NULL) {
        fprintf(g_log, "%s - Sensor %d: %s\n", ts, sensor_id,
                state ? "Magnet Removed" : "Magnet Present");
        fflush(g_log);
    } else {
        fprintf(stderr, "%s - Sensor %d: %s\n", ts, sensor_id,
                state ? "Magnet Removed" : "Magnet Present");
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read helper                                                  */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin, int *out)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %d\n", pin, v);
        return -1;
    }
    *out = v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pins ---- */
    const int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", pins[i]);
            fclose(g_log);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* TMAG5110A1 has an internal pull-up on its OUT pin; disable
         * pigpio's internal pull-up so the sensor's open-drain output
         * is left floating. */
        if (gpioSetPullUpDown(pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_OFF) failed\n",
                    pins[i]);
            fclose(g_log);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* Verify the mode/pull call succeeded. */
        if (gpioGetMode(pins[i]) != PI_INPUT ||
            gpioGetPullUpDown(pins[i]) != PI_PUD_OFF) {
            fprintf(stderr, "GPIO pin %d mode/pull verification failed\n",
                    pins[i]);
            fclose(g_log);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- initial read ---- */
    int prev[3] = {0, 0, 0};
    int first_read = 1;

    while (g_running) {
        int vals[3];
        int err = 0;

        for (int i = 0; i < num_pins; i++) {
            if (read_sensor(pins[i], &vals[i]) != 0) {
                err = 1;
            }
        }

        if (err) {
            /* Transient read error — log and continue. */
            if (first_read) {
                fprintf(stderr, "Initial sensor read failed; aborting.\n");
                break;
            }
            gpioDelay(POLL_US);
            continue;
        }

        if (first_read) {
            prev[0] = vals[0];
            prev[1] = vals[1];
            prev[2] = vals[2];
            first_read = 0;
        } else {
            /* Log only on state change. */
            for (int i = 0; i < num_pins; i++) {
                if (vals[i] != prev[i]) {
                    log_event(i + 1, vals[i]);
                    prev[i] = vals[i];
                }
            }
        }

        gpioDelay(POLL_US);
    }

    /* ---- clean shutdown ---- */
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

