/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor (BCM 5..12)
 * and drives an 8-bit binary counter on GPIO 17..24.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define NUM_OUTPUTS 8
#define POLL_MS      10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int output_pins[NUM_OUTPUTS]  = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, int channel, int counter)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    else
        fflush(log);
}

static void print_touch_event(int channel, int counter)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *output_lines[NUM_OUTPUTS];
    int sensor_values[NUM_CHANNELS];
    int prev_values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(sensor_lines, 0, sizeof(sensor_lines));
    memset(output_lines, 0, sizeof(output_lines));

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- acquire sensor lines ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- acquire output lines ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (output_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- request sensor lines as inputs ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "touch_counter") < 0) {
            fprintf(stderr, "gpiod_line_request_input(%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- request output lines as outputs, initial value 0 ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (gpiod_line_request_output(output_lines[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    output_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- stabilization delay ---- */
    usleep(STABILIZE_MS * 1000);

    /* ---- read initial sensor values ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_values[i] = gpiod_line_get_value(sensor_lines[i]);
        if (sensor_values[i] < 0) {
            fprintf(stderr, "gpiod_line_get_value(%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_values[i] = sensor_values[i];
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u) failed: %s\n",
                        sensor_pins[i], strerror(errno));
                continue; /* skip this channel this iteration */
            }

            if (val == 1 && prev_values[i] == 0) {
                int counter = (prev_values[i] == 0) ? 0 : 1;
                for (int j = 0; j < NUM_OUTPUTS; j++) {
                    if (gpiod_line_set_value(output_lines[j], counter & 1) < 0) {
                        fprintf(stderr, "gpiod_line_set_value(%u) failed: %s\n",
                                output_pins[j], strerror(errno));
                    }
                }
                print_touch_event(i + 1, counter);
                log_event(FILE *log = fopen("touch_log.txt", "a"),
                          i + 1, counter);
                counter = (counter + 1) % 256;
            }
            prev_values[i] = val;
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- reset all output pins to 0 ---- */
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output_lines[i] != NULL)
            (void)gpiod_line_set_value(output_lines[i], 0);
    }

    /* ---- release lines ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
    }
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output_lines[i] != NULL)
            gpiod_line_release(output_lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Touch sensor monitoring stopped.\n");

    return ret;
}

