code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_header_if_new(void) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        /* File does not exist yet; create it and write header. */
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("fopen(log_file, 'w')");
            return -1;
        }
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fclose(fp);
    } else {
        /* File exists; check if it is empty (no header yet). */
        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        fclose(fp);
        if (size == 0) {
            fp = fopen(LOG_FILE, "w");
            if (fp == NULL) {
                perror("fopen(log_file, 'w')");
                return -1;
            }
            fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
            fclose(fp);
        }
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, value);
        return -1;
    }
    return value;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    const int num_sensors = sizeof(pins) / sizeof(pins[0]);
    int sensor_values[num_sensors];
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            goto cleanup_gpio;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Warning: gpioSetPullUpDown failed for pin %d\n", pins[i]);
        }
    }

    if (write_header_if_new() != 0) {
        goto cleanup_gpio;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup_gpio;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup_gpio;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(log_file, 'a')");
        goto cleanup_gpio;
    }

    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            sensor_values[i] = read_sensor(pins[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: failed to read sensor %d\n", i + 1);
                goto cleanup_all;
            }
        }

        if (log_data(log_fp, sensor_values[0], sensor_values[1],
                     sensor_values[2], sensor_values[3]) != 0) {
