        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        fclose(fp);
        if (size == 0) {
            fp = fopen(LOG_FILE, "w");
            if (fp == NULL) {
                perror("fopen(log_file, 'w')");
                return -1;
            }
            fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
            fclose(fp);
        }
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
