static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a TCRT5000 module as an active-low digital output.
 * Returns 0 (obstacle) or 1 (clear) on success, -1 on error.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return v;
}

static void log_data(FILE *f, int s1, int s2, int led)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(f, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(f) != 0) {
        fprintf(stderr, "fflush failed on log\n");
    }
