{
    int rc;

    /* --- pigpio init -------------------------------------------------- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "gpioInitialise failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ------------------------------------------ */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for SENSOR1_PIN %d\n", SENSOR1_PIN);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for SENSOR2_PIN %d\n", SENSOR2_PIN);
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for LED_PIN %d\n", LED_PIN);
        goto cleanup;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite failed for LED_PIN %d\n", LED_PIN);
        goto cleanup;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

