    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            gpioDelay(POLL_US);
            continue;
        }

        /* TCRT5000: 0 = obstacle detected, 1 = clear */
        int led = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, led) != 0) {
            fprintf(stderr, "gpioWrite failed for LED_PIN %d\n", LED_PIN);
        }

        log_data(g_log, s1, s2, led);

        gpioDelay(POLL_US);
    }

    printf("\nShutting down gracefully...\n");

cleanup:
    /* --- Graceful shutdown ------------------------------------------ */
    gpioWrite(LED_PIN, 0);
    if (g_log != NULL) {
        if (fclose(g_log) != 0) {
            perror("fclose log");
        }
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

