/*
 * Raspberry Pi 4 Model B - 3-Way Tracing Sensor Reader
 *
 * Reads left, center, and right IR reflectance states from a SunFounder
 * 3-Way Tracing Sensor via the GPIO bus.
 *
 * Wiring (BCM numbering):
 *   Left sensor  -> GPIO17 (physical pin 11)
 *   Center sensor -> GPIO27 (physical pin 13)
 *   Right sensor  -> GPIO22 (physical pin 15)
 *
 * The sensor outputs are active-low: a '1' indicates no IR detected,
 * a '0' indicates IR detected.
 *
 * Build:  gcc -Wall -Wextra -O2 -o tracing_sensor tracing_sensor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single GPIO pin and return the raw digital value.           */
/* Returns 0 or 1 on success, -1 on read error.                       */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n",
                pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as an input with internal pull-up.            */
/* Returns 0 on success, -1 on failure.                              */
/* ------------------------------------------------------------------ */
static int configure_input_with_pullup(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }

    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log the three sensor states to the console.                         */
/* ------------------------------------------------------------------ */
static void log_sensor_states(int left, int center, int right)
{
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper: release any GPIO resources.                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Release the GPIO pins so they are no longer in use. */
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_OFF);

    /* Deselect the pins. */
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure each sensor pin as an input with internal pull-up. */
    if (configure_input_with_pullup(LEFT_SENSOR_PIN) != 0) {
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (configure_input_with_pullup(CENTER_SENSOR_PIN) != 0) {
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (configure_input_with_pullup(RIGHT_SENSOR_PIN) != 0) {
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("3-Way Tracing Sensor Reader started.\n");
    printf("Left: GPIO%d, Center: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop. */
    while (g_running) {
        int left  = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: failed to read one or more sensor pins.\n");
            break;
        }

        log_sensor_states(left, center, right);

        /* Sleep for 100 ms. */
        usleep(POLL_INTERVAL_US);
    }

    /* Clean up and terminate pigpio. */
    cleanup();
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

