#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x80

#define SI1175_REG_PART_ID      0x00
#define SI1175_REG_HW_KEY       0x07
#define SI1175_REG_ALS_VIS_LSB  0x22
#define SI1175_REG_ALS_VIS_MSB  0x23

#define SI1175_PART_ID_EXPECTED  0x45

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, uint8_t reg_msb, uint16_t *value)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0) return -1;
    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int init_si1175(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1175_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1175_PART_ID_EXPECTED);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1175_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Failed to write HW_KEY.\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    if (init_si1175(fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        goto cleanup;
    }

    printf("Si1175 ALS sensor initialized. Reading every 100 ms (Ctrl+C to stop).\n");

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, SI1175_REG_ALS_VIS_LSB,
                           SI1175_REG_ALS_VIS_MSB, &raw) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            printf("Raw ALS value: %u\n", raw);
        }
        usleep(100000);
    }

    printf("\nExiting gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

