/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5
 *   TP2 -> GPIO6
 *   TP3 -> GPIO13
 *   TP4 -> GPIO19
 *   TP5 -> GPIO26
 *   TP6 -> GPIO12
 *   TP7 -> GPIO16
 *   TP8 -> GPIO20
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry if interrupted by signal */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_idx = 0;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        struct timespec ts_start, ts_end;
        long elapsed_ms;

        if (clock_gettime(CLOCK_MONOTONIC, &ts_start) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }
            if (val != 0) {
                printf("[%ld.s] CH%d=%d", ts_start.tv_sec, i, val);
                break;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts_end) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        elapsed_ms = (ts_end.tv_sec - ts_start.tv_sec) * 1000L +
                     (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000L;

        if (elapsed_ms < POLL_INTERVAL_MS) {
            sleep_ms(POLL_INTERVAL_MS - elapsed_ms);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

