#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_TIME  5
#define HUE_STEP   360

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void fade_led(int red, int green, int blue)
{
    if (red < 0) red = 0;
    if (red > 255) red = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0) blue = 0;
    if (blue > 255) blue = 255;

    for (int i = 0; i < FADE_STEPS; i++) {
        int r = red + (i * red / FADE_STEPS);
        int g = green + (i * green / FADE_STEPS);
        int b = blue + (i * blue / FADE_STEPS);
        if (gpioPWM(RED_PIN,   r) != 0) syslog(LOG_ERR, "gpioPWM(RED_PIN) failed");
        if (gpioPWM(GREEN_PIN, g) != 0) syslog(LOG_ERR, "gpioPWM(GREEN_PIN) failed");
        if (gpioPWM(BLUE_PIN,  b) != 0) syslog(LOG_ERR, "gpioPWM(BLUE_PIN) failed");
        gpioDelay(1000000 / FADE_STEPS);
    }
}

static void set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red) != 0) syslog(LOG_ERR, "gpioPWM(RED_PIN) failed");
    if (gpioPWM(GREEN_PIN, green) != 0) syslog(LOG_ERR, "gpioPWM(GREEN_PIN) failed");
    if (gpioPWM(BLUE_PIN,  blue) != 0) syslog(LOG_ERR, "gpioPWM(BLUE_PIN) failed");
}

static void cleanup(void)
{
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != PWM_FREQ) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    int red   = rand() % 256;
    int green = rand() % 256;
    int blue  = rand() % 256;

    syslog(LOG_INFO, "Starting RGB fade loop (R=%d G=%d B=%d)", red, green, blue);

    while (g_running) {
        fade_led(red, green, blue);

        int new_red   = rand() % 256;
        int new_green = rand() % 256;
        int new_blue  = rand() % 256;

        if (new_red   < 0) new_red   = 0;
        if (new_red   > 255) new_red   = 255;
        if (new_green < 0) new_green = 0;
        if (new_green > 255) new_green = 255;
        if (new_blue  < 0) new_blue  = 0;
        if (new_blue  > 255) new_blue  = 255;

        if (new_red   != red   || new_green != green || new_blue  != blue) {
            red   = new_red;
            green = new_green;
            blue  = new_blue;
        }

        for (int i = 0; i < FADE_STEPS && g_running; i++) {
            int r   = red   + (new_red   - red)   * i / FADE_STEPS;
            int g   = green + (new_green - green) * i / FADE_STEPS;
            int b   = blue  + (new_blue  - blue)  * i / FADE_STEPS;
            if (gpioPWM(RED_PIN,   r) != 0) syslog(LOG_ERR, "gpioPWM(RED_PIN) failed");
            if (gpioPWM(GREEN_PIN, g) != 0) syslog(LOG_ERR, "gpioPWM(GREEN_PIN) failed");
            if (gpioPWM(BLUE_PIN,  b) != 0) syslog(LOG_ERR, "gpioPWM(BLUE_PIN) failed");
            gpioDelay(1000000 / FADE_STEPS);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

