#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE     0x00
#define TCS34725_ATIME      0x01
#define TCS34725_ID         0x12
#define TCS34725_CDATAL    0x14
#define TCS34725_CDATAH    0x15
#define TCS34725_RDATAL    0x16
#define TCS34725_RDATAH    0x17
#define TCS34725_GDATAL    0x18
#define TCS34725_GDATAH    0x19
#define TCS34725_BDATAL    0x1A
#define TCS34725_BDATAH    0x1B

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define LED_GPIO 17
#define RED_THRESHOLD 200

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 2 bytes from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_byte(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Failed to read TCS34725 ID\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) return -1;
    usleep(3000);

    if (i2c_write_byte(fd, TCS34725_ATIME, 0x0F) != 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) return -1;
    usleep(3000);
    return 0;
}

static int tcs34725_read(int fd, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    if (i2c_read_word(fd, TCS34725_RDATAL, red) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATAL, green) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATAL, blue) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_CDATAL, clear) != 0) return -1;
    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
        i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        cleanup(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup(fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Polling every 200ms...\n");

    while (g_running) {
        uint16_t red, green, blue, clear;
        if (tcs34725_read(fd, &red, &green, &blue, &clear) != 0) {
            fprintf(stderr, "Sensor read failed, re-initializing...\n");
            i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
            usleep(3000);
            if (tcs34725_init(fd) != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
            continue;
        }

        printf("R: %5u, G: %5u, B: %5u, C: %5u\n", red, green, blue, clear);

        if (red > RED_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        usleep(200000);
    }

    cleanup(fd);
    return EXIT_SUCCESS;
}

