/*
 * Raspberry Pi 4 Model B — BH1750 ambient light sensor → WS2812B LED strip
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (I2C bus 1 SDA)
 *   BH1750 SCL  → GPIO3  (I2C bus 1 SCL)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   WS2812B DIN → GPIO18 (BCM 18, PCM_CLK)
 *   WS2812B VCC → 5 V (use external 5 V supply; Pi 4 3.3 V is insufficient)
 *   WS2812B GND → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_to_led light_to_led.c -lpigpio -lrt
 *   sudo ./light_to_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

