#define LED_PIN        18            /* BCM 18 — PCM_CLK for WS2812B */
#define NUM_LEDS       10
#define PWM_RANGE      255
#define PWM_DUTY_MAX   255

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

