/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (pin 3, I2C bus 1)
 *   BH1750 SCL  → GPIO3  (pin 5, I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO11 (SPI0 MISO, pin 23)
 *   APA102 CS   → GPIO9  (SPI0 CE0,  pin 21)
 *   APA102 VCC  → 5 V
 *   APA102 GND  → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x5C
#define NUM_LEDS       16
#define SPI_SPEED_HZ   1000000U   /* 1 MHz */
#define CONV_MS        120        /* BH1750 conversion time */
#define SAMPLE_MS     1000        /* sampling interval */

/* APA102 frame: 32-bit start, 32-bit LED, 32-bit end → 4 bytes total */
#define APA102_FRAME_SIZE 4

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit result from the BH1750.
 * Returns 0 on success and stores the raw count in *out;
 * returns -1 on I2C error.
 */
static int bh1750_read(int fd, uint16_t *out)
{
    uint8_t buf[2];

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *bus)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
