#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define LED_GPIO 10
#define LED_SPI_CHANNEL 0
#define LED_SPI_SPEED 1000000
#define NUM_LEDS 1
#define CONVERSION_DELAY_MS 180
#define FADE_DELAY_MS 500
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n",
                address, strerror(errno));
        return -1;
    }

    uint8_t cmd = 0x10; /* Continuous H-Resolution mode */
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to write to I2C device 0x%02X: %s\n",
                address, strerror(errno));
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from I2C device 0x%02X: %s\n",
                address, strerror(errno));
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

static int calculate_average(int *values, int num_values) {
    int sum = 0;
    for (int i = 0; i < num_values; i++) {
        if (values[i] >= 0) {
            sum += values[i];
        }
    }
    return (num_values > 0) ? (sum / num_values) : 0;
}

static int set_led_brightness(int spi_fd, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t data[NUM_LEDS * 4 + 1];
    int idx = 0;
    data[idx++] = 0x00;
    data[idx++] = 0x00;
    data[idx++] = 0x00;
    data[idx++] = 0x00;
    for (int i = 0; i < NUM_LEDS; i++) {
        data[idx++] = (uint8_t)(brightness * 255 / NUM_LEDS);
        data[idx++] = 0x00;
        data[idx++] = 0xFF;
        data[idx++] = 0x00;
    }
    data[idx++] = 0x00;

    if (spiXfer(spi_fd, (uint8_t *)data, (uint8_t *)data + idx, idx) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    int spi_fd = -1;
    int led_brightness = 0;
    int led_brightness_history[NUM_LEDS] = {0};
    int led_brightness_index = 0;
    int led_brightness_direction = 1;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n",
                    I2C_BUS, strerror(errno));
            continue;
        }

        int address = 0x5C + (i * 2);
        if (read_bh1750(i2c_fds[i], address) < 0) {
            fprintf(stderr, "Warning: Sensor at address 0x%02X not responding.\n", address);
            close(i2c_fds[i]);
            i2c_fds[i] = -1;
        }
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &(uint8_t){0}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &(uint8_t){8}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){LED_SPI_SPEED}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int sensor_values[NUM_SENSORS];
        int valid_sensors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] < 0) continue;
            int val = read_bh1750(i2c_fds[i], 0x5C + (i * 2));
            if (val >= 0) {
                sensor_values[valid_sensors++] = val;
            }
        }

        if (valid_sensors == 0) {
            fprintf(stderr, "Warning: No valid sensor readings. Skipping cycle.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        int average = calculate_average(sensor_values, valid_sensors);
        if (average == 0) {
            fprintf(stderr, "Warning: All sensor readings invalid. Skipping cycle.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        led_brightness = average;
        led_brightness_history[led_brightness_index] = led_brightness;
        led_brightness_index = (led_brightness_index + 1) % NUM_LEDS;
        led_brightness_direction = (led_brightness_direction * -1);

        if (set_led_brightness(spi_fd, led_brightness) < 0) {
            fprintf(stderr, "Error: Failed to set LED brightness.\n");
            break;
        }

        usleep(FADE_DELAY_MS * 1000);
    }

cleanup:
    if (spi_fd >= 0) {
        set_led_brightness(spi_fd, 0);
        close(spi_fd);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    gpioTerminate();
    return 0;
}

