            fprintf(stderr, "Warning: Sensor at address 0x%02X not responding.\n", address);
            close(i2c_fds[i]);
            i2c_fds[i] = -1;
        }
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] >= 0) close(i2c_fds[i]);
        }
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &(uint8_t){0}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &(uint8_t){8}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){LED_SPI_SPEED}) < 0) {
        fprintf(stderr, "Error: Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        int sensor_values[NUM_SENSORS];
        int valid_sensors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] < 0) continue;
            int val = read_bh1750(i2c_fds[i], 0x5C + (i * 2));
            if (val >= 0) {
                sensor_values[valid_sensors++] = val;
            }
        }

        if (valid_sensors == 0) {
            fprintf(stderr, "Warning: No valid sensor readings. Skipping cycle.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        int average = calculate_average(sensor_values, valid_sensors);
        if (average == 0) {
            fprintf(stderr, "Warning: All sensor readings invalid. Skipping cycle.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        led_brightness = average;
        led_brightness_history[led_brightness_index] = led_brightness;
        led_brightness_index = (led_brightness_index + 1) % NUM_LEDS;
        led_brightness_direction = (led_brightness_direction * -1);

        if (set_led_brightness(spi_fd, led_brightness) < 0) {
            fprintf(stderr, "Error: Failed to set LED brightness.\n");
            break;
        }

        usleep(FADE_DELAY_MS * 1000);
    }

cleanup:
    if (spi_fd >= 0) {
        set_led_brightness(spi_fd, 0);
        close(spi_fd);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    gpioTerminate();
    return 0;
}

