#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x29
#define GPIO_PIN 18
#define NUM_LEDS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS_CONF 0x01
#define VEML7700_REG_ALS_DATA 0x02

#define VEML7700_CONFIG 0x0000
#define VEML7700_ALS_CONF 0x0000
#define VEML7700_ALS_DATA 0x0000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_pin = GPIO_PIN;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (val >> 8) & 0xFF, val & 0xFF};
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg16(fd, VEML7700_REG_CONFIG, VEML7700_CONFIG) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg16(fd, VEML7700_REG_ALS_CONF, VEML7700_ALS_CONF) < 0) {
        fprintf(stderr, "Error writing ALS config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int fd, uint16_t *lux) {
    uint16_t als_data = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, &als_data) == 0) {
            *lux = als_data;
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int calculate_brightness(uint16_t lux) {
    if (lux == 0) {
        return 0;
    }
    float ratio = (float)lux / 65535.0f;
    if (ratio < 0.01f) {
        return 0;
    }
    float gamma_corrected = powf(ratio, 1.2f);
    return (int)(gamma_corrected * 255.0f);
}

static void ws2812b_send_data(int gpio_pin, uint8_t *data, int num_leds) {
    if (num_leds == 0) {
        return;
    }
    uint32_t period_us = 1000 / (5 * num_leds);
    uint32_t high_us = period_us / 2;
    uint32_t low_us = period_us - high_us;

    for (int i = 0; i < num_leds; i++) {
        uint32_t led_data = (data[i] << 24) | (data[i] << 16) | (data[i] << 8) | data[i];
        if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
            return;
        }
        if (gpioWrite(gpio_pin, 0) < 0) {
            fprintf(stderr, "Failed to write GPIO low: %s\n", strerror(errno));
            return;
        }
        usleep(low_us);
        if (gpioWrite(gpio_pin, 1) < 0) {
            fprintf(stderr, "Failed to write GPIO high: %s\n", strerror(errno));
            return;
        }
        usleep(high_us);
    }
}

static void ws2812b_clear(int gpio_pin, int num_leds) {
    uint8_t *data = malloc(num_leds * 4);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < num_leds; i++) {
        data[i] = 0;
    }
    ws2812b_send_data(gpio_pin, data, num_leds);
    free(data);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700 sensor\n");
        close(i2c_fd);
        return 1;
    }

    gpio_pin = GPIO_PIN;
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", gpio_pin, strerror(errno));
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    ws2812b_clear(gpio_pin, NUM_LEDS);

    while (running) {
        uint16_t lux = 0;
        if (veml7700_read_lux(i2c_fd, &lux) == 0) {
            int brightness = calculate_brightness(lux);
            printf("Lux: %u, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value after %d retries\n", MAX_RETRIES);
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    ws2812b_clear(gpio_pin, NUM_LEDS);
    gpioTerminate();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Program terminated gracefully.\n");
    return 0;
}

