#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define SELF_TEST_BLINK_MS 500
#define SELF_TEST_READ_INTERVAL_MS 100
#define MAIN_LOOP_DELAY_MS 50
#define ERROR_BLINK_MS 100
#define ERROR_BLINK_COUNT 5
#define ERROR_BLINK_ON_MS 100
#define ERROR_BLINK_OFF_MS 100
#define ERROR_SIGNAL_MS 200
#define ERROR_SIGNAL_MS_2 200
#define ERROR_SIGNAL_MS_3 600
#define ERROR_SIGNAL_MS_4 200

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int self_test(void) {
    log_event("Starting self-test");

    for (int i = 0; i < 2 && running; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(SELF_TEST_BLINK_MS * 1000);
        gpioWrite(LED_PIN, 0);
        gpioDelay(SELF_TEST_BLINK_MS * 1000);
    }

    for (int i = 0; i < 5 && running; i++) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("Error: gpioRead failed during self-test");
            return -1;
        }
        if (val == 0) {
            log_event("Flame detected (persistent LOW)");
            return -1;
        }
        gpioDelay(SELF_TEST_READ_INTERVAL_MS * 1000);
    }

    if (!running) return -1;

    if (val == 0) {
        log_event("Flame detected (persistent LOW) - error condition");
        return -1;
    }

    log_event("Self-test complete");
    return 0;
}

static void error_signal(void) {
    log_event("Error signal received - activating buzzer and LED");

    for (int i = 0; i < ERROR_BLINK_COUNT && running; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(ERROR_BLINK_MS * 1000);
        gpioWrite(LED_PIN, 0);
        gpioDelay(ERROR_BLINK_MS * 1000);
    }

    for (int i = 0; i < 3 && running; i++) {
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(ERROR_SIGNAL_MS * 1000);
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(ERROR_SIGNAL_MS * 1000);
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(ERROR_SIGNAL_MS_2 * 1000);
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(ERROR_SIGNAL_MS_3 * 1000);
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(ERROR_SIGNAL_MS_4 * 1000);
        gpioWrite(BUZZER_PIN, 0);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    log_event("Error signal cleared - exiting");
    return;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (self_test() != 0) {
        log_event("Self-test failed - exiting");
        gpioTerminate();
        return 1;
    }

    log_event("Main loop started");

    while (running) {
        int val = gpioRead(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("Error: gpioRead failed in main loop");
            gpioDelay(MAIN_LOOP_DELAY_MS * 1000);
            continue;
        }

        if (val == 0) {
            log_event("Flame detected - activating buzzer and LED");
            gpioWrite(BUZZER_PIN, 1);
            gpioWrite(LED_PIN, 1);
            while (running) {
                int r = gpioRead(FLAME_SENSOR_PIN);
                if (r < 0) {
                    log_event("Error: gpioRead failed in main loop");
                    break;
                }
                if (r == 1) {
                    log_event("Flame cleared - deactivating buzzer and LED");
                    gpioWrite(BUZZER_PIN, 0);
                    gpioWrite(LED_PIN, 0);
                    break;
                }
                gpioDelay(MAIN_LOOP_DELAY_MS * 1000);
            }
        } else {
            gpioDelay(MAIN_LOOP_DELAY_MS * 1000);
        }
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

