#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x5C
#define LED_GPIO 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 1
#define MAX_LUX 1000.0
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(180000);
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) return -1;
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_circular_buffer(float lux, float *buffer, int *index, int size) {
    buffer[*index] = lux;
    *index = (*index + 1) % size;
}

static float calculate_average(const float *buffer, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return (size > 0) ? (sum / size) : 0.0f;
}

static void set_led_frequency(float lux) {
    float freq = MIN_FREQ + (lux / MAX_LUX) * (MAX_FREQ - MIN_FREQ);
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;
    int half_period_us = (int)(500000.0f / freq);
    if (half_period_us < 1) half_period_us = 1;
    int on_us = half_period_us / 2;
    int off_us = half_period_us / 2;
    if (on_us > 0) {
        if (gpioWrite(LED_GPIO, 1) < 0) {
            fprintf(stderr, "Failed to set LED GPIO high\n");
            return;
        }
        usleep(on_us);
        if (gpioWrite(LED_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to set LED GPIO low\n");
            return;
        }
        usleep(off_us);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    float average_lux = 0.0f;
    int led_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, skipping sample\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        update_circular_buffer(lux, lux_buffer, &buffer_index, BUFFER_SIZE);
        average_lux = calculate_average(lux_buffer, BUFFER_SIZE);

        set_led_frequency(lux);

        if (lux > MAX_LUX) {
            led_state = !led_state;
            if (gpioWrite(LED_GPIO, led_state) < 0) {
                fprintf(stderr, "Failed to toggle LED GPIO\n");
            }
        }

        printf("Lux: %.2f, Average: %.2f, LED: %s\n", lux, average_lux, led_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

