#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEG_A 1
#define SEG_B 2
#define SEG_C 3
#define SEG_D 4
#define SEG_E 5
#define SEG_F 6
#define SEG_G 7
#define SEG_DP 8

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

void display_digit(int digit) {
    unsigned char pattern[8];
    switch (digit) {
        case 5: pattern[0] = (1 << SEG_A) | (1 << SEG_B) | (1 << SEG_C) | (1 << SEG_D) | (1 << SEG_E) | (1 << SEG_F) | (1 << SEG_G); break;
        default: pattern[0] = 0; break;
    }

    for (int i = 0; i < 8; i++) {
        if (gpioWrite(CLOCK_PIN, 1) != 0) { fprintf(stderr, "Error: gpioWrite(CLOCK_PIN,1) failed\n"); return; }
        if (gpioWrite(DATA_PIN, pattern[i] & 0x01) != 0) { fprintf(stderr, "Error: gpioWrite(DATA_PIN,1) failed\n"); return; }
        if (gpioWrite(CLOCK_PIN, 0) != 0) { fprintf(stderr, "Error: gpioWrite(CLOCK_PIN,0) failed\n"); return; }
        if (gpioWrite(LATCH_PIN, 1) != 0) { fprintf(stderr, "Error: gpioWrite(LATCH_PIN,1) failed\n"); return; }
        if (gpioWrite(LATCH_PIN, 0) != 0) { fprintf(stderr, "Error: gpioWrite(LATCH_PIN,0) failed\n"); return; }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        display_digit(5);
        gpioDelay(500000);
        display_digit(5);
        gpioDelay(500000);
    }

    gpioWrite(LATCH_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(DATA_PIN, 0);
    gpioTerminate();
    return 0;
}

