#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_PERIOD_SEC 2
#define CONSUMER "blink_button"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge event detection */
    struct gpiod_line_request_config button_config = {
        .consumer = CONSUMER,
        .request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };
    if (gpiod_line_request(button_line, &button_config, 0) < 0) {
        perror("gpiod_line_request (button)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d every %d seconds. Press the button (GPIO%d) to stop.\n",
           LED_PIN, BLINK_PERIOD_SEC, BUTTON_PIN);
    fflush(stdout);

    /* Blink LED with 1-second timeout per period */
    while (running) {
        int val = gpiod_line_get_value(led_line);
        if (val < 0) {
            perror("gpiod_line_get_value (LED)");
            goto cleanup;
        }
        if (val == 1) {
            /* Turn LED on */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value (LED on)");
                goto cleanup;
            }
            /* Wait for 1 second, checking running flag every 100 ms */
            for (int i = 0; i < 10 && running; i++) {
                usleep(100000);
            }
            if (!running) break;
            val = gpiod_line_get_value(led_line);
            if (val < 0) {
                perror("gpiod_line_get_value (LED)");
                goto cleanup;
            }
            if (val == 0) {
                /* Turn LED off */
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value (LED off)");
                    goto cleanup;
                }
            }
        } else {
            /* Turn LED off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value (LED off)");
                goto cleanup;
            }
            /* Wait for 1 second, checking running flag every 100 ms */
            for (int i = 0; i < 10 && running; i++) {
                usleep(100000);
            }
            if (!running) break;
        }
    }

    /* Stop blinking immediately on button press */
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value (LED off)");
        goto cleanup;
    }
    printf("Button pressed! Blinking stopped.\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (led_line) gpiod_line_release(led_line);
    if (button_line) gpiod_line_release(button_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

