#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN      24
#define BUTTON_PIN   22
#define BLINK_US     500000   /* 500 ms */
#define POLL_US      10000    /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Button-controlled LED on GPIO%d, button on GPIO%d.\n", LED_PIN, BUTTON_PIN);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        int level = gpioRead(BUTTON_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", BUTTON_PIN, level);
            break;
        }

        if (level == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to set GPIO%d high.\n", LED_PIN);
                break;
            }
            gpioDelay(BLINK_US);
            if (!g_running)
                break;
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to set GPIO%d low.\n", LED_PIN);
                break;
            }
            gpioDelay(BLINK_US);
        }

        gpioDelay(POLL_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

