#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS  10000000L  /* 10 ms -> 100 Hz */
#define PWM_STEP_NS    1000L      /* 1 ms per step */
#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_line_value(struct gpiod_line *line, int value) {
    int rc = gpiod_line_set_value(line, value);
    if (rc < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
    }
    return rc;
}

static int pwm_step(struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue,
                    int red_val, int green_val, int blue_val) {
    int red_ns = (int)(PWM_PERIOD_NS * red_val / 100);
    int green_ns = (int)(PWM_PERIOD_NS * green_val / 100);
    int blue_ns = (int)(PWM_PERIOD_NS * blue_val / 100);

    if (red_ns < 0) red_ns = 0;
    if (green_ns < 0) green_ns = 0;
    if (blue_ns < 0) blue_ns = 0;

    if (set_line_value(red, 0) < 0) return -1;
    if (set_line_value(green, 0) < 0) return -1;
    if (set_line_value(blue, 0) < 0) return -1;

    struct timespec ts = {
        .tv_sec  = 0,
        .tv_nsec = (long)red_ns
    };
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL) < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "clock_nanosleep failed: %s\n", strerror(errno));
        return -1;
    }

    if (set_line_value(red, 1) < 0) return -1;
    if (set_line_value(green, 1) < 0) return -1;
    if (set_line_value(blue, 1) < 0) return -1;

    ts.tv_sec  = 0;
    ts.tv_nsec = (long)green_ns;
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL) < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "clock_nanosleep failed: %s\n", strerror(errno));
        return -1;
    }

    if (set_line_value(red, 0) < 0) return -1;
    if (set_line_value(green, 0) < 0) return -1;
    if (set_line_value(blue, 0) < 0) return -1;

    ts.tv_sec  = 0;
    ts.tv_nsec = (long)blue_ns;
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL) < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "clock_nanosleep failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *green = NULL, *blue = NULL;
    int rc = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red   = gpiod_chip_get_line(chip, RED_PIN);
    green = gpiod_chip_get_line(chip, GREEN_PIN);
    blue  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red || !green || !blue) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue,  "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        int red_val  = rand() % 101;
        int green_val = rand() % 101;
        int blue_val  = rand() % 101;

        if (pwm_step(red, green, blue, red_val, green_val, blue_val) < 0) {
            fprintf(stderr, "PWM step failed, exiting.\n");
            goto cleanup;
        }

        if (rand() % 100 < 10) {
            int new_red  = rand() % 101;
            int new_green = rand() % 101;
            int new_blue  = rand() % 101;
            if (pwm_step(red, green, blue, new_red, new_green, new_blue) < 0) {
                fprintf(stderr, "PWM step failed, exiting.\n");
                goto cleanup;
            }
        }

        struct timespec ts = {
            .tv_sec  = 0,
            .tv_nsec = (long)COLOR_CHANGE_MS * 1000000L
        };
        if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "clock_nanosleep failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (red)  gpiod_line_release(red);
    if (green) gpiod_line_release(green);
    if (blue)  gpiod_line_release(blue);
    if (chip)  gpiod_chip_close(chip);
    return rc;
}

