/*
 * impact_monitor.c — Raspberry Pi Zero W
 *
 * Monitors an Adafruit LSM303DLHC accelerometer on I2C bus 1 at 10 Hz.
 * When the total G-force magnitude exceeds a threshold, it triggers a
 * GPIO17 (BCM) impact interrupt and logs timestamped accelerometer
 * data to impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_monitor impact_monitor.c -lpigpio -lrt
 * Run:    sudo ./impact_monitor [-t threshold_g]
 */

