#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x48
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_REG_ALS_LSB, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *als = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    *red = ((uint16_t)(uint8_t)buf[3] << 8) | (uint8_t)buf[2];
    *green = ((uint16_t)(uint8_t)buf[5] << 8) | (uint8_t)buf[4];
    *blue = ((uint16_t)(uint8_t)buf[7] << 8) | (uint8_t)buf[6];

    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void control_led(uint16_t als) {
    int brightness = (int)((float)als / 65535.0f * PWM_RANGE);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    if (gpioPWM(LED_GPIO, brightness) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", LED_GPIO);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    uint16_t als, red, green, blue;
    int retry_count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", LED_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", LED_GPIO);
        cleanup();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            log_data(als, red, green, blue);
            control_led(als);
            retry_count = 0;
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
            if (retry_count < 3) {
                gpioDelay(RETRY_DELAY_US);
                retry_count++;
            } else {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

