#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x49
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define OUT_X_L_XYZ    0x28
#define OUT_X_H_XYZ    0x29
#define OUT_Y_L_XYZ    0x2A
#define OUT_Y_H_XYZ    0x2B
#define OUT_Z_L_XYZ    0x2C
#define OUT_Z_H_XYZ    0x2D
#define SAMPLE_PERIOD_US 50000
#define CAL_SAMPLES     100
#define THRESHOLD_DPS  50.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int gyro_init(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who) < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1;
    return 0;
}

static int gyro_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L_XYZ, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int calibrate_gyro(int fd, int16_t *x_off, int16_t *y_off, int16_t *z_off) {
    int16_t sx = 0, sy = 0, sz = 0;
    int valid = 0;
    for (int i = 0; i < CAL_SAMPLES && g_running; i++) {
        int16_t rx, ry, rz;
        if (gyro_read_xyz(fd, &rx, &ry, &rz) == 0) {
            sx += rx; sy += ry; sz += rz;
            valid++;
        }
        usleep(1000);
    }
    if (!valid) {
        fprintf(stderr, "Error: calibration incomplete (%d samples)\n", valid);
        return -1;
    }
    *x_off = sx / valid;
    *y_off = sy / valid;
    *z_off = sz / valid;
    return 0;
}

static void log_data(FILE *f, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(f);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
