/*
 * ADXL345 accelerometer logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM) via ~330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -o adxl345_log adxl345_log.c -lpigpio -lrt
 * Run:    sudo ./adxl345_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants (from datasheet) ---- */
#define ADXL345_I2C_BUS        1
#define ADXL345_DEVICE_ADDRESS 0x05          /* SA0 tied to GND */
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_BW_RATE    0x2C
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_REG_BW_RATE_VAL 0x0A   /* 100 Hz output data rate */
#define ADXL345_REG_POWER_CTL_VAL 0x08  /* standby -> measure mode */
#define ADXL345_REG_DATA_FORMAT_VAL 0x0B /* full resolution, +/-2g */
#define ADXL345_DEVID_EXPECTED 0xE5

/* ---- Application constants ---- */
#define LED_GPIO        17
#define ACCEL_THRESHOLD 2.0f   /* g */
#define SAMPLE_PERIOD_US 100000  /* 100 ms -> 10 Hz */
#define LOG_FILE        "accel_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] writeByteData reg=0x%02X val=0x%02X failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[I2C] readBlock reg=0x%02X len=%u failed: %d\n",
                reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "[I2C] short read: got %d of %u bytes\n", rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                               */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_block(handle, ADXL345_REG_DEVID, &devid, 1) != 0) {
        fprintf(stderr, "[ADXL345] cannot read DEVID register\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ADXL345] unexpected DEVID=0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }
    printf("[ADXL345] device ID verified: 0x%02X\n", devid);

    /* Standby mode first so configuration writes take effect */
    if (i2c_write_byte(handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        return -1;
    }
    gpioDelay(1000);  /* 1 ms settle */

    /* Data format: full resolution, +/-2g range */
    if (i2c_write_byte(handle, ADXL345_REG_DATA_FORMAT, ADXL345_REG_DATA_FORMAT_VAL) < 0) {
        return -1;
    }

    /* Output data rate: 100 Hz */
    if (i2c_write_byte(handle, ADXL345_REG_BW_RATE, ADXL345_REG_BW_RATE_VAL) < 0) {
        return -1;
    }

    /* Measure mode */
    if (i2c_write_byte(handle, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_VAL) < 0) {
        return -1;
    }

    gpioDelay(1000);  /* 1 ms settle */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g)                                               */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t raw[6];
    int16_t rx, ry, rz;

    if (i2c_read_block(handle, ADXL345_REG_DATAX0, raw, 6) != 0) {
        return -1;
    }

    rx = (int16_t)((raw[1] << 8) | raw[0]);
    ry = (int16_t)((raw[3] << 8) | raw[2]);
    rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* Full-resolution mode: 1 mg/LSB -> 0.001 g/LSB */
    *x = (float)rx * 0.001f;
    *y = (float)ry * 0.001f;
    *z = (float)rz * 0.001f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[LOG] fprintf failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(ADXL345_I2C_BUS, ADXL345_DEVICE_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                ADXL345_I2C_BUS, ADXL345_DEVICE_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] cannot open %s for append\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("[INFO] logging ADXL345 data to %s (Ctrl-C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "[ERROR] logging failed; continuing\n");
            }
            if (fabsf(x) > ACCEL_THRESHOLD ||
                fabsf(y) > ACCEL_THRESHOLD ||
                fabsf(z) > ACCEL_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            /* On read failure, turn LED off and keep running */
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

