    if (i2c_write_byte(handle, ADXL345_REG_POWER_CTL, ADXL345_REG_POWER_CTL_VAL) < 0) {
        return -1;
    }

    gpioDelay(1000);  /* 1 ms settle */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g)                                               */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t raw[6];
    int16_t rx, ry, rz;

    if (i2c_read_block(handle, ADXL345_REG_DATAX0, raw, 6) != 0) {
        return -1;
    }

    rx = (int16_t)((raw[1] << 8) | raw[0]);
    ry = (int16_t)((raw[3] << 8) | raw[2]);
    rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* Full-resolution mode: 1 mg/LSB -> 0.001 g/LSB */
    *x = (float)rx * 0.001f;
    *y = (float)ry * 0.001f;
    *z = (float)rz * 0.001f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[LOG] fprintf failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(ADXL345_I2C_BUS, ADXL345_DEVICE_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                ADXL345_I2C_BUS, ADXL345_DEVICE_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] cannot open %s for append\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("[INFO] logging ADXL345 data to %s (Ctrl-C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "[ERROR] logging failed; continuing\n");
            }
            if (fabsf(x) > ACCEL_THRESHOLD ||
                fabsf(y) > ACCEL_THRESHOLD ||
                fabsf(z) > ACCEL_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            /* On read failure, turn LED off and keep running */
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

