/*
 * Raspberry Pi Zero W – LSM303DLHC Compass Logger
 *
 * Wiring:
 *   LSM303DLHC VCC  -> Pi 3V3 (Pin 1)
 *   LSM303DLHC GND  -> Pi GND  (Pin 9)
 *   LSM303DLHC SCL  -> Pi GPIO3 / SCL1 (Pin 5)
 *   LSM303DLHC SDA  -> Pi GPIO2 / SDA1 (Pin 3)
 *
 * Build:  gcc -O2 -Wall -o compass_logger compass_logger.c -lpigpio -lm
 * Run:    sudo ./compass_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1 0x20
#define LSM303_ACCEL_CTRL_REG4 0x23
#define LSM303_MAG_CTRL_REG1   0x20
#define LSM303_MAG_CTRL_REG2   0x21
#define LSM303_MAG_WHO_AM_I     0x0F
#define LSM303_ACCEL_OUT_X_L   0x28
#define LSM303_MAG_OUT_X_H     0x31

/* ---- Scaling factors ---- */
#define ACCEL_SCALE 16384.0f   /* LSB per g  (9.81 g / 16384) */
#define MAG_SCALE   0.15f      /* LSB per gauss (1 gauss / 0.15) */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_accel = -1;
static int g_i2c_mag   = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an LSM303 register. Returns 0 on success.   */
static int lsm_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at `reg` (auto-increment). Returns 0  */
/* on success, -1 on error.                                          */
static int lsm_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize LSM303DLHC accelerometer. Returns 0 on success.         */
static int init_accelerometer(void)
{
    /* Standby -> wake up, 100 Hz ODR, normal mode */
    if (lsm_write_reg(g_i2c_accel, LSM303_ACCEL_CTRL_REG1, 0x00) < 0) return -1;
    if (lsm_write_reg(g_i2c_accel, LSM303_ACCEL_CTRL_REG4, 0x00) < 0) return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Verify WHO_AM_I */
    uint8_t who;
    if (lsm_read_block(g_i2c_accel, LSM303_ACCEL_CTRL_REG1, &who, 1) < 0) return -1;
    if (who != 0x3B) {
        fprintf(stderr, "[ERROR] Accel WHO_AM_I mismatch: 0x%02X (expected 0x3B)\n", who);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize LSM303DLHC magnetometer. Returns 0 on success.         */
static int init_magnetometer(void)
{
    /* Standby -> wake up, 100 Hz ODR, normal mode */
    if (lsm_write_reg(g_i2c_mag, LSM303_MAG_CTRL_REG1, 0x00) < 0) return -1;
    if (lsm_write_reg(g_i2c_mag, LSM303_MAG_CTRL_REG2, 0x00) < 0) return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Verify WHO_AM_I */
    uint8_t who;
    if (lsm_read_block(g_i2c_mag, LSM303_MAG_CTRL_REG1, &who, 1) < 0) return -1;
    if (who != 0x2D) {
        fprintf(stderr, "[ERROR] Mag WHO_AM_I mismatch: 0x%02X (expected 0x2D)\n", who);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer (X/Y/Z) in g. Returns 0 on success.             */
static int read_accelerometer(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (lsm_read_block(g_i2c_accel, LSM303_ACCEL_OUT_X_L, buf, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)rx / ACCEL_SCALE;
    *y = (float)ry / ACCEL_SCALE;
    *z = (float)rz / ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read magnetometer (X/Y/Z) in gauss. Returns 0 on success.         */
static int read_magnetometer(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (lsm_read_block(g_i2c_mag, LSM303_MAG_OUT_X_H, buf, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)rx * MAG_SCALE;
    *y = (float)ry * MAG_SCALE;
    *z = (float)rz * MAG_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading in degrees.                                */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float h = atan2f(-mz * cosf(pitch) + my * sinf(pitch),
                     sqrtf(mz * mz * cosf(pitch) * cosf(roll) +
                           mx * mx * sinf(roll) * sinf(pitch) +
                           my * mz * sinf(roll) * cosf(roll) +
                           mz * mx * sinf(pitch) * sinf(roll) +
                           mx * my * cosf(pitch) * sinf(roll) +
                           my * my * cosf(pitch) * cosf(roll)));

    h = fmodf(h + 180.0f, 360.0f);
    if (h < 0.0f) h += 360.0f;
    return h;
}

/* ------------------------------------------------------------------ */
static void log_data(float ax, float ay, float az,
                     float mx, float my, float mz, float heading)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("[ERROR] fopen(compass_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ax, ay, az, mx, my, mz, heading);
    } else {
        fprintf(fp, "timestamp_error,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                ax, ay, az, mx, my, mz, heading);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        i2cClose(g_i2c_mag);
        g_i2c_mag = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    g_i2c_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_accel < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(accel, 0x%02X) failed: %d\n",
                LSM303_ACCEL_ADDR, g_i2c_accel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (g_i2c_mag < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(mag, 0x%02X) failed: %d\n",
                LSM303_MAG_ADDR, g_i2c_mag);
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_accelerometer() < 0) {
        fprintf(stderr, "[FATAL] Accel init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (init_magnetometer() < 0) {
        fprintf(stderr, "[FATAL] Mag init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303DLHC compass logger started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float ax, ay, az, mx, my, mz, heading;

        if (read_accelerometer(&ax, &ay, &az) < 0) {
            fprintf(stderr, "[WARN] Accel read failed; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_magnetometer(&mx, &my, &mz) < 0) {
            fprintf(stderr, "[WARN] Mag read failed; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        heading = calculate_heading(ax, ay, az, mx, my, mz);

        log_data(ax, ay, az, mx, my, mz, heading);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

