#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 10000
#define NUM_SENSORS 2
#define LOG_FILE_NAME "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS] = { -1, -1 };
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c_sensor(int bus, int handle) {
    if (handle >= 0) {
        i2cClose(handle);
        handle = -1;
    }
    handle = i2cOpen(bus, 0x69, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x69: %d\n", bus, handle);
        return -1;
    }
    return handle;
}

static int read_sensor_data(int handle, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C handle %d: %d\n", handle, bytes_read);
        return -1;
    }
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2) {
    struct timespec ts1, ts2;
    if (clock_gettime(CLOCK_REALTIME, &ts1) != 0) {
        perror("clock_gettime");
        return -1.0;
    }
    if (clock_gettime(CLOCK_REALTIME, &ts2) != 0) {
        perror("clock_gettime");
        return -1.0;
    }
    double diff_sec = (ts2.tv_sec - ts1.tv_sec) + (ts2.tv_nsec - ts1.tv_nsec) / 1e9;
    return diff_sec;
}

static int log_data(FILE *fp, int16_t s1, int16_t s2, double tdoa) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(fp, "%ld.%09ld,%d,%d,%.6f\n",
                ts.tv_sec, ts.tv_nsec, s1, s2, tdoa) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = init_i2c_sensor(I2C_BUS, -1);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor %d\n", i);
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        for (int i = 0; i < NUM_SENSORS; i++) {
            i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return 1;
    }

    while (running) {
        int16_t s1 = 0, s2 = 0;
        bool read_ok = true;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] < 0) {
                read_ok = false;
                break;
            }
            if (read_sensor_data(i2c_handles[i], &s1) != 0) {
                read_ok = false;
                break;
            }
            if (read_sensor_data(i2c_handles[i], &s2) != 0) {
                read_ok = false;
                break;
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Skipping sample due to sensor read failure\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        double tdoa = calculate_tdoa(s1, s2);
        if (tdoa < 0) {
            fprintf(stderr, "Error calculating TDOA\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(log_file, s1, s2, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

