/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 *
 * SPI0 CE0  ->  GPIO8  (BCM 8, SPI0 CE0)
 * SPI0 SCLK ->  GPIO11 (BCM 11)
 * SPI0 MISO ->  GPIO9  (BCM 9)
 * SPI0 MOSI ->  GPIO10 (BCM 10)
 *
 * SPI mode 3:  CPOL=1, CPHA=1, 8-bit words, 1 MHz
 * ADIS16488A 16-bit command word: MSB=0, 7-bit register address, 16-bit data
 *   command_word[0] = 0x00  (don't-care)
 *   command_word[1] = (reg << 1) | 0x80  (read)
 *   command_word[2] = 0x00  (don't-care)
 *   command_word[3] = 0x00  (don't-care)
 *   response_word[0] = 0x00  (don't-care)
 *   response_word[1] = (reg << 1) | 0x40  (data MSB)
 *   response_word[2] = data_low nibble
 *   response_word[3] = data_low nibble
 *
 * Gyro  sensitivity: 0.005 deg/sec/LSB
 * Accel sensitivity: 0.00025 g/LSB
 *
 * Build:  gcc -O2 -Wall -Wextra -o adis16488 adis16488.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        3

#define GYRO_SENSITIVITY 0.005f   /* deg/sec per LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g per LSB */

#define SAMPLE_PERIOD_US 100000U  /* 100 ms */
#define STALL_DELAY_US   40U      /* 40 us stall between read requests */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_fp) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * ADIS16488A 16-bit command word: MSB=0, 7-bit register address, 16-bit data
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int adis_read_word(uint8_t reg, int16_t *out)
{
    uint8_t tx[4] = { 0x00, (uint8_t)((reg << 1) | 0x80), 0x00, 0x00 };
    uint8_t rx[4] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = STALL_DELAY_US;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    /* response_word[1] = (reg << 1) | 0x40  -> data MSB */
    *out = (int16_t)(((uint16_t)rx[1] & 0x7F) << 8 | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data conversion                                                     */
/* ------------------------------------------------------------------ */
static void convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
                         int16_t accel_x, int16_t accel_y, int16_t accel_z,
                         float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps,
                         float *accel_x_g, float *accel_y_g, float *accel_z_g)
{
    *gyro_x_dps = (float)gyro_x * GYRO_SENSITIVITY;
    *gyro_y_dps = (float)gyro_y * GYRO_SENSITIVITY;
    *gyro_z_dps = (float)gyro_z * GYRO_SENSITIVITY;
    *accel_x_g  = (float)accel_x * ACCEL_SENSITIVITY;
    *accel_y_g  = (float)accel_y * ACCEL_SENSITIVITY;
    *accel_z_g  = (float)accel_z * ACCEL_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *ts, float gx, float gy, float gz,
                    float ax, float ay, float az)
{
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                ts, gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    g_fp = fopen("imu_data.csv", "w");
    if (!g_fp) {
        fprintf(stderr, "fopen(imu_data.csv): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (fprintf(g_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n") < 0) {
        fprintf(stderr, "fprintf(header): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (fflush(g_fp) != 0) {
        fprintf(stderr, "fflush(header): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("ADIS16488A logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        if (adis_read_word(0x00, &gyro_x) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis_read_word(0x01, &gyro_y) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis_read_word(0x02, &gyro_z) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis_read_word(0x03, &accel_x) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis_read_word(0x04, &accel_y) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (adis_read_word(0x05, &accel_z) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gx, gy, gz, ax, ay, az;
        convert_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z,
                     &gx, &gy, &gz, &ax, &ay, &az);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (log_data(g_fp, ts, gx, gy, gz, ax, ay, az) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    return EXIT_SUCCESS;
}

