           SPI_MAX_SPEED, SPI_MODE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t gx = 0, gy = 0, gz = 0, ax = 0, ay = 0, az = 0;

        if (read_register(ADIS16448_REG_GYRO_XOUT, &gx) < 0 ||
