                     ax * ACCEL_SCALE, ay * ACCEL_SCALE, az * ACCEL_SCALE);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

