/* The ADIS16448 expects a read command (reg_addr | 0x8000) followed     */
/* by a dummy transfer (0x0000) to clock out the 16-bit data.             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adis16448_read_reg(int fd, uint8_t reg_addr, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg_addr | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
