#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

#define REG_SMPLRT_DIV  0x19
#define REG_PWR_MGMT_1  0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu bytes: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6886_init(int fd)
{
    if (i2c_write_byte(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);
    if (i2c_write_byte(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;
    if (i2c_write_byte(fd, REG_PWR_MGMT_1, 0x01) < 0)
        return -1;
    usleep(100000);
    return 0;
}

static int read_accel_gyro(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                           int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int main(void)
{
    int fd = -1;
    int retries = 3;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU6886 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6886 initialized. Reading every 50 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        int ok = 0;

        for (int attempt = 0; attempt < retries && g_running; attempt++) {
            if (read_accel_gyro(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);
        }

        if (ok) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", retries);
        }

        usleep(50000);
    }

    if (fd >= 0)
        close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

