#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADXL345_ADDR   0x05
#define LED_GPIO       17
#define IMPACT_THRESHOLD 2.5f
#define SCALE_FACTOR   256.0f
#define POLL_DELAY_US  10000
#define LED_ON_US      500000

/* ADXL345 registers */
#define REG_DEVID       0x00
#define REG_POWER_CTL   0x2D
#define REG_DATA_FORMAT 0x31
#define REG_DATAX0      0x32
#define REG_BW_RATE     0x2C

/* Expected device ID */
#define DEVID_EXPECTED  0xE5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int verify_device(int handle)
{
    uint8_t devid;
    if (i2c_read_reg8(handle, REG_DEVID, &devid) < 0)
        return -1;
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, DEVID_EXPECTED);
        return -1;
    }
    return 0;
}

static int init_adxl345(int handle)
{
    if (i2c_write_reg8(handle, REG_POWER_CTL, 0x00) < 0) return -1; /* standby */
    if (i2c_write_reg8(handle, REG_DATA_FORMAT, 0x00) < 0) return -1; /* full res, +/-2g */
    if (i2c_write_reg8(handle, REG_BW_RATE, 0x0A) < 0) return -1;     /* 100 Hz */
    if (i2c_write_reg8(handle, REG_POWER_CTL, 0x08) < 0) return -1; /* measure */
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t data[6];
    int rc = i2cReadI2CBlockData(handle, REG_DATAX0, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: %d\n", rc);
        return -1;
    }

    int16_t x_raw = (int16_t)((data[1] << 8) | data[0]);
    int16_t y_raw = (int16_t)((data[3] << 8) | data[2]);
    int16_t z_raw = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)x_raw / SCALE_FACTOR;
    *y = (float)y_raw / SCALE_FACTOR;
    *z = (float)z_raw / SCALE_FACTOR;
    return 0;
}

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
