        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 not detected on I2C bus %d at 0x%02X\n",
                I2C_BUS, ADXL345_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_adxl345(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_log_file = fopen("impact_log.txt", "a");
    if (!g_log_file) {
        perror("Failed to open impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring acceleration (threshold %.2f g)...\n", IMPACT_THRESHOLD);

    while (g_running) {
        float x, y, z, magnitude;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
