#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICM20602_ADDR 0x68
#define ACCEL_XOUT_H 0x2D
#define GYRO_XOUT_H 0x33
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE 131.0f
#define SAMPLE_PERIOD_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_byte(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(int handle, uint8_t reg, int16_t *val) {
    uint8_t hi, lo;
    if (read_byte(handle, reg, &hi) < 0) return -1;
    if (read_byte(handle, reg + 1, &lo) < 0) return -1;
    *val = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, int len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C burst read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static void log_sample(FILE *f, const char *ts, float ax, float ay, float az,
                       float gx, float gy, float gz) {
    fprintf(f, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", ts, ax, ay, az, gx, gy, gz);
    fflush(f);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t whoami = 0;
    if (read_byte(i2c_handle, WHO_AM_I, &whoami) < 0) {
        cleanup();
        return 1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        cleanup();
        return 1;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
        fflush(log_file);
    }

    while (!terminate) {
        uint8_t buf[12];
        if (read_burst(i2c_handle, ACCEL_XOUT_H, buf, 12) < 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
        int16_t gx = (int16_t)((buf[6] << 8) | buf[7]);
        int16_t gy = (int16_t)((buf[8] << 8) | buf[9]);
        int16_t gz = (int16_t)((buf[10] << 8) | buf[11]);

        float axf = ax / ACCEL_SCALE;
        float ayf = ay / ACCEL_SCALE;
        float azf = az / ACCEL_SCALE;
        float gxf = gx / GYRO_SCALE;
        float gyf = gy / GYRO_SCALE;
        float gzf = gz / GYRO_SCALE;

        time_t now = time(NULL);
        struct tm tmv;
        localtime_r(&now, &tmv);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

        log_sample(log_file, ts, axf, ayf, azf, gxf, gyf, gzf);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

