        struct tm tmv;
        localtime_r(&now, &tmv);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

        log_sample(log_file, ts, axf, ayf, azf, gxf, gyf, gzf);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
