#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MMA8451_ADDR 0x1D
#define MMA8451_ID_REG 0x00
#define MMA8451_ID_VALUE 0x45
#define MMA8451_CTRL_REG1 0x2A
#define MMA8451_CTRL_REG2 0x2B
#define MMA8451_OUT_X_L 0x08
#define MMA8451_OUT_X_H 0x09
#define MMA8451_OUT_Y_L 0x0A
#define MMA8451_OUT_Y_H 0x0B
#define MMA8451_OUT_Z_L 0x0C
#define MMA8451_OUT_Z_H 0x0D
#define MMA8451_RANGE 2.0f
#define MMA8451_SENSITIVITY 1024.0f
#define LED_GPIO 17
#define POLL_INTERVAL_US 100000
#define LED_ON_DURATION_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int verify_sensor_id(void) {
    uint8_t id = 0;
    if (read_register(MMA8451_ID_REG, &id) != 0) {
        return -1;
    }
    if (id != MMA8451_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n",
                MMA8451_ID_VALUE, id);
        return -1;
    }
    printf("MMA8451Q verified (ID=0x%02X)\n", id);
    return 0;
}

static int init_mma8451(void) {
    if (write_register(MMA8451_CTRL_REG1, 0x00) != 0) return -1;
    if (write_register(MMA8451_CTRL_REG2, 0x00) != 0) return -1;
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (read_register(MMA8451_OUT_X_L, &xl) != 0) return -1;
    if (read_register(MMA8451_OUT_X_H, &xh) != 0) return -1;
    if (read_register(MMA8451_OUT_Y_L, &yl) != 0) return -1;
    if (read_register(MMA8451_OUT_Y_H, &yh) != 0) return -1;
    if (read_register(MMA8451_OUT_Z_L, &zl) != 0) return -1;
    if (read_register(MMA8451_OUT_Z_H, &zh) != 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x / MMA8451_SENSITIVITY;
    *y = (float)raw_y / MMA8451_SENSITIVITY;
    *z = (float)raw_z / MMA8451_SENSITIVITY;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(log_file);
}

static void control_led(float x, float y, float z) {
    static bool led_on = false;
    if (fabsf(x) > MMA8451_RANGE || fabsf(y) > MMA8451_RANGE || fabsf(z) > MMA8451_RANGE) {
        if (!led_on) {
            if (gpioWrite(LED_GPIO, 1) == 0) {
                led_on = true;
            }
        }
    } else {
        if (led_on) {
            if (gpioWrite(LED_GPIO, 0) == 0) {
                led_on = false;
            }
        }
    }
}

