#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x31
#define GPIO_CHIP       "gpiochip4"
#define INT1_PIN        17
#define LOG_FILE        "freefall_log.csv"
#define POLL_TIMEOUT_MS 1000

/* ADXL345 registers */
#define REG_DEVID       0x00
#define REG_POWER_CTL   0x2D
#define REG_INT_ENABLE  0x2E
#define REG_INT_MAP     0x2F
#define REG_DATA_FORMAT 0x31
#define REG_DATAX0      0x32
#define REG_DATAX1      0x33
#define REG_DATAY0      0x34
#define REG_DATAY1      0x35
#define REG_DATAZ0      0x36
#define REG_DATAZ1      0x37

#define DEVID_EXPECTED  0xE5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1 = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, REG_DEVID, &devid) < 0)
        return -1;
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode before any configuration */
    if (i2c_write_reg8(fd, REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Data format: full resolution, +/- 2 g, right-justified */
    if (i2c_write_reg8(fd, REG_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Enable INT1 on INT1 pin (bit 3) */
    if (i2c_write_reg8(fd, REG_INT_ENABLE, 0x08) < 0)
        return -1;

    /* Map INT1 to INT1 (bit 3) */
    if (i2c_write_reg8(fd, REG_INT_MAP, 0x08) < 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg8(fd, REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static void cleanup(void)
{
    if (g_int1) {
        gpiod_line_set_value(g_int1, 0);
        gpiod_line_release(g_int1);
        g_int1 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, REG_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_int1 = gpiod_chip_get_line(g_chip, INT1_PIN);
    if (!g_int1) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_int1, "adxl345-int1") < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as input: %s\n",
                INT1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ftell(g_log) == 0)
        fprintf(g_log, "Timestamp,X,Y,Z\n");

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    int ret = EXIT_SUCCESS;

    while (g_running) {
        int val = gpiod_line_get_value(g_int1);
        if (val < 0) {
            fprintf(stderr, "GPIO read error on line %d: %s\n",
                    INT1_PIN, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }
        if (val == 1) {
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                ret = EXIT_FAILURE;
                break;
            }
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char ts_str[32];
            strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
            long ms = ts.tv_nsec / 1000000L;
            if (fprintf(g_log, "%s.%03ld,%d,%d,%d\n",
                        ts_str, ms,
                        (int16_t)(ts.tv_sec), (int16_t)(ts.tv_nsec / 1000000L),
                        (int16_t)(ts.tv_nsec % 1000000L)) < 0) {
                fprintf(stderr, "Log write error: %s\n", strerror(errno));
                ret = EXIT_FAILURE;
                break;
            }
            if (fflush(g_log) != 0)
                fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        }
        usleep(POLL_TIMEOUT_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

