#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6D

#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define CTRL3_C 0x12
#define CTRL4 0x1E
#define CTRL5 0x1F
#define CTRL6_XL 0x20
