        return -1;
    }

    if (i2c_write_byte(fd, CTRL1_XL, 0x80) < 0) return -1;
    if (i2c_write_byte(fd, CTRL2_G, 0x80) < 0) return -1;
    if (i2c_write_byte(fd, CTRL3_C, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, CTRL4, 0x38) < 0) return -1;
    if (i2c_write_byte(fd, CTRL5, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, CTRL6_XL, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, CTRL7_G, 0x00) < 0) return -1;

    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUTX_L_XL, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUTX_L_G, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
