    *y = (float)raw_y * GYRO_SENSITIVITY;
    *z = (float)raw_z * GYRO_SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float ax, float ay, float az, float gx, float gy, float gz) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
