/*
 * ADIS16266 Gyroscope Logger for Raspberry Pi 3 Model B+
 * SPI channel 0 (CE0 / GPIO8), mode 3 (CPOL=1, CPHA=1), 1 MHz
 * Logs angular rate to gyro_log.csv at 10 ms intervals.
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lpigpio -lrt
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_MODE       3          /* CPOL=1, CPHA=1 */
#define SPI_FLAGS      0          /* Mode 3, active-low CE */

#define WHO_AM_I_REG   0x00
#define WHO_AM_I_VAL   0x1626     /* ADIS16266 WHO_AM_I register value */
#define GYRO_OUT_REG   0x04
#define GYRO_SCALE     0.0305f    /* deg/sec per LSB at 1 kHz output */
#define SAMPLE_US      10000     /* 10 ms */
#define LOG_FILE       "gyro_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_read_register(uint8_t reg, uint16_t *out)
{
    char tx[3] = { (char)(reg | 0x80), 0x00, 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI read failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2];
    return 0;
}

static int spi_write_register(uint8_t reg, uint16_t val)
{
    char tx[3] = { (char)(reg & 0x7F), (char)(val >> 8), (char)(val & 0xFF) };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI write failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADIS16266 operations                                                */
/* ------------------------------------------------------------------ */
static int adis16266_init(void)
{
    uint16_t who = 0;
    if (spi_read_register(WHO_AM_I_REG, &who) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    printf("ADIS16266 detected (WHO_AM_I=0x%04X)\n", who);

    /* Optional: configure output data rate to 1 kHz (bits 7:4 = 0x0) */
    if (spi_write_register(GYRO_OUT_REG, 0x0000) != 0)
        return -1;

    return 0;
}

static int adis16266_read_gyro_rate(float *rate)
{
    uint16_t raw = 0;
    if (spi_read_register(GYRO_OUT_REG, &raw) != 0)
        return -1;
    *rate = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,GyroRate_deg_s\n");
    return 0;
}

static void log_sample(float rate)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%.4f\n", ts, rate);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- init sensor --- */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    if (log_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging ADIS16266 gyro data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float rate = 0.0f;
        if (adis16266_read_gyro_rate(&rate) == 0) {
            log_sample(rate);
            printf("Gyro rate: %.4f deg/s\n", rate);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

