        fprintf(stderr, "SPI write failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADIS16266 operations                                                */
/* ------------------------------------------------------------------ */
static int adis16266_init(void)
{
    uint16_t who = 0;
    if (spi_read_register(WHO_AM_I_REG, &who) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    printf("ADIS16266 detected (WHO_AM_I=0x%04X)\n", who);

    /* Optional: configure output data rate to 1 kHz (bits 7:4 = 0x0) */
    if (spi_write_register(GYRO_OUT_REG, 0x0000) != 0)
        return -1;

    return 0;
}

static int adis16266_read_gyro_rate(float *rate)
{
    uint16_t raw = 0;
    if (spi_read_register(GYRO_OUT_REG, &raw) != 0)
        return -1;
    *rate = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,GyroRate_deg_s\n");
    return 0;
}

static void log_sample(float rate)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s,%.4f\n", ts, rate);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- init sensor --- */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    if (log_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging ADIS16266 gyro data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float rate = 0.0f;
        if (adis16266_read_gyro_rate(&rate) == 0) {
            log_sample(rate);
            printf("Gyro rate: %.4f deg/s\n", rate);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

