#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GYRO_ADDR 0x60
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x49
#define OUT_X_L 0x1D
#define OUT_X_H 0x1E
#define OUT_Y_L 0x1F
#define OUT_Y_H 0x20
#define OUT_Z_L 0x21
#define OUT_Z_H 0x22
#define SENSITIVITY 8.75f
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gyro(void) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int who = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who == WHO_AM_I_VAL) {
            return 0;
        }
        fprintf(stderr, "Warning: WHO_AM_I returned 0x%02X (expected 0x%02X), retry %d/%d\n",
                who, WHO_AM_I_VAL, retries + 1, MAX_RETRIES);
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000);
        }
    }
    fprintf(stderr, "Error: GY-50 not detected after %d retries\n", MAX_RETRIES);
    return -1;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (rc=%d)\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%09ld,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t raw_x, raw_y, raw_z;
    float x, y, z;

    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            x = (float)raw_x / SENSITIVITY;
            y = (float)raw_y / SENSITIVITY;
            z = (float)raw_z / SENSITIVITY;
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

