#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped flame event line to the log file.               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    const char *state_str;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    state_str = flame_detected ? "YES" : "...";

    if (fprintf(g_log_file, "%s – Flame detected: %s\n",
                timestamp, state_str) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    printf("%s – Flame detected: %s\n", timestamp, state_str);
    fflush(stdout);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor. Returns 1 (flame), 0 (no flame), -1 on error. */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_SUCCESS;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Open log file in append mode ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", FLAME_SENSOR_GPIO);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected < 0) {
            fprintf(stderr, "Sensor read error — logging error event.\n");
            log_event(0);
        } else {
            log_event(flame_detected);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

