#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x48
#define SAMPLE_PERIOD_US 100000
#define LOG_FILE       "vibration_log.csv"

/* D7S-0001 acceleration registers (16-bit, little-endian on the bus) */
#define REG_X_LSB      0x00
#define REG_X_MSB      0x01
#define REG_Y_LSB      0x02
#define REG_Y_MSB      0x03
#define REG_Z_LSB      0x04
#define REG_Z_MSB      0x05
#define REG_TEMP_LSB   0x06
#define REG_TEMP_MSB   0x07
