#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define HALL_SENSOR_1_PIN 17
#define HALL_SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_DELAY_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_data(FILE *fp, int sensor1_value, int sensor2_value) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long milliseconds = ts.tv_nsec / 1000000;

    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, milliseconds, sensor1_value, sensor2_value) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;

    if (gpioSetMode(HALL_SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", HALL_SENSOR_1_PIN);
        ret = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetMode(HALL_SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", HALL_SENSOR_2_PIN);
        ret = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", HALL_SENSOR_1_PIN);
        ret = EXIT_FAILURE;
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", HALL_SENSOR_2_PIN);
        ret = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        ret = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    printf("Conveyor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = gpioRead(HALL_SENSOR_1_PIN);
        int sensor2_value = gpioRead(HALL_SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading GPIO pins: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (log_data(fp, sensor1_value, sensor2_value) != 0) {
            fprintf(stderr, "Error logging data\n");
            ret = EXIT_FAILURE;
            break;
        }

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("Conveyor halted!\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        ret = EXIT_FAILURE;
    }

cleanup_gpio:
    gpioTerminate();
    return ret;
}

