#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LOG_FILE    "vibration_log.txt"
#define SAMPLE_US   100000

/* ADXL354B Register Addresses */
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_STATUS     0x08
#define ADXL354B_REG_XDATA_L    0x08
#define ADXL354B_REG_XDATA_H    0x09
#define ADXL354B_REG_YDATA_L    0x0A
#define ADXL354B_REG_YDATA_H    0x0B
#define ADXL354B_REG_ZDATA_L    0x0C
#define ADXL354B_REG_ZDATA_H    0x0D
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_INT_ENABLE 0x2E
#define ADXL354B_REG_INT_MAP    0x2F
#define ADXL354B_REG_INT_SOURCE 0x30
#define ADXL354B_REG_RESET      0x2C

#define ADXL354B_DEVID_AD_VAL   0xC2
#define ADXL354B_STATUS_STABLE  0x01

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx, rx, 2);
        if (result == 2) {
            *value = (uint8_t)rx[1];
            return 0;
        }
        fprintf(stderr, "SPI read error on reg 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
        retries--;
        gpioDelay(1000);
    }
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx, rx, 2);
        if (result == 2) {
            return 0;
        }
        fprintf(stderr, "SPI write error on reg 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
        retries--;
        gpioDelay(1000);
    }
    return -1;
}

static int adxl354b_reset(void) {
    uint8_t status = 0;
    if (spi_read_register(ADXL354B_REG_RESET, &status) != 0) {
        fprintf(stderr, "Failed to read reset status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        if (spi_write_register(ADXL354B_REG_RESET, 0x01) != 0) {
            fprintf(stderr, "Failed to reset device\n");
            return -1;
        }
        gpioDelay(1000);
        if (spi_read_register(ADXL354B_REG_RESET, &status) != 0) {
            fprintf(stderr, "Failed to read reset status after reset\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            fprintf(stderr, "Reset did not complete\n");
            return -1;
        }
    }
    return 0;
}

static int adxl354b_init(void) {
    uint8_t devid = 0;
    if (spi_read_register(ADXL354B_REG_DEVID_AD, &devid) != 0) {
        fprintf(stderr, "Failed to read DEVID\n");
        return -1;
    }
    if (devid != ADXL354B_DEVID_AD_VAL) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X)\n", devid, ADXL354B_DEVID_AD_VAL);
        return -1;
    }

    if (adxl354b_reset() != 0) {
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear POWER_CTL\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Failed to write INT_MAP\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_INT_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Failed to write INT_ENABLE\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_INT_SOURCE, 0x00) != 0) {
        fprintf(stderr, "Failed to write INT_SOURCE\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x09) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL (RUN bit)\n");
        return -1;
    }

    if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
        fprintf(stderr, "Failed to read STATUS\n");
        return -1;
    }
    if ((status & ADXL354B_STATUS_STABLE) == 0) {
        fprintf(stderr, "Sensor not stable yet\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char tx[7] = { (char)(ADXL354B_REG_XDATA_L | 0x80 | 0x40), 0, 0, 0, 0, 0, 0 };
    char rx[7] = { 0, 0, 0, 0, 0, 0, 0 };
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx, rx, 7);
        if (result == 7) {
            *x = (int16_t)(((uint8_t)rx[2] << 8) | (uint8_t)rx[1]);
            *y = (int16_t)(((uint8_t)rx[4] << 8) | (uint8_t)rx[3]);
            *z = (int16_t)(((uint8_t)rx[6] << 8) | (uint8_t)rx[5]);
            return 0;
        }
        fprintf(stderr, "SPI read error: %d, retries left: %d\n", result, retries - 1);
        retries--;
        gpioDelay(1000);
    }
    return -1;
}

static void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADXL354B initialized. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    spi_write_register(ADXL354B_REG_POWER_CTL, 0x00);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

