#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0x03  /* Mode 3: active-high clock, MSB first */
#define SAMPLE_DELAY_US 10000  /* 10 ms between samples */
#define GYRO_SCALE 0.05f      /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f   /* g per LSB */

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_word(int handle, uint8_t address, int16_t *data) {
    char tx[2] = { (char)(address | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    int ret;

    ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    *data = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_word(handle, 0x01, &raw_gyro_x) != 0) return -1;
    if (spi_read_word(handle, 0x03, &raw_gyro_y) != 0) return -1;
    if (spi_read_word(handle, 0x05, &raw_gyro_z) != 0) return -1;
    if (spi_read_word(handle, 0x07, &raw_accel_x) != 0) return -1;
    if (spi_read_word(handle, 0x09, &raw_accel_y) != 0) return -1;
    if (spi_read_word(handle, 0x0B, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

static int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("IMU logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        ret = read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z,
                            &accel_x, &accel_y, &accel_z);
        if (ret == 0) {
            if (log_data(log_file, gyro_x, gyro_y, gyro_z,
                         accel_x, accel_y, accel_z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "IMU read failed, skipping sample\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("IMU logging stopped.\n");
    return EXIT_SUCCESS;
}

