/*
 * KY-032 IR obstacle-avoidance sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC        -> 3.3 V (physical pin 1)
 *   GND        -> GND  (physical pin 9)
 *
 * The KY-032 is active-low: 0 = obstacle detected, 1 = path clear.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky032_reader ky032_reader.c -lpigpio -lrt
 * Run:    sudo ./ky032_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_DELAY_US 100000          /* 100 ms between polls */
#define NUM_SENSORS 2

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT) failed");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM) failed");
}

/*
 * Read the state of all sensor lines in a single bulk read.
 * Returns 0 on success, -1 on error.
 */
static int read_all_sensors(int *s1, int *s2)
{
    int rc = gpioRead(SENSOR1_GPIO);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %d\n",
                SENSOR1_GPIO, rc);
        return -1;
    }
    *s1 = rc;

    rc = gpioRead(SENSOR2_GPIO);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %d\n",
                SENSOR2_GPIO, rc);
        return -1;
    }
    *s2 = rc;

    return 0;
}

static void log_data(int s1, int s2)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("[%s] Sensor 1: %s  Sensor 2: %s\n",
           timestamp,
           s1 == 0 ? "OBSTACLE" : "PATH_CLEAR",
           s2 == 0 ? "OBSTACLE" : "PATH_CLEAR");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    install_signal_handlers();

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor lines to settle */
    gpioDelay(100000);  /* 100 ms */

    printf("KY-032 obstacle-avoidance reader started.\n");
    printf("  Sensor 1: GPIO%d  Sensor 2: GPIO%d\n",
           SENSOR1_GPIO, SENSOR2_GPIO);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int s1, s2;

        if (read_all_sensors(&s1, &s2) != 0) {
            fprintf(stderr, "Error: failed to read sensor data.\n");
            break;
        }

        log_data(s1, s2);

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

