/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16266 SDO -> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16266 SDA -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16266 SCL -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: /dev/spidev0.0, Mode 3, 1 MHz, MSB-first
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADIS16266_REG_XGYRO_OUT  0x00
#define ADIS16266_REG_YGYRO_OUT  0x02
#define ADIS16266_REG_ZGYRO_OUT  0x04
#define ADIS16266_REG_TEMP_OUT   0x06
#define ADIS16266_REG_STATUS     0x08

#define ADIS16266_GYRO_SCALE  0.02f   /* deg/sec per LSB */
#define ADIS16266_TEMP_SCALE  0.01f   /* deg C per LSB */
#define ADIS16266_READ_DELAY_US 100000U /* 100 ms between reads */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * ADIS16266 two-transfer read protocol (MSB-first):
 *   Transfer 1: [0x80 | reg] [0x00]  -> read 2 bytes
 *   Transfer 2: [0x00] [0x00]        -> dummy clock to clock out data
 * Result: 16-bit value in rx_buf[1..2].
 */
static int adis16266_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(0x80 | reg), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static int adis16266_read_gyro(int fd, float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg(fd, ADIS16266_REG_XGYRO_OUT, &raw_x) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_YGYRO_OUT, &raw_y) < 0) return -1;
    if (adis16266_read_reg(fd, ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0) return -1;

    *x = (float)raw_x * ADIS16266_GYRO_SCALE;
    *y = (float)raw_y * ADIS16266_GYRO_SCALE;
    *z = (float)raw_z * ADIS16266_GYRO_SCALE;
    return 0;
}

static int adis16266_read_temp(int fd, float *temp)
{
    uint16_t raw;
    if (adis16266_read_reg(fd, ADIS16266_REG_TEMP_OUT, &raw) < 0) return -1;
    *temp = (float)raw * ADIS16266_TEMP_SCALE;
    return 0;
}

static void sleep_us(unsigned us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sigint_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("SPI mode  : %u\n", mode);
    printf("SPI bits  : %u\n", bits);
    printf("SPI speed : %u Hz\n", speed);
    printf("Sampling every 100 ms. Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float x, y, z, temp;

        if (adis16266_read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyroscope read error (sensor absent or bus fault)\n");
        } else if (adis16266_read_temp(fd, &temp) < 0) {
            fprintf(stderr, "Temperature read error\n");
        } else {
            printf("X: %+.4f deg/s  Y: %+.4f deg/s  Z: %+.4f deg/s  Temp: %+.2f C\n",
                   x, y, z, temp);
        }

        sleep_us(ADIS16266_READ_DELAY_US);
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

