/*
 * Raspberry Pi 4 Model B – Adafruit FXOS8700 breakout reader
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2  (BCM 2, I2C bus 1 SDA)
 *   FXOS8700 SCL  -> GPIO3  (BCM 3, I2C bus 1 SCL)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o fxos8700 fxos8700.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 register map (datasheet rev 1.0) ---- */
#define FXOS8700_REG_ID       0x00
#define FXOS8700_REG_STATUS   0x01
#define FXOS8700_REG_OUT_X_MSB 0x08  /* accelerometer X MSB */
#define FXOS8700_REG_M_OUT_X_MSB 0x09  /* magnetometer X MSB */

#define FXOS8700_ID_VALUE     0x70
#define FXOS8700_STATUS_MST   0x01  /* magnet sensor ready */
#define FXOS8700_STATUS_AST   0x02  /* accel sensor ready */

#define I2C_BUS_DEV          "/dev/i2c-1"
#define SAMPLE_PERIOD_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t got = read(fd, dst, n);
    if (got < 0 || (size_t)got != n) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, got, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor state ---- */

typedef struct {
    int fd;
    int id;
    int status;
} sensor_ctx_t;

static int sensor_init(sensor_ctx_t *ctx, int bus)
{
    ctx->fd = open(I2C_BUS_DEV, O_RDWR);
    if (ctx->fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS_DEV, strerror(errno));
        return -1;
    }

    if (ioctl(ctx->fd, I2C_SLAVE, 0x0D) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x0D) failed: %s\n", strerror(errno));
        close(ctx->fd);
        ctx->fd = -1;
        return -1;
    }

    uint8_t id = 0;
    if (i2c_read_block(ctx->fd, FXOS8700_REG_ID, &id, 1) < 0) {
        close(ctx->fd);
        ctx->fd = -1;
        return -1;
    }
    ctx->id = id;

    if (ctx->id != FXOS8700_ID_VALUE) {
        fprintf(stderr, "FXOS8700 ID mismatch: got 0x%02X, expected 0x%02X\n",
                ctx->id, FXOS8700_ID_VALUE);
        close(ctx->fd);
        ctx->fd = -1;
        return -1;
    }

    /* Quick status poll to confirm MST and AST are ready */
    uint8_t status = 0;
    if (i2c_read_block(ctx->fd, FXOS8700_REG_STATUS, &status, 1) < 0) {
        close(ctx->fd);
        ctx->fd = -1;
        return -1;
    }
    ctx->status = status;

    /* Put sensor into standby so configuration changes take effect */
    if (i2c_write_byte(ctx->fd, 0x0F, 0x00) < 0) {
        close(ctx->fd);
        ctx->fd = -1;
        return -1;
    }
    usleep(10000);  /* 10 ms settle */

    return 0;
}

static void sensor_close(sensor_ctx_t *ctx)
{
    if (ctx->fd >= 0) {
        close(ctx->fd);
        ctx->fd = -1;
    }
}

/* ---- Data parsing ---- */

/*
 * Combined 12-byte block (accel + mag, left-aligned):
 *   [0..1]  accel X(14-bit)  [2..3]  accel Y(14-bit)
 *   [4..5]  accel Z(14-bit)  [6..7]  mag  X(16-bit)
 *   [8..9]  mag Y(16-bit)   [10..11] mag Z(16-bit)
 */
static void parse_sensor_data(const uint8_t *raw, int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    *ax = (int16_t)((raw[0] << 8) | raw[1]) >> 2;  /* 14-bit left-aligned */
    *ay = (int16_t)((raw[2] << 8) | raw[3]) >> 2;
    *az = (int16_t)((raw[4] << 8) | raw[5]) >> 2;
    *mx = (int16_t)((raw[6] << 8) | raw[7]);
    *my = (int16_t)((raw[8] << 8) | raw[9]);
    *mz = (int16_t)((raw[10] << 8) | raw[11]);
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_ctx_t ctx = { .fd = -1, .id = 0, .status = 0 };

    if (sensor_init(&ctx, 1) < 0) {
        return EXIT_FAILURE;
    }

    printf("FXOS8700 detected (ID=0x%02X). Status=0x%02X\n", ctx.id, ctx.status);

    while (g_running) {
        uint8_t raw[12];
        if (i2c_read_block(ctx.fd, FXOS8700_REG_OUT_X_MSB, raw, sizeof(raw)) < 0) {
            /* Transient read failure – back off and retry */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        int16_t ax, ay, az, mx, my, mz;
        parse_sensor_data(raw, &ax, &ay, &az, &mx, &my, &mz);

        printf("Accel X=%6d Y=%6d Z=%6d  |  Mag X=%6d Y=%6d Z=%6d\n",
               ax, ay, az, mx, my, mz);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    sensor_close(&ctx);
    return EXIT_SUCCESS;
}

