#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_DURATION_US 5000000
#define POLL_INTERVAL_US 1000000
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

static void print_status(int high_count, int threshold)
{
    char ts[TIMESTAMP_LEN];
    get_timestamp(ts, sizeof(ts));

    if (high_count > threshold) {
        printf("%s ALERT: High readings count: %d (threshold: %d)\n",
               ts, high_count, threshold);
    } else {
        printf("%s Status: High readings count: %d (threshold: %d)\n",
               ts, high_count, threshold);
    }
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high readings per window\n");
        fprintf(stderr, "  must be a positive integer\n");
        return EXIT_FAILURE;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (BCM). Threshold: %d\n",
           SENSOR_PIN, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        int read_error = 0;

        for (int i = 0; i < WINDOW_DURATION_US / SAMPLE_INTERVAL_US && g_running; i++) {
            int level = gpioRead(SENSOR_PIN);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on pin %d\n", SENSOR_PIN);
                read_error = 1;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (read_error) {
            break;
        }

        print_status(high_count, threshold);

        if (g_running) {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    gpioTerminate();
    printf("\nProgram terminated.\n");
    return EXIT_SUCCESS;
}

