/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two TIP120-driven 5 V relay modules on GPIO17 (Door A) and GPIO27 (Door B)
 * control 12 V electromagnetic door locks.  A 5 s unlock window energises the
 * relay HIGH (door unlocked), then returns LOW (door locked).
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(char *buf, size_t len)
{
    if (len < 6) {
        fprintf(stderr, "Error: code buffer too small\n");
        return -1;
    }
    for (int i = 0; i < 6; i++) {
        int c = (rand() % 10) + '0';
        if (c == '\0') {
            fprintf(stderr, "Error: random number generator failed\n");
            return -1;
        }
        buf[i] = c;
    }
    return 0;
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL, *line_b = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(line_a)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(line_b)");
        goto cleanup;
    }

    srand((unsigned)time(NULL));

    printf("Door access system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        char code[6];
        if (generate_code(code, sizeof(code)) != 0)
            break;

        printf("Generated security code: %s\n", code);

        printf("Enter your 6-digit security code: ");
        fflush(stdout);

        char line[256];
        size_t n = 0;
        while (g_running && n < sizeof(line) - 1) {
            int c = getchar();
            if (c == '\n' || c == EOF) {
                line[n] = '\0';
                break;
            }
            if (c != '\r') {
                line[n++] = (char)c;
            }
        }

        if (n == 0) {
            printf("Invalid input. Please enter a 6-digit code.\n");
            continue;
        }

        if (strncmp(line, code, 6) == 0) {
            printf("Access granted!\n");
            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access event\n");

            /* Energise relay for 5 s (check g_running every second) */
            for (int i = 0; i < UNLOCK_SEC && g_running; i++) {
                if (gpiod_line_set_value(line_a, 1) != 0) {
                    perror("gpiod_line_set_value(line_a, 1)");
                    goto cleanup;
                }
                if (gpiod_line_set_value(line_b, 1) != 0) {
                    perror("gpiod_line_set_value(line_b, 1)");
                    goto cleanup;
                }
                sleep(1);
            }

            if (gpiod_line_set_value(line_a, 0) != 0) {
                perror("gpiod_line_set_value(line_a, 0)");
                goto cleanup;
            }
            if (gpiod_line_set_value(line_b, 0) != 0) {
                perror("gpiod_line_set_value(line_b, 0)");
                goto cleanup;
            }
        } else {
            printf("Access denied\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure doors are locked on exit */
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");
    return ret;
}

