#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x5D
#define BH1750_CMD_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_light_level(int handle, float *lux_out) {
    if (i2cWriteByte(handle, BH1750_CMD_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error: failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 2).\n", bytes_read);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(const char *timestamp, float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending.\n", LOG_FILE);
        return;
    }
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float lux = 0.0f;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (!timeinfo) {
            fprintf(stderr, "Error: localtime failed.\n");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (read_light_level(i2c_handle, &lux) == 0) {
            log_data(timestamp, lux);
            printf("%s  Lux: %.2f\n", timestamp, lux);
        } else {
            fprintf(stderr, "%s  Error: failed to read light level.\n", timestamp);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

