#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5D
#define PWM_PIN 18
#define PORT 12345
#define LOG_FILE "frequency_log.txt"
#define SAMPLE_INTERVAL_US 20000
#define PWM_DUTY 128
#define PWM_RANGE 255

#define MPR121_SOFTRESET 0x80
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_TOUCHTH_0 0x41
#define MPR121_TOUPTH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ELECTRODE_FILT 0x5E
#define MPR121_TOUCHTH_1 0x41
#define MPR121_TOUPTH_1 0x42
#define MPR121_DEBOUNCE_1 0x5B
#define MPR121_CONFIG1_1 0x5C
#define MPR121_CONFIG2_1 0x5D
#define MPR121_ELECTRODE_FILT_1 0x5E

#define AUTH_SECRET "MySecretKey"
#define CMD_PREFIX "MOTION_DETECTED:"
#define CMD_LEN 32

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int fd, uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(fd, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (mpr121_write(fd, MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(fd, MPR121_ELECTRODE_CONFIG, 0x0C) != 0) return -1;
    if (mpr121_write(fd, MPR121_ELECTRODE_FILT, 0x24) != 0) return -1;
    if (mpr121_write(fd, MPR121_DEBOUNCE, 0x00) != 0) return -1;
    if (mpr121_write(fd, MPR121_CONFIG1, 0x10) != 0) return -1;
    if (mpr121_write(fd, MPR121_CONFIG2, 0x20) != 0) return -1;
    if (mpr121_write(fd, MPR121_ELECTRODE_FILT_1, 0x24) != 0) return -1;
    if (mpr121_write(fd, MPR121_DEBOUNCE_1, 0x00) != 0) return -1;
    if (mpr121_write(fd, MPR121_CONFIG1_1, 0x10) != 0) return -1;
    if (mpr121_write(fd, MPR121_CONFIG2_1, 0x20) != 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(fd, MPR121_TOUCHTH_0 + 2 * i, 12) != 0) return -1;
        if (mpr121_write(fd, MPR121_TOUPTH_0 + 2 * i, 12) != 0) return -1;
    }
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(fd, MPR121_TOUCHTH_1 + 2 * i, 13) != 0) return -1;
        if (mpr121_write(fd, MPR121_TOUPTH_1 + 2 * i, 13) != 0) return -1;
    }
    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_data) {
    char buf[24];
    if (i2cReadI2CBlockData(fd, MPR121_TOUCH_STATUS, buf, 24) != 24) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *touch_data = ((uint16_t)(buf[1] & 0x0F) << 8) | (uint8_t)buf[0];
    return 0;
}

static int authenticate_command(const char *cmd) {
    if (strlen(cmd) < CMD_LEN) return 0;
    if (strncmp(cmd, CMD_PREFIX, CMD_LEN) != 0) return 0;
    if (strcmp(cmd + CMD_LEN, AUTH_SECRET) != 0) return 0;
    return 1;
}

static void play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) return;
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(errno));
        return;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Failed to start PWM: %s\n", strerror(errno));
        return;
    }
    gpioDelay(duration_ms * 1000);
    gpioPWM(PWM_PIN, 0);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%d\n", frequency);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (pigpio_initialized) {
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioPWM(PWM_PIN, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Setsockopt failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Bind failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Listen failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Theremin listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Accept failed: %s\n", strerror(errno));
            continue;
        }

        char buffer[1024] = {0};
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes < 0) {
            fprintf(stderr, "Receive failed: %s\n", strerror(errno));
            close(client_fd);
            continue;
        }
        if (bytes == 0) {
            close(client_fd);
            continue;
        }
        buffer[bytes] = '\0';

        if (authenticate_command(buffer)) {
            uint16_t touch_data = 0;
            if (read_touch_data(i2c_fd, &touch_data) == 0) {
                int frequency = (int)touch_data;
                play_tone(frequency, 5000);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Failed to read touch data\n");
            }
            close(client_fd);
        } else {
            const char *err_msg = "Invalid command\n";
            send(client_fd, err_msg, strlen(err_msg), 0);
            close(client_fd);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

