#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x1E
#define MAG_REG_XOUT_H 0x00
#define LED_GPIO       17
#define PWM_RANGE      255
#define PWM_FREQ       1000
#define SAMPLE_US      100000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu bytes: %s\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, MAG_REG_XOUT_H, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t y_raw = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t z_raw = (int16_t)((raw[4] << 8) | raw[5]);

    *x = (float)x_raw;
    *y = (float)y_raw;
    *z = (float)z_raw;
    return 0;
}

static void set_led_brightness(int gpio, float magnitude)
{
    int brightness = (int)(magnitude * 10.0f);
    if (brightness < 0)   brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(gpio, brightness) != 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", gpio);
}

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen("magnetometer_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        goto cleanup;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg8(fd, 0x0F, 0x57) != 0) {
        fprintf(stderr, "Failed to configure LSM303DLHC\n");
        goto cleanup;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        goto cleanup;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        goto cleanup;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LED_GPIO);
        goto cleanup;
    }
    if (gpioPWM(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", LED_GPIO);
        goto cleanup;
    }

    printf("Magnetometer monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;
        int retries = 0;
        bool ok = false;

        while (retries < MAX_RETRIES && g_running) {
            if (read_magnetometer(fd, &x, &y, &z) == 0) {
                ok = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                usleep(10000);
        }

        if (!ok) {
            fprintf(log_fp, "Error: magnetometer read failed after %d retries\n", MAX_RETRIES);
            fflush(log_fp);
            continue;
        }

        set_led_brightness(LED_GPIO, (float)z);
        usleep(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    if (log_fp)
        fclose(log_fp);
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
    return rc;
}

