/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data over I2C at ~10 ms intervals and
 * stores each sample in a 64-entry in-memory circular buffer.
 * On a rising edge of the INT1 pin (BCM GPIO 23, physical pin 16),
 * dumps the last 10 samples to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants (datasheet rev 1.1) ---- */
#define LSM303D_ADDR        0x1E
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG2   0x21
#define LSM303D_CTRL_REG3   0x22
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_CTRL_REG5   0x24
#define LSM303D_CTRL_REG6   0x25
#define LSM303D_CTRL_REG7   0x26
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_EN     0x31
#define LSM303D_INT1_THRESH 0x32

/* ---- Application constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define GPIO_CHIP          "gpiochip4"   /* BCM GPIO on Pi Zero W */
#define INT1_BCM_PIN       23            /* BCM GPIO 23, physical pin 16 */
#define BUFFER_SIZE        64
#define SAMPLE_PERIOD_US   10000         /* 10 ms */
#define SENSITIVITY_MG_PER_LSB 0.061f
#define THRESHOLD_MG       2000.0f

/* ---- Data structure ---- */
typedef struct {
    float x, y, z;
} accel_sample_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
static accel_sample_t g_buffer[BUFFER_SIZE];
static int g_buf_head = 0;
static int g_buf_count = 0;

/* ---- Prototypes ---- */
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_read_reg16(int fd, uint8_t reg, int16_t *val);
static int  init_lsm303d(int fd);
static int  read_accel(int fd, accel_sample_t *sample);
static void dump_buffer(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303D initialization                                               */
/* ------------------------------------------------------------------ */
static int init_lsm303d(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — device absent or bus error.\n");
        return -1;
    }
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Enable accelerometer X, Y, Z axes */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x0C) != 0)
        return -1;

    /* Enable magnetometer X, Y, Z axes */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG2, 0x0C) != 0)
        return -1;

    /* 100 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x0D) != 0)
        return -1;

    /* 2000 mg threshold for INT1 */
    if (i2c_write_reg8(fd, LSM303D_INT1_THRESH, (uint8_t)(THRESHOLD_MG / 2.0f)) != 0)
        return -1;

    /* Enable INT1 (rising edge) */
    if (i2c_write_reg8(fd, LSM303D_INT1_EN, 0x01) != 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Accelerometer read                                                    */
/* ------------------------------------------------------------------ */
static int read_accel(int fd, accel_sample_t *sample)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A, &raw_x) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 2, &raw_y) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 4, &raw_z) != 0)
        return -1;

