    sample->y = (float)raw_y * SENSITIVITY_MG_PER_LSB / 1000.0f;
    sample->z = (float)raw_z * SENSITIVITY_MG_PER_LSB / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer operations                                          */
/* ------------------------------------------------------------------ */
static void add_sample(accel_sample_t sample)
{
    g_buffer[g_buf_head] = sample;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void dump_buffer(void)
{
