        int idx = (g_buf_head - g_buf_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] X=%.3f  Y=%.3f  Z=%.3f  mg\n",
               i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
