static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  i2c_read_reg16(int fd, uint8_t reg, int16_t *val);
static int  init_lsm303d(int fd);
static int  read_accel(int fd, accel_sample_t *sample);
static void dump_buffer(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303D initialization                                               */
/* ------------------------------------------------------------------ */
static int init_lsm303d(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — device absent or bus error.\n");
        return -1;
    }
    if (who_am_i != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Enable accelerometer X, Y, Z axes */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x0C) != 0)
        return -1;

    /* Enable magnetometer X, Y, Z axes */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG2, 0x0C) != 0)
        return -1;

    /* 100 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x0D) != 0)
        return -1;

    /* 2000 mg threshold for INT1 */
    if (i2c_write_reg8(fd, LSM303D_INT1_THRESH, (uint8_t)(THRESHOLD_MG / 2.0f)) != 0)
        return -1;

    /* Enable INT1 (rising edge) */
    if (i2c_write_reg8(fd, LSM303D_INT1_EN, 0x01) != 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, LSM303D_INT1_CFG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Accelerometer read                                                    */
/* ------------------------------------------------------------------ */
static int read_accel(int fd, accel_sample_t *sample)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A, &raw_x) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 2, &raw_y) != 0)
        return -1;
    if (i2c_read_reg16(fd, LSM303D_OUT_X_L_A + 4, &raw_z) != 0)
        return -1;

    sample->x = (float)raw_x * SENSITIVITY_MG_PER_LSB / 1000.0f;
    sample->y = (float)raw_y * SENSITIVITY_MG_PER_LSB / 1000.0f;
    sample->z = (float)raw_z * SENSITIVITY_MG_PER_LSB / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer operations                                          */
/* ------------------------------------------------------------------ */
static void add_sample(accel_sample_t sample)
{
    g_buffer[g_buf_head] = sample;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void dump_buffer(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s — Last %d acceleration samples:\n", ts, g_buf_count);
    for (int i = 0; i < g_buf_count; i++) {
        int idx = (g_buf_head - g_buf_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] X=%.3f  Y=%.3f  Z=%.3f  mg\n",
               i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                         */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_BCM_PIN);
    if (!g_int1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                INT1_BCM_PIN, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d-int1") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n",
                INT1_BCM_PIN, strerror(errno));
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm303d(g_i2c_fd) != 0) {
