#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DELAY_MS 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(solenoid1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(solenoid2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (solenoids off) */
    if (gpiod_line_request_output(line1, "solenoid1", 0) < 0) {
        perror("gpiod_line_request_output(solenoid1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "solenoid2", 0) < 0) {
        perror("gpiod_line_request_output(solenoid2)");
        goto cleanup;
    }

    /* Ensure solenoids are off at startup */
    if (gpiod_line_set_value(line1, 0) < 0) {
        perror("gpiod_line_set_value(solenoid1, 0)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value(solenoid2, 0)");
        goto cleanup;
    }

    printf("Alternating solenoids on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SOLENOID1_PIN, SOLENOID2_PIN);

    while (running) {
        /* Activate solenoid1 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(solenoid1, 1)");
            goto cleanup;
        }
        printf("Solenoid1 ON\n");
        fflush(stdout);

        /* Sleep 500 ms using nanosleep for portability */
        struct timespec ts = { .tv_sec = DELAY_MS / 1000,
                               .tv_nsec = (DELAY_MS % 1000) * 1000000L };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && running) {
            /* Interrupted by signal; loop to retry */
        }

        /* De-activate solenoid1 */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(solenoid1, 0)");
            goto cleanup;
        }
        printf("Solenoid1 OFF\n");
        fflush(stdout);

        /* Activate solenoid2 */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(solenoid2, 1)");
            goto cleanup;
        }
        printf("Solenoid2 ON\n");
        fflush(stdout);

        /* Sleep 500 ms */
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && running) {
            /* Interrupted by signal; loop to retry */
        }

        /* De-activate solenoid2 */
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(solenoid2, 0)");
            goto cleanup;
        }
        printf("Solenoid2 OFF\n");
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure solenoids are off on exit */
    if (line1) gpiod_line_set_value(line1, 0);
    if (line2) gpiod_line_set_value(line2, 0);
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

