#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <gpiod.h>

#define UART_PORT0 "/dev/serial0"
#define UART_PORT1 "/dev/serial1"
#define GPIO_CHIP "gpiochip0"
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define EXPECTED_CODE "123456"
#define READ_TIMEOUT_SEC 5
#define RELAY_HOLD_SEC 2

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int uart_init(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);
    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_code(int fd, char *buf, size_t len) {
    size_t total = 0;
    while (total < len - 1) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        struct timeval tv = {0, READ_TIMEOUT_SEC * 1000000L};
        int ret = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in select() on %s: %s\n", UART_PORT0, strerror(errno));
            return -1;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout reading from %s\n", UART_PORT0);
            return -1;
        }
        int c = fgetc(fd);
        if (c == EOF) {
            fprintf(stderr, "Error reading from %s\n", UART_PORT0);
            return -1;
        }
        if (c >= '0' && c <= '9') {
            buf[total] = c;
            total++;
        } else {
            buf[total] = '\0';
            return -1;
        }
    }
    buf[total] = '\0';
    return 0;
}

static int verify_codes(const char *code1, const char *code2) {
    if (strcmp(code1, EXPECTED_CODE) != 0 || strcmp(code2, EXPECTED_CODE) != 0) {
        fprintf(stderr, "Error: codes do not match expected code\n");
        return -1;
    }
    if (strcmp(code1, code2) != 0) {
        fprintf(stderr, "Error: codes do not match each other\n");
        return -1;
    }
    return 0;
}

static int lock_doors(struct gpiod_line *line, int hold_sec) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line HIGH: %s\n", strerror(errno));
        return -1;
    }
    printf("Locking doors for %d seconds...\n", hold_sec);
    sleep(hold_sec);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line LOW: %s\n", strerror(errno));
        return -1;
    }
    printf("Doors unlocked.\n");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    struct gpiod_line *relay1 = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *relay2 = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY2_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay1, "door-lock", 0) < 0 ||
        gpiod_line_request_output(relay2, "door-lock", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd0 = uart_init(UART_PORT0);
    if (fd0 < 0) {
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = uart_init(UART_PORT1);
    if (fd1 < 0) {
        close(fd0);
        gpiod_line_release(relay1);
        gpiod_line_release(relay2);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Door lock authentication system started. Press Ctrl+C to exit.\n");

    char code1[6] = {0};
    char code2[6] = {0};

    while (g_running) {
        if (read_code(fd0, code1, sizeof(code1)) == 0) {
            printf("Received code1: %s\n", code1);
        } else {
            fprintf(stderr, "Error reading code1\n");
        }

        if (read_code(fd1, code2, sizeof(code2)) == 0) {
            printf("Received code2: %s\n", code2);
        } else {
            fprintf(stderr, "Error reading code2\n");
        }

        if (g_running) {
            if (verify_codes(code1, code2) == 0) {
                printf("Codes verified. Locking doors.\n");
                if (lock_doors(relay1, RELAY_HOLD_SEC) != 0) {
                    fprintf(stderr, "Error locking doors\n");
                }
            }
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay1, 0);
    gpiod_line_set_value(relay2, 0);
    close(fd0);
    close(fd1);
    gpiod_line_release(relay1);
    gpiod_line_release(relay2);
    gpiod_chip_close(chip);

    return 0;
}

