    log_event(LOG_INFO, msg);
}

int main(void) {
    openlog("pir_door_strike", LOG_PID | LOG_CONS, LOG_USER);
    log_shutdown();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_event(LOG_ERR, "Failed to install signal handlers: " strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event(LOG_ERR, "Failed to open gpiochip4: " strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_event(LOG_ERR, "Failed to get PIR line (GPIO4): " strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_event(LOG_ERR, "Failed to get relay line (GPIO17): " strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_event(LOG_ERR, "Failed to request PIR line as input: " strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        log_event(LOG_ERR, "Failed to request relay line as output: " strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Door strike system started.");

    time_t last_motion_time = 0;
    bool relay_active = false;
    bool in_failsafe = false;

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor: " strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                log_event(LOG_ERR, "Failed to get current time: " strerror(errno));
                usleep(POLL_INTERVAL_MS * 1000);
                continue;
            }

            if (!in_failsafe) {
                if (difftime(now, last_motion_time) >= FAILSAFE_TIMEOUT_S) {
                    log_failsafe();
                } else {
                    log_event(LOG_INFO, "Motion detected on PIR sensor.");
                    relay_active = true;
                    log_relay_event(relay_active);
                    last_motion_time = now;
                }
            }
        } else {
            if (relay_active) {
                log_relay_event(false);
                relay_active = false;
            }
            last_motion_time = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean shutdown */
    if (relay_active) {
        log_relay_event(false);
    }
    gpiod_line_release(relay_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    log_shutdown();
    return EXIT_SUCCESS;
}

