#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define TIMER_ID 0
#define TIMER_INTERVAL_SEC 60
#define RELAY_ON_TIME_SEC 300
#define PAUSE_BETWEEN_RELAYS_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        syslog(LOG_ERR, "gpioWrite failed on pin %d", pin);
        return -1;
    }
    return 0;
}

static int activate_relay(int pin, int duration_sec) {
    if (set_relay(pin, 0) != 0) return -1;
    syslog(LOG_INFO, "Relay on pin %d activated for %d seconds", pin, duration_sec);
    time_sleep(duration_sec);
    if (set_relay(pin, 1) != 0) return -1;
    syslog(LOG_INFO, "Relay on pin %d deactivated", pin);
    return 0;
}

static int deactivate_all_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (set_relay(pins[i], 1) != 0) return -1;
    }
    syslog(LOG_INFO, "All relays deactivated");
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "gpioSetMode failed on pin %d", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (set_relay(pins[i], 1) != 0) {
            gpioTerminate();
            return -1;
        }
    }
    syslog(LOG_INFO, "GPIO pins initialised: %d, %d, %d, %d", RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN);
    return 0;
}

static void cleanup_gpio(void) {
    deactivate_all_relays();
    gpioTerminate();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting irrigation system");

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetTimerFunc(TIMER_ID, TIMER_INTERVAL_SEC, activate_relay) != 0) {
        syslog(LOG_ERR, "gpioSetTimerFunc failed");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation cycle started (timer %d, interval %d s)", TIMER_ID, TIMER_INTERVAL_SEC);

    while (running) {
        time_sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

