/*
 * MPU6050 accelerometer data logger for Raspberry Pi 4 Model B.
 *
 * Uses a POSIX per-process timer (timer_create/timer_settime) to sample
 * the MPU6050 at 100 Hz.  The most recent sample is exposed via a
 * /sys/kernel/mpu6050_accel/latest driver interface.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_logger mpu6050_logger.c
 *
 * Wiring:
 *   MPU6050 VCC  -> Pi 3V3 (pin 1)
 *   MPU6050 GND  -> Pi GND  (pin 9)
 *   MPU6050 SCL  -> Pi GPIO3 / SCL1 (pin 5)
 *   MPU6050 SDA  -> Pi GPIO2 / SDA1 (pin 3)
 *
 * I2C bus:  /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS (100 * 1000 * 1000)  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU6050 driver interface (sysfs fallback)                         */
/* ------------------------------------------------------------------ */

static int mpu6050_init(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        return -1;
    }

    /* Wake the MPU6050 (clear sleep bit) */
    if (i2c_write_reg8(g_i2c_fd, MPU6050_PWR_MGMT_1, 0x00) < 0)
        return -1;

    /* Allow time for the sensor to stabilize after waking */
    usleep(100 * 1000);
    return 0;
}

static int mpu6050_read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(g_i2c_fd, MPU6050_ACCEL_XOUT_H, x) < 0)
        return -1;
    if (i2c_read_reg16(g_i2c_fd, MPU6050_ACCEL_XOUT_H + 2, y) < 0)
        return -1;
    if (i2c_read_reg16(g_i2c_fd, MPU6050_ACCEL_XOUT_H + 4, z) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    int16_t x[BUFFER_SIZE];
    int16_t y[BUFFER_SIZE];
    int16_t z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void cb_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, int16_t x, int16_t y, int16_t z)
{
    cb->x[cb->head] = x;
    cb->y[cb->head] = y;
    cb->z[cb->head] = z;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ------------------------------------------------------------------ */
/* Timer thread                                                     */
/* ------------------------------------------------------------------ */

static void timer_thread(void *arg)
{
    (void)arg;
    circular_buffer_t *cb = (circular_buffer_t *)arg;

    while (g_running) {
        int16_t x, y, z;
        if (mpu6050_read_accel(&x, &y, &z) == 0) {
            cb_push(cb, x, y, z);
        } else {
            /* Sensor absent or bus error: log and continue */
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        usleep(SAMPLE_PERIOD_NS);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (mpu6050_init() < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Create a POSIX timer thread */
    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN + 1;  /* RTMIN + 1 = timer thread */
    struct timer_attr attr;
    memset(&attr, 0, sizeof(attr));
    attr.it_interval = SAMPLE_PERIOD_NS;
    attr.it_value   = SAMPLE_PERIOD_NS;
    attr.it_flags   = 0;

    if (timer_create(CLOCK_MONOTONIC, &sev, &attr.timer_id) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    struct itimerspec its;
    its.it_value = attr.it_value;
    its.it_interval = attr.it_interval;
    its.it_value.tv_sec  = 0;
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec  = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;

    if (timer_settime(attr.timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        timer_delete(attr.timer_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Allocate circular buffer memory */
    circular_buffer_t *buffer = malloc(sizeof(circular_buffer_t));
    if (!buffer) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        timer_delete(attr.timer_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    cb_init(buffer);

    printf("MPU6050 logger started. Sampling at 100 Hz. Press Ctrl+C to stop.\n");

    /* Main loop: re-read the latest sample from the sysfs driver */
    while (g_running) {
        char path[256];
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");

        FILE *fp = fopen(path, "r");
        if (!fp) {
            fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
            usleep(SAMPLE_PERIOD_NS);
            continue;
        }

        int16_t x, y, z;
        if (fscanf(fp, "%d %d %d", &x, &y, &z) != 3) {
            fprintf(stderr, "Cannot parse latest sample; skipping.\n");
            fclose(fp);
            usleep(SAMPLE_PERIOD_NS);
            continue;
        }
        fclose(fp);

        cb_push(buffer, x, y, z);
        printf("X=%d  Y=%d  Z=%d\n", x, y, z);
        usleep(SAMPLE_PERIOD_NS);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    timer_delete(attr.timer_id);
    close(g_i2c_fd);
    free(buffer);
    return EXIT_SUCCESS;
}

