                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[i], strerror(errno));
                    goto cleanup;
                }
                relay_states[i] = 1;
            }
        }

        long long now = monotonic_seconds();
        if (now == 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (relay_states[0]) {
            if (now - RELAY1_INTERVAL_SEC >= 0) {
                if (gpiod_line_set_value(lines[0], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[0], strerror(errno));
                    goto cleanup;
                }
                relay_states[0] = 0;
            }
        } else if (now - RELAY1_INTERVAL_SEC >= 0) {
            if (gpiod_line_set_value(lines[0], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[0], strerror(errno));
                goto cleanup;
            }
            relay_states[0] = 1;
        }

        if (relay_states[1]) {
            if (now - RELAY2_INTERVAL_SEC >= 0) {
                if (gpiod_line_set_value(lines[1], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[1], strerror(errno));
                    goto cleanup;
                }
                relay_states[1] = 0;
            }
        } else if (now - RELAY2_INTERVAL_SEC >= 0) {
            if (gpiod_line_set_value(lines[1], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[1], strerror(errno));
                goto cleanup;
            }
            relay_states[1] = 1;
        }

        if (relay_states[2]) {
            if (now - RELAY3_INTERVAL_SEC >= 0) {
                if (gpiod_line_set_value(lines[2], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[2], strerror(errno));
                    goto cleanup;
                }
                relay_states[2] = 0;
            }
        } else if (now - RELAY3_INTERVAL_SEC >= 0) {
            if (gpiod_line_set_value(lines[2], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[2], strerror(errno));
                goto cleanup;
            }
            relay_states[2] = 1;
        }

        if (relay_states[3]) {
            if (now - RELAY4_INTERVAL_SEC >= 0) {
                if (gpiod_line_set_value(lines[3], 0) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[3], strerror(errno));
                    goto cleanup;
                }
                relay_states[3] = 0;
            }
        } else if (now - RELAY4_INTERVAL_SEC >= 0) {
            if (gpiod_line_set_value(lines[3], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n", pins[3], strerror(errno));
                goto cleanup;
            }
            relay_states[3] = 1;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

