#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_US 100000
#define RELAY_ON_TIME_US 3000000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s\n", ts);
    }
    fclose(fp);
    return 0;
}

static int activate_relay(void) {
    if (gpioWrite(RELAY_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on relay pin\n");
        return -1;
    }
    if (log_timestamp(LOG_FILE) < 0) {
        fprintf(stderr, "Failed to log timestamp\n");
    }
    printf("Relay activated\n");
    gpioDelay(RELAY_ON_TIME_US);
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed on relay pin\n");
        return -1;
    }
    printf("Relay deactivated\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for sound sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed to initialise relay pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_PIN, RELAY_PIN);

    while (program_running) {
        int sound = gpioRead(SOUND_SENSOR_PIN);
        if (sound < 0) {
            fprintf(stderr, "gpioRead failed on sound sensor pin\n");
            break;
        }
        if (sound == 1) {
            if (activate_relay() < 0) {
                fprintf(stderr, "Relay activation failed\n");
                break;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

