#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

#define BUFFER_SIZE 100
#define THRESHOLD 50.0

typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t h, l;
    if (i2c_read_reg8(fd, GYRO_XOUT_H, &h) < 0) return -1;
    if (i2c_read_reg8(fd, GYRO_YOUT_H, &l) < 0) return -1;
    int16_t raw_x = (int16_t)((h << 8) | l);
    int16_t raw_y = (int16_t)((h << 8) | l);
    int16_t raw_z = (int16_t)((h << 8) | l);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void buffer_add(CircularBuffer *buf, float x, float y, float z) {
    buf->x[buf->head] = x;
    buf->y[buf->head] = y;
    buf->z[buf->head] = z;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void callback(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > THRESHOLD) {
        printf("Angular velocity threshold exceeded: %.2f deg/s\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    CircularBuffer gyro_buffer = {0};
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    printf("Starting data acquisition. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
            usleep(100000);
            continue;
        }
        buffer_add(&gyro_buffer, x, y, z);
        callback(x, y, z);
        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

