/*
 * CO2 monitor for Raspberry Pi 3 Model B+
 * Sensor : MH-Z19B on /dev/serial0 @ 9600 baud
 * TXD    : GPIO14 (BCM)
 * RXD    : GPIO15 (BCM)
 * API    : JSON { "timestamp": "...", "co2_ppm": "...", "error": "..." }
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver_library -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define GPIO_TX          14
#define GPIO_RX          15
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5
#define RESPONSE_TIMEOUT  1000000  /* microseconds */
#define READ_RETRIES     3
#define READ_RETRY_DELAY 100000   /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;   /* 8 data bits */
    tty.c_cflag |= (CLOCAL | CREAD);                /* enable receiver */
    tty.c_cflag &= ~(PARENB | PARODD);              /* no parity */
    tty.c_cflag &= ~CSTOPB;                         /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;                         /* no hardware flow control */

    tty.c_iflag  = 0;                                /* raw input */
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);          /* no software flow control */
    tty.c_lflag  = 0;                                /* non-canonical */
    tty.c_oflag  = 0;                                /* raw output */

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;                             /* block up to 0.1 s */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* MH-Z19B read                                                        */
/* ------------------------------------------------------------------ */
/*
 * The MH-Z19B expects a 9-byte command sequence:
 *   0x02, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
 * Each byte is sent independently, then the device responds with
 * a 9-byte payload containing the ppm value (bytes 1..9).
 */
static int read_co2(int fd, uint8_t *data, size_t len)
{
    if (len < 9) {
        fprintf(stderr, "read_co2: request %zu bytes, need >= 9\n", len);
        return -1;
    }

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        ssize_t n = write(fd, data, len);
        if (n < 0) {
            fprintf(stderr, "write: %s\n", strerror(errno));
            usleep(READ_RETRY_DELAY);
            continue;
        }
        if ((size_t)n != len) {
            fprintf(stderr, "write: short write (%zd/%zu)\n", n, len);
            usleep(READ_RETRY_DELAY);
            continue;
        }

        /* Wait for the sensor to respond */
        usleep(100000);  /* 100 ms */

        ssize_t r = read(fd, data, len);
        if (r < 0) {
            fprintf(stderr, "read: %s\n", strerror(errno));
            usleep(READ_RETRY_DELAY);
            continue;
        }
        if (r != (ssize_t)len) {
            fprintf(stderr, "read: short read (%zd/%zu)\n", r, len);
            usleep(READ_RETRY_DELAY);
            continue;
        }

        /* Verify checksum */
        uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3] +
                                     data[4] + data[5] + data[6] + data[7] + data[8]);
        if (checksum != data[8]) {
            fprintf(stderr, "checksum mismatch: calc=0x%02X recv=0x%02X\n",
                    checksum, data[8]);
            usleep(READ_RETRY_DELAY);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "read_co2: failed after %d retries\n", READ_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                       */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint64_t timestamp_us, uint16_t ppm, int error)
{
    if (fp == NULL) {
        fprintf(stderr, "log_data: null file pointer\n");
        return -1;
    }

    if (error) {
        fprintf(fp, "{\"timestamp\": %llu, \"co2_ppm\": 0, \"error\": \"sensor_error\"}\n",
                (unsigned long long)timestamp_us);
    } else {
        fprintf(fp, "{\"timestamp\": %llu, \"co2_ppm\": %u, \"error\": \"none\"}\n",
                (unsigned long long)timestamp_us, (unsigned int)ppm);
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (g_err_fp == NULL) {
        fprintf(stderr, "log_error: error log not open\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(g_err_fp, "timestamp=? %s\n", msg);
    } else {
        fprintf(g_err_fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp != NULL) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (g_err_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", ERROR_LOG_FILE, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Initialize UART */
    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitor started. UART=%s @ 9600 baud, TX=GPIO%d, RX=GPIO%d\n",
           UART_DEVICE, GPIO_TX, GPIO_RX);
    printf("Logging to %s every %d seconds. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* Main loop */
    while (g_running) {
        uint8_t cmd[9] = {0x02, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        uint8_t data[9];

        if (read_co2(g_uart_fd, data, sizeof(data)) != 0) {
            log_error("CO2 read failed");
            /* Continue running; next iteration may succeed */
            continue;
        }

        uint64_t now = (uint64_t)clock() * 1000ULL;
        uint16_t ppm = (uint16_t)((data[1] << 8) | data[2]);

        if (log_data(g_log_fp, now, ppm, 0) != 0) {
            log_error("JSON write failed");
        }

        printf("CO2: %u ppm (timestamp: %llu us)\n", ppm, (unsigned long long)now);

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

