/*
 * HMC5883L heading monitor with hard-iron compensation and GPIO alert.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: HMC5883L magnetometer
 * Alert:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_alert hmc5883l_alert.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_alert
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x19          /* HMC5883L default address (SDA low) */
#define ALERT_GPIO         17
#define BUFFER_SIZE        100
#define DEVIATION_THRESHOLD 10.0          /* degrees */
#define TARGET_HEADING     90.0           /* degrees */
#define SAMPLE_PERIOD_US   100000        /* 100 ms */
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET (-50)

/* HMC5883L registers */
#define REG_CONFIG         0x00
#define REG_MODE           0x02
#define REG_DATA_X_MSB     0x03
#define REG_DATA_Z_MSB     0x05
#define REG_DATA_Y_MSB     0x07

/* Config: 3-wire mode, 15 Hz output data rate, continuous conversion */
#define CONFIG_CONTINUOUS  0x00
#define CONFIG_3WIRE       0x20

/* Mode: continuous conversion */
#define MODE_CONTINUOUS    0x00

/* ---- Data structures ---- */
typedef struct {
    time_t timestamp;
    double heading;          /* degrees */
} HeadingData;

typedef struct {
    HeadingData data[BUFFER_SIZE];
    int head;                 /* next write slot */
    int count;                /* valid entries */
} CircularBuffer;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static CircularBuffer g_buffer;

/* ---- Prototypes ---- */
static int  init_hmc5883l(void);
static int  read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
static double compensate_heading(int16_t x, int16_t y);
static void  buffer_add(CircularBuffer *cb, double heading);
static void  buffer_print(const CircularBuffer *cb);
static void  alert_callback(int gpio, int level, uint32_t tick, void *userdata);
static void  signal_handler(int sig);
static void  cleanup(void);

/* ---- Implementation ---- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int init_hmc5883l(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }

    /* Wake up: 3-wire mode, continuous conversion */
    if (i2cWriteByteData(g_i2c_handle, REG_CONFIG, CONFIG_3WIRE | CONFIG_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: failed to write config register.\n");
        return -1;
    }

    /* Start continuous conversion */
    if (i2cWriteByteData(g_i2c_handle, REG_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: failed to write mode register.\n");
        return -1;
    }

    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(g_i2c_handle, REG_DATA_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed.\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *z = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *y = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    return 0;
}

static double compensate_heading(int16_t x, int16_t y)
{
    double x_comp = (double)x - HARD_IRON_X_OFFSET;
    double y_comp = (double)y - HARD_IRON_Y_OFFSET;

    double heading = atan2(y_comp, x_comp) * 180.0 / M_PI;

    /* Normalize to [0, 360) */
    if (heading < 0.0)
        heading += 360.0;

    return heading;
}

static void buffer_add(CircularBuffer *cb, double heading)
{
    time(&cb->data[cb->head].timestamp);
    cb->data[cb->head].heading = heading;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void buffer_print(const CircularBuffer *cb)
{
    printf("\n--- Circular Buffer (%d entries) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char tbuf[32];
        struct tm *tm_info = localtime(&cb->data[idx].timestamp);
        if (tm_info)
            strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm_info);
        else
            snprintf(tbuf, sizeof(tbuf), "unknown");
        printf("[%s] Heading: %.2f degrees\n", tbuf, cb->data[idx].heading);
    }
    printf("-------------------------------------\n");
}

static void alert_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    double heading = compensate_heading(0, 0); /* placeholder */
    buffer_add(&g_buffer, heading);

    if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(500000); /* 500 ms */
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Initialize magnetometer */
    if (init_hmc5883l() != 0) {
        fprintf(stderr, "Error: HMC5883L initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    g_buffer.head  = 0;
    g_buffer.count = 0;

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Register alert callback */
    if (gpioSetAlertFuncEx(ALERT_GPIO, alert_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for GPIO %d.\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HMC5883L heading monitor running. Press Ctrl+C to exit.\n");
    printf("Target heading: %.1f degrees. Deviation threshold: %.1f degrees.\n",
           TARGET_HEADING, DEVIATION_THRESHOLD);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(&x, &y, &z) == 0) {
            double heading = compensate_heading(x, y);
            buffer_add(&g_buffer, heading);
            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Warning: magnetometer read failed, retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

