/*
 * Raspberry Pi 5 – BH1750 ambient light sensor → RGB lamp control
 *
 * Wiring:
 *   BH1750 SDA  → GPIO 2  (I2C bus 1 SDA)
 *   BH1750 SCL  → GPIO 3  (I2C bus 1 SCL)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   RGB RED     → GPIO 17 (BCM)
 *   RGB GREEN   → GPIO 27 (BCM)
 *   RGB BLUE    → GPIO 22 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o lighting lighting.c -lpigpio -lrt
 * Run:    sudo ./lighting
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define BH1750_ADDR        0x5C          /* 0x5C is the default / recommended
                                           address for the BH1750 on I2C bus 1 */

#define RED_PIN            17
#define GREEN_PIN          27
#define BLUE_PIN           22

#define LUX_THRESHOLD_LOW  50
#define LUX_THRESHOLD_MED  150
#define LUX_THRESHOLD_HIGH 300

#define LOG_FILE           "lighting_log.txt"
#define SAMPLE_PERIOD_US   1000000          /* 1 second */
#define CONVERSION_DELAY_US 120000           /* 120 ms (max conversion time ~120 ms) */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------ */
static int  bh1750_init(int fd);
static int  bh1750_read_lux(int fd, float *lux_out);
static void set_relay_colors(int red, int green, int blue);
static void log_data(float lux, int red, int green, int blue);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- BH1750 ---------------------------------- */
static int bh1750_init(int fd)
{
    /* Power on (bit 0 = 1) */
    if (i2cWriteByteData(fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "[BH1750] Failed to power on: %s\n", strerror(errno));
        return -1;
    }
    /* Wait for the first conversion to complete */
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    /*
     * The BH1750 one-shot measurement command (0x10) triggers a
     * single-shot conversion.  The result is returned in the
     * 2-byte data buffer at 0x00.
     */
    if (i2cWriteByteData(fd, 0x00, 0x10) < 0) {
        fprintf(stderr, "[BH1750] Failed to trigger conversion: %s\n",
                strerror(errno));
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    int raw = i2cReadWordData(fd, 0x00);
    if (raw < 0) {
        fprintf(stderr, "[BH1750] Failed to read conversion result: %s\n",
                strerror(errno));
        return -1;
    }

    /* The 16-bit result is in the lower 16 bits of the word (big-endian
