#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define DISTANCE_MIN 10
#define DISTANCE_MAX 100
#define DISTANCE_THRESHOLD 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4,
                           int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (gpioWrite(motor_a_in1, 1) < 0) return -1;
    if (gpioWrite(motor_a_in2, 0) < 0) return -1;
    if (gpioWrite(motor_b_in3, 1) < 0) return -1;
    if (gpioWrite(motor_b_in4, 0) < 0) return -1;

    if (gpioPWM(motor_a_in2, speed) < 0) return -1;
    if (gpioPWM(motor_b_in4, speed) < 0) return -1;

    return 0;
}

static int stop_motors(void) {
    int rc = 0;
    if (gpioWrite(MOTOR_A_IN1, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_B_IN3, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) rc = -1;
    if (gpioPWM(MOTOR_A_IN2, 0) < 0) rc = -1;
    if (gpioPWM(MOTOR_B_IN4, 0) < 0) rc = -1;
    return rc;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < DISTANCE_MIN || distance_a > DISTANCE_MAX ||
        distance_b < DISTANCE_MIN || distance_b > DISTANCE_MAX) {
        fprintf(stderr, "Distance values must be between %d and %d cm\n",
                DISTANCE_MIN, DISTANCE_MAX);
        return EXIT_FAILURE;
    }

    if (distance_a < distance_b) {
        int temp = distance_a;
        distance_a = distance_b;
        distance_b = temp;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Distance A: %d cm, Distance B: %d cm\n",
           distance_a, distance_b);

    while (running) {
        int speed_a = (distance_a < DISTANCE_THRESHOLD) ? distance_a : DISTANCE_THRESHOLD;
        int speed_b = (distance_b < DISTANCE_THRESHOLD) ? distance_b : DISTANCE_THRESHOLD;

        if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, speed_a) < 0) {
            fprintf(stderr, "Failed to set motor speed\n");
            break;
        }
        if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, speed_b) < 0) {
            fprintf(stderr, "Failed to set motor speed\n");
            break;
        }

        usleep(100000);
    }

    stop_motors();
    gpioTerminate();
    printf("Motor control stopped.\n");
    return EXIT_SUCCESS;
}

