/* ------------------------------------------------------------------ */
/* Lock / unlock sequence (four-step two-phase)                         */
/* ------------------------------------------------------------------ */
static void lock_sequence(void)
{
    /* Phase 1: IN1 IN2 IN3 IN4 */
    if (safe_write(IN1, 1) < 0) return;
    if (safe_write(IN2, 1) < 0) return;
    if (safe_write(IN3, 1) < 0) return;
    if (safe_write(IN4, 1) < 0) return;
