    if (safe_write(IN3, 1) < 0) return;
    if (safe_write(IN4, 1) < 0) return;
    gpioDelay(STEP_DELAY_US);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        /* De-energize all coils */
        safe_write(IN1, 0);
        safe_write(IN2, 0);
        safe_write(IN3, 0);
        safe_write(IN4, 0);
        g_pigpio_initialized = 0;
    }
