           "UNLOCK (GPIO23) to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_val = gpioRead(LOCK_BUTTON);
        int unlock_val = gpioRead(UNLOCK_BUTTON);

        if (lock_val < 0 || unlock_val < 0) {
            fprintf(stderr, "Warning: GPIO read error on button read\n");
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        if (lock_val == 0 && !lock_pressed) {
            lock_pressed = true;
            printf("LOCK pressed\n");
            lock_steps = 0;
            stepper_drive(step_sequence, 4);
            lock_steps = STEPS_PER_REV;
            gpioDelay(STEP_DELAY_US * lock_steps);
            lock_steps = 0;
            printf("Lock complete.\n");
        } else if (unlock_val == 0 && !unlock_pressed) {
            unlock_pressed = true;
            printf("UNLOCK pressed\n");
            unlock_steps = 0;
            stepper_drive(step_sequence, 4);
            unlock_steps = STEPS_PER_REV;
            gpioDelay(STEP_DELAY_US * unlock_steps);
            unlock_steps = 0;
            printf("Unlock complete.\n");
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
