#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <linux/pwm.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_NS 1000000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_mpu6050_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 14) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

static float calculate_pitch(int16_t ax, int16_t ay, int16_t az) {
    float roll = atan2((float)ay, (float)az) * 180.0 / M_PI;
    float pitch = atan2(-((float)ax), sqrt((float)ay * (float)ay + (float)az * (float)az)) * 180.0 / M_PI;
    return pitch;
}

static float calculate_roll(int16_t ax, int16_t ay, int16_t az) {
    float roll = atan2((float)ay, (float)az) * 180.0 / M_PI;
    float pitch = atan2(-((float)ax), sqrt((float)ay * (float)ay + (float)az * (float)az)) * 180.0 / M_PI;
    return roll;
}

static int set_servo_angle(int duty_ns) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *period_file = fopen(path, "w");
    if (!period_file) return -1;
    fprintf(period_file, "%d", PWM_PERIOD_NS);
    fclose(period_file);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    FILE *duty_file = fopen(path, "w");
    if (!duty_file) return -1;
    fprintf(duty_file, "%d", duty_ns);
    fclose(duty_file);

    return 0;
}

static void log_data(float pitch, float roll, int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d,%d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            pitch, roll, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 0;
        bool success = false;

        while (retries < MAX_RETRIES && running) {
            if (read_mpu6050_data(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                success = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries, MAX_RETRIES, strerror(errno));
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read MPU6050 after %d retries\n", MAX_RETRIES);
            continue;
        }

        float pitch = calculate_pitch(ax, ay, az);
        float roll = calculate_roll(ax, ay, az);

        int duty_ns = (int)(PWM_DUTY_NS * (pitch + 90.0f) / 180.0f);
        if (duty_ns < 0) duty_ns = 0;
        if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;

        if (set_servo_angle(duty_ns) < 0) {
            fprintf(stderr, "Failed to set servo angle: %s\n", strerror(errno));
        }

        log_data(pitch, roll, ax, ay, az, gx, gy, gz);
        usleep(100000);
    }

    cleanup();
    return 0;
}

