/*
 * Smart Home Lighting System for Raspberry Pi Zero W
 *
 * Reads a 24-hour schedule file (lighting_schedule.txt) and controls four
 * relay-controlled lamp actuators via GPIO4, GPIO17, GPIO27, and GPIO22.
 * A 30-minute fade is performed when a transition is required.
 *
 * Build: gcc -O2 -Wall -o lighting_system lighting_system.c -lpigpio -lrt
 * Run:   sudo ./lighting_system
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS 4
#define FADE_DURATION_SEC 1800
#define FADE_HZ 100
#define FADE_STEPS (FADE_DURATION_SEC * FADE_HZ / 1000)

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define SCHEDULE_FILE "lighting_schedule.txt"

typedef struct {
    int relay_pin;
    int on;
} Lamp;

static Lamp lamps[NUM_LAMPS] = {
    {RELAY1_PIN, 0},
    {RELAY2_PIN, 0},
    {RELAY3_PIN, 0},
    {RELAY4_PIN, 0}
};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *start_hour, int *start_minute, int *start_second) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int found = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *time_str = strtok(line, ";");
        if (!time_str) continue;

        char *endptr;
        int hour = strtol(time_str, &endptr, 10);
        if (endptr == time_str) continue;

        char *ampm = strtok(NULL, ";");
        if (!ampm) continue;

        char *relay_str = strtok(NULL, ";");
        if (!relay_str) continue;

        char *on_off = strtok(NULL, ";");
        if (!on_off) continue;

        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) {
            fprintf(stderr, "Invalid time format: %s\n", line);
            continue;
        }

        if (strcmp(ampm, "AM") == 0 && hour > 11) {
            hour -= 12;
            strcpy(ampm, "PM");
        } else if (strcmp(ampm, "PM") == 0 && hour <= 11) {
            hour += 12;
        }

        if (strcmp(relay_str, "1") == 0) lamps[0].relay_pin = RELAY1_PIN;
        else if (strcmp(relay_str, "2") == 0) lamps[0].relay_pin = RELAY2_PIN;
        else if (strcmp(relay_str, "3") == 0) lamps[0].relay_pin = RELAY3_PIN;
        else if (strcmp(relay_str, "4") == 0) lamps[0].relay_pin = RELAY4_PIN;
        else {
            fprintf(stderr, "Invalid relay number: %s\n", relay_str);
            continue;
        }

        if (strcmp(on_off, "on") == 0) lamps[0].on = 1;
        else if (strcmp(on_off, "off") == 0) lamps[0].on = 0;
        else {
            fprintf(stderr, "Invalid on/off value: %s\n", on_off);
            continue;
        }

        found = 1;
        break;
    }

    fclose(fp);

    if (!found) {
        fprintf(stderr, "No valid schedule entries found in file.\n");
        return -1;
    }

    *start_hour = hour;
    *start_minute = minute;
    *start_second = second;
    return 0;
}

static void set_lamp_state(int relay_pin, int on) {
    gpioWrite(relay_pin, on ? 1 : 0);
}

static void fade_lamps(int duration_sec) {
    int step = duration_sec / FADE_STEPS;
    if (step <= 0) step = 1;

    for (int i = 0; i < FADE_STEPS && running; i++) {
        for (int j = 0; j < NUM_LAMPS; j++) {
            int duty = (i * 100) / FADE_STEPS;
            set_lamps(j, duty);
        }
        gpioDelay(1000000 / FADE_HZ);
    }

    for (int i = 0; i < FADE_STEPS && running; i++) {
        for (int j = 0; j < NUM_LAMPS; j++) {
            int duty = (i * 100) / FADE_STEPS;
            set_lamps(j, duty);
        }
        gpioDelay(1000000 / FADE_HZ);
    }

    for (int i = 0; i < FADE_STEPS && running; i++) {
        for (int j = 0; j < NUM_LAMPS; j++) {
            int duty = (i * 100) / FADE_STEPS;
            set_lamps(j, duty);
        }
        gpioDelay(1000000 / FADE_HZ);
    }
}

static void set_lamps(int on) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        set_lamps(lamps[i].relay_pin, on);
    }
}

static void cleanup(void) {
    set_lamps(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        gpioSetMode(lamps[i].relay_pin, PI_OUTPUT);
        gpioWrite(lamps[i].relay_pin, 0);
    }

    int start_hour, start_minute, start_second;
    if (read_schedule(SCHEDULE_FILE, &start_hour, &start_minute, &start_second) != 0) {
        fprintf(stderr, "Error reading schedule file. Exiting.\n");
        cleanup();
        return 1;
    }

    time_t current_time = time(NULL);
    struct tm *current_tm = localtime(&current_time);
    if (!current_tm) {
        fprintf(stderr, "Error getting local time. Exiting.\n");
        cleanup();
        return 1;
    }

    int current_hour = current_tm->tm_hour;
    int current_minute = current_tm->tm_min;
    int current_second = current_tm->tm_sec;

    while (running) {
        if (current_hour != start_hour || current_minute != start_minute || current_second != start_second) {
            if (current_hour < 0 || current_hour > 23 || current_minute < 0 || current_minute > 59 || current_second < 0 || current_second > 59) {
                fprintf(stderr, "Invalid time. Exiting.\n");
                break;
            }

            if (current_hour == start_hour && current_minute == start_minute && current_second == start_second) {
                set_lamps(0);
            } else {
                set_lamps(1);
            }

            if (read_schedule(SCHEDULE_FILE, &start_hour, &start_minute, &start_second) != 0) {
                fprintf(stderr, "Error reading schedule file. Exiting.\n");
                break;
            }
        }

        current_time = time(NULL);
        current_tm = localtime(&current_time);
        if (current_tm) {
            current_hour = current_tm->tm_hour;
            current_minute = current_tm->tm_min;
            current_second = current_tm->tm_sec;
        }

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

