#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 10.0
#define MAX_DISTANCE_CM 400.0
#define MIN_FREQUENCY_HZ 50
#define MAX_FREQUENCY_HZ 20000
#define LOOP_DELAY_US 20000
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1;
    return 0;
}

static double measure_distance(void) {
    if (trigger_sensor() < 0) {
