#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_MAG_ADDR 0x1E
#define LSM303_MAG_CTRL_REG1 0x20
#define LSM303_MAG_CTRL_REG2 0x21
#define LSM303_MAG_OUT_X_L 0x28
#define LSM303_MAG_OUT_X_H 0x29
#define LSM303_MAG_OUT_Y_L 0x2A
#define LSM303_MAG_OUT_Y_H 0x2B
#define LSM303_MAG_OUT_Z_L 0x2C
#define LSM303_MAG_OUT_Z_H 0x2D

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "mag_log.csv"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (i2c_read_reg(fd, LSM303_MAG_OUT_X_L, &x_l) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_X_H, &x_h) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Y_L, &y_l) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Y_H, &y_h) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Z_L, &z_l) < 0) return -1;
    if (i2c_read_reg(fd, LSM303_MAG_OUT_Z_H, &z_h) < 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float x_mag = (float)x;
    float y_mag = (float)y;
    float z_mag = (float)z;

    float x_comp = x_mag - 10.0f;
    float y_comp = y_mag + 5.0f;
    float z_comp = z_mag - 20.0f;

    float heading = atan2f(y_comp, x_comp) * 180.0f / M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static const char *determine_compass_direction(float heading) {
    if (heading >= 337.5f && heading <= 0.0f) return "N";
    if (heading >= 337.5f - 45.0f && heading < 337.5f) return "NE";
    if (heading >= 337.5f - 90.0f && heading < 337.5f - 45.0f) return "E";
    if (heading >= 337.5f - 135.0f && heading < 337.5f - 90.0f) return "SE";
    if (heading >= 337.5f - 180.0f && heading < 337.5f - 135.0f) return "S";
    if (heading >= 337.5f - 225.0f && heading < 337.5f - 180.0f) return "SW";
    if (heading >= 337.5f - 270.0f && heading < 337.5f - 225.0f) return "W";
    if (heading >= 337.5f - 315.0f && heading < 337.5f - 270.0f) return "NW";
    return "Unknown";
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, %d, %d, %d, %.2f\n", timestamp, x, y, z, heading) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int16_t x, y, z;
    float heading;
    const char *direction;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_MAG_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to configure magnetometer control register 1\n");
        goto cleanup;
    }
    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Failed to configure magnetometer control register 2\n");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    printf("Starting magnetometer readings. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_magnetometer(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error, skipping sample\n");
        } else {
            heading = calculate_heading(x, y, z);
            direction = determine_compass_direction(heading);
            printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);

            if (log_data(fp, x, y, z, heading) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

