/*
 * TTP223 capacitive touch sensor -> relay toggle with software debounce.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: TTP223 on GPIO4 (BCM), pull-down
 * Relay:  5 V relay module on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_monitor relay_monitor.c -lpigpio -lrt
 * Run:    sudo ./relay_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEBOUNCE_US      200000   /* 200 ms */
#define POLL_DELAY_US    10000    /* 10 ms  */
#define LOG_FILE         "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_last_touch_tick = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
                ts, state ? "ON" : "OFF") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    if (gpioWrite(RELAY_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Interrupt service routine (ISR)                                       */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0)            /* only rising edge */
        return;

    uint32_t elapsed = tick - g_last_touch_tick;
    if (elapsed < DEBOUNCE_US)
        return;

    g_last_touch_tick = tick;

    int new_state = !gpioRead(RELAY_PIN);
    if (relay_set(new_state) != 0)
        return;

    if (log_relay_state(new_state) != 0)
        fprintf(stderr, "Warning: failed to log relay state\n");

    printf("Touch detected -> relay %s\n", new_state ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- relay pin as output, initial OFF ---- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- touch sensor pin as input with pull-down ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- register ISR ---- */
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0,
                         touch_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223 on GPIO%d, relay on GPIO%d. Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    /* ---- main loop: sleep until signal ---- */
    while (g_running) {
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Force relay OFF */
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) during shutdown failed\n");
    }

    /* Log final state */
    if (log_relay_state(0) != 0)
        fprintf(stderr, "Warning: failed to log final relay state\n");

    /* Unregister ISR */
    gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);

    /* Cleanup pigpio */
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

