#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define IRRIGATION_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO %d high\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Warning: failed to deactivate relay %zu\n", i);
        }
    }
}

static void log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level) < 0) {
            fprintf(stderr, "Error: failed to write to log file\n");
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error: failed to flush log file\n");
        }
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }
}

static int simulate_moisture_reading(void) {
    return rand() % 101;
}

int main(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int relay_number = 1;
    int moisture_level;
    int rc = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (log_file = fopen(LOG_FILE, "a") == NULL) {
        perror("fopen(" LOG_FILE ")");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        moisture_level = simulate_moisture_reading();

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d (below threshold %d)\n", moisture_level, MOISTURE_THRESHOLD);

            for (size_t i = 0; i < num_pins && running; ++i) {
                if (gpioWrite(pins[i], 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay %zu\n", i);
                    rc = EXIT_FAILURE;
                    goto cleanup;
                }
                printf("Activating relay %zu\n", i + 1);
                log_irrigation(i + 1, moisture_level);

                for (int s = 0; s < IRRIGATION_DURATION && running; ++s) {
                    sleep(1);
                }

                if (gpioWrite(pins[i], 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay %zu\n", i);
                    rc = EXIT_FAILURE;
                    goto cleanup;
                }
                printf("Deactivating relay %zu\n", i + 1);
                log_irrigation(i + 1, moisture_level);

                if (i < num_pins - 1) {
                    sleep(1);
                }
            }
        } else {
            printf("Moisture level: %d (above threshold %d)\n", moisture_level, MOISTURE_THRESHOLD);
        }

        for (int s = 0; s < IRRIGATION_INTERVAL && running; ++s) {
            sleep(1);
        }
    }

cleanup:
    deactivate_all_relays();
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose(log_file)");
            rc = EXIT_FAILURE;
        }
        log_file = NULL;
    }
    gpioTerminate();
    return rc;
}

