/*
 * Automated plant watering system for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - Valve servo:  SG90 on GPIO17 (physical pin 11, BCM)
 *   - Nozzle servo: SG90 on GPIO18 (physical pin 12, BCM)
 *
 * Library: pigpio (C API)
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

/* SG90 pulse-width limits (microseconds) */
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_OPEN_PULSE 1500  /* 90 degrees */

