/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int open_valve(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid valve angle %d (must be 0-180)\n", angle);
        return -1;
    }

    int pulse = SERVO_MIN_PULSE +
                (int)((float)angle / 180.0f * (float)(SERVO_MAX_PULSE - SERVO_MIN_PULSE));

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (gpioServo(VALVE_SERVO_PIN, pulse) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: gpioServo failed for valve (angle %d, pulse %d), attempt %d/%d\n",
                angle, pulse, attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES) {
            gpioDelay(BACKOFF_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: valve servo open failed after %d retries\n", MAX_RETRIES);
    return -1;
}

