        if (attempt < MAX_RETRIES) {
            gpioDelay(BACKOFF_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: valve servo close failed after %d retries\n", MAX_RETRIES);
    return -1;
}

