/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int spray_nozzle(int angles[], int num_angles)
{
    for (int i = 0; i < num_angles; ++i) {
        int angle = angles[i];
        int pulse = SERVO_MIN_PULSE +
                    (int)((float)angle / 180.0f * (float)(SERVO_MAX_PULSE - SERVO_MIN_PULSE));

        for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
            if (gpioServo(NOZZLE_SERVO_PIN, pulse) == 0) {
                return 0;
            }
            fprintf(stderr, "Warning: gpioServo failed for nozzle (angle %d, pulse %d), attempt %d/%d\n",
