#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define GYRO_XOUT_H    0x43
#define GYRO_YOUT_H    0x45
#define GYRO_ZOUT_H    0x47
#define SAMPLE_HZ      10
#define SAMPLE_PERIOD  (1000000 / SAMPLE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, 0x6A, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x6B, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x6C, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x6D, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x6E, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x6F, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x70, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x71, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x72, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x73, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x74, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x75, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x76, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x77, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x7B, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x7C, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x7D, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x7E, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x7F, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor may be absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("gyro_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open gyro_log.txt: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU6050 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error — continuing\n");
        } else {
            log_data(fp, x, y, z);
        }
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

