#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEP_DELAY_US 3000
#define STEPS_PER_ROTATION 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_step(int a, int b, int c, int d) {
    if (gpioWrite(IN1, a) < 0) return -1;
    if (gpioWrite(IN2, b) < 0) return -1;
    if (gpioWrite(IN3, c) < 0) return -1;
    if (gpioWrite(IN4, d) < 0) return -1;
    return 0;
}

static int rotate(int steps, int direction) {
    int step_sequence[8] = {1, 0, 0, 0, 1, 1, 0, 0};
    int *seq = step_sequence + (direction == 1 ? 0 : 8);

    for (int i = 0; i < steps && running; i++) {
        if (set_step(seq[i % 8], seq[(i + 1) % 8], seq[(i + 2) % 8], seq[(i + 3) % 8]) < 0) {
            fprintf(stderr, "Error: gpioWrite failed during step %d\n", i);
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    return rotate(STEPS_PER_ROTATION, 1);
}

static int unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    return rotate(STEPS_PER_ROTATION, -1);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(IN4, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door control system started. Press LOCK (GPIO24) to lock, UNLOCK (GPIO23) to unlock.\n");
    fflush(stdout);

    int last_lock_state = 0;
    int last_unlock_state = 0;

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed\n");
            break;
        }

        if (lock_state != last_lock_state) {
            if (lock_state == 1 && last_unlock_state == 0) {
                if (lock_door() < 0) {
                    fprintf(stderr, "Error: lock_door failed\n");
                    break;
                }
            } else if (lock_state == 0 && last_unlock_state == 1) {
                if (unlock_door() < 0) {
                    fprintf(stderr, "Error: unlock_door failed\n");
                    break;
                }
            }
            last_lock_state = lock_state;
        }

        if (unlock_state != last_unlock_state) {
            if (unlock_state == 1 && last_lock_state == 0) {
                if (unlock_door() < 0) {
                    fprintf(stderr, "Error: unlock_door failed\n");
                    break;
                }
            } else if (unlock_state == 0 && last_lock_state == 1) {
                if (lock_door() < 0) {
                    fprintf(stderr, "Error: lock_door failed\n");
                    break;
                }
            }
            last_unlock_state = unlock_state;
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

