#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define TRIGGER_US  10
#define LOOP_US     1000000 /* 1 s between samples */
#define MEASURE_US  60000   /* 60 ms between trigger + read */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns -1.0 on timeout or pigpio error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger low) failed: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger high) failed: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger low) failed: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    uint32_t echo_rise = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_rise) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t echo_fall = gpioTick();

    uint32_t pulse_us = echo_fall - echo_rise;
    /* distance = (pulse_us * 34300) / 2 / 1000000  (round trip, cm) */
    return (double)pulse_us * 34300.0 / 2000000.0;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance < 0.0) {
        fprintf(g_log, "%s, ERROR\n", timestamp);
    } else {
        fprintf(g_log, "%s, %.2f\n", timestamp, distance);
    }
    fflush(g_log);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file once and keep it open for the lifetime of the program */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(trigger) failed\n");
        gpioTerminate();
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(echo) failed\n");
        gpioTerminate();
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger init low) failed\n");
        gpioTerminate();
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Logging to %s every 1 s.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        double distance = measure_distance();
        log_distance(distance);
        gpioDelay(MEASURE_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

