/*
 * Raspberry Pi 4 Model B – VL53L1X distance monitor with relay control.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Relay IN    -> GPIO18 (BCM 18, pin 12) via suitable driver transistor
 *   Relay VCC   -> 3.3 V
 *   Relay GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 *   (pigpio must be run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define VL53L1X_ADDR         0x29       /* VL53L1X default I2C address (SDO tied to GND) */
#define RELAY_GPIO           18         /* BCM 18 */
#define DISTANCE_THRESHOLD   50         /* cm – relay ON when distance <= this */
#define POLL_INTERVAL_US     100000     /* 100 ms */
#define MAX_CONSECUTIVE_ERRORS 10        /* abort after this many I2C failures */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086

/* ----------------------------- Globals ----------------------------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
