    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;

    return 0;
}

/* ----------------------------- Sensor init -------------------------------- */
static int vl53l1x_init(int handle)
{
    /* Soft reset: write 0x00 to 0x0000 */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "[ERROR] VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms settle */

    /* Start continuous ranging mode */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "[ERROR] VL53L1X start ranging failed\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms settle */

    return 0;
}

/* ----------------------------- Distance read ------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Poll the data-ready bit (bit 0 of 0x0089) until it reads 0x01 */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "[ERROR] I2C read of range status failed\n");
            return -1;
