        if (status & 0x01)
            break;
        gpioDelay(5000);  /* 5 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "[ERROR] VL53L1X data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance (big-endian) from 0x0096 */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        fprintf(stderr, "[ERROR] I2C read of distance failed\n");
        return -1;
