/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are driven via the libgpiod API on BCM GPIO17,
 * GPIO18, GPIO27, and GPIO22 (physical pins 11, 12, 13, 15).
 *
 * The program activates each relay for 5 s, repeating the sequence once
 * every 86 400 s (24 h), with a 60 s poll interval.  Every GPIO and file
 * I/O operation is checked for errors, and the program exits cleanly on
 * SIGINT / SIGTERM.
 *
 * Build:  gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_ON_TIME   5          /* seconds */
#define POLL_INTERVAL   60         /* seconds */
#define CYCLE_PERIOD    86400       /* seconds (24 h) */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_start_time(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (chip)
            (void)gpiod_line_set_value(chip, relay_pins[i], 1);   /* inactive */
    }
    if (chip)
        gpiod_chip_close(chip);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
