/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are driven via the libgpiod API on BCM GPIO17,
 * GPIO18, GPIO27, and GPIO22 (physical pins 11, 12, 13, 15).
 *
 * The program activates each relay for 5 s, repeating the sequence once
 * every 86 400 s (24 h), with a 60 s poll interval.  Every GPIO and file
 * I/O operation is checked for errors, and the program exits cleanly on
 * SIGINT / SIGTERM.
 *
 * Build:  gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_ON_TIME   5          /* seconds */
#define POLL_INTERVAL   60         /* seconds */
#define CYCLE_PERIOD    86400       /* seconds (24 h) */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_start_time(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (chip)
            (void)gpiod_line_set_value(chip, relay_pins[i], 1);   /* inactive */
    }
    if (chip)
        gpiod_chip_close(chip);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try gpiochip0 on older kernels */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup(chip);
            return EXIT_FAILURE;
        }
    }

    /* Request all four lines as outputs, initially inactive (HIGH) */
    if (gpiod_line_request_output(lines[0], "watering", 1) != 0) {
        fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                relay_pins[0], strerror(errno));
        cleanup(chip);
        return EXIT_FAILURE;
    }
    for (int i = 1; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering", 1) != 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup(chip);
            return EXIT_FAILURE;
        }
    }

    if (log_start_time(LOG_FILE) != 0) {
        cleanup(chip);
        return EXIT_FAILURE;
    }

    time_t last_cycle = time(NULL);
    if (last_cycle == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        cleanup(chip);
        return EXIT_FAILURE;
    }

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            break;
        }

        /* Full cycle: activate each relay once, then wait CYCLE_PERIOD */
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) != 0) {
                fprintf(stderr, "Failed to set GPIO line %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                break;
            }
            sleep(RELAY_ON_TIME);
            if (gpiod_line_set_value(lines[i], 1) != 0) {
                fprintf(stderr, "Failed to set GPIO line %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                break;
            }
        }

        /* Sleep for the remainder of the 24-hour cycle */
        time_t remaining = now - last_cycle;
        if (remaining < 0)
            remaining += CYCLE_PERIOD;
        if (remaining > 0)
            sleep((useconds_t)remaining);

        last_cycle = now;
    }

    cleanup(chip);
    return EXIT_SUCCESS;
}

