#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOG_FILE "smart_lighting.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int setup_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int set_relay_intensity(int pin, int intensity) {
    if (intensity < 0 || intensity > PWM_RANGE) {
        fprintf(stderr, "Invalid intensity %d for GPIO %d\n", intensity, pin);
        return -1;
    }
    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio(RELAY1_PIN) != 0 ||
        setup_gpio(RELAY2_PIN) != 0 ||
        setup_gpio(RELAY3_PIN) != 0 ||
        setup_gpio(RELAY4_PIN) != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Smart lighting system started");

    int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

    for (int i = 0; i < num_relays; i++) {
        if (set_relay_intensity(relay_pins[i], 0) != 0) {
            log_event("Error setting initial relay intensity");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    log_event("Starting sunrise simulation");

    while (running) {
        for (int i = 0; i < num_relays; i++) {
            if (set_relay_intensity(relay_pins[i], PWM_RANGE) != 0) {
                log_event("Error setting relay intensity");
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        log_event("All relays set to full intensity");

        for (int i = 0; i < 30 && running; i++) {
            sleep(1);
            for (int j = 0; j < num_relays; j++) {
                if (set_relay_intensity(relay_pins[j], PWM_RANGE - (i + 1) * 64) != 0) {
                    log_event("Error setting relay intensity");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
            log_event("Relays gradually decreasing intensity");
        }
    }

    log_event("Smart lighting system stopped");
    for (int i = 0; i < num_relays; i++) {
        set_relay_intensity(relay_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

