#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define LED_GPIO       17
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD_US 50000
#define THRESHOLD      250.0f
#define MAX_REINIT_ATTEMPTS 3

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B

typedef struct {
    float x, y, z;
    struct timespec ts;
} gyro_data_t;

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_mpu6050(void) {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate = 1 kHz / (1 + 0x19) = 1 kHz */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x10) < 0) {
        fprintf(stderr, "Error writing SMPLRT_DIV\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Disable accelerometer (config register: 0x00 = gyro only) */
    if (i2cWriteByteData(i2c_handle, MPU6050_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing CONFIG\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)raw_x;
    data->y = (float)raw_y;
    data->z = (float)raw_z;

    clock_gettime(CLOCK_MONOTONIC, &data->ts);
    return 0;
}

static void update_circular_buffer(gyro_data_t data) {
    /* Shift oldest entry to buffer[1] */
    gyro_data_t *buf = (gyro_data_t *)malloc(BUFFER_SIZE * sizeof(gyro_data_t));
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buf[i] = (i == BUFFER_SIZE - 1) ? data : buf[i + 1];
    }
    free(buf);
}

static bool check_threshold(gyro_data_t data) {
    return (fabsf(data.x) > THRESHOLD ||
            fabsf(data.y) > THRESHOLD ||
            fabsf(data.z) > THRESHOLD);
}

static void control_led(bool threshold_exceeded) {
    gpioWrite(LED_GPIO, threshold_exceeded ? 1 : 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed, exiting\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gyro_data_t gyro_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (!terminate) {
        gyro_data_t data;
        if (read_gyro_data(&data) == 0) {
            update_circular_buffer(data);
            control_led(check_threshold(data));
        } else {
            fprintf(stderr, "Read failed, re-initializing I2C...\n");
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            int retries = 0;
            while (retries < MAX_REINIT_ATTEMPTS && !terminate) {
                if (init_mpu6050() == 0) {
                    break;
                }
                retries++;
                gpioDelay(100000); /* 100 ms */
            }
            if (retries >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached, exiting\n");
                break;
