#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define CS_LINE_NAME    "cs0"
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES     3

/* MPU-9250 register addresses */
#define MPU9250_REG_SMPLRT_DIV  0x19
#define MPU9250_REG_PWR_MGMT_1  0x6B
#define MPU9250_REG_GYRO_XOUT_H 0x43
#define MPU9250_REG_GYRO_YOUT_H 0x45
#define MPU9250_REG_GYRO_ZOUT_H 0x47

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_spi_fd = -1;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_chip = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mpu9250_reg(uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 2) == 0) {
            *val = rx[1];
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int read_mpu9250_gyro(float *x, float *y, float *z)
{
    uint8_t tx[7] = { (uint8_t)(MPU9250_REG_GYRO_XOUT_H | 0x80), 0, 0, 0, 0, 0, 0 };
    uint8_t rx[7] = { 0 };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 7) == 0) {
            int16_t raw_x = (int16_t)((rx[2] << 8) | rx[1]);
            int16_t raw_y = (int16_t)((rx[4] << 8) | rx[3]);
            int16_t raw_z = (int16_t)((rx[6] << 8) | rx[5]);
            *x = (float)raw_x / 131.0f;
            *y = (float)raw_y / 131.0f;
            *z = (float)raw_z / 131.0f;
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long nanos = ts.tv_nsec;
    if (fprintf(fp, "%s.%09ld,%.6f,%.6f,%.6f\n", timestamp, nanos, x, y, z) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return 1;
    }
    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_cs_line = NULL;
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Wake up MPU-9250: clear SLEEP bit in PWR_MGMT_1 */
    if (read_mpu9250_reg(MPU9250_REG_PWR_MGMT_1, &g) != 0) {
        fprintf(stderr, "Failed to read PWR_MGMT_1: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (g & 0x80) {
        g &= 0xFF;
        if (write(g_spi_fd, &g, 1) != 1) {
            fprintf(stderr, "Failed to write PWR_MGMT_1: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    /* Sample rate divider: 1 kHz / (1 + SMPLRT_DIV) */
    if (read_mpu9250_reg(MPU9250_REG_SMPLRT_DIV, &g) != 0) {
        fprintf(stderr, "Failed to read SMPLRT_DIV: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (g & 0x07) {
        g &= 0x0F;
        if (write(g_spi_fd, &g, 1) != 1) {
            fprintf(stderr, "Failed to write SMPLRT_DIV: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-9250 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_mpu9250_gyro(&x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

