/*
 * MPU-6050 Gyroscope Monitor with SPI and GPIO Alert
 * Board:  Raspberry Pi 3 Model B+
 * SPI:    CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 * LED:    GPIO17 (BCM, physical pin 11)
 *
 * Reads angular velocity from an MPU-6050 via SPI and stores samples
 * in a 64-entry in-memory circular buffer.  When any axis exceeds
 * +/−200 °/s a warning LED blinks for 500 ms.  SIGINT triggers a
 * CSV dump of the buffer and clean shutdown.
 *
 * Build:  gcc -O2 -Wall -o mpu6050_monitor mpu6050_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      3900000    /* 3.9 MHz — well within MPU-6050 2-wire limit */
#define SPI_MODE       0          /* SPI mode 0, MSB first */
#define SPI_FLAGS      0          /* default: active-low CE, 8-bit words */

#define LED_PIN        17         /* BCM 17, physical pin 11 */
#define THRESHOLD      200.0f     /* deg/s */
#define BUFFER_SIZE    64
#define SAMPLE_DELAY_US 10000     /* 10 ms between samples */
#define LED_ON_US      500000     /* 500 ms LED pulse */
#define LED_OFF_US     500000     /* 500 ms LED gap */
#define MAX_SPI_RETRIES 3

/* MPU-6050 registers (SPI, 8-bit, big-endian) */
#define MPU6050_REG_SMPLRT_DIV  0x19
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1  0x6B

/* ----------------------------- Globals ---------------------------------- */
static int      spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Data ------------------------------------- */
typedef struct {
    time_t     timestamp;
    float      gyro_x, gyro_y, gyro_z;
} gyro_sample_t;

typedef struct {
    gyro_sample_t samples[BUFFER_SIZE];
    int           head;
    int           count;
} circular_buffer_t;

static circular_buffer_t buffer;

/* ----------------------------- Prototypes ------------------------------- */
static int  spi_init(void);
static int  spi_read_register(uint8_t reg, uint8_t *val);
static int  spi_write_register(uint8_t reg, uint8_t val);
static int  read_gyro(float *gx, float *gy, float *gz);
static void buffer_add(float gx, float gy, float gz);
static void check_threshold(float gx, float gy, float gz);
static void led_pulse(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI helpers ------------------------------ */
static int spi_init(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE | SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", spi_handle);
        return -1;
    }
    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *val)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);  /* read bit */
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI read failed for reg 0x%02X.\n", reg);
        return -1;
    }
    *val = (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t val)
{
    char tx[2];
    tx[0] = (char)(reg & 0x7F);  /* write bit */
    tx[1] = (char)val;

    if (spiXfer(spi_handle, tx, NULL, 2) != 2) {
        fprintf(stderr, "Error: SPI write failed for reg 0x%02X.\n", reg);
        return -1;
    }
    return 0;
}

/* ----------------------------- Gyro read -------------------------------- */
static int read_gyro(float *gx, float *gy, float *gz)
{
    uint8_t xh, xl, yh, yl, zh, zl;

    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H, &xh) != 0)
        return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 1, &xl) != 0)
        return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 2, &yh) != 0)
        return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 3, &yl) != 0)
        return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 4, &zh) != 0)
        return -1;
    if (spi_read_register(MPU6050_REG_GYRO_XOUT_H + 5, &zl) != 0)
        return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *gx = (float)raw_x / 131.0f;
    *gy = (float)raw_y / 131.0f;
    *gz = (float)raw_z / 131.0f;
    return 0;
}

/* ----------------------------- Buffer ------------------------------------ */
static void buffer_add(float gx, float gy, float gz)
{
    buffer.samples[buffer.head].timestamp  = time(NULL);
    buffer.samples[buffer.head].gyro_x    = gx;
    buffer.samples[buffer.head].gyro_y    = gy;
    buffer.samples[buffer.head].gyro_z    = gz;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE)
        buffer.count++;
}

static void check_threshold(float gx, float gy, float gz)
{
    if (fabsf(gx) > THRESHOLD || fabsf(gy) > THRESHOLD || fabsf(gz) > THRESHOLD) {
        led_pulse();
    }
}

static void led_pulse(void)
{
    if (gpioWrite(LED_PIN, 1) != 0)
        fprintf(stderr, "Warning: gpioWrite(1) failed on LED.\n");
    gpioDelay(LED_ON_US);
    if (gpioWrite(LED_PIN, 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(0) failed on LED.\n");
    gpioDelay(LED_OFF_US);
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure MPU-6050: wake from sleep, sample rate 1 kHz, gyro full res */
    if (spi_write_register(MPU6050_REG_PWR_MGMT_1, 0x00) != 0 ||
        spi_write_register(MPU6050_REG_SMPLRT_DIV, 0x07) != 0 ||
        spi_write_register(MPU6050_REG_GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: MPU-6050 configuration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(100000);  /* 100 ms */

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed; Ctrl-C will not clean up.\n");
    }

    printf("MPU-6050 monitoring started.  SPI ch%d @ %d Hz, LED on GPIO%d.\n",
           SPI_CHANNEL, SPI_SPEED, LED_PIN);
    printf("Threshold: +/−%.1f °/s.  Press Ctrl-C to exit.\n", THRESHOLD);

    /* Main loop */
    while (running) {
        float gx, gy, gz;

        if (read_gyro(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Error: gyro read failed; skipping sample.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        buffer_add(gx, gy, gz);
        check_threshold(gx, gy, gz);

        printf("%ld,%.2f,%.2f,%.2f\n",
               (long)buffer.samples[buffer.head].timestamp,
               buffer.samples[buffer.head].gyro_x,
               buffer.samples[buffer.head].gyro_y,
               buffer.samples[buffer.head].gyro_z);

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

