#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x18
#define LED_GPIO 17
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        return -1;
    }

    return 0;
}

static int si1145_read_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_vis_data0 = 0, als_vis_data1 = 0, ps1_data0 = 0, ps1_data1 = 0;

    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &als_vis_data0) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA1, &als_vis_data1) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA0, &ps1_data0) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA1, &ps1_data1) < 0) return -1;

    *ambient_light = (uint16_t)((als_vis_data0 << 8) | als_vis_data1);
    *proximity = (uint16_t)((ps1_data0 << 8) | ps1_data1);

    return 0;
}

static int log_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void control_led(uint16_t proximity) {
    if (proximity > 100) {
        if (gpioWrite(LED_GPIO, 1) < 0) {
            fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
        }
    } else {
        if (gpioWrite(LED_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
        }
    }
}

int main(void) {
    uint16_t ambient_light, proximity;
    int retries;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    gpioWrite(LED_GPIO, 0);

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (si1145_read_data(i2c_fd, &ambient_light, &proximity) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(ambient_light, proximity) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        control_led(proximity);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

