#define LOG_FILE     "seismic_events.txt"
#define ALERT_DURATION_MS 2000
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            log_event("Sensor 1: Tilt detected (rising edge)");
        } else if (level == 0) {
            log_event("Sensor 1: Tilt released (falling edge)");
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            log_event("Sensor 2: Tilt detected (rising edge)");
        } else if (level == 0) {
            log_event("Sensor 2: Tilt released (falling edge)");
        }
    }
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        log_event("Error: Failed to set alert pin HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        log_event("Error: Failed to set alert pin LOW");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Error: Failed to register callback for sensor pins\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Application started: Seismic monitoring system");

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Application shutting down");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

