/*
 * ADXRS290 dual-axis MEMS gyroscope reader for Raspberry Pi Zero W.
 *
 * Hardware SPI0: CE0=GPIO8 (BCM), SCLK=GPIO11 (BCM), MOSI=GPIO10 (BCM),
 *               MISO=GPIO9  (BCM).  The ADXRS290 is configured for read
 *               mode (MSB=1) and the data payload is returned in the
 *               16-bit register address.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:    sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_PIN        17         /* BCM 17 */
#define RATE_THRESHOLD 20.0f      /* degrees/second */
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  100000     /* microseconds (100 ms) */

/* ADXRS290 register address: MSB=1 for read, LSB=0 for X-axis.
 * The 16-bit address is returned as the data payload. */
#define ADXRS290_READ_ADDR 0x0001
#define ADXRS290_DATA_REG 0x0000

/* ----------------------------- Data types ------------------------------- */
typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static circular_buffer_t g_buffer;
static pthread_t g_buffer_thread;

/* ----------------------------- Prototypes ------------------------------- */
static int  spi_init(void);
static int  spi_transfer(uint8_t *tx, uint8_t *rx, int len);
static int  read_gyro_rate(float *rate);
static void buffer_add(circular_buffer_t *buf, const gyro_data_t *d);
static void *buffer_thread(void *arg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI -------------------------------------- */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/*
 * ADXRS290 read sequence:
 *   1. Write 16-bit address (MSB=1) to the device.
 *   2. Read 16-bit data payload.
 *   3. The 16-bit address is returned as the data payload.
 */
static int spi_transfer(uint8_t *tx, uint8_t *rx, int len)
{
    if (len < 0 || len > 32) {
        fprintf(stderr, "spi_transfer: invalid length %d\n", len);
        return -1;
    }

    /* ADXRS290 read: write 16-bit address, then read 16-bit data. */
    uint8_t addr[2] = { (uint8_t)(ADXRS290_READ_ADDR >> 8),
                        (uint8_t)(ADXRS290_READ_ADDR & 0xFF) };
    uint8_t data[2] = {0, 0};

    if (spiXfer(g_spi_handle, (char *)addr, (char *)data, 2) != 2) {
        fprintf(stderr, "spiXfer (addr) failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }

    if (spiXfer(g_spi_handle, (char *)data, (char *)data, 2) != 2) {
        fprintf(stderr, "spiXfer (data) failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }

    memcpy(tx, data, len);
    return 0;
}

/* ----------------------------- Gyro read -------------------------------- */
static int read_gyro_rate(float *rate)
{
    uint8_t tx[32] = {0};
    uint8_t rx[32] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) != 0)
        return -1;

    /* rx[0..1] = 16-bit address returned by the device. */
    uint16_t addr = ((uint16_t)rx[0] << 8) | rx[1];
    if (addr != ADXRS290_READ_ADDR) {
        fprintf(stderr, "Unexpected read address: 0x%04X\n", addr);
        return -1;
    }

    /* rx[2..17] = 16-bit data payload. */
    int16_t raw = ((int16_t)rx[2] << 8) | rx[3];
    *rate = (float)raw / 32768.0f;   /* 1 LSB = 1 deg/s */
    return 0;
}

/* ----------------------------- Circular buffer -------------------------- */
static void buffer_add(circular_buffer_t *buf, const gyro_data_t *d)
{
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = *d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void *buffer_thread(void *arg)
{
    (void)arg;
    circular_buffer_t *buf = &g_buffer;

    while (g_running) {
        gyro_data_t d;
        if (read_gyro_rate(&d.timestamp) != 0) {
            fprintf(stderr, "Gyro read failed; skipping sample.\n");
            struct timespec ts = {0, SAMPLE_PERIOD * 1000};
            nanosleep(&ts, NULL);
            continue;
        }

        d.rate = d.timestamp.tv_sec + d.timestamp.tv_nsec / 1e9f;
        buffer_add(buf, &d);
        struct timespec ts = d.timestamp;
        printf("Rate: %+.2f deg/s  |  Timestamp: %ld.%09ld\n",
               d.rate, (long)ts.tv_sec, (long)ts.tv_nsec);
        fflush(stdout);

        struct timespec rem = {0, SAMPLE_PERIOD * 1000};
        nanosleep(&rem, NULL);
    }
    return NULL;
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    pthread_join(g_buffer_thread, NULL);
    pthread_mutex_destroy(&g_buffer.mutex);
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    memset(&g_buffer, 0, sizeof(g_buffer));
    if (pthread_mutex_init(&g_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "pthread_mutex_init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start buffer thread */
    if (pthread_create(&g_buffer_thread, NULL, buffer_thread, NULL) != 0) {
        fprintf(stderr, "pthread_create failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring ADXRS290 (SPI0 CE0, 1 MHz, mode 0). "
           "Threshold: %.1f deg/s. Press Ctrl+C to exit.\n",
           RATE_THRESHOLD);

    /* Main loop */
    while (g_running) {
        float rate;
        if (read_gyro_rate(&rate) != 0) {
            fprintf(stderr, "Gyro read failed; continuing.\n");
            struct timespec ts = {0, SAMPLE_PERIOD * 1000};
            nanosleep(&ts, NULL);
            continue;
        }

        if (rate > RATE_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        struct timespec ts = {0, SAMPLE_PERIOD * 1000};
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

