#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_FREQ 100
#define PWM_RANGE 255
#define FADE_STEP 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d (brightness %d)\n", pin, brightness);
        return -1;
    }
    return 0;
}

static void fade_lamp(int pin, int duration, int start_brightness, int end_brightness) {
    if (start_brightness >= end_brightness) return;
    int step = (end_brightness - start_brightness) / duration;
    int elapsed = 0;
    int brightness = start_brightness;
    while (g_running && elapsed < duration && brightness <= end_brightness) {
        if (set_lamp_brightness(pin, brightness) != 0) return;
        brightness += step;
        elapsed++;
        gpioDelay(1000000 / PWM_FREQ);
    }
    if (set_lamp_brightness(pin, 0) != 0) return;
}

static void cleanup(void) {
    set_lamp_brightness(LAMP1_PIN, 0);
    set_lamp_brightness(LAMP2_PIN, 0);
    set_lamp_brightness(LAMP3_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration <= 0 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be between 1 and %d seconds\n", MAX_DURATION);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
