#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5D
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_US 100000
#define POLL_DELAY_US 10000
#define LOG_FILE "touch_relay.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_init(int handle) {
    if (i2cWriteByteData(handle, 0x80, 0x63) < 0) return -1;
    if (i2cWriteByteData(handle, 0x5B, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x5C, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, 0x5D, 0x04) < 0) return -1;
    if (i2cWriteByteData(handle, 0x5E, 0x0C) < 0) return -1;
    if (i2cWriteByteData(handle, 0x7B, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x7C, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x7D, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x7E, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x7F, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, 0x80, 0x63) < 0) return -1;
    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, 0x00, buf, 2) != 2) return -1;
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void toggle_relay(int gpio) {
    int current = gpioRead(gpio);
    if (current < 0) {
        log_error("Failed to read GPIO state");
        return;
    }
    if (gpioWrite(gpio, !current) < 0) {
        log_error("Failed to write GPIO state");
        return;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t prev_touch = 0;
    bool relay_state = false;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_handle, &touch_status) < 0) {
            log_error("Failed to read touch status from MPR121");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool electrode0_touched = (touch_status & 0x0001) != 0;

        if (electrode0_touched && !relay_state) {
            toggle_relay(RELAY_GPIO);
            relay_state = true;
        } else if (!electrode0_touched && relay_state) {
            toggle_relay(RELAY_GPIO);
            relay_state = false;
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return EXIT_SUCCESS;
}

