#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define LOOP_DELAY_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_dispense(int sol1, int sol2, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, GPIO%d, GPIO%d, %d ms\n", ts, sol1, sol2, duration_ms);
    } else {
        fprintf(fp, "(time-error), GPIO%d, GPIO%d, %d ms\n", sol1, sol2, duration_ms);
    }
    fclose(fp);
    return 0;
}

static int dispense(int sol1_pin, int sol2_pin, int duration_ms) {
    if (gpioWrite(sol1_pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", sol1_pin);
        return -1;
    }
    if (gpioWrite(sol2_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", sol2_pin);
        gpioWrite(sol1_pin, 0);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(sol1_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", sol1_pin);
        return -1;
    }
    if (gpioWrite(sol2_pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", sol2_pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;
    while (g_running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        if (!g_running) break;
        if (dispense(SOLENOID_2_PIN, SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        if (!g_running) break;
        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    return rc;
}

