        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(ENA, PI_OUTPUT) != 0 ||
        gpioSetMode(ENB, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(ENA, 1) != 0 || gpioWrite(ENB, 1) != 0) {
        fprintf(stderr, "Error: failed to set ENA/ENB HIGH\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

static void set_motor_speed(int motor, int speed) {
    if (speed < -255 || speed > 255) {
        fprintf(stderr, "Error: speed %d out of range [-255, 255]\n", speed);
        return;
    }
    if (motor == MOTOR_A_FORWARD) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor == MOTOR_A_BACKWARD) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
    } else if (motor == MOTOR_B_FORWARD) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else if (motor == MOTOR_B_BACKWARD) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
    } else {
        fprintf(stderr, "Error: invalid motor %d\n", motor);
        return;
    }
    gpioPWM(ENA, speed);
    gpioPWM(ENB, speed);
}

static void stop_motors(void) {
    set_motor_speed(MOTOR_A_FORWARD, 0);
    set_motor_speed(MOTOR_A_BACKWARD, 0);
    set_motor_speed(MOTOR_B_FORWARD, 0);
    set_motor_speed(MOTOR_B_BACKWARD, 0);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

static float calculate_tilt_error(float distance) {
    return (float)rand() / (float)RAND_MAX * 20.0f - 10.0f;
}

static float calculate_distance(void) {
    return (float)rand() / (float)RAND_MAX * 398.0f + 2.0f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Self-balancing robot started. Press Ctrl+C to stop.\n");

    while (running) {
        float tilt_error = calculate_tilt_error(0.0f);
        float distance = calculate_distance();

        if (distance < OBSTACLE_DISTANCE_THRESHOLD) {
            set_motor_speed(MOTOR_A_FORWARD, 50);
            set_motor_speed(MOTOR_B_FORWARD, 50);
            set_motor_speed(MOTOR_A_BACKWARD, 50);
            set_motor_speed(MOTOR_B_BACKWARD, 50);
        } else {
            int motor_a_speed = (int)(Kp * tilt_error + Ki * (distance - OBSTACLE_DISTANCE_THRESHOLD) + Kd * (tilt_error - (distance - OBSTACLE_DISTANCE_THRESHOLD)));
            int motor_b_speed = (int)(Kp * tilt_error + Ki * (distance - OBSTACLE_DISTANCE_THRESHOLD) + Kd * (tilt_error - (distance - OBSTACLE_DISTANCE_THRESHOLD)));

            if (motor_a_speed < -255) motor_a_speed = -255;
            if (motor_a_speed > 255) motor_a_speed = 255;
            if (motor_b_speed < -255) motor_b_speed = -255;
            if (motor_b_speed > 255) motor_b_speed = 255;

            set_motor_speed(MOTOR_A_FORWARD, motor_a_speed);
            set_motor_speed(MOTOR_A_BACKWARD, 0);
            set_motor_speed(MOTOR_B_FORWARD, motor_b_speed);
            set_motor_speed(MOTOR_B_BACKWARD, 0);
        }

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

