#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
        return -1;
    }
    return value;
}

static int toggle_relay(void) {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d.\n", RELAY_PIN);
        return -1;
    }

    if (gpioWrite(RELAY_PIN, !current_state) != 0) {
        fprintf(stderr, "Error: failed to write to GPIO%d.\n", RELAY_PIN);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_detected = read_touch_sensor();
        if (touch_detected < 0) {
            fprintf(stderr, "Warning: sensor read error, continuing.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_detected == 1) {
            printf("Touch detected! Relaying activated.\n");
            if (toggle_relay() != 0) {
                fprintf(stderr, "Warning: relay toggle failed.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

