#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define DEFAULT_DEVICE      "default"
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0
#define DEFAULT_GPIO_RED    17
#define DEFAULT_GPIO_GREEN  18
#define DEFAULT_GPIO_BLUE   27
#define DEFAULT_PWM_RANGE   255
#define DEFAULT_PWM_FREQ    1000
#define DEFAULT_PWM_DUTY    128
#define DEFAULT_PWM_DELAY   1
#define DEFAULT_PWM_MODE    0

#define PWM_FREQ_HZ         1000
#define PWM_RANGE           255
#define PWM_DUTY_ON         128
#define PWM_DUTY_OFF        0

#define SAMPLE_RATE_HZ      DEFAULT_SAMPLE_RATE
#define PERIOD_SIZE         DEFAULT_PERIOD_SIZE
#define SENSITIVITY         DEFAULT_SENSITIVITY
#define GATE_DELAY_US       10000
#define LOOP_DELAY_US       10000

typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_alsa_available = 0;
static volatile sig_atomic_t g_alsa_initialized = 0;
static volatile sig_atomic_t g_alsa_handle = -1;
static volatile sig_atomic_t g_alsa_state = 0;
static volatile sig_atomic_t g_alsa_suspended = 0;
static volatile sig_atomic_t g_alsa_prepared = 0;
static volatile sig_atomic_t g_alsa_resumed = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_alsa_handle >= 0) {
        snd_pcm_drain(g_alsa_handle);
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = -1;
    }
    if (g_alsa_initialized) {
        gpioPWM(g_alsa_gpio_red, 0);
        gpioPWM(g_alsa_gpio_green, 0);
        gpioPWM(g_alsa_gpio_blue, 0);
        gpioTerminate();
        g_alsa_initialized = 0;
    }
    g_alsa_prepared = 0;
    g_alsa_resumed = 0;
    g_alsa_suspended = 0;
    g_alsa_state = 0;
    g_alsa_available = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(g_alsa_gpio_red, PI_OUTPUT);
    gpioSetMode(g_alsa_gpio_green, PI_OUTPUT);
    gpioSetMode(g_alsa_gpio_blue, PI_OUTPUT);
    gpioSetPWMfrequency(g_alsa_gpio_red, PWM_FREQ_HZ);
    gpioSetPWMfrequency(g_alsa_gpio_green, PWM_FREQ_HZ);
    gpioSetPWMfrequency(g_alsa_gpio_blue, PWM_FREQ_HZ);
    gpioSetPWMrange(g_alsa_gpio_red, PWM_RANGE);
    gpioSetPWMrange(g_alsa_gpio_green, PWM_RANGE);
    gpioSetPWMrange(g_alsa_gpio_blue, PWM_RANGE);
    return 0;
}

static int init_leds(void) {
    if (init_gpio() != 0) {
        return -1;
    }
    gpioPWM(g_alsa_gpio_red, PWM_DUTY_OFF);
    gpioPWM(g_alsa_gpio_green, PWM_DUTY_OFF);
    gpioPWM(g_alsa_gpio_blue, PWM_DUTY_OFF);
    return 0;
}

static int init_alsa(void) {
    g_alsa_available = 0;
    g_alsa_prepared = 0;
    g_alsa_resumed = 0;
    g_alsa_suspended = 0;
    g_alsa_state = 0;
    g_alsa_handle = -1;

    if (snd_module_open(&g_alsa_handle, NULL, 0, NULL) < 0) {
        fprintf(stderr, "Error: snd_module_open failed: %s\n", strerror(errno));
        return -1;
    }
    g_alsa_available = 1;

    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_hw_params_alloca(&hw_params);
    if (snd_pcm_hw_params_any(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_any failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_access(g_alsa_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_access failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_format(g_alsa_handle, hw_params, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_format failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_channels(g_alsa_handle, hw_params, 1) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_channels failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_rate_near(g_alsa_handle, hw_params, &SAMPLE_RATE_HZ, 0) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_rate_near failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_period_size_near(g_alsa_handle, hw_params, &PERIOD_SIZE, 0) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_period_size_near failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params failed: %s\n", strerror(errno));
        return -1;
    }
    g_alsa_prepared = 1;
    return 0;
}

static int open_alsa_stream(void) {
    snd_pcm_stream_t stream = SND_PCM_STREAM_RECEIVE;
    snd_pcm_uframes_t frame_size = PERIOD_SIZE;
    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_hw_params_alloca(&hw_params);
    int err = 0;

    if (snd_pcm_open(&g_alsa_handle, DEFAULT_DEVICE, stream, 0) < 0) {
        fprintf(stderr, "Error: snd_pcm_open failed: %s\n", strerror(errno));
        return -1;
    }
    g_alsa_state = 0;
    g_alsa_suspended = 0;

    if (snd_pcm_hw_params_any(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_any failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_access(g_alsa_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_access failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_format(g_alsa_handle, hw_params, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_format failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_channels(g_alsa_handle, hw_params, 1) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_channels failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_rate_near(g_alsa_handle, hw_params, &SAMPLE_RATE_HZ, 0) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_rate_near failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params_set_period_size_near(g_alsa_handle, hw_params, &PERIOD_SIZE, 0) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_period_size_near failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_hw_params(g_alsa_handle, hw_params) < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params failed: %s\n", strerror(errno));
        return -1;
    }
    if (snd_pcm_prepare(g_alsa_handle) < 0) {
        fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n", strerror(errno));
        return -1;
    }
    g_alsa_prepared = 1;
    return 0;
}

static int start_alsa_stream(void) {
    if (!g_alsa_prepared) {
        fprintf(stderr, "Error: ALSA stream not prepared\n");
        return -1;
    }
    if (g_alsa_suspended) {
        fprintf(stderr, "Error: ALSA stream suspended\n");
        return -1;
    }
    if (snd_pcm_prepare(g_alsa_handle) < 0) {
        fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n", strerror(errno));
        return -1;
    }
    g_alsa_suspended = 1;
    return 0;
}

static int stop_alsa_stream(void) {
    if (g_alsa_suspended) {
        g_alsa_suspended = 0;
    }
    if (g_alsa_prepared) {
        snd_pcm_drain(g_alsa_handle);
        snd_pcm_close(g_alsa_handle);
        g_alsa_handle = -1;
        g_alsa_prepared = 0;
    }
    return 0;
}

static int read_alsa_buffer(short *buffer, int buffer_size) {
    if (g_alsa_suspended) {
        fprintf(stderr, "Error: ALSA stream suspended\n");
        return -1;
    }
    if (g_alsa_state == 0) {
        if (snd_pcm_prepare(g_alsa_handle) < 0) {
            fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n", strerror(errno));
            return -1;
        }
        g_alsa_state = 1;
    }
    int frames = snd_pcm_readi(g_alsa_handle, buffer, buffer_size);
    if (frames < 0) {
        fprintf(stderr, "Error: snd_pcm_readi failed: %s\n", strerror(errno));
        return -1;
    }
    if (frames == 0) {
        fprintf(stderr, "Error: snd_pcm_readi returned 0 (no data)\n");
        return -1;
    }
    g_alsa_state = 0;
    return 0;
}

static double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * (double)buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

static RGBColor map_amplitude_to_color(double amplitude) {
    RGBColor color = {0, 0, 0};
    if (amplitude > 1.0) amplitude = 1.0;
    if (amplitude < -1.0) amplitude = -1.0;
    double norm = (amplitude + 1.0) / 2.0;
    color.red = (int)(norm * 255.0);
    color.green = (int)((1.0 - norm) * 255.0);
    color.blue = (int)((1.0 - norm) * 255.0);
    return color;
}

static void set_led_color(RGBColor color) {
    gpioPWM(g_alsa_gpio_red, color.red);
    gpioPWM(g_alsa_gpio_green, color.green);
    gpioPWM(g_alsa_gpio_blue, color.blue);
}

static void simulate_audio_input(void) {
    short buffer[PERIOD_SIZE];
    for (int i = 0; i < PERIOD_SIZE; i++) {
        buffer[i] = (short)(100.0 * (double)i / PERIOD_SIZE);
    }
    double amplitude = calculate_rms(buffer, PERIOD_SIZE);
    RGBColor color = map_amplitude_to_color(amplitude);
    set_led_color(color);
}

static void simulate_audio_input_with_sine(void) {
    short buffer[PERIOD_SIZE];
    for (int i = 0; i < PERIOD_SIZE; i++) {
        buffer[i] = (short)(100.0 * (double)i / PERIOD_SIZE);
    }
    double amplitude = calculate_rms(buffer, PERIOD_SIZE);
    amplitude = amplitude * SENSITIVITY;
    if (amplitude > 1.0) amplitude = 1.0;
    if (amplitude < -1.0) amplitude = -1.0;
    double phase = (double)i / PERIOD_SIZE * 2.0 * M_PI;
    double sine = sin(phase);
    amplitude = (amplitude + 1.0) / 2.0 * sine;
    amplitude = amplitude * 100.0;
    if (amplitude > 100.0) amplitude = 100.0;
    if (amplitude < -100.0) amplitude = -100.0;
    short buffer_sine[PERIOD_SIZE];
