#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CTIME 0x02
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define TCS34725_ID_VALUE 0x44

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData failed for reg 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed for reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

static int tcs34725_init(int handle) {
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x00) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CTIME, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x01) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_color(int handle, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_word(handle, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, time_t timestamp, uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    fprintf(fp, "%ld,%u,%u,%u,%u\n", timestamp, c, r, g, b);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int id = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error: Failed to read TCS34725 ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Error: TCS34725 ID mismatch (got 0x%02X, expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (!fp) {
        perror("Error opening color_data.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "timestamp,c,r,g,b\n");

    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_color(i2c_handle, &c, &r, &g, &b) == 0) {
            time_t now = time(NULL);
            log_data(fp, now, c, r, g, b);
        } else {
            fprintf(stderr, "Warning: sensor read failed, logging zeros\n");
            log_data(fp, 0, 0, 0, 0, 0);
        }
        gpioDelay(500000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

