            return -1;
        }
    }
    return 0;
}

static int set_sunset(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioPWM(pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int set_nighttime(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioPWM(pins[i], duty_cycle) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    set_all_relays(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sunrise/Sunset Lamp Controller started. Press Ctrl+C to exit.\n");

    while (running) {
        if (set_all_relays(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (set_sunrise(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        for (int i = 0; i < SUNRISE_DURATION && running; ++i) {
            if (set_sunrise(i + 1) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            gpioDelay(100000);
        }

        if (!running) break;

        if (set_all_relays(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (set_daytime(100) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        for (int i = 0; i < DAYTIME_DURATION && running; ++i) {
            if (set_daytime(100 - (i + 1)) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            gpioDelay(100000);
        }

        if (!running) break;

        if (set_all_relays(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (set_sunset(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        for (int i = 0; i < SUNSET_DURATION && running; ++i) {
            if (set_sunset(i + 1) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            gpioDelay(100000);
        }

        if (!running) break;

        if (set_all_relays(0) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (set_nighttime(100) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        for (int i = 0; i < NIGHTTIME_DURATION && running; ++i) {
            if (set_nighttime(100 - (i + 1)) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            gpioDelay(100000);
        }
    }

    cleanup();
    printf("Sunrise/Sunset Lamp Controller stopped.\n");
    return EXIT_SUCCESS;
}

