        if (log_file == NULL) {
            perror("fopen(log_file)");
            return -1;
        }
    }

    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        perror("fprintf(log_file)");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush(log_file)");
        return -1;
    }
    return 0;
}

int main(void) {
    int last_trigger_ms = 0;
    char timestamp[32];
    char filename[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    while (running) {
        int sensor_value = gpioRead(SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_GPIO);
            break;
        }

        if (sensor_value == 0) {
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo == NULL) {
                fprintf(stderr, "localtime failed\n");
                break;
            }
            if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                fprintf(stderr, "Failed to get timestamp\n");
                break;
            }

            if (last_trigger_ms > 0 && (time(NULL) - last_trigger_ms) < (DEBOUNCE_MS / 1000)) {
                printf("Motion detected at %s\n", timestamp);
            } else {
                last_trigger_ms = (int)(time(NULL) * 1000);
                if (capture_video(filename) != 0) {
                    fprintf(stderr, "Video capture failed\n");
                } else {
                    printf("Video captured: %s.h264\n", filename);
                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }
                }
            }
        }
        gpioDelay(10000);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

