            timestamp, moisture,
            relay1_state ? "ON" : "OFF",
            relay2_state ? "ON" : "OFF",
            relay3_state ? "ON" : "OFF",
            relay4_state ? "ON" : "OFF");
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
