        perror("Error opening log file");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    while (running) {
        int moisture = rand() % 100 + 1;
        int relay1_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;

        if (gpioWrite(RELAY1_PIN, relay1_state) != 0 ||
            gpioWrite(RELAY2_PIN, relay2_state) != 0 ||
            gpioWrite(RELAY3_PIN, relay3_state) != 0 ||
            gpioWrite(RELAY4_PIN, relay4_state) != 0) {
            fprintf(stderr, "Error: failed to write GPIO pin\n");
            break;
        }

        log_data(moisture, relay1_state, relay2_state, relay3_state, relay4_state);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; ++i) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    deactivate_all_relays();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

