#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define MAX_DISTANCE_CM 400.0
#define MAX_PULSE_US 23000
#define SAMPLE_INTERVAL_US 200000
#define TIMEOUT_THRESHOLD_US 100000

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static volatile int g_valid = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        g_start_tick = tick;
        g_echo_received = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_received = 1;
    }
}

static void *measurement_task(void *arg) {
    (void)arg;
    while (g_running) {
        trigger_sensor();
        uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;
        uint32_t start = 0;
        int received = 0;
        int timeout = 0;

        while (g_running) {
            if (g_echo_received) {
                received = 1;
                break;
            }
            if (gpioTick() >= deadline) {
                timeout = 1;
                break;
            }
            gpioDelay(100);
        }

        if (timeout) {
            pthread_mutex_lock(&g_mutex);
            g_valid = 0;
            pthread_mutex_unlock(&g_mutex);
            continue;
        }

        if (!received) {
            pthread_mutex_lock(&g_mutex);
            g_valid = 0;
            pthread_mutex_unlock(&g_mutex);
            continue;
        }

        pthread_mutex_lock(&g_mutex);
        start = g_start_tick;
        end = g_end_tick;
        g_echo_received = 0;
        g_valid = 1;
        pthread_mutex_unlock(&g_mutex);

        uint32_t pulse_us = end - start;
        double distance = -1.0;
        if (pulse_us <= MAX_PULSE_US) {
            distance = (pulse_us * MAX_DISTANCE_CM) / 58.0;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint64_t ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
        if (g_log_file) {
            fprintf(g_log_file, "%llu,%.2f\n", (unsigned long long)ns, distance);
            fflush(g_log_file);
        }
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize TRIG_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t measurement_thread;
    if (pthread_create(&measurement_thread, NULL, measurement_task, NULL) != 0) {
        perror("Failed to create measurement thread");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    pthread_join(measurement_thread, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    fclose(g_log_file);
    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);
    return EXIT_SUCCESS;
}

