#define LIS3DH_ADDR    0x19
#define BUZZER_GPIO    17
#define SAMPLE_PERIOD_US 100000
#define FREEFALL_THRESHOLD_G 0.2f
#define IMPACT_THRESHOLD_G 1.5f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int init_lis3dh(int fd) {
    if (i2c_write_byte(fd, 0x11, 0x0C) < 0) return -1;
