static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, 0x28, buf, 6) < 0) return -1;
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    float freefall_threshold = FREEFALL_THRESHOLD_G;
    float impact_threshold = IMPACT_THRESHOLD_G;

    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                freefall_threshold = atof(optarg);
                break;
            case 'i':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold_g] [-i impact_threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (freefall_threshold <= 0.0f || impact_threshold <= 0.0f) {
        fprintf(stderr, "Error: Threshold values must be positive.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lis3dh(i2c_fd) < 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read failed, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold) {
            printf("Free-fall detected!\n");
        } else if (magnitude > impact_threshold) {
            printf("Impact detected!\n");
            gpioWrite(BUZZER_GPIO, 1);
            usleep(1000000);
            gpioWrite(BUZZER_GPIO, 0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

