#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY_US 1000
#define SQUARE_SIZE_MM 50
#define STEPS_PER_REV 2048
#define GEAR_RATIO 64

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4,
                  MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to write GPIO %d low\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void set_motor_pins(int motor, int step) {
    switch (motor) {
        case 1: gpioWrite(MOTOR1_IN1, step & 1); gpioWrite(MOTOR1_IN2, (step >> 1) & 1);
                gpioWrite(MOTOR1_IN3, (step >> 2) & 1); gpioWrite(MOTOR1_IN4, (step >> 3) & 1);
                break;
        case 2: gpioWrite(MOTOR2_IN1, step & 1); gpioWrite(MOTOR2_IN2, (step >> 1) & 1);
                gpioWrite(MOTOR2_IN3, (step >> 2) & 1); gpioWrite(MOTOR2_IN4, (step >> 3) & 1);
                break;
    }
}

static void move_motor(int motor, int steps) {
    for (int i = 0; i < steps && running; ++i) {
        set_motor_pins(motor, i % 4);
        gpioDelay(STEP_DELAY_US);
    }
}

static void stop_motors(void) {
    set_motor_pins(1, 0); set_motor_pins(2, 0);
    gpioDelay(STEP_DELAY_US);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int steps_per_square = (SQUARE_SIZE_MM * STEPS_PER_REV) / (SQUARE_SIZE_MM * GEAR_RATIO);
    printf("Moving %d steps for %d mm square\n", steps_per_square, SQUARE_SIZE_MM);

    move_motor(1, steps_per_square);
    move_motor(2, steps_per_square);

    stop_motors();
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return EXIT_SUCCESS;
}

