#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <getopt.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c.h>
#include <syslog.h>
#include <sys/stat.h>

#define LIS3DH_ADDRESS_MIN 0x28
#define LIS3DH_ADDRESS_MAX 0x29
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)", reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3dh(int fd) {
    if (i2c_write_byte(fd, LIS3DH_CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_byte(fd, LIS3DH_CTRL_REG4, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, LIS3DH_OUT_X_L, buf, 6) < 0) return -1;
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw / 4096.0f;
    *y = (float)y_raw / 4096.0f;
    *z = (float)z_raw / 4096.0f;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Cannot open log file %s: %s", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;
    float threshold = DEFAULT_THRESHOLD;
    int i2c_address = 0;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < LIS3DH_ADDRESS_MIN || i2c_address > LIS3DH_ADDRESS_MAX) {
                    fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x28-0x29)\n", i2c_address);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("high_acceleration", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting high acceleration detection (threshold=%.2f g, addr=0x%02X)", threshold, i2c_address);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Cannot open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        syslog(LOG_ERR, "Cannot set I2C slave address 0x%02X: %s", i2c_address, strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (init_lis3dh(i2c_fd) < 0) {
        syslog(LOG_ERR, "LIS3DH initialization failed");
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "LIS3DH initialized at 0x%02X, threshold=%.2f g", i2c_address, threshold);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            syslog(LOG_ERR, "Read error, continuing");
        } else if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            log_event(x, y, z);
            syslog(LOG_INFO, "High acceleration detected: X=%.3f, Y=%.3f, Z=%.3f", x, y, z);
            if (system("sudo shutdown -h now") != 0) {
                syslog(LOG_ERR, "shutdown command failed");
            }
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    if (i2c_fd >= 0) close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

