/*
 * Autonomous line-following robot for Raspberry Pi 5.
 *
 * Hardware:
 *   - SunFounder 3-Way Tracking Sensor (IR reflectance, digital GPIO)
 *     Left   -> GPIO4  (BCM)
 *     Center -> GPIO17 (BCM)
 *     Right  -> GPIO27 (BCM)
 *   - Active-high alert LED/buzzer -> GPIO22 (BCM)
 *
 * Behavior:
 *   Polls the three sensors every 10 ms.  Drives the alert LED HIGH for 2 s
 *   when the center sensor reports "no line" for five consecutive readings.
 *   Otherwise:
 *     - Forward when center detects a line (logic 0).
 *     - Turn left  when left sensor detects a line.
 *     - Turn right when right sensor detects a line.
 *     - Stop when all sensors report "no line".
 *
 * Build:  gcc -O2 -Wall -Wextra -o line_follower line_follower.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_LED_PIN    22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000   /* 10 ms */
#define ALERT_HOLD_US  2000000 /* 2 s  */

/* ------------------------------------------------------------------ */
/* Circular buffer for sensor readings                                 */
/* ------------------------------------------------------------------ */
typedef struct {
    int  left[BUFFER_SIZE];
    int  center[BUFFER_SIZE];
    int  right[BUFFER_SIZE];
    int  head;
    int  count;
} sensor_buffer_t;

static sensor_buffer_t sensor_buffer = {0};

