#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x49
#define RELAY_GPIO     17
#define THRESHOLD_MT   5.0f
#define SAMPLE_US      100000
#define POLL_ATTEMPTS  50
#define LOG_FILE       "magnetic_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp-error] %s\n", msg);
    }
    fclose(fp);
}

static int read_si7210(float *field_mT)
{
    char buf[2];
    int rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        log_event("I2C read failed");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *field_mT = (float)raw / 100.0f;
    return 0;
}

static int write_si7210(float field_mT)
{
    char buf[2];
    int16_t val = (int16_t)((field_mT * 100.0f) + 0.5f);
    buf[0] = (char)(val >> 8);
    buf[1] = (char)(val & 0xFF);
    int rc = i2cWriteDevice(g_i2c_handle, buf, 2);
    if (rc != 0) {
        log_event("I2C write failed");
        return -1;
    }
    return 0;
}

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("gpioWrite failed");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        float field_mT;
        if (read_si7210(&field_mT) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Field: %.2f mT", field_mT);
            log_event(msg);

            if (field_mT > THRESHOLD_MT) {
                if (gpioRead(RELAY_GPIO) == 0) {
                    control_relay(1);
                }
            } else {
                control_relay(0);
            }
        } else {
            log_event("Sensor read failed; deactivating relay");
            control_relay(0);
        }

        usleep(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

