/*
 * Raspberry Pi Zero W — Dual SLF3S-1300F liquid-flow sensor monitor
 *
 * Sensors : Sensirion SLF3S-1300F (40 ml/min) on I2C bus 1
 *   Sensor 1: address 0x36, Sensor 2: address 0x3F
 *   (Per datasheet: SLF3S-1300F uses 0x36 for 40 ml/min variant)
 *
 * Relay   : Active-high safety relay on GPIO 18 (BCM)
 *
 * Log     : flow_log.txt (append mode, flushed immediately)
 *
 * Build   : gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lsb5
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SENSOR1_ADDR     0x36
#define SENSOR2_ADDR     0x3F
#define RELAY_GPIO       18
#define FLOW_THRESHOLD   5.0f
#define POLL_DELAY_US    100000   /* 100 ms */
#define LOG_FILE         "flow_log.txt"

/* ---- I2C / pigpio helpers ------------------------------------------------ */
static int i2c_open(int addr)
{
    int fd = open("/dev/i2c-"  PRIdI  "/0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/i2c-0 failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---------------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Sensor read ---------------------------------------------------------- */
static int read_sensor(int fd, float *flow_out)
{
    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_out = (float)raw / 100.0f;   /* 40 ml/min */
    return 0;
}

/* ---- Logging ------------------------------------------------------------- */
static void log_flow(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ---- Relay control ------------------------------------------------------- */
static int set_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "gpioWrite(%d) failed\n", state);
        return -1;
    }
    return 0;
}

/* ---- Cleanup ------------------------------------------------------------- */
static void cleanup(void)
{
    /* De-energize relay first for safety */
    gpioWrite(RELAY_GPIO, 0);
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    if (i2c_close(SENSOR1_ADDR) < 0) {
        fprintf(stderr, "i2c close 0x%02X failed\n", SENSOR1_ADDR);
    }
    if (i2c_close(SENSOR2_ADDR) < 0) {
        fprintf(stderr, "i2c close 0x%02X failed\n", SENSOR2_ADDR);
    }
    /* pigpio cleanup */
}

/* ---- Signal handler ----------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    exit(0);
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* --- pigpio init ----------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO ---------------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) initial failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- I2C sensors --------------------------------------------------- */
    int fd1 = i2c_open(SENSOR1_ADDR);
    if (fd1 < 0) { gpioTerminate(); return EXIT_FAILURE; }

    int fd2 = i2c_open(SENSOR2_ADDR);
    if (fd2 < 0) { i2c_close(fd1); gpioTerminate(); return EXIT_FAILURE; }

    /* --- Start measurement (two-byte command: 0x2C 0x40) ---------------- */
    uint8_t cmd[2] = {0x2C, 0x40};
    if (write(fd1, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "start measurement 0x%02X failed: %s\n",
                0x2C, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (write(fd2, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "start measurement 0x%02X failed: %s\n",
                0x2C, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ---------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop ----------------------------------------------------- */
    while (1) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_sensor(fd1, &f1) == 0);
        int ok2 = (read_sensor(fd2, &f2) == 0);

        if (ok1 && ok2) {
            log_flow(f1, f2);
            if (f1 >= FLOW_THRESHOLD && f2 >= FLOW_THRESHOLD) {
                set_relay(1);
            } else {
                set_relay(0);
            }
        } else {
            /* On read failure, do not change relay state */
            if (ok1) fprintf(stderr, "Sensor 1 read failed\n");
            if (ok2) fprintf(stderr, "Sensor 2 read failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Unreachable --------------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

