                set_relay(1);
            } else {
                set_relay(0);
            }
        } else {
            /* On read failure, do not change relay state */
            if (ok1) fprintf(stderr, "Sensor 1 read failed\n");
            if (ok2) fprintf(stderr, "Sensor 2 read failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Unreachable --------------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

