    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on ENA: %s", strerror(errno));
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on IN1: %s", strerror(errno));
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on IN2: %s", strerror(errno));
        rc = -1;
    }
    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);
