        gpioWrite(MOTOR_IN1_PIN, 0) < 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on motor init pins");
        goto fail_init;
    }

    syslog(LOG_INFO, "Rain Window: ready (poll=%d ms, run=%d s, drywait=%d s)",
           POLL_INTERVAL_US / 1000, MOTOR_RUN_SEC, DRY_WAIT_SEC);

