/*
 * Door-lock servo control via two push buttons on a Raspberry Pi.
 *
 * Wiring (BCM numbering):
 *   GPIO 18 -> Servo signal (physical pin 12)
 *   GPIO 21 -> Lock  button (pressed -> GND)
 *   GPIO 22 -> Unlock button (pressed -> GND)
 *
 * The buttons are wired to GND when pressed, so internal pull-ups are
 * required.  A short sleep between polls keeps CPU usage low.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000   /* 2 ms  */
#define UNLOCK_PULSE_US 1000  /* 1 ms  */
#define DEBOUNCE_US    50000  /* 50 ms  */
#define POLL_DELAY_US   10000  /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Send a pulse width to the servo pin.  Returns 0 on success, -1 on
 * failure (pigpio may have already stopped). */
static int send_pulse(int pin, int pulse_us)
{
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "gpioServo(pin=%d, %d us) failed\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure buttons as inputs with internal pull-ups ---- */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- start with servo stopped ---- */
    if (send_pulse(SERVO_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door-lock servo ready.  Lock=GPIO%d  Unlock=GPIO%d\n",
           LOCK_BUTTON, UNLOCK_BUTTON);
    printf("Press Ctrl-C to exit.\n");

    bool lock_pressed = false;
    bool unlock_pressed = false;

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "gpioRead failed (lock=%d, unlock=%d)\n",
                    lock_state, unlock_state);
            break;
        }

        if (lock_state == 0 && !lock_pressed) {
            /* Rising edge: button pressed */
            if (send_pulse(SERVO_PIN, LOCK_PULSE_US) != 0) {
                break;
            }
            lock_pressed = true;
            printf("Lock pressed -> servo pulse %d us\n", LOCK_PULSE_US);
        } else if (lock_state == 1 && lock_pressed) {
            /* Falling edge: button released */
            lock_pressed = false;
        }

        if (unlock_state == 0 && !unlock_pressed) {
            if (send_pulse(SERVO_PIN, UNLOCK_PULSE_US) != 0) {
                break;
            }
            unlock_pressed = true;
            printf("Unlock pressed -> servo pulse %d us\n", UNLOCK_PULSE_US);
        } else if (unlock_state == 1 && unlock_pressed) {
            unlock_pressed = false;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (send_pulse(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to stop servo pulse\n");
    }
    gpioDelay(100000);  /* 100 ms settle */
    if (send_pulse(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to stop servo pulse\n");
    }
    gpioDelay(100000);  /* 100 ms settle */

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

