#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event_type, int duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - %s - Duration: %d seconds\n", ts, event_type, duration);
    } else {
        fprintf(fp, "(timestamp error) - %s - Duration: %d seconds\n", event_type, duration);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

static int activate_floodlight(void) {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 1) failed\n");
        return -1;
    }
