/*
 * MPR121 Capacitive Touch Sensor -> Relay Toggle on Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C1 SCL)
 *   MPR121 ADDR -> GND (I2C address 0x5D)
 *   MPR121 VDD -> 3.3V
 *   MPR121 GND -> GND
 *   Relay IN  -> GPIO17 (BCM)
 *   Relay VCC -> 3.3V
 *   Relay GND -> GND
 *
 * Build: gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR        0x5D
#define RELAY_GPIO         17
#define DEBOUNCE_MS        200
#define POLL_DELAY_US      10000   /* 10 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG     0x5E
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCL          0x2D
#define MPR121_FDL          0x2E
#define MPR121_DEBOUNCE     0x2F
#define MPR121_CONFIG1      0x5B
#define MPR121_CONFIG2      0x5C
#define MPR121_ELECONFIG0   0x5E
#define MPR121_SOFTRESET    0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* Read a single byte from an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int b = i2cReadByteData(handle, reg);
    if (b < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *value = (uint8_t)b;
    return 0;
}

/* Initialize the MPR121 sensor. Returns 0 on success, -1 on error. */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle after reset */

    /* Baseline filtering (rising) */
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL, 0x20) < 0) return -1;

    /* Debounce: 3 samples for all electrodes */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, SFI = 4 samples, CDT = 0.5 us */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 us, ESI = 4 ms */
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, auto-config */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

/* Read the 16-bit touch status (low byte first). Returns 0 on success, -1 on error. */
static int mpr121_read_touch_status(int handle, uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Toggle the relay state. Returns 0 on success, -1 on error. */
static int relay_toggle(int gpio)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", gpio);
        return -1;
    }
    if (gpioWrite(gpio, !level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, !level);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address 0x5D */
    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPR121 touch sensor ready. Press Ctrl+C to exit.\n");

    uint16_t prev_touch = 0;
    bool relay_on = false;

    while (g_running) {
        uint16_t touch = 0;
        if (mpr121_read_touch_status(g_i2c_handle, &touch) < 0) {
            fprintf(stderr, "Warning: touch read failed, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Rising edge on electrode 0 */
        if (touch & 0x0001 && (prev_touch & 0x0001) == 0) {
            if (relay_on) {
                relay_on = false;
                if (relay_toggle(RELAY_GPIO) < 0) {
                    fprintf(stderr, "Error: relay toggle failed\n");
                    break;
                }
            } else {
                relay_on = true;
                if (relay_toggle(RELAY_GPIO) < 0) {
                    fprintf(stderr, "Error: relay toggle failed\n");
                    break;
                }
            }
        }

        prev_touch = touch;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    if (relay_on) {
        gpioWrite(RELAY_GPIO, 0);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

