#include <time.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <gpiod.h>

#define PORT 5000
#define GPIO_SERVO 17
#define GPIO_PIR 4
#define PWM_FREQ 50
#define PWM_PERIOD_US 20000
#define PWM_HALF_PERIOD_US (PWM_PERIOD_US / 2)
#define PULSE_WIDTH_US 2000
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_event(const char *message, int priority, const char *context) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];
        localtime_r(&now, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        fprintf(log_file, "[%s] %s (priority %d, context: %s)\n",
                timestamp, message, priority, context);
        fflush(log_file);
    }
    syslog(priority, "%s (priority %d, context: %s)", message, priority, context);
    pthread_mutex_unlock(&log_mutex);
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_event("Failed to open gpiochip4", LOG_ERR, "gpio_init");
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, GPIO_SERVO);
    if (!servo_line) {
        log_event("Failed to get servo GPIO line", LOG_ERR, "gpio_init");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!pir_line) {
        log_event("Failed to get PIR GPIO line", LOG_ERR, "gpio_init");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo-pwm", 0) < 0) {
