static void *handle_client(void *arg) {
    int client_fd = *(int *)arg;
    free(arg);

    char buffer[1024];
    ssize_t bytes_received;

    while (running) {
        memset(buffer, 0, sizeof(buffer));
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            char *command = strtok(buffer, " \n\r");
            if (command) {
                char *angle_str = strtok(NULL, " \n\r");
                if (command[0] == 't' && command[3] == 'h' && command[4] == 'e') {
                    if (angle_str && angle_str[0] >= '0' && angle_str[0] <= '9') {
                        int angle = atoi(angle_str);
                        if (set_servo_angle(angle) == 0) {
                            char response[64];
                            snprintf(response, sizeof(response), "Servo moved to angle: %d", angle);
                            send(client_fd, response, strlen(response), 0);
                        } else {
                            log_event("Failed to set servo angle", LOG_ERR, "set_servo_angle");
                            send(client_fd, "Error: Failed to set servo angle", strlen("Error: Failed to set servo angle"), 0);
                        }
                    } else {
                        log_event("Invalid servo angle format", LOG_ERR, "set_servo_angle");
                        send(client_fd, "Error: Invalid angle format", strlen("Error: Invalid angle format"), 0);
                    }
                } else if (strcmp(command, "PIR") == 0) {
                    int pir_value = gpiod_line_get_value(pir_line);
                    if (pir_value < 0) {
                        log_event("Failed to read PIR sensor", LOG_ERR, "handle_client");
                        send(client_fd, "Error: Failed to read PIR sensor", strlen("Error: Failed to read PIR sensor"), 0);
                    } else {
                        char response[16];
                        snprintf(response, sizeof(response), "PIR:%d", pir_value);
                        send(client_fd, response, strlen(response), 0);
                    }
                } else {
                    log_event("Unknown command", LOG_ERR, "handle_client");
                    send(client_fd, "Error: Unknown command", strlen("Error: Unknown command"), 0);
                }
            }
        } else if (bytes_received == 0) {
            log_event("Client disconnected", LOG_INFO, "handle_client");
            break;
        } else {
            if (errno != EINTR) {
                log_event("Socket error", LOG_ERR, "handle_client");
            }
            break;
        }
    }

    close(client_fd);
    return NULL;
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_event("Failed to open log file", LOG_ERR, "main");
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed", LOG_ERR, "main");
        fclose(log_file);
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Socket creation failed", LOG_ERR, "main");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("setsockopt failed", LOG_ERR, "main");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Bind failed", LOG_ERR, "main");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Listen failed", LOG_ERR, "main");
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_event("Server listening on port 5000", LOG_INFO, "main");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            log_event("Accept failed", LOG_ERR, "main");
            break;
        }

        int *new_fd = malloc(sizeof(int));
        if (!new_fd) {
            log_event("Memory allocation failed", LOG_ERR, "main");
            close(client_fd);
            continue;
        }
        *new_fd = client_fd;

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, handle_client, (void *)new_fd) != 0) {
            log_event("Failed to create thread", LOG_ERR, "main");
            free(new_fd);
            close(client_fd);
        } else {
            pthread_detach(thread_id);
        }
    }

    log_event("Shutting down server", LOG_INFO, "main");
    if (server_fd >= 0) close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

