/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient light sensor + grow-light relay
 *
 * Wiring:
 *   BH1750 SDA  -> GPIO2  (I2C1 SDA)
 *   BH1750 SCL  -> GPIO3  (I2C1 SCL)
 *   BH1750 VCC  -> 3.3 V
 *   BH1750 GND  -> GND
 *   Relay IN    -> GPIO23 (BCM)
 *   Relay VCC   -> 3.3 V
 *   Relay GND   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o grow_light grow_light.c -lpigpio -lrt
 * Run:    sudo ./grow_light
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x5D          /* 0x5C is the default; 0x5D is the officially supported address */
#define RELAY_GPIO     23
#define LUX_THRESHOLD  150.0f
#define SAMPLE_PERIOD  2             /* seconds between readings */
#define BH1750_MEAS_MS 120          /* max conversion time per datasheet */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* BH1750 read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores lux in *out_lux.
 * Returns -1 on I2C error, -2 on sensor-absent / not-responsive.
 */
static int read_bh1750(float *out_lux)
{
    char buf[2];
    int  rc;

    /* Trigger a one-shot measurement */
    rc = i2cWriteByteData(g_i2c_handle, 0x00, 0x01);
    if (rc < 0) {
        log_message("BH1750: I2C write error (trigger)");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_MEAS_MS * 1000);  /* microseconds */

    /* Read 2 bytes of result */
    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        log_message("BH1750: I2C read error (sensor absent or bus error)");
        return -2;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *out_lux = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void control_relay(float lux)
{
    int level = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, level) < 0)
        log_message("Relay GPIO write failed");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before deinitialising pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float lux;
    int   rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- relay GPIO setup ---- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_message("gpioSetMode failed for relay GPIO");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* start with relay off */

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_message("i2cOpen failed — sensor may be absent or bus error");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- log file ---- */
    g_log_file = fopen("grow_log.txt", "a");
    if (!g_log_file) {
        log_message("Failed to open grow_log.txt");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Grow light controller started");

    /* ---- main loop ---- */
    while (g_running) {
        rc = read_bh1750(&lux);
        if (rc == 0) {
            log_message("Lux:  " );
            control_relay(lux);
            printf("Lux: %.2f  Relay: %s\n",
                   lux,
                   (lux < LUX_THRESHOLD) ? "ON" : "OFF");
        } else {
            log_message("Sensor read failed — will retry next cycle");
        }

