/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Controls a relay module on GPIO17 (BCM 17, physical pin 11) via MQTT.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lpigpio -lmosquitto -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER      "localhost"
#define MQTT_PORT         1883
#define MQTT_CLIENT_ID   "relay_controller_1"
#define MQTT_TOPIC        "home/lights/control"
#define MQTT_QOS         0
#define GPIO_PIN          17
#define KEEPALIVE_SEC     60
#define RECONNECT_DELAY  5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO %d LOW", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void)
{
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                       */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    int rc;

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed for client ID '%s'", MQTT_CLIENT_ID);
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(g_mosq, mqtt_message_callback);

    rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    rc = mosquitto_subscribe(g_mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_subscribe failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    syslog(LOG_INFO, "MQTT client connected to %s:%d, subscribed to %s (QoS %d)",
           MQTT_BROKER, MQTT_PORT, MQTT_TOPIC, MQTT_QOS);
    return 0;
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    (void)mosq; (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to broker");
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq; (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message)
{
    (void)mosq; (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message received on topic '%s'", message->topic);
        return;
    }

    const char *payload = (const char *)message->payload;
    syslog(LOG_INFO, "Received MQTT payload: '%s'", payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0) {
            syslog(LOG_INFO, "Relay energised (GPIO %d HIGH)", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Failed to energise relay on GPIO %d", GPIO_PIN);
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0) {
            syslog(LOG_INFO, "Relay de-energised (GPIO %d LOW)", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Failed to de-energise relay on GPIO %d", GPIO_PIN);
        }
    } else {
        syslog(LOG_ERR, "Invalid relay command: '%s'", payload);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller (GPIO %d, MQTT %s:%d)",
           GPIO_PIN, MQTT_BROKER, MQTT_PORT);

    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Relay controller running. Press Ctrl+C to exit.");

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            if (rc == MOSQ_ERR_CONN_LOST) {
                syslog(LOG_WARNING, "MQTT connection lost, attempting reconnect");
                sleep(RECONNECT_DELAY);
                rc = mosquitto_reconnect(g_mosq);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Reconnect failed: %s", mosquitto_strerror(rc));
                }
            } else {
                syslog(LOG_ERR, "Recovery from loop error: %s", mosquitto_strerror(rc));
            }
        }
        if (g_running) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down relay controller");

    gpioWrite(GPIO_PIN, 0);
    mosquitto_disconnect(g_mosq);
    mosquitto_destroy(g_mosq);
    g_mosq = NULL;

    gpio_cleanup();
    mosquitto_lib_cleanup();
    closelog();

    return EXIT_SUCCESS;
}

