/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+
 * using a DRV8833 H-bridge and quadrature encoders.
 *
 * Wiring (BCM numbering):
 *   GPIO17 - Motor A IN1 (PWM)
 *   GPIO18 - Motor A IN2 (direction)
 *   GPIO22 - Motor B IN3 (PWM)
 *   GPIO23 - Motor B IN4 (direction)
 *   GPIO4  - Encoder A phase A
 *   GPIO5  - Encoder A phase B
 *   GPIO6  - Encoder B phase A
 *   GPIO12 - Encoder B phase B
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>

/* ---- Pin assignments (BCM) ---- */
#define MOTOR_A_IN1 17
#define MOTOR_A_DIR 18
#define MOTOR_B_IN3 22
#define MOTOR_B_DIR 23
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

/* ---- Motor parameters ---- */
#define PWM_FREQUENCY 10000          /* 10 kHz */
#define PWM_RANGE     255            /* 8-bit resolution */
#define TARGET_RPM    50.0f          /* target speed in RPM */
#define TICKS_PER_REV 64.0f          /* 64 ticks per revolution */
#define STALL_TIMEOUT_S 2.0f         /* stall detection window */

/* ---- Encoder state ---- */
typedef struct {
    atomic_uint32_t a_ticks;       /* rising-edge count on Encoder A phase A */
    atomic_uint32_t b_ticks;       /* rising-edge count on Encoder A phase B */
    atomic_uint32_t a_prev;        /* previous rising-edge count on A phase A */
    atomic_uint32_t b_prev;        /* previous rising-edge count on B phase A */
    bool a_stalled;                 /* true if no rising edge on A phase A for >STALL_TIMEOUT_S */
    bool b_stalled;                 /* true if no rising edge on B phase B for >STALL_TIMEOUT_S */
} EncoderState;

/* ---- PI control parameters ---- */
#define KP 1.0f
#define KI 0.01f
#define DT 0.1f

/* ---- Globals ---- */
static EncoderState encoder = {0};
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- ISR: count rising edges on each encoder phase ---- */
static void encoder_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;

    EncoderState *st = (EncoderState *)userdata;

    if (gpio == ENCODER_A_A) {
        if (level == 1) {
            st->a_ticks++;
            st->a_prev = st->a_ticks;
        }
    } else if (gpio == ENCODER_A_B) {
        if (level == 1) {
            st->b_ticks++;
            st->b_prev = st->b_ticks;
        }
    } else if (gpio == ENCODER_B_A) {
        if (level == 1) {
            st->b_ticks++;
            st->b_prev = st->b_ticks;
        }
    } else if (gpio == ENCODER_B_B) {
        if (level == 1) {
            st->a_ticks++;
            st->a_prev = st->a_ticks;
        }
    }
}

/* ---- Initialize pigpio and GPIO pins ---- */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {MOTOR_A_IN1, MOTOR_A_DIR, MOTOR_B_IN3, MOTOR_B_DIR,
                  ENCODER_A_A, ENCODER_A_B, ENCODER_B_A, ENCODER_B_B};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Start with motors stopped */
        if (pins[i] == MOTOR_A_IN1 || pins[i] == MOTOR_B_IN3) {
            if (gpioPWM(pins[i], 0) < 0) {
                fprintf(stderr, "Error: failed to initialize PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return -1;
            }
        }
    }

    int enc_pins[] = {ENCODER_A_A, ENCODER_A_B, ENCODER_B_A, ENCODER_B_B};
    for (size_t i = 0; i < sizeof(enc_pins) / sizeof(enc_pins[0]); ++i) {
        if (gpioSetMode(enc_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", enc_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Enable internal pull-downs so open-collector encoders read 0 */
        if (gpioSetPullUpDown(enc_pins[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", enc_pins[i]);
        }
    }

    /* Register ISR for each encoder phase */
    for (size_t i = 0; i < sizeof(enc_pins) / sizeof(enc_pins[0]); ++i) {
        if (gpioSetISRFuncEx(enc_pins[i], RISING_EDGE, 0, encoder_isr, &encoder) < 0) {
            fprintf(stderr, "Error: failed to register ISR for GPIO %d.\n", enc_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* ---- Set motor direction (0 = forward, 1 = reverse) ---- */
static void set_motor_direction(int motor, int dir) {
    if (dir == 0) {
        if (gpioWrite(MOTOR_A_DIR, 0) < 0 || gpioWrite(MOTOR_B_DIR, 0) < 0) {
            fprintf(stderr, "Error: failed to write motor direction pins.\n");
        }
    } else {
        if (gpioWrite(MOTOR_A_DIR, 1) < 0 || gpioWrite(MOTOR_B_DIR, 1) < 0) {
            fprintf(stderr, "Error: failed to write motor direction pins.\n");
        }
    }
}

/* ---- Drive a motor: IN1 high, IN3 high for forward motion ---- */
static void drive_motor(int in1, int in3, int duty) {
    if (gpioWrite(in1, 1) < 0) {
        fprintf(stderr, "Error: failed to set IN1 high.\n");
        return;
    }
    if (gpioWrite(in3, 1) < 0) {
        fprintf(stderr, "Error: failed to set IN3 high.\n");
        return;
    }
    if (gpioPWM(in1, duty) < 0) {
        fprintf(stderr, "Error: failed to set PWM on IN1.\n");
        return;
    }
    if (gpioPWM(in3, duty) < 0) {
        fprintf(stderr, "Error: failed to set PWM on IN3.\n");
        return;
    }
}

/* ---- Compute PI control output ---- */
static float compute_pi_output(float current_rpm, float target_rpm, float dt) {
    static float integral = 0.0f;
    float error = target_rpm - current_rpm;
    integral += error * dt;
    float output = KP * error + KI * integral;
    if (output < 0.0f) output = 0.0f;
    if (output > 255.0f) output = 255.0f;
    return output;
}

/* ---- Cleanup: stop motors and release pigpio ---- */
static void cleanup(void) {
    /* Stop both motors */
    drive_motor(MOTOR_A_IN1, MOTOR_A_DIR, 0);
    drive_motor(MOTOR_B_IN3, MOTOR_B_DIR, 0);

    /* Disable ISR */
    for (size_t i = 0; i < 4; ++i) {
        gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, NULL, NULL);
    }

    gpioTerminate();
}

int main(void) {
    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Motor control started. Target: %.1f RPM\n", TARGET_RPM);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        /* Read encoder tick counters (atomic reads) */
        uint32_t a_ticks = atomic_exchange(&encoder.a_ticks, 0);
        uint32_t b_ticks = atomic_exchange(&encoder.b_ticks, 0);

        /* Stall detection */
        if (a_ticks == encoder.a_prev) {
            encoder.a_stalled = true;
        } else {
            encoder.a_stalled = false;
            encoder.a_prev = a_ticks;
        }
        if (b_ticks == encoder.b_prev) {
            encoder.b_stalled = true;
        } else {
            encoder.b_stalled = false;
            encoder.b_prev = b_ticks;
        }

        if (encoder.a_stalled && encoder.b_stalled) {
            time_sleep(STALL_TIMEOUT_S);
            continue;
        }

        /* Compute PI output */
        float pi_output = compute_pi_output((float)a_ticks / TICKS_PER_REV,
                                            TARGET_RPM, DT);

        /* Drive motors */
        int duty = (int)pi_output;
        if (duty < 0) duty = 0;
        if (duty > 255) duty = 255;
        set_motor_direction(MOTOR_A_IN1, 0);
        drive_motor(MOTOR_A_IN1, MOTOR_A_DIR, duty);
        set_motor_direction(MOTOR_B_IN3, 0);
        drive_motor(MOTOR_B_IN3, MOTOR_B_DIR, duty);

        /* Print status */
        float rpm = (float)a_ticks / TICKS_PER_REV * 60.0f;
        printf("RPM: %.2f, PWM: %d\n", rpm, duty);

        time_sleep(DT);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

