        uint32_t b_ticks = atomic_exchange(&encoder.b_ticks, 0);

        /* Stall detection */
        if (a_ticks == encoder.a_prev) {
            encoder.a_stalled = true;
        } else {
            encoder.a_stalled = false;
            encoder.a_prev = a_ticks;
        }
        if (b_ticks == encoder.b_prev) {
            encoder.b_stalled = true;
        } else {
            encoder.b_stalled = false;
            encoder.b_prev = b_ticks;
        }

        if (encoder.a_stalled && encoder.b_stalled) {
            time_sleep(STALL_TIMEOUT_S);
            continue;
        }

        /* Compute PI output */
        float pi_output = compute_pi_output((float)a_ticks / TICKS_PER_REV,
                                            TARGET_RPM, DT);

        /* Drive motors */
        int duty = (int)pi_output;
        if (duty < 0) duty = 0;
        if (duty > 255) duty = 255;
        set_motor_direction(MOTOR_A_IN1, 0);
        drive_motor(MOTOR_A_IN1, MOTOR_A_DIR, duty);
        set_motor_direction(MOTOR_B_IN3, 0);
        drive_motor(MOTOR_B_IN3, MOTOR_B_DIR, duty);

        /* Print status */
        float rpm = (float)a_ticks / TICKS_PER_REV * 60.0f;
        printf("RPM: %.2f, PWM: %d\n", rpm, duty);

        time_sleep(DT);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

