/*
 * chicken_coop_monitor.c
 *
 * Raspberry Pi 4 Model B — BH1750 ambient light sensor (I2C bus 1, address 0x58)
 *   LED strip relay via GPIO17 (BCM, active-high)
 *
 * Lux threshold: below 50 at dusk, above 200 at dawn (hysteresis)
 * Polling interval: 5 s
 * Log file: chicken_coop_log.txt
 *
 * Build:  gcc -O2 -Wall -Wextra -o chicken_coop_monitor chicken_coop_monitor.c -lpigpio -lrt
 * Run:    sudo ./chicken_coop_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x58          /* 10-bit, continuous mode, no power-up delay */
#define BH1750_CONT_MODE     0x10          /* power-down + continuous mode */
#define BH1750_POWER_DOWN    0x00          /* power-down command */
#define BH1750_RESET         0x07          /* software reset */
#define BH1750_MEASURE_MS    180           /* max conversion time for 10-bit mode */
#define POLL_INTERVAL_S      5
#define LUX_DARK_THRESHOLD   50
#define LUX_DAWN_THRESHOLD   200
#define LED_GPIO             17
#define LOG_FILE             "chicken_coop_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  bh1750_init(int handle);
static int  bh1750_read_lux(int handle, int *lux_out);
static void log_event(int lux, const char *relay_state);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* --- pigpio init --------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open ------------------------------------------------------ */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- BH1750 init ---------------------------------------------------- */
    if (bh1750_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BH1750 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup ---------------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);   /* relay off at startup */

    /* --- Log file ------------------------------------------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop ----------------------------------------------------- */
    int relay_state = 0;   /* 0 = off, 1 = on */
    int lux = 0;

    while (g_running) {
        if (bh1750_read_lux(g_i2c_handle, &lux) != 0) {
            log_event(-1, "ERROR");
            /* Safety: turn relay off on sensor failure */
            gpioWrite(LED_GPIO, 0);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        log_event(lux, relay_state ? "ON" : "OFF");

        if (lux < LUX_DARK_THRESHOLD && relay_state == 0) {
            gpioWrite(LED_GPIO, 1);
            relay_state = 1;
            printf("Dusk — lux=%.0f  ->  LED ON\n", lux);
        } else if (lux > LUX_DAWN_THRESHOLD && relay_state == 1) {
            gpioWrite(LED_GPIO, 0);
            relay_state = 0;
            printf("Dawn — lux=%.0f  ->  LED OFF\n", lux);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------ BH1750 ---------------------------------- */
static int bh1750_init(int handle)
{
    /* Power down + software reset */
    if (i2cWriteByte(handle, BH1750_POWER_DOWN) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed.\n", BH1750_POWER_DOWN);
        return -1;
    }
    usleep(10000);  /* 10 ms settle after reset */

    /* Switch to continuous mode (10-bit, ~120 ms) */
    if (i2cWriteByte(handle, BH1750_CONT_MODE) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed.\n", BH1750_CONT_MODE);
        return -1;
    }
    usleep(BH1750_MEASURE_MS * 1000);  /* wait for first conversion */
    return 0;
}

static int bh1750_read_lux(int handle, int *lux_out)
{
    /* Trigger a single measurement */
    if (i2cWriteByte(handle, BH1750_CONT_MODE) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed.\n", BH1750_CONT_MODE);
        return -1;
    }
    usleep(BH1750_MEASURE_MS * 1000);

    /* Read 2 bytes (MSB first) */
    char buf[2] = {0, 0};
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2).\n", n);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) |
                       (unsigned int)(unsigned char)buf[1];
    *lux_out = (int)(raw / 1.2);  /* 10-bit -> 0.1 lx resolution */
    return 0;
}

/* ------------------------------ Logging --------------------------------- */
static void log_event(int lux, const char *relay_state)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (lux < 0) {
        fprintf(g_log_file, "%s: ERROR: sensor read failed\n", ts);
    } else {
        fprintf(g_log_file, "%s: Lux = %d, Relay = %s\n", ts, lux, relay_state);
    }
    fflush(g_log_file);
}

/* ----------------------------- Signal / cleanup ------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Relay off */
    if (g_i2c_handle >= 0) {
        gpioWrite(LED_GPIO, 0);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

