#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int read_touch_sensor(void) {
    int v = gpioRead(TOUCH_SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %d\n", TOUCH_SENSOR_PIN, v);
        return -1;
    }
    return v;
}

static int toggle_relay(void) {
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %d\n", RELAY_PIN, current);
        return -1;
    }
    if (gpioWrite(RELAY_PIN, !current) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
        return -1;
    }
    log_message(current ? "Relay turned ON" : "Relay turned OFF");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite failed to initialise relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch = read_touch_sensor();
        if (touch < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (touch == 1) {
            if (last_touch == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
                int confirm = read_touch_sensor();
                if (confirm < 0) {
                    gpioDelay(LOOP_DELAY_US);
                    continue;
                }
                if (confirm == 1) {
                    if (toggle_relay() == 0) {
                        relay_state = !relay_state;
                    }
                    last_touch = 1;
                }
            } else {
                last_touch = 1;
            }
        } else {
            last_touch = 0;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    log_message("Program terminated gracefully");
    return EXIT_SUCCESS;
}

