    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses, double interval_sec)
{
    if (interval_sec <= 0.0) return 0.0;
    return ((double)pulses / interval_sec) / 60.0;
}

static void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n",
                timestamp, lpm, solenoid_state ? "ON" : "OFF");
