        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid to open state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);
        if (!running) break;

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses, (double)SAMPLE_INTERVAL_US / 1000000.0);
        log_data(lpm, solenoid_state);

        control_solenoid(lpm);
    }

    cleanup();
    printf("Water flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

