#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define TARGET_PORT 12345
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"
#define MAX_RETRIES 1000
#define PULSE_MIN 1000
#define PULSE_MAX 2000
#define STABILIZE_TIME 1

#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int pigpio_initialized = 0;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_factor(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config.ini. Using default calibration factor %.2f\n", calibration_factor);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "calibration_factor", 17) == 0) {
            if (sscanf(line, "calibration_factor = %lf", &calibration_factor) == 1) {
                fclose(fp);
                return 0;
            }
        }
    }
    fclose(fp);
    fprintf(stderr, "Warning: config.ini missing or malformed. Using default calibration factor %.2f\n", calibration_factor);
    return 0;
}

static int hx711_read(int *raw_value) {
    int i, j;
    int data = 0;
    int timeout = 0;

    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < MAX_RETRIES; i++) {
        gpioSetMode(SCK_PIN, PI_OUTPUT);
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        gpioSetMode(SCK_PIN, PI_INPUT);
        gpioDelay(1);

        if (gpioRead(DATA_PIN) == 0) {
            for (j = 0; j < 24; j++) {
                gpioSetMode(SCK_PIN, PI_OUTPUT);
                gpioWrite(SCK_PIN, 1);
                gpioDelay(1);
                gpioSetMode(SCK_PIN, PI_INPUT);
                gpioDelay(1);
                if (gpioRead(DATA_PIN) == 1) {
                    data |= (1 << j);
                }
            }
            gpioSetMode(SCK_PIN, PI_OUTPUT);
            gpioWrite(SCK_PIN, 1);
            gpioDelay(1);
            gpioSetMode(SCK_PIN, PI_INPUT);
            gpioDelay(1);
            if (gpioRead(DATA_PIN) == 0) {
                *raw_value = data;
                return 0;
            }
        }
        timeout++;
        if (timeout > MAX_RETRIES) {
            fprintf(stderr, "Error: HX711 timeout (sensor absent or not ready)\n");
            return -1;
        }
    }
    fprintf(stderr, "Error: HX711 read timeout\n");
    return -1;
}

static int hx711_write(int value) {
    int i, j;
    int data = 0;
    int timeout = 0;

    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioSetMode(SCK_PIN, PI_OUTPUT);
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        gpioSetMode(SCK_PIN, PI_INPUT);
        gpioDelay(1);
        if (gpioRead(DATA_PIN) == 0) {
            data |= (1 << i);
        }
        gpioSetMode(SCK_PIN, PI_OUTPUT);
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        gpioSetMode(SCK_PIN, PI_INPUT);
        gpioDelay(1);
    }

    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioSetMode(SCK_PIN, PI_INPUT);
    gpioDelay(1);

    if (value < 0 || value > 32767) {
        fprintf(stderr, "Error: HX711 value out of range: %d\n", value);
        return -1;
    }
    data = value;
    for (j = 0; j < 24; j++) {
        gpioSetMode(SCK_PIN, PI_OUTPUT);
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1);
        gpioSetMode(SCK_PIN, PI_INPUT);
        gpioDelay(1);
        if (gpioRead(DATA_PIN) == 1) {
            data |= (1 << j);
        }
    }
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioSetMode(SCK_PIN, PI_INPUT);
    gpioDelay(1);

    return data;
}

static int dispense(double target_weight) {
    int raw_value;
    if (hx711_read(&raw_value) != 0) {
        return -1;
    }
    double actual_weight = (double)raw_value / calibration_factor;
    int pulse_width = (int)((actual_weight / 1000.0) * (PULSE_MAX - PULSE_MIN) + PULSE_MIN);
    if (pulse_width < PULSE_MIN) pulse_width = PULSE_MIN;
    if (pulse_width > PULSE_MAX) pulse_width = PULSE_MAX;
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    gpioDelay(STABILIZE_TIME * 1000000);
    return 0;
}

static int send_data(int sock, double target_weight, double actual_weight) {
    char buffer[256];
    int len = snprintf(buffer, sizeof(buffer), "{\"target_weight\": %.2f, \"actual_weight\": %.2f}", target_weight, actual_weight);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Error: Data formatting failed\n");
        return -1;
    }
    if (send(sock, buffer, len, 0) < 0) {
        perror("send");
        return -1;
    }
    return 0;
}

static void log_data(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("fopen log");
            return;
        }
        fprintf(fp, "[]");
        fclose(fp);
    } else {
        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        if (size > 0) {
            fseek(fp, -1, SEEK_END);
            fprintf(fp, ",\n");
        }
        fclose(fp);
    }
    fp = fopen(LOG_FILE, "r");
    if (!fp) {
        perror("fopen log");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    if (size > 0) {
        fseek(fp, -1, SEEK_END);
        fprintf(fp, ",\n");
    }
    fclose(fp);

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char json_string[512];
    int j = snprintf(json_string, sizeof(json_string),
        "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}",
        timestamp, target_weight, actual_weight, error_message ? error_message : "None");
    if (j < 0 || (size_t)j >= sizeof(json_string)) {
        fprintf(stderr, "Error: JSON formatting failed\n");
        return;
    }
    fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("fopen log");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long size2 = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    if (size2 > 0) {
        fseek(fp, -1, SEEK_END);
        fprintf(fp, ",\n");
    }
    if (size2 == 0) {
        fprintf(fp, "[\n");
    }
    fprintf(fp, "%s\n]", json_string);
    fclose(fp);
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (read_calibration_factor() != 0) {
        fprintf(stderr, "Error: Failed to read calibration factor from config.ini\n");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TARGET_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return 1;
    }

    printf("Server listening on %s:%d\n", DEFAULT_SERVER_IP, TARGET_PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        char buffer[1024];
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes < 0) {
            perror("recv");
            close(client_fd);
            continue;
        }
        if (bytes == 0) {
            printf("Client disconnected\n");
            close(client_fd);
            continue;
        }
        buffer[bytes] = '\0';

        double target_weight;
        if (sscanf(buffer, "%lf", &target_weight) == 1) {
            if (target_weight <= 0) {
                fprintf(stderr, "Error: Invalid target weight: %.2f\n", target_weight);
                send_data(client_fd, target_weight, 0.0, "Invalid target weight");
            } else {
                if (dispense(target_weight) == 0) {
                    double actual_weight;
                    if (hx711_read(&actual_weight) == 0) {
                        send_data(client_fd, target_weight, actual_weight, 0);
                        log_data(target_weight, actual_weight, 0);
                    } else {
                        send_data(client_fd, target_weight, 0.0, "Error: Failed to read actual weight");
                        log_data(target_weight, 0.0, "Error: Failed to read actual weight");
                    }
                } else {
                    send_data(client_fd, target_weight, 0.0, "Error: Dispensing failed");
                    log_data(target_weight, 0.0, "Error: Dispensing failed");
                }
            }
        } else {
            fprintf(stderr, "Error: Invalid data format: %s\n", buffer);
            send_data(client_fd, 0.0, 0.0, "Error: Invalid data format");
        }

        close(client_fd);
    }

    cleanup();
    return 0;
}

