#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_touch_state = 0;
static volatile sig_atomic_t last_relay_state = 0;
static volatile sig_atomic_t last_relay_change_time = 0;
static volatile sig_atomic_t last_relay_change_ms = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", RELAY_PIN, state);
        return -1;
    }
    return 0;
}

static int toggle_relay(void) {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", RELAY_PIN);
        return -1;
    }

    if (current_state == 1) {
        if (set_relay(0) != 0) return -1;
        log_relay_state(0);
        return 0;
    }

    if (set_relay(1) != 0) return -1;
    log_relay_state(1);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 100000) {
            fprintf(stderr, "Error: invalid debounce value '%s'\n", argv[1]);
            return 1;
        }
        debounce_ms = (int)val;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup_gpio();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup_gpio();
        return 1;
    }

    printf("Touch sensor relay control started. Touch sensor: BCM GPIO %d, Relay: BCM GPIO %d\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Debounce: %d ms (default)\n", debounce_ms);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            uint32_t now_ms = gpioTick() / 1000;
            uint32_t last_change_ms = last_relay_change_ms;
            uint32_t last_change_time = last_relay_change_time;

            if (now_ms - last_change_ms > debounce_ms) {
                if (now_ms - last_change_time > debounce_ms) {
                    if (toggle_relay() == 0) {
                        last_relay_change_time = now_ms;
                        last_relay_change_ms = debounce_ms;
                    }
                }
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return 0;
}

