#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <fcntl.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_ANGLE 90
#define STEP_ANGLE 10
#define KEY_BUF_SIZE 256

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_terminal_mode(int fd)
{
    struct termios old, new;

    if (tcgetattr(fd, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }

    new.c_lflag &= ~(ICANON | ECHO);
    new.c_cc[VMIN] = 0;
    new.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &new) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_terminal_mode(int fd)
{
    struct termios old, new;

    if (tcgetattr(fd, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }

    new.c_lflag = old.c_lflag;
    new.c_cc[VMIN] = old.c_cc[VMIN];
    new.c_cc[VTIME] = old.c_cc[VTIME];

    if (tcsetattr(fd, TCSANOW, &new) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int read_key(int fd, char *buf, size_t size)
{
    char c;
    ssize_t n = read(fd, &c, 1);

    if (n < 0) {
        if (errno == EINTR) {
            return 0;
        }
        perror("read");
        return -1;
    }

    if (n == 0) {
        return 0;
    }

    buf[0] = c;
    buf[1] = '\0';
    return 1;
}

static int adjust_angle(int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return angle;
}

static int set_servo_angle(int angle)
{
    int pulse_width = (int)(((float)angle / 180.0f) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }

    printf("Angle: %d degrees, Pulse: %d us\n", angle, pulse_width);
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SERVO_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetPWMrange(SERVO_PIN, MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for pin %d\n", SERVO_PIN);
        goto cleanup_gpio;
    }

    if (set_servo_angle(DEFAULT_ANGLE) != 0) {
        goto cleanup_gpio;
    }

    fd = open("/dev/tty", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open /dev/tty");
        goto cleanup_gpio;
    }

    if (set_terminal_mode(fd) != 0) {
        goto cleanup_fd;
    }

    char key_buf[KEY_BUF_SIZE];
    int angle = DEFAULT_ANGLE;
    int last_key = 0;

    while (g_running) {
        int key = 0;

        if (read_key(fd, key_buf, sizeof(key_buf)) == 1) {
            key = (key_buf[0] == '+') ? 1 : -1;
        }

        if (key != 0) {
            angle = adjust_angle(angle + key);
            if (set_servo_angle(angle) != 0) {
                goto cleanup_fd;
            }
            last_key = 1;
        }

        usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup_fd:
    if (fd != -1) {
        restore_terminal_mode(fd);
        close(fd);
    }

cleanup_gpio:
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return ret;
}

