#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_US 50000
#define STABILIZE_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    return gpioRead(TOUCH_SENSOR_PIN);
}

static int toggle_relay(void) {
    int current_state = gpioRead(RELAY_PIN);
    if (current_state < 0) {
        fprintf(stderr, "Error: failed to read relay pin %d\n", RELAY_PIN);
        return -1;
    }

    if (gpioWrite(RELAY_PIN, !current_state) != 0) {
        fprintf(stderr, "Error: failed to write to relay pin %d\n", RELAY_PIN);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int stabilize_counter = 0;
    uint32_t last_stable_tick = 0;

    while (running) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error: failed to read touch sensor\n");
            break;
        }

        if (touch_value == 1) {
            if (toggle_relay() != 0) {
                break;
            }

            if (relay_state == 0) {
                relay_state = 1;
                stabilize_counter = 0;
                last_stable_tick = gpioTick();
            } else {
                uint32_t now = gpioTick();
                if (now - last_stable_tick >= (uint32_t)(STABILIZE_TIMEOUT_S * 1000000)) {
                    fprintf(stderr, "Warning: touch sensor held HIGH for >%d s, forcing relay OFF\n", STABILIZE_TIMEOUT_S);
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "Error: failed to write relay OFF\n");
                        break;
                    }
                    relay_state = 0;
                    stabilize_counter = 0;
                    last_stable_tick = 0;
                } else {
                    stabilize_counter++;
                }
            }
        } else {
            if (relay_state == 1) {
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to write relay OFF\n");
                    break;
                }
                relay_state = 0;
                stabilize_counter = 0;
                last_stable_tick = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

