#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define PWM_DUTY_MIN       0
#define PWM_DUTY_MAX       255
#define PWM_DUTY_ZERO      0

#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE_NAME      "flow_log.csv"

#define KP 1.0

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_data(float flow_rate, int valve_position)
{
    if (g_log_file == NULL)
        return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

