#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    100000
#define SPI_BITS         8
#define SPI_MODE         0

#define LOCK1_PIN        17
#define LOCK2_PIN        27
#define BUTTON_PIN       22

#define DEBOUNCE_US      50000
#define DEBOUNCE_TIMEOUT  3
#define DISENGAGE_SEC    5
#define POLL_DELAY_US    100000
#define MAX_SPI_RETRIES  4
#define MAX_LOG_RETRIES  3

#define TAG_SIZE 10
#define TAG_VALUE 0x0000000000

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log, "%s: %s\n", ts, msg);
    fflush(g_log);
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    unsigned int mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    unsigned int bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

static int spi_transfer(const unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    int rc = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (rc < 1) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rfid_tag(unsigned char *tag) {
    unsigned char tx[3] = {0x01, 0x02, 0x03};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 3) == 0) {
            if (rx[0] == 0x01 && rx[1] == 0x02 && rx[2] == 0x03) {
                memcpy(tag, rx, TAG_SIZE);
                return 0;
            }
        }
        usleep(1000);
    }
    return -1;
}

static int read_rfid_tag_valid(const unsigned char *tag) {
    if (tag[0] == 0x00 || tag[0] == 0x01) return 0;
    if (tag[1] == 0x00 || tag[1] == 0x01) return 0;
    if (tag[2] == 0x00 || tag[2] == 0x01) return 0;
    return 0;
}

static int button_init(void) {
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUTTON_PIN): %s\n", strerror(errno));
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(BUTTON_PIN): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int button_read_debounced(void) {
    int level = gpioRead(BUTTON_PIN);
    if (level < 0) {
        fprintf(stderr, "gpioRead(BUTTON_PIN): %s\n", strerror(errno));
        return -1;
    }
    if (level == 0) {
        gpioDelay(DEBOUNCE_US);
        level = gpioRead(BUTTON_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(BUTTON_PIN): %s\n", strerror(errno));
            return -1;
        }
        if (level == 0) {
            return 0;
        }
    }
    return 1;
}

static void lock Engage(void) {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
}

static void lock Disengage(void) {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        spi_transfer((unsigned char[]){0x00, 0x01, 0x02}, (unsigned char[]){0x00, 0x00, 0x00}, 3);
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    lock Engage();
    if (g_log) {
        log_event("Program terminated");
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(errno));
        return 1;
    }
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }
    if (button_init() != 0) {
        spi_close(g_spi_fd);
        gpioTerminate();
        return 1;
    }
    g_log = fopen("/var/log/door_access.log", "a");
    if (!g_log) {
        fprintf(stderr, "fopen(/var/log/door_access.log): %s\n", strerror(errno));
        spi_close(g_spi_fd);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_event("Program started");
    while (g_running) {
        unsigned char tag[TAG_SIZE];
        int rc = read_rfid_tag(tag);
        if (rc == 0) {
            if (read_rfid_tag_valid(tag)) {
                log_event("Access granted");
                if (button_read_debounced() == 0) {
                    log_event("Button pressed without valid tag");
                } else {
                    log_event("Button pressed with valid tag");
                    lock Engage();
                    sleep(DISENGAGE_SEC);
                    lock Disengage();
                    log_event("Access denied");
                }
            } else {
                log_event("Invalid RFID tag");
            }
        } else {
            log_event("RFID read failed");
        }
        usleep(POLL_DELAY_US);
    }
    cleanup();
    return 0;
}

