#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define SAMPLE_TIME_US 100000

#define TARGET_SPEED 60.0
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

#define LOG_FILE "motor_log.csv"

static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t encoder_mutex1 = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder_mutex2 = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int ena;
    int in1;
    int in2;
} Motor1;

typedef struct {
    int enb;
    int in3;
    int in4;
} Motor2;

typedef struct {
    int a;
    int b;
} Encoder;

static Motor1 motor1 = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2};
static Motor2 motor2 = {MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
static Encoder encoder1 = {ENCODER1_A, ENCODER1_B};
static Encoder encoder2 = {ENCODER2_A, ENCODER2_B};

static double integral1 = 0.0;
static double integral2 = 0.0;
static double prev_error1 = 0.0;
static double prev_error2 = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double speed1, double speed2, double p1, double i1, double d1, double p2, double i2, double d2, double output1, double output2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, speed1, speed2, p1, i1, d1, p2, i2, d2, output1, output2);
    fflush(log_file);
}

static void set_motor_speed(Motor1 *m, double speed) {
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    int duty = (int)(speed / (double)PWM_RANGE * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(m->ena, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for Motor1 ENA\n");
    }
    if (gpioWrite(m->in1, (duty > 0) ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for Motor1 IN1\n");
    }
    if (gpioWrite(m->in2, (duty < 0) ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for Motor1 IN2\n");
    }
}

static void set_motor_speed(Motor2 *m, double speed) {
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    int duty = (int)(speed / (double)PWM_RANGE * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(m->enb, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for Motor2 ENB\n");
    }
    if (gpioWrite(m->in3, (duty > 0) ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for Motor2 IN3\n");
    }
    if (gpioWrite(m->in4, (duty < 0) ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for Motor2 IN4\n");
    }
}

static int read_encoder(Encoder *e, int *a, int *b) {
    int val;
    int ret;

    ret = gpioSetMode(e->a, PI_INPUT);
    if (ret != 0) return -1;
    ret = gpioSetMode(e->b, PI_INPUT);
    if (ret != 0) return -1;
    ret = gpioSetPullUpDown(e->a, PI_PUD_UP);
    if (ret != 0) return -1;
    ret = gpioSetPullUpDown(e->b, PI_PUD_UP);
    if (ret != 0) return -1;

    val = gpioRead(e->a);
    if (val < 0) return -1;
    *a = val;

    val = gpioRead(e->b);
    if (val < 0) return -1;
    *b = val;

    return 0;
}

static void *encoder_thread1(void *arg) {
    (void)arg;
    int a, b;
    int count = 0;
    int ret;

    while (running) {
        ret = read_encoder(&encoder1, &a, &b);
        if (ret != 0) {
            fprintf(stderr, "Error: Failed to read encoder 1\n");
            gpioDelay(SAMPLE_TIME_US);
            continue;
        }

        pthread_mutex_lock(&encoder_mutex1);
        count += (a != b) ? 1 : 0;
        pthread_mutex_unlock(&encoder_mutex1);

        gpioDelay(SAMPLE_TIME_US);
    }
    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    int a, b;
    int count = 0;
    int ret;

    while (running) {
        ret = read_encoder(&encoder2, &a, &b);
        if (ret != 0) {
            fprintf(stderr, "Error: Failed to read encoder 2\n");
            gpioDelay(SAMPLE_TIME_US);
            continue;
        }

