        pthread_mutex_unlock(&encoder_mutex2);

        gpioDelay(SAMPLE_TIME_US);
    }
    return NULL;
}

static double calculate_pid(Motor1 *m, double target_speed, double current_speed, double *integral, double *prev_error) {
    double error = target_speed - current_speed;
    *integral += error;
    double derivative = error - *prev_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    return output;
}

int main(void) {
    int ret;
    pthread_t t1, t2;
    double speed1, speed2, p1, i1, d1, p2, i2, d2, output1, output2;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    fprintf(log_file, "Timestamp,Speed1(RPM),Speed2(RPM),P1, I1, D1, P2, I2, D2, Output1, Output2\n");
    fflush(log_file);

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        fclose(log_file);
        return 1;
    }

    ret = gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    if (ret != 0) goto fail;

    ret = gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    if (ret != 0) goto fail;
    ret = gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    if (ret != 0) goto fail;

    ret = gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    if (ret != 0) goto fail;
    ret = gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);
    if (ret != 0) goto fail;

    ret = gpioSetMode(ENCODER1_A, PI_INPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(ENCODER1_B, PI_INPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(ENCODER2_A, PI_INPUT);
    if (ret != 0) goto fail;
    ret = gpioSetMode(ENCODER2_B, PI_INPUT);
    if (ret != 0) goto fail;

    ret = gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    if (ret != 0) goto fail;
    ret = gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    if (ret != 0) goto fail;
    ret = gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    if (ret != 0) goto fail;
    ret = gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);
    if (ret != 0) goto fail;

    ret = gpioSetAlertFuncEx(ENCODER1_A, encoder_thread1, NULL);
    if (ret != 0) goto fail;
    ret = gpioSetAlertFuncEx(ENCODER1_B, NULL, NULL);
    if (ret != 0) goto fail;
    ret = gpioSetAlertFuncEx(ENCODER2_A, encoder_thread2, NULL);
    if (ret != 0) goto fail;
    ret = gpioSetAlertFuncEx(ENCODER2_B, NULL, NULL);
    if (ret != 0) goto fail;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        speed1 = calculate_pid(&motor1, TARGET_SPEED, 0.0, &integral1, &prev_error1);
        speed2 = calculate_pid(&motor2, TARGET_SPEED, 0.0, &integral2, &prev_error2);

        set_motor_speed(&motor1, speed1);
        set_motor_speed(&motor2, speed2);

        output1 = speed1;
        output2 = speed2;

        log_data(speed1, speed2, p1 = Kp, i1 = Ki, d1 = Kd, p2 = Kp, i2 = Ki, d2 = Kd, output1, output2);

        gpioDelay(SAMPLE_TIME_US);
    }

    set_motor_speed(&motor1, 0.0);
    set_motor_speed(&motor2, 0.0);
    gpioDelay(100000);

    gpioTerminate();
    fclose(log_file);
    return 0;

fail:
    gpioTerminate();
    fclose(log_file);
    return 1;
}

