#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5D
#define I2C_BUS 1
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_TTH 0x41
#define MPR121_ELE0_RTH 0x42
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_ELECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) != 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) != 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) != 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) != 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_ELE0_TTH + (i * 2), 0x0F) != 0) return -1;
        if (mpr121_write_reg(MPR121_ELE0_RTH + (i * 2), 0x0A) != 0) return -1;
    }

    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) != 0) return -1;
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x00) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    uint16_t prev_status = 0;
    int relay_state = 0;

    while (running) {
        uint16_t status;
        if (read_touch_status(&status) == 0) {
            uint16_t new_status = status & 0x0FFF;
            if (new_status != prev_status) {
                int touched = (new_status != 0) ? 1 : 0;
                relay_state = touched;
                gpioWrite(RELAY_GPIO, relay_state);
                log_relay_state(relay_state);
                prev_status = new_status;
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

