#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_SEC 5
#define VALVE2_PAUSE_SEC 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int activate_valve(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        log_event("Error: Failed to set GPIO HIGH (relay ON)");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        log_event("Error: Failed to set GPIO LOW (relay OFF)");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        log_event("Activating Valve 1");
        if (activate_valve(VALVE1_GPIO, VALVE1_DURATION_MS) != 0) {
            log_event("Error: Valve 1 activation failed");
        }

        if (!running) break;

        log_event("Pausing Valve 1");
        sleep(VALVE1_PAUSE_SEC);

        if (!running) break;

        log_event("Activating Valve 2");
        if (activate_valve(VALVE2_GPIO, VALVE2_DURATION_MS) != 0) {
            log_event("Error: Valve 2 activation failed");
        }

        if (!running) break;

        log_event("Pausing Valve 2");
        sleep(VALVE2_PAUSE_SEC);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

