static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(0x80, 0x63) < 0) return -1; /* Stop mode */
    if (mpr121_write(0x5B, 0x00) < 0) return -1; /* FFI = 0 */
    if (mpr121_write(0x5C, 0x01) < 0) return -1; /* CDC = 16 */
    if (mpr121_write(0x5D, 0x04) < 0) return -1; /* ESI = 4 */
