#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define LOG_FILE "door_events.log"
#define POLL_INTERVAL_US 50000
#define UNLOCK_DURATION_US 500000
#define RATE_LIMIT_US 2000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%lld,%s\n", timestamp_ms, event_type);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate relay: %s\n", strerror(errno));
        return;
    }
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_US);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay: %s\n", strerror(errno));
    }
    log_event("Door locked");
}

static void *pir_monitor(void *arg) {
    (void)arg;
    int last_state = 0;
    uint32_t last_event_tick = 0;

    while (running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read PIR pin: %s\n", strerror(errno));
            break;
        }

        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_event_tick > RATE_LIMIT_US) {
                unlock_door();
                last_event_tick = now;
            }
        }
        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set PIR pull-down: %s\n", strerror(errno));
        gpioTerminate();
