#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int generate_pattern(int steps, int *duties, int *durations) {
    if (steps < MIN_STEPS || steps > MAX_STEPS) {
        fprintf(stderr, "Error: invalid pattern length %d (must be %d-%d)\n",
                steps, MIN_STEPS, MAX_STEPS);
        return -1;
    }

    for (int i = 0; i < steps; i++) {
        duties[i] = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        durations[i] = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) +
                       MIN_DURATION_MS;
    }

    return 0;
}

static int play_pattern(const int *duties, const int *durations, int steps) {
    for (int i = 0; i < steps; i++) {
        if (gpioPWM(MOTOR1_PIN, duties[i]) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", MOTOR1_PIN);
            return -1;
        }
        if (gpioPWM(MOTOR2_PIN, duties[i]) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", MOTOR2_PIN);
            return -1;
        }
        usleep(durations[i] * 1000);
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int *duties = (int *)malloc((size_t)steps * sizeof(int));
    int *durations = (int *)malloc((size_t)steps * sizeof(int));

    if (duties == NULL || durations == NULL) {
        fprintf(stderr, "Error: memory allocation failed\n");
        free(duties);
        free(durations);
        gpioTerminate();
        return 1;
    }

    while (!shutdown_flag) {
        int steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
        if (generate_pattern(steps, duties, durations) != 0) {
            fprintf(stderr, "Error: failed to generate pattern\n");
            break;
        }

        if (play_pattern(duties, durations, steps) != 0) {
            fprintf(stderr, "Error: failed to play pattern\n");
            break;
        }
    }

    free(duties);
    free(durations);
    cleanup();
    return 0;
}

