#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_INTERVAL_US 500000
#define READ_TIMEOUT_US 500000
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

static volatile sig_atomic_t running = 1;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = 0;

    while (gpioRead(data_pin) == 0) {
        if (++timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line is low for too long.\n");
            return -1;
        }
        gpioDelay(100);
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(data_pin)) {
            data |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double calculate_weight(int raw_data) {
    return (raw_data - offset) / scale_factor;
}

static int log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);

    fclose(fp);
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *saveptr = NULL;
        char *token = strtok_r(line, " \t", &saveptr);
        if (!token) continue;

        char *endptr = NULL;
        double val = strtod(token, &endptr);
        if (endptr == token) continue;

        if (strcmp(token, "scale_factor") == 0) {
            scale_factor = val;
        } else if (strcmp(token, "offset") == 0) {
            offset = val;
        }
    }

    fclose(fp);
    return 0;
}

static int save_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file for writing");
        return -1;
    }

    fprintf(fp, "scale_factor = %.2f\n", scale_factor);
    fprintf(fp, "offset = %.2f\n", offset);

    fclose(fp);
    return 0;
}

static int calibrate_hx711(void) {
    int sum = 0;
    int valid_readings = 0;

    printf("Calibrating HX711 (100 readings at 0 load)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1;
        }
        sum += raw;
        valid_readings++;
        gpioDelay(1000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid HX711 readings during calibration.\n");
        return -1;
    }

    offset = (double)sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static int engage_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to engage solenoid.\n");
        return -1;
    }
    printf("Solenoid engaged.\n");
    return 0;
}

static int disengage_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to disengage solenoid.\n");
        return -1;
    }
    printf("Solenoid disengaged.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-up on HX711 data pin.\n");
    }

    if (load_calibration() != 0) {
        fprintf(stderr, "Using default calibration values.\n");
    }

    if (calibrate_hx711() != 0) {
        fprintf(stderr, "Calibration failed. Continuing with loaded values.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    printf("Monitoring weight. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            if (engage_solenoid(SOLENOID_PIN) != 0) {
                fprintf(stderr, "Error engaging solenoid.\n");
            }
        } else {
            if (disengage_solenoid(SOLENOID_PIN) != 0) {
                fprintf(stderr, "Error disengaging solenoid.\n");
            }
        }

        if (log_weight(weight) != 0) {
            fprintf(stderr, "Error logging weight.\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    disengage_solenoid(SOLENOID_PIN);
    save_calibration();
    gpioTerminate();
    return 0;
}

