    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid HX711 readings during calibration.\n");
        return -1;
    }

    offset = (double)sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static int engage_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to engage solenoid.\n");
        return -1;
    }
    printf("Solenoid engaged.\n");
    return 0;
}

static int disengage_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to disengage solenoid.\n");
        return -1;
    }
    printf("Solenoid disengaged.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-up on HX711 data pin.\n");
    }

    if (load_calibration() != 0) {
        fprintf(stderr, "Using default calibration values.\n");
    }

    if (calibrate_hx711() != 0) {
        fprintf(stderr, "Calibration failed. Continuing with loaded values.\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    printf("Monitoring weight. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "Error reading HX711. Skipping iteration.\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            if (engage_solenoid(SOLENOID_PIN) != 0) {
                fprintf(stderr, "Error engaging solenoid.\n");
            }
        } else {
            if (disengage_solenoid(SOLENOID_PIN) != 0) {
                fprintf(stderr, "Error disengaging solenoid.\n");
            }
        }

        if (log_weight(weight) != 0) {
            fprintf(stderr, "Error logging weight.\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    disengage_solenoid(SOLENOID_PIN);
    save_calibration();
    gpioTerminate();
    return 0;
}

