static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

static int control_motor(int in1, int in2, int pwm) {
    if (gpioWrite(MOTOR_IN1_PIN, in1) < 0) {
        syslog(LOG_ERR, "Failed to write IN1 (GPIO %d)", MOTOR_IN1_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, in2) < 0) {
        syslog(LOG_ERR, "Failed to write IN2 (GPIO %d)", MOTOR_IN2_PIN);
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, pwm) < 0) {
        syslog(LOG_ERR, "Failed to set PWM (GPIO %d)", MOTOR_PWM_PIN);
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
