        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin %d as input", RAIN_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin %d as output", MOTOR_IN1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin %d as output", MOTOR_IN2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin %d as output", MOTOR_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control program started");

    while (program_running) {
        if (read_rain_sensor()) {
            syslog(LOG_INFO, "Rain detected");
            log_event("Rain detected");
            if (control_motor(1, 0, PWM_DUTY_CYCLE) == 0) {
                log_event("Motor started");
                for (int i = 0; i < MOTOR_RUN_TIME && program_running; i++) {
                    gpioDelay(1000000 / MOTOR_RUN_TIME);
                }
                if (control_motor(0, 0, 0) == 0) {
                    log_event("Motor stopped");
                } else {
                    log_event("Motor stop failed");
                }
            } else {
                log_event("Motor start failed");
            }
        }
        for (int i = 0; i < RAIN_CHECK_INTERVAL && program_running; i++) {
            gpioDelay(60000000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

