#include <unistd.h>
#include <pigpio.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define READ_INTERVAL 1
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_hx711(int *raw_out) {
    int timeout = 0;
    while (gpioRead(HX711_DT) == 1) {
        if (++timeout > HX711_TIMEOUT_US) {
            log_event("HX711 timeout: data line stuck high");
            return -1;
        }
        gpioDelay(100);
    }
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DT)) {
            value |= 1;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);
    *raw_out = (int32_t)value;
    return 0;
}

static double calculate_weight(int raw) {
    return (double)raw / 1000.0;
}

static void activate_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        log_event("Error: failed to activate solenoid");
        return;
    }
    log_event("Solenoid lock activated");
    sleep(LOCK_DURATION);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Error: failed to deactivate solenoid");
    } else {
        log_event("Solenoid lock deactivated");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT, PI_INPUT) != 0 ||
        gpioSetMode(HX711_SCK, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        int raw;
        if (read_hx711(&raw) != 0) {
            log_event("HX711 read failed");
            sleep(READ_INTERVAL);
            continue;
        }

        double weight = calculate_weight(raw);
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Weight: %.2f g", weight);
        log_event(log_buf);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold, activating solenoid");
            activate_solenoid();
        }

        sleep(READ_INTERVAL);
    }

    log_event("System shutting down");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

