#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_THRESHOLD 5.0
#define TIMEOUT_US 100000
#define LOCK_DURATION_US 5000000
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_factor(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for reading. Creating new file.\n", CALIBRATION_FILE);
        fp = fopen(CALIBRATION_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Error: cannot create %s. Exiting.\n", CALIBRATION_FILE);
            return -1;
        }
        printf("Place a known weight on the load cell and press Enter to save calibration factor.\n");
        getchar();
        calibration_factor = 1.0;
        if (fprintf(fp, "%.6f\n", calibration_factor) < 0) {
            fprintf(stderr, "Error: failed to write calibration factor.\n");
            fclose(fp);
            return -1;
        }
        fclose(fp);
        printf("Calibration factor saved to %s.\n", CALIBRATION_FILE);
        return 0;
    }

    double factor;
    if (fscanf(fp, "%lf", &factor) != 1) {
        fprintf(stderr, "Error: invalid calibration factor in %s. Using default 1.0.\n", CALIBRATION_FILE);
        calibration_factor = 1.0;
    } else {
        calibration_factor = factor;
    }
    fclose(fp);
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set HX711_DATA_PIN mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set HX711_CLOCK_PIN mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SOLENOID_PIN mode.\n");
        gpioTerminate();
        return -1;
    }

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1000);
    return 0;
}

static int read_hx711_raw(int32_t *raw_value) {
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck low (timeout).\n");
            return -1;
        }
