#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading config file '%s': %s\n",
                filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *saveptr = NULL;
    char *token = strtok_r(line, "=\n", &saveptr);
    if (!token) {
        fprintf(stderr, "Error: config file '%s' is empty or malformed.\n",
                filename);
        return -1;
    }

    token = strtok_r(NULL, "=\n", &saveptr);
    if (!token) {
        fprintf(stderr, "Error: missing duration in config file '%s'.\n",
                filename);
        return -1;
    }

    char *endptr = NULL;
    long val = strtol(token, &endptr, 10);
    if (endptr == token) {
        fprintf(stderr, "Error: invalid duration '%s' in config file '%s'.\n",
                token, filename);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration %ld out of range [1,%d] in config file '%s'.\n",
                val, MAX_DURATION, filename);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int set_valve(int gpio_pin, int duration)
{
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }

    printf("Watering valve on GPIO%d for %d seconds.\n", gpio_pin, duration);
    fflush(stdout);

    if (sleep(duration) != 0) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal during watering.\n");
        } else {
            fprintf(stderr, "Error: sleep() failed: %s\n", strerror(errno));
        }
        return -1;
    }

    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }

    printf("Watering valve off.\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (read_config(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration of 5 seconds.\n");
        duration = 5;
    }

    if (set_valve(GPIO_PIN, duration) != 0) {
        fprintf(stderr, "Error: valve activation failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        sleep(1);
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn valve off on exit: %s\n",
                strerror(errno));
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

