/*
 * line_follower.c — Raspberry Pi Zero W
 *
 * Line-following robot using a Keywish 3-Way IR sensor and an L298N dual
 * H-bridge driver.  Sensors are active-low digital inputs; PWM outputs are
 * driven at 1 kHz.  The robot turns right when only the left sensor is
 * low, left when only the right sensor is low, and stops when both middle
 * and both side sensors are low.  All control cycles are logged to
 * trace_log.txt.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 left  -> GPIO4
 *   Sensor 2 middle -> GPIO17
 *   Sensor 3 right  -> GPIO27
 *   Motor 1 PWM    -> GPIO22
 *   Motor 2 PWM    -> GPIO23
 *   Motor 3 PWM    -> GPIO24
 *   Motor 4 PWM    -> GPIO25
 *
 * Build:  gcc -O2 -Wall -Wextra -o line_follower line_follower.c -lpigpio -lrt
 * Run:    sudo ./line_follower
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define MOTOR1_PIN 22
#define MOTOR2_PIN 23
#define MOTOR3_PIN 24
#define MOTOR4_PIN 25

/* ---- Timing ---- */
#define PWM_FREQUENCY 1000          /* Hz */
#define PWM_RANGE     255           /* duty-cycle resolution */
#define LOOP_DELAY_US 10000         /* 10 ms */

/* ---- Control constants ---- */
#define BASE_SPEED 150              /* 0–255 */
#define TURN_RIGHT  50             /* 50/255 */
#define TURN_LEFT   (-50)           /* -50/255 */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void log_data(int s1, int s2, int s3,
                     int m1, int m2, int m3, int m4);
static void set_motor_speed(int pin, int speed);
static void stop_motors(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set sensor pins as inputs.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins as outputs ---- */
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR3_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pins as outputs.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(MOTOR3_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(MOTOR4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Ensure motors start stopped ---- */
    stop_motors();

    /* ---- Open log file ---- */
    g_log = fopen("trace_log.txt", "a");
    if (g_log == NULL) {
        perror("Error opening trace_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main control loop ---- */
    while (g_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);
        int s3 = gpioRead(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Error: GPIO read failure (s1=%d s2=%d s3=%d).\n",
                    s1, s2, s3);
            break;
        }

        /* Active-low: 0 = sensor present, 1 = no sensor */
        int left  = (s1 == 0) ? 0 : 1;
        int middle = (s2 == 0) ? 0 : 1;
        int right  = (s3 == 0) ? 0 : 1;

        int m1, m2, m3, m4;

        if (middle == 0) {
            /* Straight: both sides present */
            m1 = m2 = BASE_SPEED;
            m3 = m4 = 0;
        } else if (left == 0) {
            /* Turn right: left side present, right side absent */
            m1 = BASE_SPEED;
            m2 = BASE_SPEED + TURN_RIGHT;
            m3 = m4 = 0;
        } else if (right == 0) {
            /* Turn left: left side absent, right side present */
            m1 = BASE_SPEED + TURN_LEFT;
            m2 = BASE_SPEED;
            m3 = 0;
            m4 = BASE_SPEED + TURN_LEFT;
        } else {
            /* No sensor present: stop */
            m1 = m2 = m3 = m4 = 0;
        }

        /* ---- Apply PWM ---- */
        set_motor_speed(MOTOR1_PIN, m1);
        set_motor_speed(MOTOR2_PIN, m2);
        set_motor_speed(MOTOR3_PIN, m3);
        set_motor_speed(MOTOR4_PIN, m4);

        /* ---- Log ---- */
        log_data(s1, s2, s3, m1, m2, m3, m4);

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    stop_motors();
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_data(int s1, int s2, int s3,
                     int m1, int m2, int m3, int m4)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log, "%s,%d,%d,%d,%d,%d,%d\n",
                ts, s1, s2, s3, m1, m2, m3) < 0) {
        perror("Error writing to log file");
    }
    if (fflush(g_log) != 0) {
        perror("Error flushing log file");
    }
}

/* ------------------------------------------------------------------ */
static void set_motor_speed(int pin, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (gpioPWM(pin, speed) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed.\n", pin, speed);
    }
}

/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    set_motor_speed(MOTOR1_PIN, 0);
    set_motor_speed(MOTOR2_PIN, 0);
    set_motor_speed(MOTOR3_PIN, 0);
    set_motor_speed(MOTOR4_PIN, 0);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();

    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

