#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x5C
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int lux, bool relay_on) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;

    fprintf(fp, "%s.%03ld, Lux: %d, Relay: %s\n",
            timestamp, ms, lux, relay_on ? "ON" : "OFF");
    fclose(fp);
}

static int read_lux(void) {
    if (i2cWriteByte(i2c_handle, 0x10) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    int raw = i2cReadWordData(i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read lux value from sensor.\n");
        return -1;
    }
    return (int)((raw & 0xFF) | ((raw >> 8) & 0xFF));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize relay to OFF state.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow lamp controller started. Press Ctrl+C to exit.\n");

    while (running) {
        int lux = read_lux();
        if (lux >= 0) {
            log_data(lux, lux < LUX_THRESHOLD);
            if (lux < LUX_THRESHOLD) {
                if (gpioWrite(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "Error: Failed to turn relay ON.\n");
                } else {
                    printf("Lux: %d < %d, Relay ON\n", lux, LUX_THRESHOLD);
                }
            } else {
                if (gpioWrite(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Error: Failed to turn relay OFF.\n");
                } else {
                    printf("Lux: %d >= %d, Relay OFF\n", lux, LUX_THRESHOLD);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read lux value. Retrying...\n");
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

