#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2000
#define SERVO_OPEN 2000
#define SERVO_CLOSED 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_PULSE || angle > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(SERVO_PIN, angle) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set button pins as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: cannot set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (set_servo_angle(SERVO_CLOSED) == 0) {
                printf("Lock pressed. Door locked.\n");
            }
            gpioDelay(100000);
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (set_servo_angle(SERVO_OPEN) == 0) {
                printf("Unlock pressed. Door unlocked.\n");
            }
            gpioDelay(100000);
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

