#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, value);
        return -1;
    }
    return 0;
}

static int safe_gpio_read(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }
    return val;
}

static int pulse_motor(int pin, int duration_ms) {
    if (safe_gpio_write(pin, 1) != 0) return -1;
    gpioDelay(duration_ms * 1000);
    if (safe_gpio_write(pin, 0) != 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (pulse_motor(MOTOR1_PIN, MOTOR1_DURATION_MS) != 0) break;
        if (!running) break;
        if (pulse_motor(MOTOR2_PIN, MOTOR2_DURATION_MS) != 0) break;
        if (!running) break;
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    /* Stop motors and release GPIO lines */
    safe_gpio_write(MOTOR1_PIN, 0);
    safe_gpio_write(MOTOR2_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

