#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timeval tv;
    tv.tv_sec = us / 1000000;
    tv.tv_usec = us % 1000000;
    nanosleep(&tv, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000);
}

static void sleep_s(unsigned int s) {
    sleep_us(s * 1000000);
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static void alarm_led_on(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        log_message("Error: failed to set alarm LED high");
    }
}

static void alarm_led_off(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        log_message("Error: failed to set alarm LED low");
    }
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void cleanup_zmq(void *context, void *socket) {
    if (socket) {
        zmq_close(socket);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

int main(int argc, char *argv[]) {
    const char *mode = (argc > 1) ? argv[1] : "sound_sensor";
    const char *zmq_address = ZMQ_ADDRESS;
    const char *zmq_topic = ZMQ_TOPIC;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
