#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

#define NEC_HDR_MARK  9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK  560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE  50
#define MAX_PULSES    68
#define MAX_FRAME     68

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_times[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static volatile uint32_t frame_start = 0;
static volatile bool frame_in_progress = false;
static volatile bool decoding = false;
static volatile uint32_t decoded_command = 0;
static volatile bool command_valid = false;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s: %s", msg, strerror(errno));
    fprintf(stderr, "Error: %s: %s\n", msg, strerror(errno));
}

static void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
    printf("%s\n", msg);
}

static void log_command(uint32_t cmd) {
    char buf[64];
    snprintf(buf, sizeof(buf), "Decoded command: 0x%08X", cmd);
    log_info(buf);
}

static void process_frame(void) {
    if (!frame_in_progress || !decoding) return;

    if (pulse_count < MAX_FRAME) {
        uint32_t frame_len = pulse_count * (NEC_BIT_MARK + NEC_ONE_SPACE);
        if (frame_len > MAX_FRAME) {
            log_error("Frame too long");
            return;
        }
        uint32_t checksum = 0;
        for (int i = 0; i < 32; i++) {
            checksum += pulse_times[i];
        }
        uint8_t inv_checksum = 0;
        for (int i = 0; i < 32; i++) {
            inv_checksum += pulse_times[32 - 1 - i];
        }
        if (checksum != inv_checksum) {
            log_error("NEC checksum mismatch");
            return;
        }
        decoded_command = (uint32_t)checksum;
        command_valid = true;
        decoding = false;
        frame_in_progress = false;
        pulse_count = 0;
    }
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) return;
    if (last_tick != 0) {
        uint32_t diff = tick - last_tick;
        if (diff > 0) {
            pulse_times[pulse_count++] = diff;
        }
    }
    last_tick = tick;
    if (pulse_count >= MAX_PULSES) {
        log_error("Pulse buffer overflow");
        pulse_count = 0;
        return;
    }
    if (level == 1 && pulse_count == 1) {
        frame_start = pulse_times[0];
        frame_in_progress = true;
        decoding = true;
    }
    process_frame();
}

static void mqtt_connect(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_error("mosquitto_new failed");
        return;
    }
    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_connect failed");
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("mosquitto_connect_callback failed");
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        uint32_t cmd = 0;
        if (sscanf(payload, "%32x", &cmd) == 1) {
            log_command(cmd);
            int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("mosquitto_publish failed");
            }
        } else {
            log_error("Invalid payload format");
        }
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    (void)mosq;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_disconnect failed");
    }
}

static void mqtt_loop(void) {
    int rc = mosquitto_loop(mosq, 100, 1);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_loop failed");
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    log_info("Starting IR decoder");

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        log_error("Failed to set alert function");
        gpioTerminate();
        closelog();
        return 1;
    }

    mqtt_connect();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_info("Starting network loop");
    while (running) {
        mqtt_loop();
        gpioDelay(100000);
    }

    log_info("Shutting down");
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL);
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();
    return 0;
}

