    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    log_info("Starting IR decoder");

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        log_error("Failed to set alert function");
        gpioTerminate();
        closelog();
        return 1;
    }

    mqtt_connect();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_info("Starting network loop");
    while (running) {
        mqtt_loop();
        gpioDelay(100000);
    }

    log_info("Shutting down");
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL);
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();
    return 0;
}

