#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x5C
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_PERIOD  1
#define CONV_DELAY_MS  180

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, uint8_t addr, float *lux_out)
{
    if (fd < 0) {
        *lux_out = NAN;
        return -1;
    }

    if (write(fd, (uint8_t[]){0x10, 0x01}, 2) != 2) {
        fprintf(stderr, "BH1750 write: %s\n", strerror(errno));
        *lux_out = NAN;
        return -1;
    }

    usleep(CONV_DELAY_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: %s\n", n < 0 ? strerror(errno) : "short read");
        *lux_out = NAN;
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, const char *msg)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fds[NUM_SENSORS];
    int sockfd = -1;
    int exit_code = EXIT_SUCCESS;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(I2C_BUS, BH1750_ADDR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open I2C for sensor %d\n", i + 1);
            exit_code = EXIT_FAILURE;
            goto cleanup;
        }
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    while (!g_terminate) {
        char line[256];
        int ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = NAN;
            if (bh1750_read(i2c_fds[i], BH1750_ADDR, &lux) == 0) {
                snprintf(line, sizeof(line), "%d,%.1f", i + 1, lux);
            } else {
                snprintf(line, sizeof(line), "%d,NaN", i + 1);
                ok = 0;
            }
        }

        if (send_multicast(sockfd, line) < 0) {
            fprintf(stderr, "Multicast send failed\n");
            exit_code = EXIT_FAILURE;
            goto cleanup;
        }

        if (ok) {
            printf("Sensor 1: %.1f lux | Sensor 2: %.1f lux | Sensor 3: %.1f lux | Sensor 4: %.1f lux\n",
                   (lux > 0.0f) ? lux : 0.0f,
                   (lux > 0.0f) ? lux : 0.0f,
                   (lux > 0.0f) ? lux : 0.0f,
                   (lux > 0.0f) ? lux : 0.0f);
        } else {
            fprintf(stderr, "Sensor read failed; skipping multicast\n");
        }

        for (int i = 0; i < SAMPLE_PERIOD && !g_terminate; i++)
            sleep(1);
    }

cleanup:
    if (sockfd >= 0) close(sockfd);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    return exit_code;
}

