#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 2 bytes from the AWM7300V sensor.
 * Returns 0 on success and stores the 14-bit flow value in *flow_raw.
 * Returns -1 on I2C error (EIO), -2 on ENXIO (sensor absent).
 */
static int read_airflow(int fd, uint16_t *flow_raw)
{
    uint8_t buf[2];
    ssize_t n;

    /* Issue a zero-length write to generate a start condition. */
    if (write(fd, buf, 0) < 0) {
        if (errno == EIO)
            return -1;
        if (errno == ENXIO)
            return -2;
        return -1;
    }

    /* Small delay so the sensor has time to respond. */
    usleep(1000);

    /* Read two bytes of data. */
    n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            return -1;
        return -2; /* ENXIO */
    }

    /* Extract the 14-bit flow value from the two bytes. */
    *flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_raw &= 0x3FFF; /* Mask out the 2 status bits. */
    return 0;
}

/* Convert the 14-bit flow value to SLPM. */
static float convert_to_slpm(uint16_t flow_raw)
{
    /* AWM7300V: 0.1 SLPM per LSB. */
    return (float)flow_raw * 0.1f;
}

/* Log a timestamped flow-rate entry to the log file. */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address. */
    if (ioctl(fd, I2C_SLAVE, 0x76) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x76) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open the log file in append mode. */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Airflow monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t flow_raw = 0;
        int retries = 0;
        int success = 0;

        /* Retry loop for transient I2C read failures. */
        while (retries < MAX_RETRIES && g_running) {
            int result = read_airflow(fd, &flow_raw);
            if (result == 0) {
                success = 1;
                break;
            }

            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "I2C read attempt %d/%d failed (code %d).\n",
                        retries, MAX_RETRIES, result);
                if (result == -2) {
                    fprintf(stderr, "Sensor not responding (ENXIO).\n");
                }
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (success) {
            float flow_rate = convert_to_slpm(flow_raw);
            if (log_flow_rate(fp, flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate.\n");
            } else {
                printf("Flow rate: %.2f SLPM\n", flow_rate);
            }
        } else {
            fprintf(stderr, "Failed to read airflow data after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep for the sample period, but wake early if a signal arrives. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    if (fd >= 0) {
        if (close(fd) != 0) {
            fprintf(stderr, "close(%d) failed: %s\n", fd, strerror(errno));
            rc = EXIT_FAILURE;
        }
    }

    printf("\nAirflow monitoring stopped.\n");
    return rc;
}

