/*
 * AS7341 10-Channel Light/Color Sensor reader for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * Logs spectral and lux data to spectral_log.csv every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o as7341_monitor as7341_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (from Adafruit datasheet) ---- */
#define AS7341_I2C_ADDR          0x74
#define AS7341_ENABLE            0x00
#define AS7341_CFG6              0x01
#define AS7341_ID                0x00
#define AS7341_DATA              0x02
#define AS7341_DATA_LEN          16  /* 10 channels × 2 bytes each */

/* Enable register bits */
#define AS7341_PON               0x01
#define AS7341_SP_EN             0x20

/* CFG6 register bits */
#define AS7341_SMUX              0x03
#define AS7341_SMUX_CFG          0x00  /* F1-F8, Clear, NIR */

/* Expected device ID */
#define AS7341_ID_VALUE         0x84

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Configure SMUX: F1–F8, Clear, NIR */
    if (i2c_write_reg8(fd, AS7341_CFG6, AS7341_SMUX_CFG) != 0)
        return -1;

    /* Enable spectral measurement */
    if (i2c_write_reg8(fd, AS7341_ENABLE, AS7341_PON | AS7341_SP_EN) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_spectral_data(int fd, uint16_t *data)
{
    if (i2c_read_reg16(fd, AS7341_DATA, data) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t *data, int n)
{
    float lux = 0.0f;
    for (int i = 0; i < n; i++)
        lux += (float)data[i] * 0.1f;  /* rough approximation */
    return lux / (float)n;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *timestamp, float lux)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor into power-down state before closing */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("spectral_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open spectral_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t spectral_data[AS7341_DATA_LEN];
        int rc = read_spectral_data(g_i2c_fd, spectral_data);

        if (rc == 0) {
            float lux = calculate_lux(spectral_data, 10);
            time_t rawtime;
            time(&rawtime);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_data(g_log_fp, timestamp, lux) != 0)
                fprintf(stderr, "Logging failed — continuing.\n");

            printf("%s  Lux: %.2f\n", timestamp, lux);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }

        /* Sleep 5 s in 1 s increments so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

