#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 8192
#define MAX_OBJECTS 100
#define MAGIC_WORD_SIZE 8
#define TLV_HEADER_SIZE 8
#define TLV_TYPE_RANGE_DOPPLER 1
#define TLV_TYPE_RANGE_PROFILE 2
#define TLV_TYPE_DOPPLER_PROFILE 3
#define TLV_TYPE_RANGE_INDEX 4
#define TLV_TYPE_DOPPLER_INDEX 5
#define TLV_TYPE_RANGE_PROFILE_INDEX 6
#define TLV_TYPE_DOPPLER_PROFILE_INDEX 7

typedef struct {
    uint32_t magic_word[MAGIC_WORD_SIZE];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) mmw_frame_header_t;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) tlv_header_t;

typedef struct {
    float range;
    float velocity;
} __attribute__((packed)) object_data_t;

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int read_exact(int handle, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = serRead(handle, (char *)(buf + total), len - total);
        if (n < 0) {
            fprintf(stderr, "UART read error: %d\n", n);
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            continue;
        }
        total += n;
    }
    return 0;
}

static int find_magic_word(int handle, uint32_t *magic) {
    uint8_t buf[MAX_FRAME_SIZE];
    int idx = 0;
    while (idx < MAX_FRAME_SIZE - MAGIC_WORD_SIZE) {
        if (read_exact(handle, buf + idx, 1) != 0) return -1;
        if (buf[idx] == 0x02 && buf[idx + 1] == 0x01) {
            memcpy(magic, buf + idx + 2, MAGIC_WORD_SIZE);
            return 0;
        }
        idx++;
    }
    return -1;
}

static int process_frame(int handle, uint32_t *magic) {
    uint32_t total_packet_len = magic[0] | (magic[1] << 8) |
                                (magic[2] << 16) | (magic[3] << 24);
    if (total_packet_len < MAGIC_WORD_SIZE || total_packet_len > MAX_FRAME_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", total_packet_len);
        return -1;
    }

    uint8_t *frame = malloc(total_packet_len);
    if (!frame) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    if (read_exact(handle, frame, total_packet_len) != 0) {
        free(frame);
        return -1;
    }

    uint32_t num_tlvs = magic[6] | (magic[7] << 8);
    uint32_t offset = MAGIC_WORD_SIZE;
    uint32_t num_detected_obj = magic[12] | (magic[13] << 8) |
                                 (magic[14] << 16) | (magic[15] << 24);

    for (uint32_t i = 0; i < num_tlvs; i++) {
        if (offset + TLV_HEADER_SIZE > total_packet_len) break;
        tlv_header_t hdr;
        memcpy(&hdr, frame + offset, TLV_HEADER_SIZE);
        offset += TLV_HEADER_SIZE;

        if (offset + hdr.length > total_packet_len) break;

        if (hdr.type == TLV_TYPE_RANGE_DOPPLER) {
            uint32_t range_idx = hdr.length / sizeof(object_data_t);
            if (range_idx > num_detected_obj) range_idx = num_detected_obj;
            for (uint32_t j = 0; j < range_idx; j++) {
                object_data_t obj;
                memcpy(&obj, frame + offset + j * sizeof(object_data_t), sizeof(object_data_t));
                if (obj.range >= 0.0f && obj.velocity >= 0.0f) {
                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                    fprintf(csv_file, "%s,%u,%.2f,%.2f\n", timestamp, j, obj.range, obj.velocity);
                    fflush(csv_file);
                }
            }
        }
        offset += hdr.length;
    }

    free(frame);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    uint32_t magic[MAGIC_WORD_SIZE];
    if (find_magic_word(uart_handle, magic) != 0) {
        fprintf(stderr, "Failed to find magic word\n");
        cleanup();
        return 1;
    }

    uint32_t frame_number = 0;
    uint32_t num_detected_obj = 0;

    while (running) {
        if (process_frame(uart_handle, magic) != 0) {
            fprintf(stderr, "Frame processing error\n");
        }
        frame_number++;
        num_detected_obj = magic[12] | (magic[13] << 8) |
                           (magic[14] << 16) | (magic[15] << 24);
        if (num_detected_obj > MAX_OBJECTS) num_detected_obj = MAX_OBJECTS;
        gpioDelay(10000);
    }

    printf("Shutting down gracefully...\n");
    cleanup();
    return 0;
}

