#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <termios.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int uart_init(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_line(int fd, char *line, size_t line_size) {
    size_t i = 0;
    char ch;
    ssize_t n;

    while (i < line_size - 1) {
        n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return 0;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            return 0;
        }

        if (ch == '\n') {
            line[i] = '\0';
            return 1;
        }

        if (ch != '\r') {
            line[i++] = ch;
        }
    }

    line[i] = '\0';
    return 0;
}

static int parse_detection(const char *line, double *timestamp, double *range) {
    char *endptr = NULL;
    errno = 0;
    *timestamp = strtod(line, &endptr);
    if (errno != 0 || endptr == line || *endptr != ',') {
        return -1;
    }

    char *range_str = endptr + 1;
    errno = 0;
    *range = strtod(range_str, &endptr);
    if (errno != 0 || endptr == range_str || *endptr != '\0') {
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = uart_init(UART_DEVICE);
    if (g_uart_fd < 0) {
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    char line[LINE_BUF_SIZE];
    size_t line_len = 0;

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval tv;
        tv.tv_sec = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(fd + 1, &readfds, NULL, NULL, &tv);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error from select: %s\n", strerror(errno));
            break;
        }

        if (sel == 0) {
            fprintf(stderr, "Timeout waiting for UART data.\n");
            continue;
        }

        if (read_uart_line(g_uart_fd, line_buf, sizeof(line_buf)) == 0) {
            if (line_len + strlen(line_buf) >= sizeof(line)) {
                fprintf(stderr, "Line buffer overflow, discarding.\n");
                line_len = 0;
                continue;
            }

            strncpy(line + line_len, line_buf, sizeof(line) - line_len);
            line[line_len] = '\0';
            line_len += strlen(line_buf);

            char *newline = strchr(line, '\n');
            if (newline) {
                *newline = '\0';
                line_len = (newline - line) + 1;
            }

            char *ts_str = NULL, *range_str = NULL;
            double timestamp = 0.0, range = 0.0;

            if (parse_detection(line, &timestamp, &range) == 0) {
                printf("Timestamp: %s, Range: %.2f meters\n", ctime(&timestamp), range);
                fflush(stdout);
            } else {
                fprintf(stderr, "Invalid detection format: %s\n", line);
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    return 0;
}

