    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void log_sensor_states(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static void send_emergency_stop(int left, int middle, int right) {
    if (uart_fd < 0) {
        fprintf(stderr, "UART not initialized\n");
        return;
    }

    const char *message = "EMERGENCY STOP!\n";
    size_t len = strlen(message);

    ssize_t bytes_written = write(uart_fd, message, len);
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
    } else {
        printf("Sent emergency stop message: %s", message);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistors\n");
        gpioTerminate();
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("Tracking sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int left  = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor GPIO pins\n");
        } else {
            log_sensor_states(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop(left, middle, right);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioTerminate();

    return 0;
}

